// AVTOMATİK YARADILIB — scripts/build-daily-hadith.mjs (əl ilə dəyişməyin)
// "Günün hədisi" push siyahısı: yalnız səhih (Buxari / Muslim), saytda səhifəsi olan hədislər.
// Mətnlər saytdakı ilə eynidir (src/data/hadiths.js). Oxuyan: server/daily-hadith.js
'use strict'
module.exports = [{"id":1,"t":{"az":"İslam beş şey üzərində qurulmuşdur: Allahdan başqa ilah olmadığına şəhadət, namaz, zəkat, həcc və Ramazan orucu.","en":"Islam is built on five things: testimony that there is no god but Allah, prayer, zakat, hajj, and fasting Ramadan.","ru":"Ислам основан на пяти вещах: свидетельстве, что нет бога, кроме Аллаха, молитве, закяте, хадже и посте в Рамадан.","tr":"İslam beş şey üzerine kurulmuştur: Allah'tan başka ilah olmadığına şehadet, namaz, zekât, hac ve Ramazan orucu.","ar":"بُنِيَ الإِسْلاَمُ عَلَى خَمْسٍ"},"src":{"az":"Buxari 8","en":"Bukhari 8","ru":"Бухари 8","tr":"Buhârî 8","ar":"البخاري 8"}},{"id":2,"t":{"az":"İman yetmiş küsur şaxədir. Ən yüksəyi \"La ilaha illallah\", ən aşağısı yoldan əziyyətvericini kənarlaşdırmaqdır.","en":"Faith has over seventy branches. The highest is saying \"La ilaha illallah\" and the lowest is removing harm from the road.","ru":"Вера имеет более семидесяти ветвей. Высшая — произнесение \"Нет бога, кроме Аллаха\", низшая — убрать с дороги что-то вредное.","tr":"İman yetmiş küsur şubedir. En yücesi 'La ilahe illallah' demek, en aşağısı ise yoldan zararlı bir şeyi kaldırmaktır.","ar":"الإِيمَانُ بِضْعٌ وَسَبْعُونَ شُعْبَةً"},"src":{"az":"Muslim 35","en":"Muslim 35","ru":"Муслим 35","tr":"Müslim 35","ar":"مسلم 35"}},{"id":3,"t":{"az":"Heç biriniz özü üçün istədiyini qardaşı üçün istəməyincə (kamilmənalı) mömin ola bilməz.","en":"None of you truly believes until he loves for his brother what he loves for himself.","ru":"Никто из вас по-настоящему не уверует, пока не будет желать своему брату того же, чего желает себе.","tr":"Sizden biriniz, kendisi için istediğini kardeşi için de istemedikçe gerçek anlamda iman etmiş olmaz.","ar":"لاَ يُؤْمِنُ أَحَدُكُمْ حَتَّى يُحِبَّ لأَخِيهِ مَا يُحِبُّ لِنَفْسِهِ"},"src":{"az":"Buxari 13","en":"Bukhari 13","ru":"Бухари 13","tr":"Buhârî 13","ar":"البخاري 13"}},{"id":4,"t":{"az":"İmanı ən kamil olan mömin əxlaqı ən gözəl olanıdır.","en":"The most complete believers in faith are those with the best character.","ru":"Самый совершенный в вере верующий — тот, кто обладает лучшим нравом.","tr":"İmanı en kâmil olan mü'min, ahlakı en güzel olandır.","ar":"أَكْمَلُ المُؤْمِنِينَ إِيمَاناً أَحْسَنُهُمْ خُلُقاً"},"src":{"az":"Tirmizi 1162","en":"Tirmidhi 1162","ru":"Тирмизи 1162","tr":"Tirmizî 1162","ar":"الترمذي 1162"}},{"id":5,"t":{"az":"Kim Allahdan başqa ilah olmadığını bilərək ölsə cənnətə girər.","en":"Whoever dies knowing that there is no god but Allah will enter Paradise.","ru":"Кто умрёт, зная, что нет бога, кроме Аллаха, тот войдёт в рай.","tr":"Allah'tan başka ilah olmadığını bilerek ölen cennete girer.","ar":"مَنْ مَاتَ وَهُوَ يَعْلَمُ أَنَّهُ لاَ إِلَهَ إِلاَّ اللَّهُ دَخَلَ الجَنَّةَ"},"src":{"az":"Muslim 26","en":"Muslim 26","ru":"Муслим 26","tr":"Müslim 26","ar":"مسلم 26"}},{"id":6,"t":{"az":"Din nəsihətdir. Dedik: Kimə? Dedi: Allaha, Kitabına, Peyğəmbərinə, müsəlmanların rəhbərlərinə və ümumi müsəlmanlara.","en":"Religion is sincerity. We asked: To whom? He said: To Allah, His Book, His Messenger, Muslim leaders, and Muslims in general.","ru":"Религия — это искренность. Мы спросили: к кому? Он ответил: к Аллаху, Его Книге, Его Посланнику, предводителям мусульман и мусульманам в целом.","tr":"Din nasihattır. Kime? dedik. Allah'a, Kitabına, Peygamberine, Müslümanların yöneticilerine ve geneline, dedi.","ar":"الدِّينُ النَّصِيحَةُ"},"src":{"az":"Muslim 55","en":"Muslim 55","ru":"Муслим 55","tr":"Müslim 55","ar":"مسلم 55"}},{"id":7,"t":{"az":"Allaha ən sevimli əməl az da olsa davamlı olanıdır.","en":"The most beloved deeds to Allah are those done consistently, even if they are few.","ru":"Самые любимые дела у Аллаха — те, что совершаются постоянно, пусть и немногие.","tr":"Allah'a en sevimli amel, az da olsa devamlı yapılandır.","ar":"أَحَبُّ الأَعْمَالِ إِلَى اللَّهِ أَدْوَمُهَا وَإِنْ قَلَّ"},"src":{"az":"Buxari 6465","en":"Bukhari 6465","ru":"Бухари 6465","tr":"Buhârî 6465","ar":"البخاري 6465"}},{"id":8,"t":{"az":"Əməllər ancaq niyyətlərə görədir. Hər kəs üçün niyyət etdiyi vardır.","en":"Actions are by intentions. Every person will have what they intended.","ru":"Дела оцениваются по намерениям. И каждому достанется то, что он намеревался получить.","tr":"Ameller niyetlere göredir. Herkes niyetine göre karşılık alır.","ar":"إِنَّمَا الأَعْمَالُ بِالنِّيَّاتِ"},"src":{"az":"Buxari 1","en":"Bukhari 1","ru":"Бухари 1","tr":"Buhârî 1","ar":"البخاري 1"}},{"id":9,"t":{"az":"Ən xeyirliniz Quranı öyrənən və öyrədəndir.","en":"The best of you are those who learn the Quran and teach it.","ru":"Лучшие из вас — те, кто учит Коран и обучает ему других.","tr":"En hayırlınız Kur'an'ı öğrenen ve öğretendir.","ar":"خَيْرُكُمْ مَنْ تَعَلَّمَ القُرْآنَ وَعَلَّمَهُ"},"src":{"az":"Buxari 5027","en":"Bukhari 5027","ru":"Бухари 5027","tr":"Buhârî 5027","ar":"البخاري 5027"}},{"id":10,"t":{"az":"Hər bidət zəlalətdir, hər zəlalət isə oddadır.","en":"Every innovation (in religion) is misguidance, and every misguidance is in the Fire.","ru":"Каждое нововведение в религии — заблуждение, а каждое заблуждение ведёт в огонь.","tr":"Her bidat sapıklıktır ve her sapıklık cehennemdedir.","ar":"كُلُّ بِدْعَةٍ ضَلاَلَةٌ"},"src":{"az":"Muslim 867","en":"Muslim 867","ru":"Муслим 867","tr":"Müslim 867","ar":"مسلم 867"}},{"id":11,"t":{"az":"Allah yumşaqdır, yumşaqlığı sevir.","en":"Allah is gentle and loves gentleness.","ru":"Аллах мягок и любит мягкость.","tr":"Allah yumuşaktır ve yumuşaklığı sever.","ar":"إِنَّ اللَّهَ رَفِيقٌ يُحِبُّ الرِّفْقَ"},"src":{"az":"Muslim 2593","en":"Muslim 2593","ru":"Муслим 2593","tr":"Müslim 2593","ar":"مسلم 2593"}},{"id":14,"t":{"az":"Güclü pəhləvan deyil; güclü qəzəb zamanı özünü saxlayan şəxsdir.","en":"The strong person is not the one who can wrestle; the strong person is the one who controls themselves when angry.","ru":"Сильный — не тот, кто побеждает в борьбе; сильный — тот, кто владеет собой в гневе.","tr":"Güçlü olan güreşte galip gelen değil; öfke anında kendine hâkim olan kişidir.","ar":"لَيْسَ الشَّدِيدُ بِالصُّرَعَةِ إِنَّمَا الشَّدِيدُ الَّذِي يَمْلِكُ نَفْسَهُ عِنْدَ الغَضَبِ"},"src":{"az":"Buxari 6114","en":"Bukhari 6114","ru":"Бухари 6114","tr":"Buhârî 6114","ar":"البخاري 6114"}},{"id":16,"t":{"az":"Kim Allaha və axirət gününə inanırsa, ya xeyirli söz desin, ya da sussun.","en":"Whoever believes in Allah and the Last Day should speak good or remain silent.","ru":"Кто верует в Аллаха и в Судный день, пусть говорит хорошее или молчит.","tr":"Allah'a ve ahiret gününe inanan ya hayır söylesin ya da sussun.","ar":"مَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَاليَوْمِ الآخِرِ فَلْيَقُلْ خَيْرًا أَوْ لِيَصْمُتْ"},"src":{"az":"Buxari 6018","en":"Bukhari 6018","ru":"Бухари 6018","tr":"Buhârî 6018","ar":"البخاري 6018"}},{"id":17,"t":{"az":"Müsəlman, müsəlmanların dilindən və əlindən salamat olduğu şəxsdir.","en":"A Muslim is one from whose tongue and hand other Muslims are safe.","ru":"Мусульманин — тот, от языка и руки которого в безопасности другие мусульмане.","tr":"Müslüman, diğer Müslümanların dilinden ve elinden emin olduğu kişidir.","ar":"الْمُسْلِمُ مَنْ سَلِمَ الْمُسْلِمُونَ مِنْ لِسَانِهِ وَيَدِهِ"},"src":{"az":"Buxari 10","en":"Bukhari 10","ru":"Бухари 10","tr":"Buhârî 10","ar":"البخاري 10"}},{"id":18,"t":{"az":"Qiyamət günü mənə ən sevimli və məcliscə ən yaxın olanlarınız əxlaqca ən gözəl olanlarınızdır.","en":"The most beloved of you to me and the closest in seating on the Day of Judgment are those with the best character.","ru":"Самые любимые мне и ближайшие ко мне в день Суда — те из вас, кто обладает лучшим нравом.","tr":"Kıyamet günü bana en sevimli ve en yakın oturanlarınız, ahlakı en güzel olanlarınızdır.","ar":"إِنَّ مِنْ أَحَبِّكُمْ إِلَيَّ وَأَقْرَبِكُمْ مِنِّي مَجْلِساً يَوْمَ الْقِيَامَةِ أَحَاسِنَكُمْ أَخْلاَقاً"},"src":{"az":"Tirmizi 2018","en":"Tirmidhi 2018","ru":"Тирмизи 2018","tr":"Tirmizî 2018","ar":"الترمذي 2018"}},{"id":19,"t":{"az":"Həya ancaq xeyir gətirir.","en":"Modesty brings nothing but good.","ru":"Стыдливость приносит только благо.","tr":"Haya yalnızca hayır getirir.","ar":"الحَيَاءُ لاَ يَأْتِي إِلاَّ بِخَيْرٍ"},"src":{"az":"Buxari 6117","en":"Bukhari 6117","ru":"Бухари 6117","tr":"Buhârî 6117","ar":"البخاري 6117"}},{"id":20,"t":{"az":"Qardaşının üzünə gülümsəmən sədəqədir.","en":"Your smile at your brother is a charity.","ru":"Твоя улыбка брату — это милостыня.","tr":"Kardeşinin yüzüne gülümsemen sadakadır.","ar":"ابْتَسَامَتُكَ فِي وَجْهِ أَخِيكَ صَدَقَةٌ"},"src":{"az":"Tirmizi 1956","en":"Tirmidhi 1956","ru":"Тирмизи 1956","tr":"Tirmizî 1956","ar":"الترمذي 1956"}},{"id":21,"t":{"az":"Namazın ən fəziləti qiraətin uzunluğudur.","en":"The best prayer is that with the longest standing (recitation).","ru":"Лучшая молитва — та, в которой долго стоят (долго читают).","tr":"Namazın en fazileti, kıyamın (kıraatin) uzun olmasıdır.","ar":"أَفْضَلُ الصَّلاَةِ طُولُ الْقُنُوتِ"},"src":{"az":"Muslim 756","en":"Muslim 756","ru":"Муслим 756","tr":"Müslim 756","ar":"مسلم 756"}},{"id":22,"t":{"az":"Qul Rəbbinə ən yaxın olduğu an səcdə halındakı andır.","en":"The servant is closest to his Lord when in prostration.","ru":"Раб ближе всего к своему Господу, когда он совершает земной поклон.","tr":"Kul, Rabbine en yakın olduğu an secdededir.","ar":"أَقْرَبُ مَا يَكُونُ الْعَبْدُ مِنْ رَبِّهِ وَهُوَ سَاجِدٌ"},"src":{"az":"Muslim 482","en":"Muslim 482","ru":"Муслим 482","tr":"Müslim 482","ar":"مسلم 482"}},{"id":23,"t":{"az":"Təmizlik imanın yarısıdır.","en":"Purity is half of faith.","ru":"Чистота — половина веры.","tr":"Temizlik imanın yarısıdır.","ar":"الطَّهُورُ شَطْرُ الإِيمَانِ"},"src":{"az":"Muslim 223","en":"Muslim 223","ru":"Муслим 223","tr":"Müslim 223","ar":"مسلم 223"}},{"id":24,"t":{"az":"Yer üzü mənə məscid və təmizlik vasitəsi edildi.","en":"The earth has been made for me a mosque and a means of purification.","ru":"Земля сделана для меня мечетью и средством очищения.","tr":"Yeryüzü benim için mescit ve temizleyici kılındı.","ar":"جُعِلَتْ لِيَ الأَرْضُ مَسْجِداً وَطَهُوراً"},"src":{"az":"Buxari 335","en":"Bukhari 335","ru":"Бухари 335","tr":"Buhârî 335","ar":"البخاري 335"}},{"id":25,"t":{"az":"Kim dəstəmazı gözəl alarsa, günahları bədənindən çıxar.","en":"Whoever performs ablution well, his sins leave from his body.","ru":"Кто хорошо совершит омовение, тот увидит, как грехи выйдут из его тела.","tr":"Abdesti güzel alan kimsenin günahları bedeninden çıkar.","ar":"مَنْ تَوَضَّأَ فَأَحْسَنَ الوُضُوءَ خَرَجَتْ خَطَايَاهُ مِنْ جَسَدِهِ"},"src":{"az":"Muslim 245","en":"Muslim 245","ru":"Муслим 245","tr":"Müslim 245","ar":"مسلم 245"}},{"id":26,"t":{"az":"Namazı məni necə qıldığımı gördüyünüz kimi qılın.","en":"Pray as you have seen me praying.","ru":"Молитесь так, как вы видели меня молящимся.","tr":"Beni namaz kılarken nasıl gördüyseniz öyle namaz kılın.","ar":"صَلُّوا كَمَا رَأَيْتُمُونِي أُصَلِّي"},"src":{"az":"Buxari 631","en":"Bukhari 631","ru":"Бухари 631","tr":"Buhârî 631","ar":"البخاري 631"}},{"id":27,"t":{"az":"Cəhənnəmdən qorunun, olmasa yarım xurma ilə də olsa.","en":"Guard yourselves against the Fire, even by giving half a date in charity.","ru":"Оберегайтесь огня, пусть даже ценой половины финика.","tr":"Ateşten korunun; yarım hurmayla da olsa.","ar":"اتَّقُوا النَّارَ وَلَوْ بِشِقِّ تَمْرَةٍ"},"src":{"az":"Buxari 1417","en":"Bukhari 1417","ru":"Бухари 1417","tr":"Buhârî 1417","ar":"البخاري 1417"}},{"id":29,"t":{"az":"Kim Ramazan gecəsini iman və savab ümidi ilə ibadətlə keçirsə, keçmiş günahları bağışlanar.","en":"Whoever stands in prayer during Ramadan with faith and expecting reward, his previous sins are forgiven.","ru":"Кто проводит ночи Рамадана в молитве с верой и надеждой на награду, тому прощаются прежние грехи.","tr":"Kim Ramazan gecelerini iman ve sevap umarak ibadet ederek geçirirse, geçmiş günahları bağışlanır.","ar":"مَنْ قَامَ رَمَضَانَ إِيمَاناً وَاحْتِسَاباً غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ"},"src":{"az":"Buxari 37","en":"Bukhari 37","ru":"Бухари 37","tr":"Buhârî 37","ar":"البخاري 37"}},{"id":30,"t":{"az":"Dəstəmazı çətinliyə baxmayaraq tam almaq, məscidlərə çox getmək, namazdan sonra növbəti namazı gözləmək — budur Allah yolunda saf olmaq.","en":"Perfecting ablution despite difficulty, walking often to mosques, and waiting for prayer after prayer — that is guarding the frontier.","ru":"Совершение омовения несмотря на трудности, частое посещение мечетей и ожидание следующей молитвы — вот защита рубежей.","tr":"Güçlüğe rağmen abdesti tam almak, mescitlere çok gitmek ve namazdan sonra namazı beklemek — işte ribat budur.","ar":"أَلاَ أَدُلُّكُمْ عَلَى مَا يَمْحُو اللَّهُ بِهِ الخَطَايَا"},"src":{"az":"Muslim 251","en":"Muslim 251","ru":"Муслим 251","tr":"Müslim 251","ar":"مسلم 251"}},{"id":32,"t":{"az":"Qiyamət günü quldan ilk hesab sorulacaq şey namazdır.","en":"The first thing a servant will be held accountable for on the Day of Judgment is prayer.","ru":"Первое, о чём спросят раба в День Суда, — это молитва.","tr":"Kıyamet günü kuldan ilk hesabı sorulacak şey namazdır.","ar":"أَوَّلُ مَا يُحَاسَبُ بِهِ الْعَبْدُ يَوْمَ الْقِيَامَةِ الصَّلاَةُ"},"src":{"az":"Tirmizi 413","en":"Tirmidhi 413","ru":"Тирмизи 413","tr":"Tirmizî 413","ar":"الترمذي 413"}},{"id":33,"t":{"az":"İnsanla şirk və küfr arasındakı fərq namazı tərk etməkdir.","en":"Between a person and shirk and kufr is the abandonment of prayer.","ru":"Между человеком и многобожием или неверием — оставление молитвы.","tr":"Kişi ile şirk ve küfür arasındaki fark namazı terk etmektir.","ar":"بَيْنَ الرَّجُلِ وَبَيْنَ الشِّرْكِ وَالكُفْرِ تَرْكُ الصَّلاَةِ"},"src":{"az":"Muslim 82","en":"Muslim 82","ru":"Муслим 82","tr":"Müslim 82","ar":"مسلم 82"}},{"id":34,"t":{"az":"Beş vaxt namaz arasındakı günahlar üçün kəffarədir.","en":"The five prayers are expiation for what is between them.","ru":"Пятикратная молитва является искуплением за грехи, совершённые между ними.","tr":"Beş vakit namaz, aralarındaki günahlara keffarettir.","ar":"الصَّلَوَاتُ الخَمْسُ كَفَّارَةٌ لِمَا بَيْنَهُنَّ"},"src":{"az":"Muslim 233","en":"Muslim 233","ru":"Муслим 233","tr":"Müslim 233","ar":"مسلم 233"}},{"id":35,"t":{"az":"Camaatla namaz tək başına namazdan iyirmi yeddi dərəcə üstündür.","en":"Prayer in congregation is superior to individual prayer by twenty-seven degrees.","ru":"Коллективная молитва превосходит одиночную молитву на двадцать семь степеней.","tr":"Cemaatle namaz, tek başına kılınan namazdan yirmi yedi derece üstündür.","ar":"صَلاَةُ الجَمَاعَةِ تَفْضُلُ صَلاَةَ الفَذِّ بِسَبْعٍ وَعِشْرِينَ دَرَجَةً"},"src":{"az":"Buxari 645","en":"Bukhari 645","ru":"Бухари 645","tr":"Buhârî 645","ar":"البخاري 645"}},{"id":36,"t":{"az":"Kim sübh namazını qılsa, o Allahın himayəsindədir.","en":"Whoever prays Fajr is under the protection of Allah.","ru":"Кто совершит утреннюю молитву, тот находится под защитой Аллаха.","tr":"Kim sabah namazını kılarsa, Allah'ın güvencesi altındadır.","ar":"مَنْ صَلَّى الصُّبْحَ فَهُوَ فِي ذِمَّةِ اللَّهِ"},"src":{"az":"Muslim 657","en":"Muslim 657","ru":"Муслим 657","tr":"Müslim 657","ar":"مسلم 657"}},{"id":38,"t":{"az":"Biriniz məscidə girəndə iki rəkət namaz qılmadan oturmasın.","en":"When one of you enters the mosque, do not sit until you have prayed two rak'ahs.","ru":"Когда кто-то из вас входит в мечеть, пусть не садится, пока не совершит два рак'ата молитвы.","tr":"Biriniz mescide girdiğinde iki rekât namaz kılmadan oturmasın.","ar":"إِذَا دَخَلَ أَحَدُكُمُ الْمَسْجِدَ فَلَا يَجْلِسْ حَتَّى يُصَلِّيَ رَكْعَتَيْنِ"},"src":{"az":"Buxari 1163","en":"Bukhari 1163","ru":"Бухари 1163","tr":"Buhârî 1163","ar":"البخاري 1163"}},{"id":39,"t":{"az":"Ayaq üstə namaz qıl; bacarmasan, oturaq; bacarmasan, yan üstə.","en":"Pray standing; if you cannot, then sitting; if you cannot, then on your side.","ru":"Молись стоя; если не можешь, то сидя; если не можешь, то лёжа на боку.","tr":"Ayakta namaz kıl; yapamazsan oturarak; yapamazsan yan üstü.","ar":"صَلِّ قَائِماً فَإِنْ لَمْ تَسْتَطِعْ فَقَاعِداً فَإِنْ لَمْ تَسْتَطِعْ فَعَلَى جَنْبٍ"},"src":{"az":"Buxari 1117","en":"Bukhari 1117","ru":"Бухари 1117","tr":"Buhârî 1117","ar":"البخاري 1117"}},{"id":40,"t":{"az":"Namazda sıranı düz tutun.","en":"Straighten your rows in prayer.","ru":"Выравнивайте ряды в молитве.","tr":"Namazda safları düzeltin.","ar":"أَقِيمُوا الصَّفَّ فِي الصَّلاَةِ"},"src":{"az":"Buxari 717","en":"Bukhari 717","ru":"Бухари 717","tr":"Buhârî 717","ar":"البخاري 717"}},{"id":41,"t":{"az":"Quranı oxuyun; o qiyamət günü oxuyanlara şəfaət edər.","en":"Recite the Quran, for it will come as an intercessor for its companions on the Day of Judgment.","ru":"Читайте Коран, ибо в День Суда он явится заступником для тех, кто его читает.","tr":"Kur'an okuyun; o kıyamet günü onu okuyanlar için şefaatçi olarak gelecektir.","ar":"اقْرَؤُوا الْقُرْآنَ فَإِنَّهُ يَأْتِي يَوْمَ الْقِيَامَةِ شَفِيعاً لأَصْحَابِهِ"},"src":{"az":"Muslim 804","en":"Muslim 804","ru":"Муслим 804","tr":"Müslim 804","ar":"مسلم 804"}},{"id":42,"t":{"az":"Quran ya sənin lehinə, ya da əleyhinə dəlildir.","en":"The Quran is either a proof for you or against you.","ru":"Коран либо довод в твою пользу, либо против тебя.","tr":"Kur'an ya senin lehine ya da aleyhine bir delildir.","ar":"الْقُرْآنُ حُجَّةٌ لَكَ أَوْ عَلَيْكَ"},"src":{"az":"Muslim 223","en":"Muslim 223","ru":"Муслим 223","tr":"Müslim 223","ar":"مسلم 223"}},{"id":43,"t":{"az":"Quranı mahir oxuyan şərəfli yazıçı mələklərlə birgə olar.","en":"The one who is proficient in reciting the Quran will be with the noble, obedient scribes.","ru":"Тот, кто искусно читает Коран, будет вместе с благородными, праведными писцами.","tr":"Kur'an'ı mahirane okuyan, şerefli ve itaatkar yazıcı meleklerle beraberdir.","ar":"الَّذِي يَقْرَأُ الْقُرْآنَ وَهُوَ مَاهِرٌ بِهِ مَعَ السَّفَرَةِ الْكِرَامِ الْبَرَرَةِ"},"src":{"az":"Buxari 4937","en":"Bukhari 4937","ru":"Бухари 4937","tr":"Buhârî 4937","ar":"البخاري 4937"}},{"id":44,"t":{"az":"Kim Allahın kitabından bir hərf oxusa, ona bir savab vardır; bir savab on mislidir.","en":"Whoever recites a letter of the Quran will have one good deed — each good deed is multiplied by ten.","ru":"Кто прочитает хоть одну букву из Книги Аллаха, получит одну добродетель, а каждая добродетель умножается в десять раз.","tr":"Kim Allah'ın Kitabı'ndan bir harf okursa, bir hasene kazanır; her hasene on katıyla karşılık görür.","ar":"مَنْ قَرَأَ حَرْفاً مِنْ كِتَابِ اللَّهِ فَلَهُ بِهِ حَسَنَةٌ"},"src":{"az":"Tirmizi 2910","en":"Tirmidhi 2910","ru":"Тирмизи 2910","tr":"Tirmizî 2910","ar":"الترمذي 2910"}},{"id":45,"t":{"az":"Allah bu kitab vasitəsilə xalqları yüksəldir, başqalarını alçaldır.","en":"Allah elevates peoples by this Book and degrades others by it.","ru":"Аллах возвышает одни народы этой Книгой и унижает с её помощью другие.","tr":"Allah bu kitapla bazı milletleri yükseltir ve diğerlerini alçaltır.","ar":"إِنَّ اللَّهَ يَرْفَعُ بِهَذَا الْكِتَابِ أَقْوَاماً وَيَضَعُ بِهِ آخَرِينَ"},"src":{"az":"Muslim 817","en":"Muslim 817","ru":"Муслим 817","tr":"Müslim 817","ar":"مسلم 817"}},{"id":46,"t":{"az":"Quran əhli Allahın əhli və xüsusi seçilmişləridir.","en":"The people of the Quran are the family of Allah and His special ones.","ru":"Люди Корана — это семья Аллаха и Его избранники.","tr":"Kur'an ehli, Allah'ın ailesi ve özel kullarıdır.","ar":"أَهْلُ الْقُرْآنِ هُمْ أَهْلُ اللَّهِ وَخَاصَّتُهُ"},"src":{"az":"İbn Macə 215","en":"Ibn Majah 215","ru":"Ибн Маджа 215","tr":"İbn Mâce 215","ar":"ابن ماجه 215"}},{"id":47,"t":{"az":"Quranı səslərinizlə bəzəyin.","en":"Beautify the Quran with your voices.","ru":"Украшайте Коран своими голосами.","tr":"Kur'an'ı seslerinizle güzelleştirin.","ar":"زَيِّنُوا الْقُرْآنَ بِأَصْوَاتِكُمْ"},"src":{"az":"Əbu Davud 1468","en":"Abu Dawud 1468","ru":"Абу Дауд 1468","tr":"Ebû Dâvûd 1468","ar":"أبو داود 1468"}},{"id":51,"t":{"az":"Elm öyrənmək hər müsəlmana fərzdür.","en":"Seeking knowledge is an obligation upon every Muslim.","ru":"Получение знаний обязательно для каждого мусульманина.","tr":"İlim öğrenmek her Müslümana farzdır.","ar":"طَلَبُ الْعِلْمِ فَرِيضَةٌ عَلَى كُلِّ مُسْلِمٍ"},"src":{"az":"İbn Macə 224","en":"Ibn Majah 224","ru":"Ибн Маджа 224","tr":"İbn Mâce 224","ar":"ابن ماجه 224"}},{"id":52,"t":{"az":"Kim elm axtararaq bir yol getsə, Allah ona cənnətə aparan yolu asanlaşdırar.","en":"Whoever travels a path seeking knowledge, Allah will make easy for him a path to Paradise.","ru":"Кто идёт путём в поисках знания, тому Аллах облегчит путь в рай.","tr":"Kim ilim arayarak bir yola girerse, Allah ona cennete giden yolu kolaylaştırır.","ar":"مَنْ سَلَكَ طَرِيقاً يَلْتَمِسُ فِيهِ عِلْماً سَهَّلَ اللَّهُ لَهُ طَرِيقاً إِلَى الجَنَّةِ"},"src":{"az":"Muslim 2699","en":"Muslim 2699","ru":"Муслим 2699","tr":"Müslim 2699","ar":"مسلم 2699"}},{"id":53,"t":{"az":"Alimlər peyğəmbərlərin varisləridirlər.","en":"Scholars are the heirs of the prophets.","ru":"Учёные — наследники пророков.","tr":"Âlimler, peygamberlerin mirasçılarıdır.","ar":"الْعُلَمَاءُ وَرَثَةُ الأَنْبِيَاءِ"},"src":{"az":"Əbu Davud 3641","en":"Abu Dawud 3641","ru":"Абу Дауд 3641","tr":"Ebû Dâvûd 3641","ar":"أبو داود 3641"}},{"id":54,"t":{"az":"Alimin abid üzərindəki üstünlüyü ayın digər ulduzlara üstünlüyü kimidir.","en":"The superiority of a scholar over a worshipper is like the moon over the rest of the stars.","ru":"Превосходство учёного над просто поклоняющимся подобно превосходству луны над всеми остальными звёздами.","tr":"Âlimin abid üzerindeki üstünlüğü, ayın diğer yıldızlar üzerindeki üstünlüğü gibidir.","ar":"فَضْلُ الْعَالِمِ عَلَى الْعَابِدِ كَفَضْلِ الْقَمَرِ عَلَى سَائِرِ الْكَوَاكِبِ"},"src":{"az":"Tirmizi 2682","en":"Tirmidhi 2682","ru":"Тирмизи 2682","tr":"Tirmizî 2682","ar":"الترمذي 2682"}},{"id":55,"t":{"az":"Allah kimin xeyirini istəsə, onu dində fəqih edər.","en":"Whoever Allah wishes good for, He grants him understanding of the religion.","ru":"Кому Аллах желает блага, тому дарует понимание религии.","tr":"Allah kimin için hayır dilerse, onu din konusunda anlayışlı kılar.","ar":"مَنْ يُرِدِ اللَّهُ بِهِ خَيْراً يُفَقِّهْهُ فِي الدِّينِ"},"src":{"az":"Buxari 71","en":"Bukhari 71","ru":"Бухари 71","tr":"Buhârî 71","ar":"البخاري 71"}},{"id":56,"t":{"az":"İnsan ölüncə üç şeydən başqa əməli kəsilər: Cari sədəqə, yararlanılan elm, dua edən saleh övlad.","en":"When a person dies, all deeds cease except three: ongoing charity, beneficial knowledge, and a righteous child who prays for them.","ru":"Когда человек умирает, все его дела прекращаются, кроме трёх: непрекращающейся милостыни, полезного знания и праведного сына, молящегося за него.","tr":"İnsan ölünce ameli kesilir; ancak üçü devam eder: Sadaka-ı cariye, faydalanılan ilim ve dua eden salih evlat.","ar":"إِذَا مَاتَ الإِنْسَانُ انْقَطَعَ عَنْهُ عَمَلُهُ إِلاَّ مِنْ ثَلاَثَةٍ"},"src":{"az":"Muslim 1631","en":"Muslim 1631","ru":"Муслим 1631","tr":"Müslim 1631","ar":"مسلم 1631"}},{"id":58,"t":{"az":"Çox vaxt elmi çatdırılan onu bilavasitə dinləyəndən daha çox mənimsəmiş olur.","en":"Perhaps the one to whom knowledge is conveyed retains it better than the one who heard it directly.","ru":"Возможно, тот, кому передали знание, усвоит его лучше, чем тот, кто слышал его непосредственно.","tr":"Nice bilgi aktarılan kişi onu, doğrudan duyan kişiden daha iyi anlayıp yaşatır.","ar":"رُبَّ مُبَلَّغٍ أَوْعَى مِنْ سَامِعٍ"},"src":{"az":"Buxari 67","en":"Bukhari 67","ru":"Бухари 67","tr":"Buhârî 67","ar":"البخاري 67"}},{"id":59,"t":{"az":"Qibtə (həsəd) yalnız iki şeydə olar: Allah mal verdiyi, onu haqqın yolunda xərcləyən; Allah hikmət verdiyi, onunla qərar verən.","en":"There is no envy except in two cases: a man given wealth who spends it righteously, and a man given wisdom who judges by it.","ru":"Зависть допустима лишь в двух случаях: человек, которому Аллах дал богатство и он тратит его на правое дело; человек, которому дана мудрость и он судит по ней.","tr":"İki kişiye gıpta edilebilir: Allah'ın mal verdiği, onu hak yolunda harcayan; Allah'ın hikmet verdiği, bununla hükmedip öğreten.","ar":"لاَ حَسَدَ إِلاَّ فِي اثْنَتَيْنِ"},"src":{"az":"Buxari 73","en":"Bukhari 73","ru":"Бухари 73","tr":"Buhârî 73","ar":"البخاري 73"}},{"id":61,"t":{"az":"Oruc qalxandır.","en":"Fasting is a shield.","ru":"Пост — щит.","tr":"Oruç bir kalkandır.","ar":"الصِّيَامُ جُنَّةٌ"},"src":{"az":"Buxari 1894","en":"Bukhari 1894","ru":"Бухари 1894","tr":"Buhârî 1894","ar":"البخاري 1894"}},{"id":62,"t":{"az":"Kim Ramazanı iman və savab ümidi ilə tutarsa, keçmiş günahları bağışlanar.","en":"Whoever fasts Ramadan with faith and expecting reward, his previous sins are forgiven.","ru":"Кто постится в Рамадан с верой и в надежде на награду, тому прощаются прежние грехи.","tr":"Kim iman ederek ve sevabını umarak Ramazan orucunu tutarsa, geçmiş günahları bağışlanır.","ar":"مَنْ صَامَ رَمَضَانَ إِيمَاناً وَاحْتِسَاباً غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ"},"src":{"az":"Buxari 38","en":"Bukhari 38","ru":"Бухари 38","tr":"Buhârî 38","ar":"البخاري 38"}},{"id":63,"t":{"az":"Oruclu kəs üçün iki sevinc var: İftar vaxtındakı sevinc və Rəbbiylə görüşdəki sevinc.","en":"The fasting person has two joys: when breaking fast and when meeting his Lord.","ru":"У постящегося два радости: когда разговляется и когда встречает своего Господа.","tr":"Oruçlu için iki sevinç vardır: iftarda ve Rabbine kavuştuğunda.","ar":"لِلصَّائِمِ فَرْحَتَانِ فَرْحَةٌ حِينَ يُفْطِرُ وَفَرْحَةٌ حِينَ يَلْقَى رَبَّهُ"},"src":{"az":"Buxari 1904","en":"Bukhari 1904","ru":"Бухари 1904","tr":"Buhârî 1904","ar":"البخاري 1904"}},{"id":64,"t":{"az":"Ramazan girəndə cənnətin qapıları açılar, cəhənnəmin qapıları bağlanar, şeytanlar zəncirlənər.","en":"When Ramadan enters, the gates of Paradise are opened, the gates of Hell are closed, and the devils are chained.","ru":"Когда наступает Рамадан, открываются врата рая, закрываются врата ада, и дьяволы заключаются в цепи.","tr":"Ramazan girince cennetin kapıları açılır, cehennemin kapıları kapanır ve şeytanlar zincire vurulur.","ar":"إِذَا دَخَلَ رَمَضَانُ فُتِّحَتْ أَبْوَابُ الْجَنَّةِ وَغُلِّقَتْ أَبْوَابُ النَّارِ"},"src":{"az":"Buxari 1899","en":"Bukhari 1899","ru":"Бухари 1899","tr":"Buhârî 1899","ar":"البخاري 1899"}},{"id":65,"t":{"az":"Kim yalan sözü və onunla əməl etməyi tərk etməzsə, onun yemə-içməsini tərk etməsinin Allah üçün heç bir dəyəri yoxdur.","en":"Whoever does not give up lying and acting upon it, Allah has no need of him giving up food and drink.","ru":"Кто не откажется от лжи и действий на её основе, Аллаху не нужно, чтобы тот отказывался от еды и питья.","tr":"Kim yalan söylemeyi ve onunla amel etmeyi terk etmezse, Allah'ın onun yemesini içmesini terk etmesiyle işi yoktur.","ar":"مَنْ لَمْ يَدَعْ قَوْلَ الزُّورِ وَالْعَمَلَ بِهِ فَلَيْسَ لِلَّهِ حَاجَةٌ فِي أَنْ يَدَعَ طَعَامَهُ وَشَرَابَهُ"},"src":{"az":"Buxari 1903","en":"Bukhari 1903","ru":"Бухари 1903","tr":"Buhârî 1903","ar":"البخاري 1903"}},{"id":67,"t":{"az":"Səhər yeyin; çünki səhər yeməyində bərəkət var.","en":"Eat the pre-dawn meal, for there is blessing in it.","ru":"Кушайте на рассвете, ибо в предрассветной трапезе — благодать.","tr":"Sahur yiyin, çünkü sahurda bereket vardır.","ar":"تَسَحَّرُوا فَإِنَّ فِي السَّحُورِ بَرَكَةً"},"src":{"az":"Buxari 1923","en":"Bukhari 1923","ru":"Бухари 1923","tr":"Buhârî 1923","ar":"البخاري 1923"}},{"id":69,"t":{"az":"Kim orucluya iftar verdirərsə, oruclu kimin savabı qədər savab alar, orucludan heç nə azalmaz.","en":"Whoever feeds a fasting person will have a reward equal to his without diminishing the fasting person's reward.","ru":"Кто накормит постящегося на ифтаре, получит такую же награду, не уменьшив ничего из награды постящегося.","tr":"Oruçluya iftar ettiren, oruçlunun sevabının aynısını alır; oruçlunun sevabından da bir şey eksilmez.","ar":"مَنْ فَطَّرَ صَائِماً كَانَ لَهُ مِثْلُ أَجْرِهِ"},"src":{"az":"Tirmizi 807","en":"Tirmidhi 807","ru":"Тирмизи 807","tr":"Tirmizî 807","ar":"الترمذي 807"}},{"id":70,"t":{"az":"Səbr ayının (Ramazanın) orucu və hər aydan üç gün oruc tutmaq — ömür boyu oruc tutmaq kimidir.","en":"Fasting the month of patience (Ramadan) and three days of every month is like fasting forever.","ru":"Пост месяца терпения (Рамадана) и три дня каждого месяца — как пост вечности.","tr":"Sabır ayı (Ramazan) orucu ve her aydan üç gün oruç tutmak, ömür boyu oruç tutmak gibidir.","ar":"صَوْمُ شَهْرِ الصَّبْرِ وَثَلاَثَةِ أَيَّامٍ مِنْ كُلِّ شَهْرٍ صَوْمُ الدَّهْرِ"},"src":{"az":"Muslim 1162","en":"Muslim 1162","ru":"Муслим 1162","tr":"Müslim 1162","ar":"مسلم 1162"}},{"id":71,"t":{"az":"Qızıl-gümüş sahibi onların haqqını (zəkatını) verməzsə, qiyamət günü onlardan od lövhələri düzəldilər.","en":"No owner of gold or silver who does not pay its due will fail to have plates of fire made from it on the Day of Judgment.","ru":"Нет у владельца золота или серебра, не уплатившего их долг (закят), что в День Суда из них не были бы сделаны огненные пластины.","tr":"Altın ve gümüş sahibi olup da hakkını (zekâtını) vermeyene, kıyamet günü bunlardan ateş levhalar hazırlanır.","ar":"مَا مِنْ صَاحِبِ ذَهَبٍ وَلاَ فِضَّةٍ لاَ يُؤَدِّي مِنْهَا حَقَّهَا إِلاَّ كَانَ يَوْمَ الْقِيَامَةِ صُفِّحَتْ لَهُ صَفَائِحُ مِنْ نَارٍ"},"src":{"az":"Muslim 987","en":"Muslim 987","ru":"Муслим 987","tr":"Müslim 987","ar":"مسلم 987"}},{"id":72,"t":{"az":"Sədəqə malı azaltmaz.","en":"Charity does not decrease wealth.","ru":"Садака не уменьшает имущество.","tr":"Sadaka malı eksiltmez.","ar":"الصَّدَقَةُ لاَ تَنْقُصُ مَالاً"},"src":{"az":"Muslim 2588","en":"Muslim 2588","ru":"Муслим 2588","tr":"Müslim 2588","ar":"مسلم 2588"}},{"id":74,"t":{"az":"Sədəqənin ən fəziləti sağlam, kasıblıqdan qorxan halında verməkdir.","en":"The best charity is that given while you are healthy and fearful of poverty.","ru":"Лучшая садака — когда ты здоров и боишься бедности.","tr":"Sadakanın en faziletlisi, sağlıklıyken ve yoksulluktan korktuğun hâlde vermendir.","ar":"أَفْضَلُ الصَّدَقَةِ أَنْ تُعْطِيَ وَأَنْتَ صَحِيحٌ شَحِيحٌ"},"src":{"az":"Buxari 1419","en":"Bukhari 1419","ru":"Бухари 1419","tr":"Buhârî 1419","ar":"البخاري 1419"}},{"id":75,"t":{"az":"Allahın əli cəmaatla birgədir.","en":"The hand of Allah is with the group.","ru":"Рука Аллаха вместе с джамаатом.","tr":"Allah'ın eli cemaatle beraberdir.","ar":"يَدُ اللَّهِ مَعَ الْجَمَاعَةِ"},"src":{"az":"Tirmizi 2166","en":"Tirmidhi 2166","ru":"Тирмизи 2166","tr":"Tirmizî 2166","ar":"الترمذي 2166"}},{"id":76,"t":{"az":"Hər yaxşılıq sədəqədir.","en":"Every act of kindness is charity.","ru":"Каждое доброе дело — садака.","tr":"Her iyilik sadakadır.","ar":"كُلُّ مَعْرُوفٍ صَدَقَةٌ"},"src":{"az":"Buxari 6021","en":"Bukhari 6021","ru":"Бухари 6021","tr":"Buhârî 6021","ar":"البخاري 6021"}},{"id":77,"t":{"az":"Biriniz yarım xurma ilə olsa belə atəşdən sığınan tapsa, bunu etsin.","en":"Whoever among you can protect himself from the Fire even with half a date, let him do so.","ru":"Кто из вас может защититься от огня хотя бы полфиником, пусть сделает это.","tr":"Biriniz yarım hurmayla bile olsa ateşten sığınak bulabiliyorsa bunu yapsın.","ar":"مَنْ اسْتَطَاعَ مِنْكُمْ أَنْ يَسْتَتِرَ مِنَ النَّارِ وَلَوْ بِشَقِّ تَمْرَةٍ فَلْيَفْعَلْ"},"src":{"az":"Buxari 1417","en":"Bukhari 1417","ru":"Бухари 1417","tr":"Buhârî 1417","ar":"البخاري 1417"}},{"id":78,"t":{"az":"Mömin mömin üçün bir bina kimidir; bir-birini möhkəmləndirir.","en":"A believer to another believer is like a building — each part strengthens the other.","ru":"Верующий для другого верующего подобен зданию — они укрепляют друг друга.","tr":"Mü'min, mü'min için bir bina gibidir; birbirini sağlamlaştırır.","ar":"الْمُؤْمِنُ لِلْمُؤْمِنِ كَالْبُنْيَانِ يَشُدُّ بَعْضُهُ بَعْضاً"},"src":{"az":"Buxari 481","en":"Bukhari 481","ru":"Бухари 481","tr":"Buhârî 481","ar":"البخاري 481"}},{"id":82,"t":{"az":"\"Subhanallahi wa bihamdih, Subhanallahil azim\" — dilə yüngül, mizana ağır, Rəhmana sevimli iki kəlmə.","en":"\"Glory be to Allah and His praise, glory be to Allah the Magnificent\" — two words, light on the tongue, heavy in the scales, beloved to the Most Merciful.","ru":"\"Пречист Аллах и хвала Ему, пречист Аллах Великий\" — два слова, лёгких на языке, тяжёлых на весах, любимых Всемилостивым.","tr":"\"Sübhanallahi ve bihamdih, sübhanallahil azim\" — dile hafif, mizanda ağır, Rahman'a sevimli iki kelime.","ar":"سُبْحَانَ اللَّهِ وَبِحَمْدِهِ سُبْحَانَ اللَّهِ الْعَظِيمِ"},"src":{"az":"Buxari 6682","en":"Bukhari 6682","ru":"Бухари 6682","tr":"Buhârî 6682","ar":"البخاري 6682"}},{"id":83,"t":{"az":"Allah zikri ən xeyirli, ən pak əməldir; qızıl-gümüş infaq etməkdən, düşməni qılıncla vurmaqdan üstündür.","en":"Shall I not tell you of the best of your deeds, the purest before your King — greater than giving gold and silver and meeting the enemy with swords?","ru":"Не указать ли вам на лучшее из ваших дел, наичистейшее перед вашим Царём, превышающее раздачу золота и серебра и встречу с врагом с мечами?","tr":"Size amellerinizin en hayırlısını, Rabbiniz katında en temizini haber vereyim mi? Altın ve gümüş infakından, düşmanla kılıçla karşılaşmaktan üstün olan Allah zikridir.","ar":"أَلاَ أُنَبِّئُكُمْ بِخَيْرِ أَعْمَالِكُمْ وَأَزْكَاهَا عِنْدَ مَلِيكِكُمْ"},"src":{"az":"İbn Macə 3790","en":"Ibn Majah 3790","ru":"Ибн Маджа 3790","tr":"İbn Mâce 3790","ar":"ابن ماجه 3790"}},{"id":84,"t":{"az":"Kim hər namazdan sonra Ayətəl-Kürsü oxusa, onu cənnətə girməkdən yalnız ölüm alıkoyar.","en":"Whoever recites Ayat al-Kursi after every prayer — nothing prevents him from entering Paradise except death.","ru":"Кто читает Аят аль-Курси после каждой молитвы, тому ничто не помешает войти в рай, кроме смерти.","tr":"Her namazın arkasından Ayetü'l-Kürsi okuyanı cennetten ancak ölüm alıkoyar.","ar":"مَنْ قَرَأَ آيَةَ الْكُرْسِيِّ دُبُرَ كُلِّ صَلاَةٍ لَمْ يَمْنَعْهُ مِنْ دُخُولِ الْجَنَّةِ إِلاَّ أَنْ يَمُوتَ"},"src":{"az":"Nəsai, Sünənül-Kübra 9928","en":"An-Nasa'i, as-Sunan al-Kubra 9928","ru":"ан-Насаи, ас-Сунан аль-Кубра 9928","tr":"Nesâî, es-Sünenü'l-Kübrâ 9928","ar":"النسائي، السنن الكبرى 9928"}},{"id":85,"t":{"az":"Kim gündə yüz dəfə \"Subhanallahi wa bihamdih\" desə, günahları silinər.","en":"Whoever says \"Glory be to Allah and His praise\" one hundred times a day, his sins will be wiped away.","ru":"Кто скажет \"Пречист Аллах и хвала Ему\" сто раз в день, с того сотрутся грехи.","tr":"Kim günde yüz kere \"Sübhanallahi ve bihamdih\" derse, günahları silinir.","ar":"مَنْ قَالَ سُبْحَانَ اللَّهِ وَبِحَمْدِهِ فِي يَوْمٍ مِائَةَ مَرَّةٍ حُطَّتْ خَطَايَاهُ"},"src":{"az":"Buxari 6405","en":"Bukhari 6405","ru":"Бухари 6405","tr":"Buhârî 6405","ar":"البخاري 6405"}},{"id":86,"t":{"az":"Kim \"La ilaha illallah vahdahu la sharika lah\" deyərsə, on qul azad etmiş kimi savab olar.","en":"Whoever says \"There is no god but Allah alone, with no partner\" will have the equivalent reward of freeing ten slaves.","ru":"Кто скажет \"Нет бога, кроме Аллаха, единого, без сотоварища\", тому воздастся, как за освобождение десяти рабов.","tr":"\"La ilahe illallah vahdahu la şerike leh\" diyen, on köle azat etmiş gibi sevap kazanır.","ar":"مَنْ قَالَ لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ كَانَ لَهُ عَدْلُ عَشْرِ رِقَابٍ"},"src":{"az":"Buxari 6404","en":"Bukhari 6404","ru":"Бухари 6404","tr":"Buhârî 6404","ar":"البخاري 6404"}},{"id":88,"t":{"az":"Rəbbini zikr edən ilə etməyən dirinin ölüyə bənzədiyi kimidir.","en":"The one who remembers his Lord and the one who does not are like the living and the dead.","ru":"Поминающий своего Господа и не поминающий подобны живому и мёртвому.","tr":"Rabbini zikreden ile zikretmeyen, diri ile ölü gibidir.","ar":"مَثَلُ الَّذِي يَذْكُرُ رَبَّهُ وَالَّذِي لاَ يَذْكُرُهُ مَثَلُ الْحَيِّ وَالْمَيِّتِ"},"src":{"az":"Buxari 6407","en":"Bukhari 6407","ru":"Бухари 6407","tr":"Buhârî 6407","ar":"البخاري 6407"}},{"id":91,"t":{"az":"Sədəqə günahı söndürər, suyun odu söndürdüyü kimi.","en":"Charity extinguishes sin as water extinguishes fire.","ru":"Садака тушит грех, как вода тушит огонь.","tr":"Sadaka, suyun ateşi söndürdüğü gibi günahı söndürür.","ar":"الصَّدَقَةُ تُطْفِئُ الْخَطِيئَةَ كَمَا يُطْفِئُ الْمَاءُ النَّارَ"},"src":{"az":"Tirmizi 614","en":"Tirmidhi 614","ru":"Тирмизи 614","tr":"Tirmizî 614","ar":"الترمذي 614"}},{"id":93,"t":{"az":"Dul qadın və yoxsula yardım edən Allah yolunda cihadçı kimidir.","en":"One who works to support a widow and the poor is like a mujahid in the path of Allah.","ru":"Тот, кто трудится ради вдовы и бедняка, подобен муджахиду на пути Аллаха.","tr":"Dul kadın ve yoksul için koşturan, Allah yolunda mücahit gibidir.","ar":"السَّاعِي عَلَى الأَرْمَلَةِ وَالْمِسْكِينِ كَالْمُجَاهِدِ فِي سَبِيلِ اللَّهِ"},"src":{"az":"Buxari 6006","en":"Bukhari 6006","ru":"Бухари 6006","tr":"Buhârî 6006","ar":"البخاري 6006"}},{"id":95,"t":{"az":"Kim mömin birisinin dünya sıxıntısını gidərsə, Allah onun qiyamət sıxıntısını gidərər.","en":"Whoever relieves a believer of worldly distress, Allah will relieve him of distress on the Day of Judgment.","ru":"Кто облегчит верующему его мирскую тяготу, тому Аллах облегчит тяготу в День Суда.","tr":"Kim bir mü'minin dünya sıkıntısını giderirse, Allah da onun kıyamet sıkıntısını giderir.","ar":"مَنْ نَفَّسَ عَنْ مُؤْمِنٍ كُرْبَةً مِنْ كُرَبِ الدُّنْيَا نَفَّسَ اللَّهُ عَنْهُ كُرْبَةً مِنْ كُرَبِ يَوْمِ الْقِيَامَةِ"},"src":{"az":"Muslim 2699","en":"Muslim 2699","ru":"Муслим 2699","tr":"Müslim 2699","ar":"مسلم 2699"}},{"id":96,"t":{"az":"İnsanın hər oynağı üzərinə hər gün sədəqə vacibdir.","en":"Every joint of a person must give charity every day the sun rises.","ru":"Каждый сустав человека обязан каждый день совершать садака.","tr":"Her gün güneş doğduğunda insanın her eklemi için sadaka gerekir.","ar":"كُلُّ سُلاَمَى مِنَ النَّاسِ عَلَيْهِ صَدَقَةٌ كُلَّ يَوْمٍ"},"src":{"az":"Buxari 2989","en":"Bukhari 2989","ru":"Бухари 2989","tr":"Buhârî 2989","ar":"البخاري 2989"}},{"id":97,"t":{"az":"Sədəqənin ən xeyirlisi ehtiyacsızlıq üzərindən veriləndir.","en":"The best charity is that which comes from sufficiency.","ru":"Лучшая садака та, что исходит из достатка.","tr":"Sadakanın en hayırlısı, ihtiyaç fazlasından verilendir.","ar":"خَيْرُ الصَّدَقَةِ مَا كَانَ عَنْ ظَهْرِ غِنًى"},"src":{"az":"Buxari 1426","en":"Bukhari 1426","ru":"Бухари 1426","tr":"Buhârî 1426","ar":"البخاري 1426"}},{"id":98,"t":{"az":"Allah rızası üçün xərclədiyindən, hətta həyat yoldaşının ağzına qoyduğun tikəyə qədər savab alırsan.","en":"Every expense you make seeking the face of Allah will be rewarded, even the morsel you put in your wife's mouth.","ru":"Любое пожертвование ради лика Аллаха вознаградится, даже кусочек, который ты кладёшь в рот своей жене.","tr":"Allah rızasını gözeterek yaptığın her harcama için sevap kazanırsın; hatta eşinin ağzına koyduğun lokma için bile.","ar":"إِنَّكَ لَنْ تُنْفِقَ نَفَقَةً تَبْتَغِي بِهَا وَجْهَ اللَّهِ إِلاَّ أُجِرْتَ عَلَيْهَا"},"src":{"az":"Buxari 56","en":"Bukhari 56","ru":"Бухари 56","tr":"Buhârî 56","ar":"البخاري 56"}},{"id":99,"t":{"az":"Özündən başla, özünə sədəqə ver.","en":"Start with yourself and give charity to yourself first.","ru":"Начни с себя — дай садака самому себе.","tr":"Kendinden başla; önce kendine sadaka ver.","ar":"ابْدَأْ بِنَفْسِكَ فَتَصَدَّقْ عَلَيْهَا"},"src":{"az":"Muslim 1042","en":"Muslim 1042","ru":"Муслим 1042","tr":"Müslim 1042","ar":"مسلم 1042"}},{"id":100,"t":{"az":"Verən əl alan əldən xeyirlidir.","en":"The upper hand (giving) is better than the lower hand (taking).","ru":"Рука дающего лучше руки берущего.","tr":"Üstteki el (veren), alttaki elden (alan) daha hayırlıdır.","ar":"الْيَدُ الْعُلْيَا خَيْرٌ مِنَ الْيَدِ السُّفْلَى"},"src":{"az":"Buxari 1427","en":"Bukhari 1427","ru":"Бухари 1427","tr":"Buhârî 1427","ar":"البخاري 1427"}},{"id":101,"t":{"az":"Heç kimə səbrdən xeyirli və geniş bir əta verilməmişdir.","en":"No one has been given a gift better or more generous than patience.","ru":"Никому не дано дара лучше и обширнее, чем терпение.","tr":"Hiç kimseye sabırdan daha hayırlı ve geniş bir bağış verilmemiştir.","ar":"مَا أُعْطِيَ أَحَدٌ عَطَاءً خَيْراً وَأَوْسَعَ مِنَ الصَّبْرِ"},"src":{"az":"Buxari 1469","en":"Bukhari 1469","ru":"Бухари 1469","tr":"Buhârî 1469","ar":"البخاري 1469"}},{"id":102,"t":{"az":"Möminin işi nə qədər gözəldir! Hər işi onun üçün xeyirdir.","en":"Wondrous is the affair of a believer — all of it is good for him.","ru":"Удивительно дело верующего — всё в нём благо для него.","tr":"Mü'minin işi ne güzeldir! Her işi onun için hayırdır.","ar":"عَجَباً لأَمْرِ الْمُؤْمِنِ إِنَّ أَمْرَهُ كُلَّهُ خَيْرٌ"},"src":{"az":"Muslim 2999","en":"Muslim 2999","ru":"Муслим 2999","tr":"Müslim 2999","ar":"مسلم 2999"}},{"id":103,"t":{"az":"Müsəlmana üzüntü, xəstəlik, qəm, kədər nə gəlirsə, Allah onunla günahlarını silər.","en":"No fatigue, illness, worry, or grief afflicts a Muslim except that Allah expiates sins through it.","ru":"Ни усталость, ни болезнь, ни тревога, ни печаль не постигает мусульманина, не искупив тем самым его грехи.","tr":"Müslümana isabet eden yorgunluk, hastalık, tasa ve keder hepsinde Allah günahlarını siler.","ar":"مَا يُصِيبُ الْمُسْلِمَ مِنْ نَصَبٍ وَلاَ وَصَبٍ وَلاَ هَمٍّ وَلاَ حَزَنٍ إِلاَّ كَفَّرَ اللَّهُ"},"src":{"az":"Buxari 5641","en":"Bukhari 5641","ru":"Бухари 5641","tr":"Buhârî 5641","ar":"البخاري 5641"}},{"id":104,"t":{"az":"Mükafatın böyüklüyü bəlanın böyüklüyü ilədir.","en":"The greatness of the reward is commensurate with the greatness of the trial.","ru":"Величие награды соответствует величию испытания.","tr":"Mükâfatın büyüklüğü, belânın büyüklüğüne göredir.","ar":"إِنَّ عِظَمَ الجَزَاءِ مَعَ عِظَمِ الْبَلاَءِ"},"src":{"az":"Tirmizi 2396","en":"Tirmidhi 2396","ru":"Тирмизи 2396","tr":"Tirmizî 2396","ar":"الترمذي 2396"}},{"id":105,"t":{"az":"Səbr işıqdır.","en":"Patience is light.","ru":"Терпение — свет.","tr":"Sabır nurdur.","ar":"الصَّبْرُ ضِيَاءٌ"},"src":{"az":"Muslim 223","en":"Muslim 223","ru":"Муслим 223","tr":"Müslim 223","ar":"مسلم 223"}},{"id":106,"t":{"az":"Kim səbr etməyə çalışsa, Allah ona səbr verər.","en":"Whoever tries to be patient, Allah will grant him patience.","ru":"Кто старается быть терпеливым, тому Аллах дарует терпение.","tr":"Kim sabretmeye çalışırsa, Allah ona sabır verir.","ar":"مَنْ يَتَصَبَّرْ يُصَبِّرْهُ اللَّهُ"},"src":{"az":"Buxari 1469","en":"Bukhari 1469","ru":"Бухари 1469","tr":"Buhârî 1469","ar":"البخاري 1469"}},{"id":108,"t":{"az":"Başınıza gələn bəla üzündən ölümü arzulamayın.","en":"Do not wish for death because of some harm that has befallen you.","ru":"Не желайте смерти из-за постигшей вас беды.","tr":"Başınıza gelen bir sıkıntı sebebiyle ölümü arzulamayın.","ar":"لاَ تَتَمَنَّوُا الْمَوْتَ لِضُرٍّ نَزَلَ بِكُمْ"},"src":{"az":"Buxari 5671","en":"Bukhari 5671","ru":"Бухари 5671","tr":"Buhârî 5671","ar":"البخاري 5671"}},{"id":109,"t":{"az":"Güclü mömin zəif mömindən Allah yanında daha xeyirli və sevimlidir.","en":"A strong believer is better and more beloved to Allah than a weak believer.","ru":"Сильный верующий лучше и любимее Аллахом, чем слабый верующий.","tr":"Güçlü mü'min, zayıf mü'minden Allah'a daha hayırlı ve sevimlidir.","ar":"الْمُؤْمِنُ الْقَوِيُّ خَيْرٌ وَأَحَبُّ إِلَى اللَّهِ مِنَ الْمُؤْمِنِ الضَّعِيفِ"},"src":{"az":"Muslim 2664","en":"Muslim 2664","ru":"Муслим 2664","tr":"Müslim 2664","ar":"مسلم 2664"}},{"id":110,"t":{"az":"Bil ki, kömək səbrlə birgədir.","en":"Know that victory comes with patience.","ru":"Знай, что победа приходит вместе с терпением.","tr":"Bil ki, zafer sabırla beraberdir.","ar":"وَاعْلَمْ أَنَّ النَّصْرَ مَعَ الصَّبْرِ"},"src":{"az":"Əhməd 2803","en":"Ahmad 2803","ru":"Ахмад 2803","tr":"Ahmed 2803","ar":"أحمد 2803"}},{"id":111,"t":{"az":"Dünyada qərib ya yolçu kimi ol.","en":"Be in the world as if you are a stranger or a wayfarer.","ru":"Будь в этом мире, как чужестранец или путник.","tr":"Dünyada sanki yabancı ya da yolcu gibi ol.","ar":"كُنْ فِي الدُّنْيَا كَأَنَّكَ غَرِيبٌ أَوْ عَابِرُ سَبِيلٍ"},"src":{"az":"Buxari 6416","en":"Bukhari 6416","ru":"Бухари 6416","tr":"Buhârî 6416","ar":"البخاري 6416"}},{"id":112,"t":{"az":"Dünya möminin zindanı, kafirin cənnətidir.","en":"The world is a prison for the believer and Paradise for the disbeliever.","ru":"Мир — тюрьма для верующего и рай для неверующего.","tr":"Dünya mü'minin hapishanesi, kâfirin cennetidir.","ar":"الدُّنْيَا سِجْنُ الْمُؤْمِنِ وَجَنَّةُ الْكَافِرِ"},"src":{"az":"Muslim 2956","en":"Muslim 2956","ru":"Муслим 2956","tr":"Müslim 2956","ar":"مسلم 2956"}},{"id":113,"t":{"az":"Dünyanın axirətdəki dəyəri birinizin barmağını dənizə batırdıqda geri götürdüyü kimi.","en":"The world compared to the hereafter is like one of you putting his finger in the sea — see how much it returns.","ru":"Мир по сравнению с вечной жизнью — как если бы один из вас опустил палец в море: смотри, сколько воды он принесёт.","tr":"Dünyanın ahiret karşısındaki değeri, birinizin parmağını denize daldırdığında geri dönen su kadardır.","ar":"مَا الدُّنْيَا فِي الآخِرَةِ إِلاَّ كَمَا يَجْعَلُ أَحَدُكُمْ إِصْبَعَهُ فِي الْيَمِّ"},"src":{"az":"Muslim 2858","en":"Muslim 2858","ru":"Муслим 2858","tr":"Müslim 2858","ar":"مسلم 2858"}},{"id":115,"t":{"az":"Əgər dünya Allahın yanında bir ağcaqanad qanadı qədər dəyər olsaydı, kafirə ondan bir içim su içirtməzdi.","en":"If the world was worth a mosquito's wing in Allah's sight, He would not give a disbeliever a sip of water from it.","ru":"Если бы мир стоил у Аллаха хоть крыло комара, Он не дал бы неверному из него и глотка воды.","tr":"Dünya Allah katında bir sivrisinek kanadı kadar değer olsaydı, kâfire ondan bir yudum su içirmezdi.","ar":"لَوْ كَانَتِ الدُّنْيَا تَعْدِلُ عِنْدَ اللَّهِ جَنَاحَ بَعُوضَةٍ مَا سَقَى كَافِراً مِنْهَا شَرْبَةَ مَاءٍ"},"src":{"az":"Tirmizi 2320","en":"Tirmidhi 2320","ru":"Тирмизи 2320","tr":"Tirmizî 2320","ar":"الترمذي 2320"}},{"id":117,"t":{"az":"Dünya bir matahdır; ən xeyirli matah isə saleh arvaddır.","en":"The world is but a provision and the best provision is a righteous wife.","ru":"Мир — это лишь имущество, и лучшее из него — праведная жена.","tr":"Dünya bir geçimliktir; en hayırlısı ise saliha bir hanımdır.","ar":"الدُّنْيَا مَتَاعٌ وَخَيْرُ مَتَاعِهَا الْمَرْأَةُ الصَّالِحَةُ"},"src":{"az":"Muslim 1467","en":"Muslim 1467","ru":"Муслим 1467","tr":"Müslim 1467","ar":"مسلم 1467"}},{"id":119,"t":{"az":"Sənə faydalı olana hərs ol, Allahdan kömək dilə.","en":"Be eager for what benefits you and seek help from Allah.","ru":"Стремись к тому, что тебе полезно, и проси помощи у Аллаха.","tr":"Sana faydalı olana hırslı ol ve Allah'tan yardım dile.","ar":"احْرِصْ عَلَى مَا يَنْفَعُكَ وَاسْتَعِنْ بِاللَّهِ"},"src":{"az":"Muslim 2664","en":"Muslim 2664","ru":"Муслим 2664","tr":"Müslim 2664","ar":"مسلم 2664"}},{"id":120,"t":{"az":"Zənginlik mal çoxluğundan deyil; zənginlik qəlb zənginliyidir.","en":"Richness is not from abundance of wealth, but richness is richness of the soul.","ru":"Богатство — не от обилия имущества, а богатство — это богатство духа.","tr":"Zenginlik mal çokluğu değil; asıl zenginlik, gönül zenginliğidir.","ar":"لَيْسَ الغِنَى عَنْ كَثْرَةِ الْعَرَضِ وَلَكِنَّ الغِنَى غِنَى النَّفْسِ"},"src":{"az":"Buxari 6446","en":"Bukhari 6446","ru":"Бухари 6446","tr":"Buhârî 6446","ar":"البخاري 6446"}},{"id":121,"t":{"az":"Quran sahibinə deyiləcək: \"Oxu, yüksəl.\"","en":"It will be said to the companion of the Quran: \"Recite and ascend.\"","ru":"Обладателю Корана скажут: \"Читай и поднимайся.\"","tr":"Kur'an ehline \"Oku ve yüksel\" denilecek.","ar":"يُقَالُ لِصَاحِبِ الْقُرْآنِ اقْرَأْ وَارْتَقِ"},"src":{"az":"Tirmizi 2914","en":"Tirmidhi 2914","ru":"Тирмизи 2914","tr":"Tirmizî 2914","ar":"الترمذي 2914"}},{"id":122,"t":{"az":"Kim hesaba çəkilsə, əzab görər.","en":"Whoever is called to account will be punished.","ru":"Кого призовут к ответу, тот будет наказан.","tr":"Hesaba çekilen azap görür.","ar":"مَنْ حُوسِبَ عُذِّبَ"},"src":{"az":"Buxari 103","en":"Bukhari 103","ru":"Бухари 103","tr":"Buhârî 103","ar":"البخاري 103"}},{"id":123,"t":{"az":"Cənnət hər birinizə ayaqqabısının bağından daha yaxındır; cəhənnəm də.","en":"Paradise is nearer to one of you than the strap of your sandal — and so is the Fire.","ru":"Рай ближе к любому из вас, чем ремень его сандалии — и ад тоже.","tr":"Cennet birinize ayakkabısının bağından daha yakındır; cehennem de öyle.","ar":"الْجَنَّةُ أَقْرَبُ إِلَى أَحَدِكُمْ مِنْ شِرَاكِ نَعْلِهِ"},"src":{"az":"Buxari 6488","en":"Bukhari 6488","ru":"Бухари 6488","tr":"Buhârî 6488","ar":"البخاري 6488"}},{"id":124,"t":{"az":"Qiyamət günü insanlar arasında ilk qan məsələsindən hökm verilər.","en":"The first matter to be judged between people on the Day of Judgment will be blood (murder).","ru":"Первое, в чём будет вынесен приговор между людьми в День Суда, — это кровь.","tr":"Kıyamet günü insanlar arasında ilk olarak kan davalarından hüküm verilir.","ar":"أَوَّلُ مَا يُقْضَى بَيْنَ النَّاسِ يَوْمَ الْقِيَامَةِ فِي الدِّمَاءِ"},"src":{"az":"Buxari 6864","en":"Bukhari 6864","ru":"Бухари 6864","tr":"Buhârî 6864","ar":"البخاري 6864"}},{"id":125,"t":{"az":"Cənnətin ən aşağı dərəcəli sakininin belə bu dünyanın on misli əmlakı olar.","en":"The one with the lowest rank in Paradise will have ten times the world as their property.","ru":"Тот, кто займёт самое низшее место в раю, будет иметь имущество в десять раз больше всего этого мира.","tr":"Cennette en düşük dereceye sahip olan kişinin bile bu dünyanın on katı kadar mülkü olacak.","ar":"إِنَّ أَدْنَى أَهْلِ الْجَنَّةِ مَنْزِلَةً"},"src":{"az":"Muslim 189","en":"Muslim 189","ru":"Муслим 189","tr":"Müslim 189","ar":"مسلم 189"}},{"id":127,"t":{"az":"Cənnətdə heç gözün görmədiyini, qulağın eşitmədiyini, ürəyin düşünmədiyini var.","en":"In Paradise there is what no eye has seen, no ear has heard, and no mind has imagined.","ru":"В раю есть то, чего не видел глаз, не слышало ухо и что не представляло сердце.","tr":"Cennette hiçbir gözün görmediği, kulağın işitmediği, aklın hayal edemediği şeyler vardır.","ar":"فِي الجَنَّةِ مَا لاَ عَيْنٌ رَأَتْ وَلاَ أُذُنٌ سَمِعَتْ"},"src":{"az":"Buxari 3244","en":"Bukhari 3244","ru":"Бухари 3244","tr":"Buhârî 3244","ar":"البخاري 3244"}},{"id":128,"t":{"az":"Cəhənnəm şəhvətlərlə, cənnət isə çətinliklərlə əhatə olunmuşdur.","en":"The Fire is surrounded by desires and Paradise is surrounded by hardships.","ru":"Ад окружён страстями, а рай окружён трудностями.","tr":"Cehennem şehvetlerle, cennet ise meşakkatlerle çevrilidir.","ar":"النَّارُ حُفَّتْ بِالشَّهَوَاتِ وَالْجَنَّةُ حُفَّتْ بِالْمَكَارِهِ"},"src":{"az":"Buxari 6487","en":"Bukhari 6487","ru":"Бухари 6487","tr":"Buhârî 6487","ar":"البخاري 6487"}},{"id":129,"t":{"az":"Şəfaətimlə ən xoşbəxt olan qəlbindən xalis \"La ilaha illallah\" deyəndir.","en":"The happiest with my intercession is whoever says \"La ilaha illallah\" sincerely from the heart.","ru":"Счастливейший с моим заступничеством — тот, кто искренне, от всего сердца сказал \"Нет бога, кроме Аллаха\".","tr":"Şefaatimle en mesut olacak, kalbinden samimi bir şekilde \"La ilahe illallah\" diyendir.","ar":"أَسْعَدُ النَّاسِ بِشَفَاعَتِي مَنْ قَالَ لاَ إِلَهَ إِلاَّ اللَّهُ خَالِصاً مِنْ قَلْبِهِ"},"src":{"az":"Buxari 99","en":"Bukhari 99","ru":"Бухари 99","tr":"Buhârî 99","ar":"البخاري 99"}},{"id":130,"t":{"az":"Müsəlmanın müsəlman üzərindəki haqqı beşdir: Salamı almaq, xəstəni ziyarət etmək, cənazəni ötürmək, dəvəti qəbul etmək, asqırana dua etmək.","en":"A Muslim has five rights over another Muslim: returning greetings, visiting the sick, following the funeral, accepting invitations, and saying blessings on the sneezer.","ru":"Мусульманин имеет над мусульманином пять прав: ответить на приветствие, навестить больного, проводить в последний путь, принять приглашение, ответить на чихание.","tr":"Müslümanın Müslüman üzerinde beş hakkı vardır: Selamını almak, hastayı ziyaret etmek, cenazeyi uğurlamak, daveti kabul etmek, aksırana duymak.","ar":"حَقُّ الْمُسْلِمِ عَلَى الْمُسْلِمِ خَمْسٌ"},"src":{"az":"Buxari 1240","en":"Bukhari 1240","ru":"Бухари 1240","tr":"Buhârî 1240","ar":"البخاري 1240"}},{"id":131,"t":{"az":"Kim mənə bir salavat göndərərsə, Allah ona on salavat göndərər.","en":"Whoever sends one blessing upon me, Allah sends ten blessings upon him.","ru":"Кто помолится за меня один раз, тому Аллах воздаст десятикратно.","tr":"Kim bana bir kere salat getirirse, Allah ona on kez rahmet eder.","ar":"مَنْ صَلَّى عَلَيَّ صَلاَةً صَلَّى اللَّهُ عَلَيْهِ بِهَا عَشْراً"},"src":{"az":"Muslim 408","en":"Muslim 408","ru":"Муслим 408","tr":"Müslim 408","ar":"مسلم 408"}},{"id":132,"t":{"az":"Cimri o kəsdir ki, yanında adım zikr olunsun da üzərimə salavat gətirməsin.","en":"The miser is the one in whose presence I am mentioned, yet he does not send blessings upon me.","ru":"Скупец тот, в чьём присутствии упоминают меня, а он не благословляет меня.","tr":"Cimri o kişidir ki, yanında adım anılsın da bana salavat getirmesin.","ar":"الْبَخِيلُ الَّذِي مَنْ ذُكِرْتُ عِنْدَهُ فَلَمْ يُصَلِّ عَلَيَّ"},"src":{"az":"Tirmizi 3546","en":"Tirmidhi 3546","ru":"Тирмизи 3546","tr":"Tirmizî 3546","ar":"الترمذي 3546"}},{"id":133,"t":{"az":"Cümə günü mənə çox salavat göndərin.","en":"Increase sending blessings upon me on Fridays.","ru":"Чаще благословляйте меня в пятницу.","tr":"Cuma günleri bana çokça salavat getirin.","ar":"أَكْثِرُوا الصَّلاَةَ عَلَيَّ يَوْمَ الجُمُعَةِ"},"src":{"az":"Əbu Davud 1047","en":"Abu Dawud 1047","ru":"Абу Дауд 1047","tr":"Ebû Dâvûd 1047","ar":"أبو داود 1047"}},{"id":135,"t":{"az":"Evimi bayram yerinə çevirməyin; üzərimə salavat göndərin ki, salavat mənə çatar.","en":"Do not make my grave a place of celebration. Send blessings upon me — your blessings reach me.","ru":"Не превращайте мою могилу в место праздника. Благословляйте меня — ваши благословения доходят до меня.","tr":"Kabrimi bayram yerine çevirmeyin; bana salavat getirin, namazınız bana ulaşır.","ar":"لاَ تَجْعَلُوا بَيْتِي عِيداً وَصَلُّوا عَلَيَّ فَإِنَّ صَلاَتَكُمْ تَبْلُغُنِي"},"src":{"az":"Əbu Davud 2042","en":"Abu Dawud 2042","ru":"Абу Дауд 2042","tr":"Ebû Dâvûd 2042","ar":"أبو داود 2042"}},{"id":136,"t":{"az":"Səfər əzabın bir parçasıdır; birinizin işi bitdikdə ailəsinə tez qayıtsın.","en":"Travel is a piece of torment; when one of you finishes his business let him return quickly to his family.","ru":"Путешествие — доля мучений; когда один из вас завершит дела, пусть скорее вернётся к семье.","tr":"Yolculuk azabın bir parçasıdır; biriniz işini bitirince ailesine hemen dönsün.","ar":"السَّفَرُ قِطْعَةٌ مِنَ الْعَذَابِ"},"src":{"az":"Buxari 1804","en":"Bukhari 1804","ru":"Бухари 1804","tr":"Buhârî 1804","ar":"البخاري 1804"}},{"id":139,"t":{"az":"Verimli yerdə səfər edərkən heyvanlara haqqını verin.","en":"When you travel in fertile land, give the camels their due.","ru":"Когда путешествуете по плодородной земле, давайте животным их долю.","tr":"Verimli yerlerde seyahat ederken hayvanlara hakkını verin.","ar":"إِذَا سَافَرْتُمْ فِي الخِصْبِ فَأَعْطُوا الإِبِلَ حَقَّهَا"},"src":{"az":"Muslim 1926","en":"Muslim 1926","ru":"Муслим 1926","tr":"Müslim 1926","ar":"مسلم 1926"}},{"id":140,"t":{"az":"Qalmayacaqsan isə müsafir namazını qıl.","en":"Pray the traveler's prayer unless you intend to stay.","ru":"Молись молитвой путника, если не намерен задержаться.","tr":"Yerleşmeyeceksen yolcu namazı kıl.","ar":"صَلِّ صَلاَةَ الْمُسَافِرِ إِلاَّ أَنْ تُقِيمَ"},"src":{"az":"Buxari 1101","en":"Bukhari 1101","ru":"Бухари 1101","tr":"Buhârî 1101","ar":"البخاري 1101"}},{"id":142,"t":{"az":"Qul mən ona ata-anasından, övladından daha sevimli olmayınca iman etmiş olmaz.","en":"A servant does not truly believe until I am dearer to him than his parents and children.","ru":"Раб не уверует по-настоящему, пока я не стану ему дороже родителей и детей.","tr":"Bir kul, ben ona anne-babasından, çocuğundan daha sevimli olmadıkça gerçek anlamda iman etmiş olmaz.","ar":"لاَ يُؤْمِنُ عَبْدٌ حَتَّى أَكُونَ أَحَبَّ إِلَيْهِ مِنْ وَالِدِهِ وَوَلَدِهِ"},"src":{"az":"Buxari 15","en":"Bukhari 15","ru":"Бухари 15","tr":"Buhârî 15","ar":"البخاري 15"}},{"id":144,"t":{"az":"Bir-birinizə həsəd etməyin, bidə qalxışmayın, bir-birinizə nifrət etməyin; qardaş olun.","en":"Do not envy one another, do not overbid, do not hate one another — be brothers.","ru":"Не завидуйте друг другу, не повышайте цены искусственно, не ненавидьте друг друга — будьте братьями.","tr":"Birbirinize haset etmeyin, yapay fiyat artırımı yapmayın, birbirinizi sevmeyin — kardeş olun.","ar":"لاَ تَحَاسَدُوا وَلاَ تَنَاجَشُوا وَلاَ تَبَاغَضُوا"},"src":{"az":"Buxari 6064","en":"Bukhari 6064","ru":"Бухари 6064","tr":"Buhârî 6064","ar":"البخاري 6064"}},{"id":145,"t":{"az":"Kim cənnət əhlindən birinə baxmaq istəyirsə, buna baxsın.","en":"Whoever wants to look at a man from the people of Paradise, let him look at this man.","ru":"Кто хочет посмотреть на человека из числа жителей рая, пусть посмотрит на него.","tr":"Cennet ehlinden birine bakmak isteyen, şu kişiye baksın.","ar":"مَنْ أَرَادَ أَنْ يَنْظُرَ إِلَى رَجُلٍ مِنْ أَهْلِ الجَنَّةِ فَلْيَنْظُرْ إِلَى هَذَا"},"src":{"az":"Buxari 1397","en":"Bukhari 1397","ru":"Бухари 1397","tr":"Buhârî 1397","ar":"البخاري 1397"}},{"id":146,"t":{"az":"Allah qulunun xeyrini istəsə, onu istifadə edər.","en":"When Allah desires good for a servant, He employs him.","ru":"Когда Аллах желает блага для раба, Он использует его.","tr":"Allah bir kulu için hayır dilediğinde onu (iyilik için) çalıştırır.","ar":"إِذَا أَرَادَ اللَّهُ بِعَبْدٍ خَيْراً اسْتَعْمَلَهُ"},"src":{"az":"Buxari 7165","en":"Bukhari 7165","ru":"Бухари 7165","tr":"Buhârî 7165","ar":"البخاري 7165"}},{"id":147,"t":{"az":"Mömin bir dəlikdən iki dəfə sancılmaz.","en":"A believer is not stung from the same hole twice.","ru":"Верующий не укусят из одной норы дважды.","tr":"Mü'min, aynı delikten iki kez sokulmaz.","ar":"لاَ يُلْدَغُ الْمُؤْمِنُ مِنْ جُحْرٍ وَاحِدٍ مَرَّتَيْنِ"},"src":{"az":"Buxari 6133","en":"Bukhari 6133","ru":"Бухари 6133","tr":"Buhârî 6133","ar":"البخاري 6133"}},{"id":151,"t":{"az":"Müsəlman müsəlmanın qardaşıdır; ona zülm etmər, onu köməksiz buraxmaz.","en":"A Muslim is the brother of a Muslim — he does not oppress him nor abandon him.","ru":"Мусульманин — брат мусульманина: не угнетает его и не бросает в беде.","tr":"Müslüman, Müslümanın kardeşidir; ona zulmetmez, onu yüz üstü bırakmaz.","ar":"الْمُسْلِمُ أَخُو الْمُسْلِمِ لاَ يَظْلِمُهُ وَلاَ يَخْذُلُهُ"},"src":{"az":"Muslim 2564","en":"Muslim 2564","ru":"Муслим 2564","tr":"Müslim 2564","ar":"مسلم 2564"}},{"id":153,"t":{"az":"Ramazandan sonra ən fəzilətli oruc Allahın ayı Məhərrəmdəki orucdur.","en":"The best fasting after Ramadan is fasting in the month of Allah — Muharram.","ru":"Лучший пост после Рамадана — пост в месяце Аллаха Мухаррам.","tr":"Ramazandan sonra en faziletli oruç, Allah'ın ayı Muharrem ayı oruçlarıdır.","ar":"أَفْضَلُ الصَّوْمِ بَعْدَ رَمَضَانَ شَهْرُ اللَّهِ الْمُحَرَّمُ"},"src":{"az":"Muslim 1163","en":"Muslim 1163","ru":"Муслим 1163","tr":"Müslim 1163","ar":"مسلم 1163"}},{"id":154,"t":{"az":"Yolun haqqı gözü aşağı salmaq, əziyyət verməmək, salamı cavablamaq, yaxşılığı əmr etmək, pisliyi qadağan etməkdir.","en":"The right of the road is lowering the gaze, removing harm, returning greetings, commanding good, and forbidding evil.","ru":"Право дороги: опускать взгляд, убирать вред, отвечать на приветствие, призывать к добру и запрещать зло.","tr":"Yolun hakkı: gözü yere eğmek, zarar vermemekten, selama karşılık vermek, iyiliği emreylemek, kötülükten men etmektir.","ar":"حَقُّ الطَّرِيقِ غَضُّ الْبَصَرِ وَكَفُّ الأَذَى"},"src":{"az":"Buxari 2465","en":"Bukhari 2465","ru":"Бухари 2465","tr":"Buhârî 2465","ar":"البخاري 2465"}},{"id":155,"t":{"az":"Sizin altınızda olanlara bakın; üstünüzdəkilərə baxmayın; bu Allahın sizə olan nemətini küçümsəmirsiniz.","en":"Look at those below you and not at those above you; this is more proper so you do not underestimate the blessings of Allah.","ru":"Смотрите на тех, кто ниже вас, а не на тех, кто выше — так вы не станете умалять блага Аллаха.","tr":"Size daha aşağıda olanlara bakın, üstünüzdekine değil; bu, Allah'ın nimetini küçümsememek için daha uygundur.","ar":"أُنْظُرُوا إِلَى مَنْ أَسْفَلَ مِنْكُمْ"},"src":{"az":"Buxari 6490","en":"Bukhari 6490","ru":"Бухари 6490","tr":"Buhârî 6490","ar":"البخاري 6490"}},{"id":157,"t":{"az":"Biriniz namaza durduqda Allah onun önündədir.","en":"When one of you stands for prayer, Allah is in front of him.","ru":"Когда один из вас встаёт на молитву, Аллах перед ним.","tr":"Biriniz namaza durduğunda, Allah onun önündedir.","ar":"إِذَا قَامَ أَحَدُكُمْ إِلَى الصَّلاَةِ فَإِنَّ اللَّهَ قِبَلَ وَجْهِهِ"},"src":{"az":"Buxari 405","en":"Bukhari 405","ru":"Бухари 405","tr":"Buhârî 405","ar":"البخاري 405"}},{"id":159,"t":{"az":"Hər gün iki mələk enər; biri \"Allahım, infaq edənə əvəz ver\" deyər, digəri \"Allahım, xəsis olanın malını məhv et\" deyər.","en":"Every day two angels descend, one says \"O Allah, give more to the one who spends,\" the other says \"O Allah, destroy the wealth of the miser.\"","ru":"Каждый день спускаются два ангела: один говорит \"О Аллах, дай замену тому, кто жертвует\", другой — \"О Аллах, погуби имущество скупца\".","tr":"Her gün iki melek iner; biri \"Allah'ım, infak edene karşılık ver\" der, diğeri ise \"Allah'ım, cimrinin malını telef et\" der.","ar":"مَا مِنْ يَوْمٍ يُصْبِحُ الْعِبَادُ فِيهِ إِلاَّ وَمَلَكَانِ يَنْزِلاَنِ"},"src":{"az":"Buxari 1442","en":"Bukhari 1442","ru":"Бухари 1442","tr":"Buhârî 1442","ar":"البخاري 1442"}},{"id":160,"t":{"az":"Kim \"Allahı Rəbb, İslamı din, Muhəmmədi peyğəmbər olaraq qəbul etdim\" deyərsə, ona cənnət vacib olar.","en":"Whoever says \"I am pleased with Allah as Lord, Islam as religion, and Muhammad as Prophet,\" Paradise becomes obligatory for them.","ru":"Кто скажет \"Доволен Аллахом как Господом, исламом как религией, Мухаммадом как пророком\", тому становится обязательным рай.","tr":"'Allah'ı Rab, İslam'ı din, Muhammed'i Peygamber olarak kabul ettim' diyen için cennet vacip olur.","ar":"مَنْ قَالَ رَضِيتُ بِاللَّهِ رَبًّا وَبِالإِسْلاَمِ دِينًا وَبِمُحَمَّدٍ نَبِيًّا وَجَبَتْ لَهُ الْجَنَّةُ"},"src":{"az":"Əbu Davud 1529","en":"Abu Dawud 1529","ru":"Абу Дауд 1529","tr":"Ebû Dâvûd 1529","ar":"أبو داود 1529"}},{"id":161,"t":{"az":"Ümmətin ən xeyirlisi mənim əsrimdir, sonra onları izləyənlər.","en":"The best of my nation is my generation, then those who follow them.","ru":"Лучшие из моей уммы — моё поколение, затем те, кто идёт за ними.","tr":"Ümmetimin en hayırlısı benim asrım, sonra onları izleyenlerdir.","ar":"خَيْرُ أُمَّتِي قَرْنِي ثُمَّ الَّذِينَ يَلُونَهُمْ"},"src":{"az":"Buxari 2652","en":"Bukhari 2652","ru":"Бухари 2652","tr":"Buhârî 2652","ar":"البخاري 2652"}},{"id":164,"t":{"az":"Quranı mahir oxuyan şərəfli itaətkar mələklərlə birgədir.","en":"The one proficient in the Quran will be with the noble obedient scribes (angels).","ru":"Искусно читающий Коран будет среди благородных послушных писцов (ангелов).","tr":"Kur'an'ı mahirce okuyan, şerefli ve itaatkâr yazıcı meleklerle beraberdir.","ar":"الْمَاهِرُ بِالْقُرْآنِ مَعَ السَّفَرَةِ الْكِرَامِ الْبَرَرَةِ"},"src":{"az":"Muslim 798","en":"Muslim 798","ru":"Муслим 798","tr":"Müslim 798","ar":"مسلم 798"}},{"id":167,"t":{"az":"Dünya şirin və yaşıldır; Allah sizi onda xəlifə edib.","en":"The world is sweet and green, and Allah has made you successors in it.","ru":"Мир сладок и зелен, и Аллах сделал вас преемниками в нём.","tr":"Dünya tatlı ve yeşildir; Allah sizi onda halifeler kılmıştır.","ar":"الدُّنْيَا حُلْوَةٌ خَضِرَةٌ وَإِنَّ اللَّهَ مُسْتَخْلِفُكُمْ فِيهَا"},"src":{"az":"Muslim 2742","en":"Muslim 2742","ru":"Муслим 2742","tr":"Müslim 2742","ar":"مسلم 2742"}},{"id":168,"t":{"az":"İnsanlar qiyamət günü üç növ şəkildə toplanacaq.","en":"People will be gathered on the Day of Judgment in three groups.","ru":"Люди будут собраны в День Суда тремя группами.","tr":"İnsanlar kıyamet günü üç sınıf üzere mahşere toplanacaktır.","ar":"يُحْشَرُ النَّاسُ يَوْمَ الْقِيَامَةِ عَلَى ثَلاَثَةِ أَصْنَافٍ"},"src":{"az":"Muslim 2859","en":"Muslim 2859","ru":"Муслим 2859","tr":"Müslim 2859","ar":"مسلم 2859"}},{"id":170,"t":{"az":"Bir qövmün yanına enəndə onlar sizə qonaq hüququnu versələr, qəbul edin.","en":"When you stay with a people and they provide what is appropriate for a guest, accept it.","ru":"Если вы остановились у какого-то народа и они предоставили вам должное угощение, примите его.","tr":"Bir kavme konduğunuzda size misafire yakışanı sunarlarsa, kabul edin.","ar":"إِذَا نَزَلْتُمْ بِقَوْمٍ فَأَمَرُوا لَكُمْ بِمَا يَنْبَغِي لِلضَّيْفِ"},"src":{"az":"Əbu Davud 3752","en":"Abu Dawud 3752","ru":"Абу Дауд 3752","tr":"Ebû Dâvûd 3752","ar":"أبو داود 3752"}},{"id":171,"t":{"az":"Üç şey kimdə olarsa, imanın şirinliyini tapar: Allahı və Peyğəmbəri hər şeydən çox sevmək, insanı yalnız Allah üçün sevmək, küfrdən qorxduğu kimi oda qayıtmaqdan qorxmaq.","en":"Whoever has three traits will find the sweetness of faith: loving Allah and His Messenger above all else, loving a person only for Allah, and fearing to return to disbelief as he fears being thrown into fire.","ru":"У кого есть три качества, тот ощутит сладость веры: любить Аллаха и Его Посланника больше всего, любить человека только ради Аллаха, бояться вернуться к неверию, как боится быть брошенным в огонь.","tr":"Şu üç haslet kimde bulunursa imanın tadını bulur: Allah ve Rasulünü her şeyden çok sevmek, bir kimseyi yalnızca Allah için sevmek, küfre dönmekten ateşe atılmaktan korktuğu gibi korkmak.","ar":"ثَلاَثٌ مَنْ كُنَّ فِيهِ وَجَدَ حَلاَوَةَ الإِيمَانِ"},"src":{"az":"Buxari 16","en":"Bukhari 16","ru":"Бухари 16","tr":"Buhârî 16","ar":"البخاري 16"}},{"id":172,"t":{"az":"Zülm qiyamət günü qaranlıqlardır.","en":"Oppression is darkness on the Day of Judgment.","ru":"Тирания — тьма в День Суда.","tr":"Zulüm, kıyamet günü karanlıklardır.","ar":"الظُّلْمُ ظُلُمَاتٌ يَوْمَ الْقِيَامَةِ"},"src":{"az":"Muslim 2578","en":"Muslim 2578","ru":"Муслим 2578","tr":"Müslim 2578","ar":"مسلم 2578"}},{"id":173,"t":{"az":"Kişilər üçün ən xeyirli sıra birinci sıradır.","en":"The best rows for men are the first rows.","ru":"Лучшие ряды для мужчин — первые.","tr":"Erkekler için safların en hayırlısı, birinci saflardır.","ar":"خَيْرُ صُفُوفِ الرِّجَالِ أَوَّلُهَا"},"src":{"az":"Muslim 440","en":"Muslim 440","ru":"Муслим 440","tr":"Müslim 440","ar":"مسلم 440"}},{"id":174,"t":{"az":"Kim Bəqərə və Ali İmranı oxuyan olursa, onlar qiyamət günü iki bulud kimi gələr.","en":"Whoever recites Al-Baqara and Ali Imran, they will come on the Day of Judgment like two clouds.","ru":"Кто читает суры \"Аль-Бакара\" и \"Аль Имран\", они явятся в День Суда, как два облака.","tr":"Kim Bakara ve Al-i İmran surelerini okursa, kıyamet günü iki bulut gibi gelirler.","ar":"مَنْ قَرَأَ الْبَقَرَةَ وَآلَ عِمْرَانَ جَاءَتَا يَوْمَ الْقِيَامَةِ كَأَنَّهُمَا غَمَامَتَانِ"},"src":{"az":"Muslim 804","en":"Muslim 804","ru":"Муслим 804","tr":"Müslim 804","ar":"مسلم 804"}},{"id":175,"t":{"az":"Allah, bizdən bir hədis eşidib onu çatdıran kəsin simasını parlaq etsin.","en":"May Allah brighten the face of the one who hears a hadith from us and conveys it.","ru":"Да осветит Аллах лицо того, кто услышал от нас хадис и передал его.","tr":"Bizden bir hadis işitip onu tebliğ eden kimsenin yüzünü Allah nurlandırsın.","ar":"نَضَّرَ اللَّهُ امْرَأً سَمِعَ مِنَّا حَدِيثاً فَبَلَّغَهُ"},"src":{"az":"Tirmizi 2656","en":"Tirmidhi 2656","ru":"Тирмизи 2656","tr":"Tirmizî 2656","ar":"الترمذي 2656"}},{"id":177,"t":{"az":"Mənlə dünya arasındaki münasibət: ağacın kölgəsindən istifadə edib sonra oradan ayrılan yolçunun münasibəti kimidir.","en":"I and the world are like a rider who takes shade under a tree, then departs.","ru":"Я и мир — как путник, укрывшийся в тени дерева, а затем ушедший.","tr":"Ben ve dünya; bir ağacın gölgesinde gölgelendikten sonra oradan ayrılan yolcu gibiyiz.","ar":"مَا أَنَا وَالدُّنْيَا إِلاَّ كَرَاكِبٍ اسْتَظَلَّ تَحْتَ شَجَرَةٍ"},"src":{"az":"Tirmizi 2377","en":"Tirmidhi 2377","ru":"Тирмизи 2377","tr":"Tirmizî 2377","ar":"الترمذي 2377"}},{"id":178,"t":{"az":"Biriniz öldükdə, sabah-axşam onun oturacaq yeri — cənnət ya cəhənnəm — ona göstərilər.","en":"When one of you dies, his place in the morning and evening is shown to him — either Paradise or Hell.","ru":"Когда кто-то из вас умирает, ему утром и вечером показывают его место — рай или ад.","tr":"Biriniz öldüğünde sabah ve akşam ona makamı gösterilir: cennet mi cehennem mi.","ar":"إِذَا مَاتَ أَحَدُكُمْ عُرِضَ عَلَيْهِ مَقْعَدُهُ بِالْغَدَاةِ وَالْعَشِيِّ"},"src":{"az":"Buxari 1379","en":"Bukhari 1379","ru":"Бухари 1379","tr":"Buhârî 1379","ar":"البخاري 1379"}},{"id":179,"t":{"az":"Allahın yer üzünü gəzən mələkləri var; onlar ümmətimdən mənə salamı çatdırırlar.","en":"Allah has angels who roam the earth conveying to me the greetings of my nation.","ru":"У Аллаха есть ангелы, путешествующие по земле и передающие мне приветствия от моей общины.","tr":"Allah'ın yeryüzünde gezen melekleri var; ümmetimden bana selam ulaştırıyorlar.","ar":"إِنَّ لِلَّهِ مَلاَئِكَةً سَيَّاحِينَ فِي الأَرْضِ يُبَلِّغُونِي مِنْ أُمَّتِي السَّلاَمَ"},"src":{"az":"Nəsai 1282","en":"An-Nasa'i 1282","ru":"ан-Насаи 1282","tr":"Nesâî 1282","ar":"النسائي 1282"}},{"id":180,"t":{"az":"Qonaqpərvərlik üç gündür.","en":"Hospitality is for three days.","ru":"Гостеприимство длится три дня.","tr":"Misafirlik üç gündür.","ar":"الضِّيَافَةُ ثَلاَثَةُ أَيَّامٍ"},"src":{"az":"Buxari 6135","en":"Bukhari 6135","ru":"Бухари 6135","tr":"Buhârî 6135","ar":"البخاري 6135"}},{"id":181,"t":{"az":"Bil ki, bədəndə bir parça ət var; o düzəlsə bütün bədən düzəlir; o pozulsa bütün bədən pozulur. Diqqat: o qəlbdir.","en":"In the body there is a piece of flesh; if it is good the whole body is good, and if it is corrupt the whole body is corrupt. That is the heart.","ru":"В теле есть кусочек плоти: если он здоров — здорово всё тело; если он испорчен — испорчено всё тело. Это сердце.","tr":"Bedende bir et parçası var; o düzelirse, bütün beden düzelir; o bozulursa bütün beden bozulur. İşte o kalptir.","ar":"أَلاَ وَإِنَّ فِي الجَسَدِ مُضْغَةً إِذَا صَلَحَتْ صَلَحَ الجَسَدُ كُلُّهُ"},"src":{"az":"Buxari 52","en":"Bukhari 52","ru":"Бухари 52","tr":"Buhârî 52","ar":"البخاري 52"}},{"id":182,"t":{"az":"Haqsızlıqlardan çəkin; çünki haqsızlıqlar qiyamət günü qaranlıqlardır.","en":"Beware of injustice, for injustice will be darkness on the Day of Judgment.","ru":"Берегись несправедливости, ибо несправедливость будет тьмой в День Суда.","tr":"Zulümden sakın; zira zulümler kıyamet günü karanlıklardır.","ar":"اتَّقِ الْمَظَالِمَ فَإِنَّ الْمَظَالِمَ ظُلُمَاتٌ يَوْمَ الْقِيَامَةِ"},"src":{"az":"Muslim 2578","en":"Muslim 2578","ru":"Муслим 2578","tr":"Müslim 2578","ar":"مسلم 2578"}},{"id":183,"t":{"az":"Quranı gözəl avazla oxumayan bizdən deyil.","en":"He is not of us who does not recite the Quran beautifully.","ru":"Не из нас тот, кто не читает Коран с красивым голосом.","tr":"Kur'an'ı güzel sesle okumayanlar bizden değildir.","ar":"لَيْسَ مِنَّا مَنْ لَمْ يَتَغَنَّ بِالْقُرْآنِ"},"src":{"az":"Buxari 7527","en":"Bukhari 7527","ru":"Бухари 7527","tr":"Buhârî 7527","ar":"البخاري 7527"}},{"id":184,"t":{"az":"Sözlərin ən doğrusu Allahın kitabıdır.","en":"The most truthful of speech is the Book of Allah.","ru":"Правдивейшее из слов — Книга Аллаха.","tr":"Sözlerin en doğrusu Allah'ın Kitabı'dır.","ar":"إِنَّ أَصْدَقَ الْحَدِيثِ كِتَابُ اللَّهِ"},"src":{"az":"Muslim 867","en":"Muslim 867","ru":"Муслим 867","tr":"Müslim 867","ar":"مسلم 867"}},{"id":185,"t":{"az":"Kim elm barəsindəki sualdan gizlənsə, qiyamət günü oddan yüyən vurular.","en":"Whoever is asked about knowledge and conceals it will be bridled with a bridle of fire on the Day of Judgment.","ru":"Кто скрыл знание, которого у него спрашивали, будет обуздан в День Суда уздой из огня.","tr":"Kendisine ilim sorulduğunda onu gizleyen kişiye kıyamet günü ateşten bir gem vurulur.","ar":"مَنْ سُئِلَ عَنْ عِلْمٍ فَكَتَمَهُ أُلْجِمَ يَوْمَ الْقِيَامَةِ بِلِجَامٍ مِنْ نَارٍ"},"src":{"az":"Tirmizi 2649","en":"Tirmidhi 2649","ru":"Тирмизи 2649","tr":"Tirmizî 2649","ar":"الترمذي 2649"}},{"id":186,"t":{"az":"Heç bir müsəlman tikanlı bir şeyə dəyib-keçmirsə, mütləq onunla bir dərəcə yazılır.","en":"No Muslim is pricked by a thorn or more without a rank being written for them.","ru":"Ни один мусульманин не укалывается шипом или чем-то большим, не получив за это степень.","tr":"Bir müslüman, diken ya da daha büyük bir şeyle batıklanırsa, mutlaka onunla bir derece yazılır.","ar":"مَا مِنْ مُسْلِمٍ يُشَاكُ شَوْكَةً فَمَا فَوْقَهَا إِلاَّ كُتِبَ لَهُ بِهَا دَرَجَةٌ"},"src":{"az":"Muslim 2572","en":"Muslim 2572","ru":"Муслим 2572","tr":"Müslim 2572","ar":"مسلم 2572"}},{"id":187,"t":{"az":"Əməllər (yalnız) aqibətlərinə görədir.","en":"Actions are judged by their conclusions.","ru":"Дела оцениваются по их завершению.","tr":"Ameller sonlarına göre değerlendirilir.","ar":"إِنَّمَا الأَعْمَالُ بِخَوَاتِيمِهَا"},"src":{"az":"Buxari 6493","en":"Bukhari 6493","ru":"Бухари 6493","tr":"Buhârî 6493","ar":"البخاري 6493"}},{"id":188,"t":{"az":"Kim Allahla görüşməyi sevirsə, Allah da onunla görüşməyi sevər.","en":"Whoever loves to meet Allah, Allah loves to meet them.","ru":"Кто желает встречи с Аллахом, Аллах желает встречи с ним.","tr":"Kim Allah'a kavuşmayı severse, Allah da ona kavuşmayı sever.","ar":"مَنْ أَحَبَّ لِقَاءَ اللَّهِ أَحَبَّ اللَّهُ لِقَاءَهُ"},"src":{"az":"Buxari 6507","en":"Bukhari 6507","ru":"Бухари 6507","tr":"Buhârî 6507","ar":"البخاري 6507"}},{"id":189,"t":{"az":"Kim mənə salavat gətirməyi unutarsa, cənnətin yolunu unutdurular.","en":"Whoever forgets to send blessings upon me will forget the way to Paradise.","ru":"Кто забудет благословить меня, тому забудут путь в рай.","tr":"Bana salavat getirmeyi unutan, cennetin yolunu unutturulur.","ar":"مَنْ نَسِيَ الصَّلاَةَ عَلَيَّ أُنْسِيَ طَرِيقَ الْجَنَّةِ"},"src":{"az":"İbn Macə 908","en":"Ibn Majah 908","ru":"Ибн Маджа 908","tr":"İbn Mâce 908","ar":"ابن ماجه 908"}},{"id":192,"t":{"az":"İnsanlar arasında islah edən yalançı sayılmaz.","en":"The liar is not one who brings reconciliation between people.","ru":"Не считается лжецом тот, кто примиряет людей.","tr":"İnsanlar arasında ıslah eden, yalancı sayılmaz.","ar":"لَيْسَ الْكَذَّابُ الَّذِي يُصْلِحُ بَيْنَ النَّاسِ"},"src":{"az":"Buxari 2692","en":"Bukhari 2692","ru":"Бухари 2692","tr":"Buhârî 2692","ar":"البخاري 2692"}},{"id":193,"t":{"az":"Kim İşa namazını camaatla qılsa, gecənin yarısını ibadətlə keçirmiş kimidir.","en":"Whoever prays Isha in congregation is like one who has prayed half the night.","ru":"Кто помолится вечернюю намаз с джамаатом, тот как будто молился половину ночи.","tr":"Kim yatsı namazını cemaatle kılarsa, sanki gecenin yarısını ibadetle geçirmiş gibidir.","ar":"مَنْ صَلَّى الْعِشَاءَ فِي جَمَاعَةٍ فَكَأَنَّمَا قَامَ نِصْفَ اللَّيْلِ"},"src":{"az":"Muslim 656","en":"Muslim 656","ru":"Муслим 656","tr":"Müslim 656","ar":"مسلم 656"}},{"id":196,"t":{"az":"Mömini qəm-kədər, əziyyət nə vursaydı, günahlarına kəffarə olar.","en":"No concern, grief, or hardship afflicts a believer without it being expiation for his sins.","ru":"Ни тревога, ни печаль, ни усталость не постигают верующего, не стирая тем самым его грехи.","tr":"Mü'mine isabet eden tasa, keder ve yorgunluk günahlarına kefaret olur.","ar":"مَا أَصَابَ الْمُؤْمِنَ مِنْ هَمٍّ وَلاَ حَزَنٍ إِلاَّ كَانَ لَهُ كَفَّارَةً"},"src":{"az":"Buxari 5641","en":"Bukhari 5641","ru":"Бухари 5641","tr":"Buhârî 5641","ar":"البخاري 5641"}},{"id":197,"t":{"az":"Dünya Allah yanında bir ağcaqanad qanadı qədər belə dəyər daşımır.","en":"The world does not weigh the wing of a mosquito in Allah's sight.","ru":"Мир у Аллаха не стоит даже крыла комара.","tr":"Dünya, Allah katında bir sivrisinek kanadı kadar bile değer taşımaz.","ar":"إِنَّ الدُّنْيَا لاَ تَسَاوِي عِنْدَ اللَّهِ جَنَاحَ بَعُوضَةٍ"},"src":{"az":"Tirmizi 2320","en":"Tirmidhi 2320","ru":"Тирмизи 2320","tr":"Tirmizî 2320","ar":"الترمذي 2320"}},{"id":198,"t":{"az":"Qul qəbrindəki sorğu üçün saxlanacaq.","en":"The servant will be detained in the grave for questioning.","ru":"Раб будет задержан в могиле для допроса.","tr":"Kul, sorgulanmak için kabrinde tutulacaktır.","ar":"يُحْبَسُ الْعَبْدُ فِي قَبْرِهِ يُسْأَلُ"},"src":{"az":"Buxari 1338","en":"Bukhari 1338","ru":"Бухари 1338","tr":"Buhârî 1338","ar":"البخاري 1338"}},{"id":200,"t":{"az":"Kişi evdən çıxanda \"Bismillah, Allaha təvəkkül etdim\" desin.","en":"When a man leaves his house, let him say \"In the name of Allah, I trust in Allah.\"","ru":"Когда мужчина выходит из дому, пусть скажет \"С именем Аллаха, я уповаю на Аллаха\".","tr":"Bir kişi evinden çıktığında \"Bismillah, Allah'a tevekkül ettim\" desin.","ar":"إِذَا خَرَجَ الرَّجُلُ مِنْ بَيْتِهِ فَلْيَقُلْ بِسْمِ اللَّهِ"},"src":{"az":"Tirmizi 3426","en":"Tirmidhi 3426","ru":"Тирмизи 3426","tr":"Tirmizî 3426","ar":"الترمذي 3426"}},{"id":202,"t":{"az":"Son sözü \"La ilaha illallah\" olan cənnətə girər.","en":"Whoever's last words are \"La ilaha illallah\" will enter Paradise.","ru":"Чьи последние слова \"Нет бога, кроме Аллаха\", войдёт в рай.","tr":"Son sözü \"La ilahe illallah\" olan cennete girer.","ar":"مَنْ كَانَ آخِرُ كَلاَمِهِ لاَ إِلَهَ إِلاَّ اللَّهُ دَخَلَ الجَنَّةَ"},"src":{"az":"Əbu Davud 3116","en":"Abu Dawud 3116","ru":"Абу Дауд 3116","tr":"Ebû Dâvûd 3116","ar":"أبو داود 3116"}},{"id":203,"t":{"az":"İslam qərib başladı və yenə qərib olacaq; qəriblərə müjdə.","en":"Islam began as a stranger and will return as a stranger; glad tidings to the strangers.","ru":"Ислам начался чужеродным и вернётся чужеродным; добрая весть чужеродным.","tr":"İslam garip başladı ve garip olarak geri dönecek; gariplere müjde.","ar":"إِنَّ الإِسْلاَمَ بَدَأَ غَرِيباً وَسَيَعُودُ غَرِيباً"},"src":{"az":"Muslim 145","en":"Muslim 145","ru":"Муслим 145","tr":"Müslim 145","ar":"مسلم 145"}},{"id":205,"t":{"az":"İnsanlara şükür etməyən Allaha da şükür etmiş olmaz.","en":"Whoever does not thank people has not thanked Allah.","ru":"Кто не благодарит людей, тот не благодарит Аллаха.","tr":"İnsanlara şükretmeyen Allah'a da şükretmemiş olur.","ar":"لاَ يَشْكُرُ اللَّهَ مَنْ لاَ يَشْكُرُ النَّاسَ"},"src":{"az":"Əbu Davud 4811","en":"Abu Dawud 4811","ru":"Абу Дауд 4811","tr":"Ebû Dâvûd 4811","ar":"أبو داود 4811"}},{"id":208,"t":{"az":"Halal açıqdır, haram açıqdır.","en":"The lawful is clear and the prohibited is clear.","ru":"Дозволенное ясно и запретное ясно.","tr":"Helal açıktır, haram açıktır.","ar":"الْحَلاَلُ بَيِّنٌ وَالْحَرَامُ بَيِّنٌ"},"src":{"az":"Buxari 52","en":"Bukhari 52","ru":"Бухари 52","tr":"Buhârî 52","ar":"البخاري 52"}},{"id":209,"t":{"az":"Kim təvazökar olarsa, Allah onu yüksəldər.","en":"Whoever is humble, Allah will elevate him.","ru":"Кто смиряется, Аллах возвышает.","tr":"Kim tevazu gösterirse Allah onu yükseltir.","ar":"مَنْ تَوَاضَعَ رَفَعَهُ اللَّهُ"},"src":{"az":"Muslim 2588","en":"Muslim 2588","ru":"Муслим 2588","tr":"Müslim 2588","ar":"مسلم 2588"}},{"id":210,"t":{"az":"Təkəbbür: haqqı inkar etmək və insanları kiçik görmək.","en":"Arrogance is rejecting the truth and looking down on people.","ru":"Высокомерие — это отвергание истины и пренебрежение людьми.","tr":"Kibir; hakkı inkâr etmek ve insanları küçümsemektir.","ar":"الْكِبْرُ بَطَرُ الْحَقِّ وَغَمْطُ النَّاسِ"},"src":{"az":"Muslim 91","en":"Muslim 91","ru":"Муслим 91","tr":"Müslim 91","ar":"مسلم 91"}},{"id":211,"t":{"az":"Ölülərə söyməyin; onlar öz etdiklərinə çatıblar.","en":"Do not curse the dead, for they have passed on to what they sent forth.","ru":"Не ругайте мёртвых, ибо они перешли к тому, что совершили.","tr":"Ölülere sövmeyin; onlar önceden ne yaptıysa ona kavuştular.","ar":"لاَ تَسُبُّوا الأَمْوَاتَ فَإِنَّهُمْ قَدْ أَفْضَوْا إِلَى مَا قَدَّمُوا"},"src":{"az":"Buxari 1393","en":"Bukhari 1393","ru":"Бухари 1393","tr":"Buhârî 1393","ar":"البخاري 1393"}},{"id":213,"t":{"az":"Qeybət qardaşın xoşlamadığı şeyi arxasınca deməkdir.","en":"Backbiting is mentioning your brother in a way he would dislike.","ru":"Сплетня — это упоминать о брате то, что ему не нравится.","tr":"Gıybet, kardeşinin hoşlanmayacağı şeyi onun arkasından söylemektir.","ar":"الْغِيبَةُ ذِكْرُكَ أَخَاكَ بِمَا يَكْرَهُ"},"src":{"az":"Muslim 2589","en":"Muslim 2589","ru":"Муслим 2589","tr":"Müslim 2589","ar":"مسلم 2589"}},{"id":215,"t":{"az":"Sənə əmanət qoyana əmanəti ver.","en":"Fulfill the trust of the one who trusted you.","ru":"Верни аманат тому, кто тебе доверился.","tr":"Sana emanet edene emaneti teslim et.","ar":"أَدِّ الأَمَانَةَ إِلَى مَنِ ائْتَمَنَكَ"},"src":{"az":"Tirmizi 1264","en":"Tirmidhi 1264","ru":"Тирмизи 1264","tr":"Tirmizî 1264","ar":"الترمذي 1264"}},{"id":216,"t":{"az":"Gün ərzində on iki rəkət namaz qılan üçün cənnətdə ev tikilər.","en":"Whoever prays twelve rak'ahs in a day and night, a house will be built in Paradise.","ru":"Кто молится двенадцать рак'атов в день и ночь, тому построят дом в раю.","tr":"Gün ve gece on iki rekât namaz kılan için cennette bir ev inşa edilir.","ar":"مَنْ صَلَّى اثْنَتَيْ عَشْرَةَ رَكْعَةً فِي يَوْمٍ وَلَيْلَةٍ بُنِيَ لَهُ بَيْتٌ فِي الجَنَّةِ"},"src":{"az":"Muslim 728","en":"Muslim 728","ru":"Муслим 728","tr":"Müslim 728","ar":"مسلم 728"}},{"id":217,"t":{"az":"Bu məscidimdəki namaz başqa yerdəki min namazdan xeyirlidir.","en":"A prayer in my mosque is better than a thousand prayers elsewhere.","ru":"Молитва в этой мечети лучше тысячи молитв в другом месте.","tr":"Bu mescidimdeki bir namaz, başka yerdeki bin namazdan hayırlıdır.","ar":"صَلاَةٌ فِي مَسْجِدِي هَذَا خَيْرٌ مِنْ أَلْفِ صَلاَةٍ فِيمَا سِوَاهُ"},"src":{"az":"Buxari 1190","en":"Bukhari 1190","ru":"Бухари 1190","tr":"Buhârî 1190","ar":"البخاري 1190"}},{"id":218,"t":{"az":"Duha namazı üç yüz altmış oynaq üçün sədəqə yerinə keçər.","en":"The Duha prayer suffices as charity for three hundred and sixty joints.","ru":"Молитва Духа заменяет садака за триста шестьдесят суставов.","tr":"Duha namazı üç yüz altmış eklem için sadaka yerine geçer.","ar":"صَلاَةُ الضُّحَى تُجْزِئُ عَنْ ثَلاَثِمِائَةٍ وَسِتِّينَ سُلاَمَى"},"src":{"az":"Muslim 720","en":"Muslim 720","ru":"Муслим 720","tr":"Müslim 720","ar":"مسلم 720"}},{"id":219,"t":{"az":"Hər iki azan arasında namaz var.","en":"Between every two calls to prayer there is a prayer.","ru":"Между каждыми двумя азанами есть молитва.","tr":"Her iki ezan arasında namaz vardır.","ar":"بَيْنَ كُلِّ أَذَانَيْنِ صَلاَةٌ"},"src":{"az":"Buxari 624","en":"Bukhari 624","ru":"Бухари 624","tr":"Buhârî 624","ar":"البخاري 624"}},{"id":221,"t":{"az":"Azan eşidəndə müəzzinin dediyini siz də deyin.","en":"When you hear the adhan, say the same as the muadhdhin.","ru":"Когда услышите азан, повторяйте то же, что говорит муэдзин.","tr":"Ezan duyunca müezzinin söylediğini siz de söyleyin.","ar":"إِذَا سَمِعْتُمُ الأَذَانَ فَقُولُوا مِثْلَ مَا يَقُولُ الْمُؤَذِّنُ"},"src":{"az":"Buxari 611","en":"Bukhari 611","ru":"Бухари 611","tr":"Buhârî 611","ar":"البخاري 611"}},{"id":222,"t":{"az":"Kim namazdan bir rəkətə yetişərsə, namazı dərk etmiş sayılır.","en":"Whoever catches one rak'ah of the prayer has caught the prayer.","ru":"Кто успел на один рак'ат молитвы, тот успел на молитву.","tr":"Kim namazdan bir rekâta yetişirse namaza yetişmiş sayılır.","ar":"مَنْ أَدْرَكَ رَكْعَةً مِنَ الصَّلاَةِ فَقَدْ أَدْرَكَ الصَّلاَةَ"},"src":{"az":"Buxari 580","en":"Bukhari 580","ru":"Бухари 580","tr":"Buhârî 580","ar":"البخاري 580"}},{"id":223,"t":{"az":"Kim namazı unudarsa ya yuxuda qalsa, kəffarəsi onu xatırlayanda qılmaqdır.","en":"Whoever forgets a prayer or sleeps through it, the expiation is to pray it when remembered.","ru":"Кто забыл молитву или проспал её, искупление — совершить её, когда вспомнит.","tr":"Kim bir namazı unutur ya da uyuyup kalırsa, keffareti onu hatırladığında kılmaktır.","ar":"مَنْ نَسِيَ صَلاَةً أَوْ نَامَ عَنْهَا فَكَفَّارَتُهَا أَنْ يُصَلِّيَهَا إِذَا ذَكَرَهَا"},"src":{"az":"Muslim 684","en":"Muslim 684","ru":"Муслим 684","tr":"Müslim 684","ar":"مسلم 684"}},{"id":224,"t":{"az":"Azan ilə iqamə arasındakı dua rədd edilməz.","en":"The supplication between the adhan and iqamah is not rejected.","ru":"Мольба между азаном и икамой не отвергается.","tr":"Ezan ile ikamet arasındaki dua reddedilmez.","ar":"مَا بَيْنَ الأَذَانِ وَالإِقَامَةِ لاَ يُرَدُّ"},"src":{"az":"Tirmizi 212","en":"Tirmidhi 212","ru":"Тирмизи 212","tr":"Tirmizî 212","ar":"الترمذي 212"}},{"id":225,"t":{"az":"Namaz nurdur.","en":"Prayer is light.","ru":"Молитва — свет.","tr":"Namaz nurdur.","ar":"الصَّلاَةُ نُورٌ"},"src":{"az":"Muslim 223","en":"Muslim 223","ru":"Муслим 223","tr":"Müslim 223","ar":"مسلم 223"}},{"id":231,"t":{"az":"Kim bir xeyirə dəlalət etsə, ona edənin savabı qədər savab var.","en":"Whoever guides to something good has the same reward as the one who does it.","ru":"Кто указывает на доброе дело, получит такую же награду, как совершивший его.","tr":"Kim bir hayra rehberlik ederse, yapanın sevabı kadar sevabı olur.","ar":"مَنْ دَلَّ عَلَى خَيْرٍ فَلَهُ مِثْلُ أَجْرِ فَاعِلِهِ"},"src":{"az":"Muslim 1893","en":"Muslim 1893","ru":"Муслим 1893","tr":"Müslim 1893","ar":"مسلم 1893"}},{"id":234,"t":{"az":"İnsanların çoxu iki nemət barəsində aldanmışdır: sağlamlıq və boş vaxt.","en":"Two blessings most people are deceived about: health and free time.","ru":"Две блага, которыми большинство людей пренебрегает: здоровье и свободное время.","tr":"İnsanların çoğunun fırsatını değerlendirdiği iki nimet: sağlık ve boş vakit.","ar":"نِعْمَتَانِ مَغْبُونٌ فِيهِمَا كَثِيرٌ الصِّحَّةُ وَالْفَرَاغُ"},"src":{"az":"Buxari 6412","en":"Bukhari 6412","ru":"Бухари 6412","tr":"Buhârî 6412","ar":"البخاري 6412"}},{"id":236,"t":{"az":"Orucluya \"Cənnətə Rəyyan qapısından gir\" deyiləcək.","en":"The fasting person will be told: \"Enter Paradise through the gate of Ar-Rayyan.\"","ru":"Постящемуся скажут: \"Войди в рай через врата Ар-Райян.\"","tr":"Oruçluya: \"Cennete Reyyan kapısından gir\" denilecek.","ar":"يُقَالُ لِلصَّائِمِ ادْخُلِ الجَنَّةَ مِنْ بَابِ الرَّيَّانِ"},"src":{"az":"Buxari 1896","en":"Bukhari 1896","ru":"Бухари 1896","tr":"Buhârî 1896","ar":"البخاري 1896"}},{"id":237,"t":{"az":"Oruclu ağzının qoxusu Allah yanında müşk qoxusundan xoşdur.","en":"The smell of the fasting person's breath is more pleasant to Allah than musk.","ru":"Запах рта постящегося приятнее для Аллаха, чем запах мускуса.","tr":"Oruçlunun ağız kokusu Allah katında misk kokusundan daha güzeldir.","ar":"إِنَّ رَائِحَةَ فَمِ الصَّائِمِ أَطْيَبُ عِنْدَ اللَّهِ مِنْ رِيحِ الْمِسْكِ"},"src":{"az":"Buxari 1894","en":"Bukhari 1894","ru":"Бухари 1894","tr":"Buhârî 1894","ar":"البخاري 1894"}},{"id":238,"t":{"az":"Kim Allah yolunda bir gün oruc tutarsa, Allah onun üzünü atəşdən uzaqlaşdırar.","en":"Whoever fasts one day in Allah's cause, Allah will distance his face from the Fire.","ru":"Кто постится один день на пути Аллаха, Аллах отдалит его лицо от огня.","tr":"Kim Allah yolunda bir gün oruç tutarsa Allah onun yüzünü ateşten uzaklaştırır.","ar":"مَنْ صَامَ يَوْماً فِي سَبِيلِ اللَّهِ بَاعَدَ اللَّهُ وَجْهَهُ عَنِ النَّارِ"},"src":{"az":"Buxari 2840","en":"Bukhari 2840","ru":"Бухари 2840","tr":"Buhârî 2840","ar":"البخاري 2840"}},{"id":247,"t":{"az":"Yatarkən Ayətəl Kürsü oxuyan üçün Allah bir qoruyucu göndərər.","en":"Whoever recites Ayat al-Kursi before sleeping, a guardian from Allah remains with them.","ru":"Кто читает Аят аль-Курси перед сном, тому Аллах посылает хранителя.","tr":"Uyumadan Ayetü'l-Kürsi okuyanı Allah bir koruyucu gönderir.","ar":"مَنْ قَرَأَ آيَةَ الْكُرْسِيِّ عِنْدَ النَّوْمِ لَمْ يَزَلْ عَلَيْهِ مِنَ اللَّهِ حَافِظٌ"},"src":{"az":"Buxari 2311","en":"Bukhari 2311","ru":"Бухари 2311","tr":"Buhârî 2311","ar":"البخاري 2311"}},{"id":249,"t":{"az":"\"Subhanallahil azimi wa bihamdih\" deyənin üçün cənnətdə xurma ağacı əkilər.","en":"Whoever says \"SubhanAllahil Azim wa bihamdih\" a palm tree is planted for them in Paradise.","ru":"Кто скажет \"Пречист Великий Аллах и хвала Ему\", тому посадят пальму в раю.","tr":"\"Sübhanallahil azimi ve bihamdih\" diyenin için cennette bir hurma ağacı dikilir.","ar":"مَنْ قَالَ سُبْحَانَ اللَّهِ الْعَظِيمِ وَبِحَمْدِهِ غُرِسَتْ لَهُ نَخْلَةٌ فِي الجَنَّةِ"},"src":{"az":"Tirmizi 3464","en":"Tirmidhi 3464","ru":"Тирмизи 3464","tr":"Tirmizî 3464","ar":"الترمذي 3464"}},{"id":251,"t":{"az":"Xeyrə dəlalət edən, onu edən kimidir.","en":"The one who points to good is like the one who does it.","ru":"Указывающий на добро подобен совершающему его.","tr":"Hayra rehberlik eden, onu yapan gibidir.","ar":"الدَّالُّ عَلَى الْخَيْرِ كَفَاعِلِهِ"},"src":{"az":"Tirmizi 2670","en":"Tirmidhi 2670","ru":"Тирмизи 2670","tr":"Tirmizî 2670","ar":"الترمذي 2670"}},{"id":252,"t":{"az":"Kim ruzisinin genişləməsini istəyirsə, qohumunu ziyarət etsin.","en":"Whoever wants his provision expanded, let him maintain family ties.","ru":"Кто хочет, чтобы его удел расширился, пусть поддерживает родственные связи.","tr":"Rızkının genişlemesini isteyen, akrabasını ziyaret etsin.","ar":"مَنْ أَحَبَّ أَنْ يُبْسَطَ لَهُ فِي رِزْقِهِ فَلْيَصِلْ رَحِمَهُ"},"src":{"az":"Buxari 5986","en":"Bukhari 5986","ru":"Бухари 5986","tr":"Buhârî 5986","ar":"البخاري 5986"}},{"id":253,"t":{"az":"Heç bir mal mənə Əbu Bəkrin malı qədər fayda vermədi.","en":"No wealth has benefited me as much as Abu Bakr's wealth.","ru":"Никакое богатство не принесло мне столько пользы, сколько богатство Абу Бакра.","tr":"Hiçbir mal bana Ebu Bekir'in malı kadar fayda vermedi.","ar":"مَا نَفَعَنِي مَالٌ قَطُّ مِثْلَ مَا نَفَعَنِي مَالُ أَبِي بَكْرٍ"},"src":{"az":"Tirmizi 3661","en":"Tirmidhi 3661","ru":"Тирмизи 3661","tr":"Tirmizî 3661","ar":"الترمذي 3661"}},{"id":257,"t":{"az":"Müsibətə səbr edənin yerinə Allah daha xeyirlisini verər.","en":"Whoever is patient in affliction, Allah will replace it with something better.","ru":"Кто терпит несчастье, тому Аллах заменит его лучшим.","tr":"Musibete sabredene Allah ondan daha hayırlısını verir.","ar":"مَنْ صَبَرَ عَلَى الْمُصِيبَةِ أَبْدَلَهُ اللَّهُ خَيْراً مِنْهَا"},"src":{"az":"Muslim 918","en":"Muslim 918","ru":"Муслим 918","tr":"Müslim 918","ar":"مسلم 918"}},{"id":267,"t":{"az":"Heç biriniz Rəbbinə həsn zənn etmədən ölməsin.","en":"Let none of you die except while thinking good of his Lord.","ru":"Пусть никто из вас не умирает, не имея хорошего мнения о своём Господе.","tr":"Hiçbiriniz Rabbine hüsnüzan etmeksizin ölmesin.","ar":"لاَ يَمُوتَنَّ أَحَدُكُمْ إِلاَّ وَهُوَ يُحْسِنُ الظَّنَّ بِرَبِّهِ"},"src":{"az":"Muslim 2877","en":"Muslim 2877","ru":"Муслим 2877","tr":"Müslim 2877","ar":"مسلم 2877"}},{"id":269,"t":{"az":"İnsanların ən çox sınağa çəkiləni peyğəmbərlər, sonra dərəcəsinə görə digərləridir.","en":"The people with the greatest trials are the prophets, then those who resemble them in rank.","ru":"Сильнее всего испытывают пророков, затем им подобных по степени.","tr":"İnsanların en çok imtihana tabi tutulanu peygamberler, sonra sırasıyla diğerleridir.","ar":"أَشَدُّ النَّاسِ بَلاَءً الأَنْبِيَاءُ ثُمَّ الأَمْثَلُ فَالأَمْثَلُ"},"src":{"az":"Tirmizi 2398","en":"Tirmidhi 2398","ru":"Тирмизи 2398","tr":"Tirmizî 2398","ar":"الترمذي 2398"}},{"id":278,"t":{"az":"Kim bir mənzilə enəndə \"Auzü bikalimatillahi...\" desə, orada heç nə ona zərər verməz.","en":"Whoever says when stopping \"I seek refuge in Allah's perfect words\" will be protected.","ru":"Кто при остановке скажет \"Прибегаю к совершенным словам Аллаха\", того ничто не потревожит.","tr":"Bir yere konduğunda \"Euzu bikalimatillah...\" diyen, orada hiçbir şeyden zarar görmez.","ar":"إِذَا نَزَلَ الرَّجُلُ مَنْزِلاً فَلْيَقُلْ أَعُوذُ بِكَلِمَاتِ اللَّهِ"},"src":{"az":"Muslim 2708","en":"Muslim 2708","ru":"Муслим 2708","tr":"Müslim 2708","ar":"مسلم 2708"}},{"id":281,"t":{"az":"Kim bir qövmə bənzəyirsə, onlardandır.","en":"Whoever imitates a people is one of them.","ru":"Кто уподобляется какому-то народу, тот из них.","tr":"Kim bir kavme benzerse o kavimdendir.","ar":"مَنْ تَشَبَّهَ بِقَوْمٍ فَهُوَ مِنْهُمْ"},"src":{"az":"Əbu Davud 4031","en":"Abu Dawud 4031","ru":"Абу Дауд 4031","tr":"Ebû Dâvûd 4031","ar":"أبو داود 4031"}},{"id":282,"t":{"az":"Hər doğulan fitrat üzrə doğulur.","en":"Every child is born upon the natural disposition.","ru":"Каждый ребёнок рождается с природной склонностью.","tr":"Her doğan fıtrat üzerine doğar.","ar":"كُلُّ مُولُودٍ يُولَدُ عَلَى الْفِطْرَةِ"},"src":{"az":"Buxari 1358","en":"Bukhari 1358","ru":"Бухари 1358","tr":"Buhârî 1358","ar":"البخاري 1358"}},{"id":284,"t":{"az":"Kim Allaha və axirətə inanırsa, qonşusuna ikram etsin.","en":"Whoever believes in Allah and the Last Day, let him honor his neighbor.","ru":"Кто верует в Аллаха и Судный день, пусть чтит своего соседа.","tr":"Allah'a ve ahiret gününe inanan komşusuna ikramda bulunsun.","ar":"مَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الآخِرِ فَلَيُكْرِمْ جَارَهُ"},"src":{"az":"Buxari 6475","en":"Bukhari 6475","ru":"Бухари 6475","tr":"Buhârî 6475","ar":"البخاري 6475"}},{"id":291,"t":{"az":"Namaz iqaməti verildiydə fərzdən başqa namaz yoxdur.","en":"When prayer is established, there is no prayer except the obligatory.","ru":"Когда установлена молитва, другой молитвы нет, кроме обязательной.","tr":"Namaz ikame edildiğinde farzdan başka namaz yoktur.","ar":"إِذَا أُقِيمَتِ الصَّلاَةُ فَلاَ صَلاَةَ إِلاَّ الْمَكْتُوبَةُ"},"src":{"az":"Muslim 710","en":"Muslim 710","ru":"Муслим 710","tr":"Müslim 710","ar":"مسلم 710"}},{"id":292,"t":{"az":"Münafiqlərə ən ağır olan namaz İşa və Sübh namazlarıdır.","en":"The heaviest prayers upon the hypocrites are Isha and Fajr.","ru":"Самые тяжёлые молитвы для лицемеров — Иша и Фаджр.","tr":"Münafıklara en ağır gelen namaz Yatsı ve Sabah namazlarıdır.","ar":"إِنَّ أَثْقَلَ صَلاَةٍ عَلَى الْمُنَافِقِينَ صَلاَةُ الْعِشَاءِ وَصَلاَةُ الفَجْرِ"},"src":{"az":"Buxari 657","en":"Bukhari 657","ru":"Бухари 657","tr":"Buhârî 657","ar":"البخاري 657"}},{"id":293,"t":{"az":"İki soyuq namazı (Sübh və Əsr) qılan cənnətə girər.","en":"Whoever prays the two cool prayers (Fajr and Asr) will enter Paradise.","ru":"Кто молится две прохладные молитвы (Фаджр и Аср), войдёт в рай.","tr":"İki serin namazı (Sabah ve İkindi) kılan cennete girer.","ar":"مَنْ صَلَّى الْبَرْدَيْنِ دَخَلَ الجَنَّةَ"},"src":{"az":"Buxari 574","en":"Bukhari 574","ru":"Бухари 574","tr":"Buhârî 574","ar":"البخاري 574"}},{"id":294,"t":{"az":"Fərz namazlardan sonra ən fəzilətli namaz gecə namazıdır.","en":"The best prayer after the obligatory is the night prayer.","ru":"Лучшая молитва после обязательной — ночная молитва.","tr":"Farz namazlardan sonra en faziletli namaz gece namazıdır.","ar":"أَفْضَلُ الصَّلاَةِ بَعْدَ الْفَرِيضَةِ صَلاَةُ اللَّيْلِ"},"src":{"az":"Muslim 1163","en":"Muslim 1163","ru":"Муслим 1163","tr":"Müslim 1163","ar":"مسلم 1163"}},{"id":302,"t":{"az":"Peyğəmbərlər dinar, dirhəm miras qoymadılar; ancaq elm miras qoydular.","en":"The prophets left no gold or silver as inheritance; they left knowledge.","ru":"Пророки не оставили в наследство ни динара, ни дирхама; они оставили знание.","tr":"Peygamberler dinar ve dirhem miras bırakmadı; yalnızca ilim bıraktı.","ar":"إِنَّ الأَنْبِيَاءَ لَمْ يُوَرِّثُوا دِينَاراً وَلاَ دِرْهَماً وَإِنَّمَا وَرَّثُوا الْعِلْمَ"},"src":{"az":"Tirmizi 2682","en":"Tirmidhi 2682","ru":"Тирмизи 2682","tr":"Tirmizî 2682","ar":"الترمذي 2682"}},{"id":306,"t":{"az":"Ramazandan sonra Şəvvaldan altı gün oruc ömür boyu oruc kimidir.","en":"Six days of Shawwal after Eid is like fasting the whole year.","ru":"Шесть дней Шавваля после праздника Разговения — как пост всей жизни.","tr":"Bayramdan sonra Şevval'dan altı gün oruç, ömür boyu oruç gibidir.","ar":"سِتَّةٌ مِنْ شَوَّالٍ بَعْدَ الْفِطْرِ كَصِيَامِ الدَّهْرِ"},"src":{"az":"Muslim 1164","en":"Muslim 1164","ru":"Муслим 1164","tr":"Müslim 1164","ar":"مسلم 1164"}},{"id":307,"t":{"az":"Oruçların ən fəziləti Davudun orucu: bir gün tutar, bir gün tutmazdı.","en":"The best fasting is that of Dawud: he fasted one day and broke fast the next.","ru":"Лучший пост — пост Дауда: он постился день и разговлялся день.","tr":"Oruçların en faziletlisi Davud'unkidir: bir gün tutar, bir gün tutmazdı.","ar":"أَفْضَلُ الصِّيَامِ صِيَامُ دَاوُدَ كَانَ يَصُومُ يَوْماً وَيُفْطِرُ يَوْماً"},"src":{"az":"Buxari 1976","en":"Bukhari 1976","ru":"Бухари 1976","tr":"Buhârî 1976","ar":"البخاري 1976"}},{"id":308,"t":{"az":"Oruclu olduğunuzda pis söz danışmayın, hay-küy salmayın.","en":"When one of you is fasting, let him not speak obscenely or make noise.","ru":"Когда один из вас постится, пусть не говорит непристойное и не кричит.","tr":"Biriniz oruçlu olduğunda edepsizce konuşmasın ve bağırmasın.","ar":"إِذَا كَانَ يَوْمُ صَوْمِ أَحَدِكُمْ فَلاَ يَرْفُثْ وَلاَ يَصْخَبْ"},"src":{"az":"Buxari 1904","en":"Bukhari 1904","ru":"Бухари 1904","tr":"Buhârî 1904","ar":"البخاري 1904"}},{"id":310,"t":{"az":"Allahım, Sən əfvedənsən, əfvi sevirsən, məni əfv et.","en":"O Allah, You are the Pardoner and love pardoning, so pardon me.","ru":"О Аллах, Ты Прощающий и любишь прощение, прости меня.","tr":"Allah'ım sen affedicisin, affetmeyi seversin, beni affet.","ar":"اللَّهُمَّ إِنَّكَ عَفُوٌّ تُحِبُّ الْعَفْوَ فَاعْفُ عَنِّي"},"src":{"az":"Tirmizi 3513","en":"Tirmidhi 3513","ru":"Тирмизи 3513","tr":"Tirmizî 3513","ar":"الترمذي 3513"}},{"id":312,"t":{"az":"Kim halal qazancından bir xurma qədər sədəqə versə, Allah onu sağ əli ilə qəbul edər.","en":"Whoever gives a date's worth of charity from pure earnings, Allah accepts it with His right hand.","ru":"Кто подаст милостыню размером с финик из чистого заработка, Аллах примет её Своей правой рукой.","tr":"Kim helal kazancından hurma büyüklüğünde sadaka verirse, Allah onu sağ eliyle kabul eder.","ar":"مَنْ تَصَدَّقَ بِعِدْلِ تَمْرَةٍ مِنْ كَسْبٍ طَيِّبٍ"},"src":{"az":"Buxari 1410","en":"Bukhari 1410","ru":"Бухари 1410","tr":"Buhârî 1410","ar":"البخاري 1410"}},{"id":314,"t":{"az":"Azı verməkdən utanma.","en":"Do not be ashamed of giving little.","ru":"Не стесняйся давать мало.","tr":"Az vermekten utanma.","ar":"لاَ تَسْتَحِي مِنْ إِعْطَاءِ الْقَلِيلِ"},"src":{"az":"Buxari 6024","en":"Bukhari 6024","ru":"Бухари 6024","tr":"Buhârî 6024","ar":"البخاري 6024"}},{"id":316,"t":{"az":"Adıyla yerdə-göydə heç şeyin zərər verə bilmədiyi Allahın adıyla.","en":"In the name of Allah with Whose name nothing in the earth or heaven can cause harm.","ru":"Во имя Аллаха, с именем Которого ничто не вредит ни на земле, ни на небесах.","tr":"Adıyla yerde ve gökte hiçbir şeyin zarar veremeyeceği Allah'ın adıyla.","ar":"بِسْمِ اللَّهِ الَّذِي لاَ يَضُرُّ مَعَ اسْمِهِ شَيْءٌ"},"src":{"az":"Tirmizi 3388","en":"Tirmidhi 3388","ru":"Тирмизи 3388","tr":"Tirmizî 3388","ar":"الترمذي 3388"}},{"id":318,"t":{"az":"Allahım, qayğı, kədər, acizlik, tənbəllik, cəbənlik, buxlluq, borcun ağırlığı və insanların zülmündən Sənə sığınıram.","en":"O Allah, I seek refuge in You from worry, grief, incapacity, laziness, cowardice, miserliness, debt, and people's oppression.","ru":"О Аллах, прибегаю к Тебе от тревоги, печали, немощи, лени, трусости, скупости, долга и притеснения.","tr":"Allah'ım; tasa, keder, acizlik, tembellik, korkaklık, cimrilik, borç ağırlığından ve insanların zulmünden Sana sığınırım.","ar":"اللَّهُمَّ أَعُوذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ"},"src":{"az":"Buxari 2893","en":"Bukhari 2893","ru":"Бухари 2893","tr":"Buhârî 2893","ar":"البخاري 2893"}},{"id":319,"t":{"az":"Məclisdən ayrılarkən bu duanı deyən bağışlanar.","en":"Whoever says this supplication when leaving a gathering will be forgiven.","ru":"Кто произнесёт эту молитву, покидая собрание, будет прощён.","tr":"Meclisten ayrılırken bu duayı okuyan bağışlanır.","ar":"سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ أَشْهَدُ أَنْ لاَ إِلَهَ إِلاَّ أَنْتَ"},"src":{"az":"Tirmizi 3433","en":"Tirmidhi 3433","ru":"Тирмизи 3433","tr":"Tirmizî 3433","ar":"الترمذي 3433"}},{"id":321,"t":{"az":"Kim müsəlmanı örtərsə, Allah onu örtər.","en":"Whoever covers a Muslim, Allah will cover him.","ru":"Кто прикроет мусульманина, того прикроет Аллах.","tr":"Kim bir Müslümanı örterse, Allah onu örter.","ar":"مَنْ سَتَرَ مُسْلِماً سَتَرَهُ اللَّهُ"},"src":{"az":"Buxari 2442","en":"Bukhari 2442","ru":"Бухари 2442","tr":"Buhârî 2442","ar":"البخاري 2442"}},{"id":326,"t":{"az":"Allahı Rəbb, İslamı din, Muhəmmədi Peyğəmbər olaraq razı oldum.","en":"I am content with Allah as Lord, Islam as religion, and Muhammad as Prophet.","ru":"Я доволен Аллахом как Господом, исламом как религией и Мухаммадом как пророком.","tr":"Allah'ı Rab, İslam'ı din, Muhammed'i Peygamber olarak razı oldum.","ar":"رَضِيتُ بِاللَّهِ رَبًّا وَبِالإِسْلاَمِ دِينًا وَبِمُحَمَّدٍ نَبِيًّا"},"src":{"az":"Əbu Davud 1529","en":"Abu Dawud 1529","ru":"Абу Дауд 1529","tr":"Ebû Dâvûd 1529","ar":"أبو داود 1529"}},{"id":327,"t":{"az":"Allahım, müsibətimdə mənə ecir ver, onun yerinə daha xeyirlisini ver.","en":"O Allah, reward me in my affliction and replace it with something better.","ru":"О Аллах, вознагради меня за мою утрату и замени её лучшим.","tr":"Allah'ım, musibetimde bana ecir ver ve ondan daha hayırlısını ver.","ar":"اللَّهُمَّ أَجِرْنِي فِي مُصِيبَتِي وَأَخْلِفْ لِي خَيْراً مِنْهَا"},"src":{"az":"Muslim 918","en":"Muslim 918","ru":"Муслим 918","tr":"Müslim 918","ar":"مسلم 918"}},{"id":338,"t":{"az":"Kim bir salavat gətirsə, Allah on salavat göndərər, on günah silinər.","en":"Whoever sends one blessing upon me, Allah sends ten and removes ten sins.","ru":"Кто благословит меня один раз, Аллах благословит его десятью и снимет десять грехов.","tr":"Kim bana bir salavat getirirse Allah ona on kez rahmet eder ve on günahı silinir.","ar":"مَنْ صَلَّى عَلَيَّ وَاحِدَةً صَلَّى اللَّهُ عَلَيْهِ عَشْراً وَحَطَّ عَنْهُ عَشْرَ خَطِيئَاتٍ"},"src":{"az":"Nəsai 1297","en":"An-Nasa'i 1297","ru":"ан-Насаи 1297","tr":"Nesâî 1297","ar":"النسائي 1297"}},{"id":341,"t":{"az":"Kim Allahla görüşməyi sevsə Allah da onu sevər; kim istəməsə, Allah da istəməz.","en":"Whoever loves to meet Allah, Allah loves to meet him; whoever hates it, Allah hates it.","ru":"Кто желает встречи с Аллахом, Аллах желает встречи с ним; кто не желает — Аллах тоже.","tr":"Kim Allah'a kavuşmayı severse Allah da sever; kim sevmezse Allah da sevmez.","ar":"مَنْ أَحَبَّ لِقَاءَ اللَّهِ أَحَبَّ اللَّهُ لِقَاءَهُ وَمَنْ كَرِهَ لِقَاءَ اللَّهِ كَرِهَ اللَّهُ لِقَاءَهُ"},"src":{"az":"Buxari 6507","en":"Bukhari 6507","ru":"Бухари 6507","tr":"Buhârî 6507","ar":"البخاري 6507"}},{"id":342,"t":{"az":"Şeirdə hikmət vardır.","en":"Indeed, some poetry contains wisdom.","ru":"Воистину, в некоторых стихах есть мудрость.","tr":"Şiirde hikmet vardır.","ar":"إِنَّ مِنَ الشِّعْرِ حِكْمَةً"},"src":{"az":"Buxari 6145","en":"Bukhari 6145","ru":"Бухари 6145","tr":"Buhârî 6145","ar":"البخاري 6145"}},{"id":346,"t":{"az":"Kim məscidə gəlib namazı gözləyirsə, namazdadır.","en":"Whoever comes to the mosque and waits for prayer is in prayer.","ru":"Кто пришёл в мечеть и ожидает молитвы, тот в молитве.","tr":"Mescide gelip namazı bekleyen namaz halindedir.","ar":"مَنْ أَتَى الْمَسْجِدَ فَهُوَ فِي صَلاَةٍ مَا كَانَتِ الصَّلاَةُ تَحْبِسُهُ"},"src":{"az":"Buxari 659","en":"Bukhari 659","ru":"Бухари 659","tr":"Buhârî 659","ar":"البخاري 659"}},{"id":347,"t":{"az":"Dəstəmazı gözəl alıb Cümə namazına gələn, iki Cümə arası günahlar üçün bağışlanma alar.","en":"Whoever makes good ablution then comes to Friday prayer will be forgiven sins between the two Fridays.","ru":"Кто хорошо совершит омовение и придёт на пятничную молитву, тому прощаются грехи между двумя пятницами.","tr":"Abdestini güzel alıp Cuma namazına gelen, iki Cuma arasındaki günahlar için bağışlanır.","ar":"مَنْ تَوَضَّأَ فَأَحْسَنَ وُضُوءَهُ ثُمَّ أَتَى الجُمُعَةَ"},"src":{"az":"Muslim 857","en":"Muslim 857","ru":"Муслим 857","tr":"Müslim 857","ar":"مسلم 857"}},{"id":349,"t":{"az":"Kim Allaha və axirətə inanırsa, qonşusuna əziyyət verməsin.","en":"Whoever believes in Allah and the Last Day should not harm his neighbor.","ru":"Кто верует в Аллаха и Судный день, пусть не причиняет вреда соседу.","tr":"Allah'a ve ahiret gününe inanan komşusuna eziyet etmesin.","ar":"مَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الآخِرِ فَلاَ يُؤْذِ جَارَهُ"},"src":{"az":"Buxari 6018","en":"Bukhari 6018","ru":"Бухари 6018","tr":"Buhârî 6018","ar":"البخاري 6018"}},{"id":350,"t":{"az":"Allahım, Sən Salamsan, Salaəm Səndəndir; ey cəlal və ikram sahibi, Sən yüksəksən.","en":"O Allah, You are Peace and from You comes peace; Blessed are You, O Possessor of glory and honor.","ru":"О Аллах, Ты Мир и от Тебя мир; Благословен Ты, Обладатель величия и щедрости.","tr":"Allah'ım sen Selamsın ve selam Sendendir; ey celal ve ikram sahibi yücesin.","ar":"اللَّهُمَّ أَنْتَ السَّلاَمُ وَمِنْكَ السَّلاَمُ"},"src":{"az":"Muslim 591","en":"Muslim 591","ru":"Муслим 591","tr":"Müslim 591","ar":"مسلم 591"}},{"id":351,"t":{"az":"Allah cisminizə, görünüşünüzə baxmaz; qəlbinizə baxar.","en":"Allah does not look at your bodies or your forms, but He looks at your hearts.","ru":"Аллах смотрит не на тела и лица, а на сердца.","tr":"Allah cisimlerinize ve suretlerinize değil, kalplerinize bakar.","ar":"إِنَّ اللَّهَ لاَ يَنْظُرُ إِلَى أَجْسَامِكُمْ وَلاَ إِلَى صُوَرِكُمْ وَلَكِنْ يَنْظُرُ إِلَى قُلُوبِكُمْ"},"src":{"az":"Muslim 2564","en":"Muslim 2564","ru":"Муслим 2564","tr":"Müslim 2564","ar":"مسلم 2564"}},{"id":353,"t":{"az":"Biriniz bir münkər görsə, onu əliylə dəyişsin; bacarmasa diliylə; bacarmasa qəlbiylə — bu imanın ən zəifidir.","en":"Whoever among you sees an evil, let him change it with his hand; if he cannot, then with his tongue; if he cannot, then with his heart — that is the weakest of faith.","ru":"Кто из вас увидит зло, пусть изменит его рукой; не сможет — языком; не сможет — сердцем — это слабейшая вера.","tr":"Biriniz bir kötülük görürse onu eliyle değiştirsin; yapamazsa diliyle; yapamazsa kalbiyle — bu imanın en zayıfıdır.","ar":"مَنْ رَأَى مِنْكُمْ مُنْكَراً فَلْيُغَيِّرْهُ بِيَدِهِ"},"src":{"az":"Muslim 49","en":"Muslim 49","ru":"Муслим 49","tr":"Müslim 49","ar":"مسلم 49"}},{"id":354,"t":{"az":"Allah gecə əlini uzadır ki, gündüzün günahkar etdiyi tövbə etsin; gündüz uzadır ki, gecənin günahkarı tövbə etsin.","en":"Allah extends His hand at night so that the sinner of the day may repent, and extends it by day so that the sinner of the night may repent.","ru":"Аллах протягивает руку ночью, чтобы кающийся дня мог покаяться, и протягивает днём, чтобы мог покаяться грешник ночи.","tr":"Allah gece elini uzatır ki, gündüzün günahkârı tövbe etsin; gündüz uzatır ki, gecenin günahkârı tövbe etsin.","ar":"إِنَّ اللَّهَ يَبْسُطُ يَدَهُ بِاللَّيْلِ لِيَتُوبَ مُسِيءُ النَّهَارِ"},"src":{"az":"Muslim 2759","en":"Muslim 2759","ru":"Муслим 2759","tr":"Müslim 2759","ar":"مسلم 2759"}},{"id":360,"t":{"az":"Kim sussa, xilas oldu.","en":"Whoever remains silent is saved.","ru":"Кто промолчал — спасся.","tr":"Kim susarsa kurtulur.","ar":"مَنْ صَمَتَ نَجَا"},"src":{"az":"Tirmizi 2501","en":"Tirmidhi 2501","ru":"Тирмизи 2501","tr":"Tirmizî 2501","ar":"الترمذي 2501"}},{"id":361,"t":{"az":"Allaha ən sevimli adlar Abdullah və Abdurrahmandır.","en":"The most beloved names to Allah are Abdullah and Abdurrahman.","ru":"Самые любимые имена у Аллаха — Абдулла и Абдуррахман.","tr":"Allah'a en sevimli isimler Abdullah ve Abdurrahman'dır.","ar":"أَحَبُّ الأَسْمَاءِ إِلَى اللَّهِ عَبْدُ اللَّهِ وَعَبْدُ الرَّحْمَنِ"},"src":{"az":"Muslim 2132","en":"Muslim 2132","ru":"Муслим 2132","tr":"Müslim 2132","ar":"مسلم 2132"}},{"id":365,"t":{"az":"Rəbb gecənin son üçdə birindən daha çox qula yaxındır.","en":"The Lord is closest to the servant in the last part of the night.","ru":"Господь ближе всего к рабу в последнюю треть ночи.","tr":"Rabb, gecenin son üçte birinde kuluna en yakındır.","ar":"أَقْرَبُ مَا يَكُونُ الرَّبُّ مِنَ الْعَبْدِ فِي جَوْفِ اللَّيْلِ الآخِرِ"},"src":{"az":"Tirmizi 3579","en":"Tirmidhi 3579","ru":"Тирмизи 3579","tr":"Tirmizî 3579","ar":"الترمذي 3579"}},{"id":366,"t":{"az":"Gecə qalxdığında iki yüngül rəkətlə başla.","en":"When one of you rises at night, let him begin with two light rak'ahs.","ru":"Когда кто-то из вас встаёт ночью, пусть начинает с двух лёгких рак'атов.","tr":"Biriniz gece kalktığında iki hafif rekâtla başlasın.","ar":"إِذَا قَامَ أَحَدُكُمْ مِنَ اللَّيْلِ فَلْيَفْتَتِحْ صَلاَتَهُ بِرَكْعَتَيْنِ خَفِيفَتَيْنِ"},"src":{"az":"Muslim 768","en":"Muslim 768","ru":"Муслим 768","tr":"Müslim 768","ar":"مسلم 768"}},{"id":367,"t":{"az":"Kim hər fərz namazdan sonra Ayətəl-Kürsü oxusa, onu cənnətdən yalnız ölüm alıkoyar.","en":"Whoever recites Ayat al-Kursi after every obligatory prayer, nothing prevents him from entering Paradise except death.","ru":"Кто читает Аят аль-Курси после каждой обязательной молитвы, тому только смерть мешает войти в рай.","tr":"Her farz namazın ardından Ayetü'l-Kürsi okuyanı cennetten yalnız ölüm alıkoyar.","ar":"مَنْ قَرَأَ آيَةَ الْكُرْسِيِّ فِي دُبُرِ كُلِّ صَلاَةٍ مَكْتُوبَةٍ لَمْ يَمْنَعْهُ مِنَ الجَنَّةِ إِلاَّ أَنْ يَمُوتَ"},"src":{"az":"Nəsai, Sünənül-Kübra 9848","en":"An-Nasa'i, as-Sunan al-Kubra 9848","ru":"ан-Насаи, ас-Сунан аль-Кубра 9848","tr":"Nesâî, es-Sünenü'l-Kübrâ 9848","ar":"النسائي، السنن الكبرى 9848"}},{"id":368,"t":{"az":"Duha namazını qıl; o, Allaha çox dönənlərin namazıdır.","en":"Pray the Duha prayer, for it is the prayer of the oft-returning.","ru":"Молись молитву Духа, ибо это молитва кающихся.","tr":"Duha namazı kıl; zira o, çok tövbe edenlerin namazıdır.","ar":"صَلِّ صَلاَةَ الضُّحَى فَإِنَّهَا صَلاَةُ الأَوَّابِينَ"},"src":{"az":"Muslim 748","en":"Muslim 748","ru":"Муслим 748","tr":"Müslim 748","ar":"مسلم 748"}},{"id":370,"t":{"az":"Dua ibadətin özüdür.","en":"Supplication is worship itself.","ru":"Дуа — это и есть поклонение.","tr":"Dua ibadetin ta kendisidir.","ar":"الدُّعَاءُ هُوَ الْعِبَادَةُ"},"src":{"az":"Tirmizi 2969","en":"Tirmidhi 2969","ru":"Тирмизи 2969","tr":"Tirmizî 2969","ar":"الترمذي 2969"}},{"id":375,"t":{"az":"Quranı oxu; o qiyamət günü sahibinə şəfaət edər.","en":"Recite the Quran; it will come as an intercessor for its owner on the Day of Judgment.","ru":"Читай Коран; он явится заступником своего владельца в День Суда.","tr":"Kur'an oku; o kıyamet günü sahibine şefaatçi olarak gelir.","ar":"اقْرَأِ الْقُرْآنَ فَإِنَّهُ يَأْتِي شَفِيعاً لِأَصْحَابِهِ يَوْمَ الْقِيَامَةِ"},"src":{"az":"Muslim 804","en":"Muslim 804","ru":"Муслим 804","tr":"Müslim 804","ar":"مسلم 804"}},{"id":377,"t":{"az":"Ümmətimdən bir qrup həmişə haqq üzərə qalacaq.","en":"A group from my nation will always fight for the truth, remaining victorious.","ru":"Часть моей уммы всегда будет сражаться за истину, оставаясь победоносной.","tr":"Ümmetimden bir topluluk daima hak üzere savaşıp galip gelmeye devam edecek.","ar":"لاَ تَزَالُ طَائِفَةٌ مِنْ أُمَّتِي يُقَاتِلُونَ عَلَى الحَقِّ ظَاهِرِينَ"},"src":{"az":"Muslim 1920","en":"Muslim 1920","ru":"Муслим 1920","tr":"Müslim 1920","ar":"مسلم 1920"}},{"id":379,"t":{"az":"Kim Allah rızası üçün öyrənilən elmi dünya malı üçün öyrənərsə, qiyamət günü cənnət qoxusunu duymaz.","en":"Whoever learns for worldly gain knowledge that should be sought for Allah's sake will not smell Paradise.","ru":"Кто учит знание, искомое ради Аллаха, ради мирской выгоды, не почует аромата рая.","tr":"Allah rızası için öğrenilmesi gereken ilmi dünya çıkarı için öğrenen, cenneti kokusunu bile duymaz.","ar":"مَنْ تَعَلَّمَ عِلْماً مِمَّا يُبْتَغَى بِهِ وَجْهُ اللَّهِ لاَ يَتَعَلَّمُهُ إِلاَّ لِيُصِيبَ عَرَضاً"},"src":{"az":"Əbu Davud 3664","en":"Abu Dawud 3664","ru":"Абу Дауд 3664","tr":"Ebû Dâvûd 3664","ar":"أبو داود 3664"}},{"id":386,"t":{"az":"Kişinin miras qoyacağı ən xeyirli şey, dua edən saleh övladdır.","en":"The best a person leaves behind is a righteous child who prays for them.","ru":"Лучшее, что оставляет человек после себя — праведный ребёнок, молящийся за него.","tr":"Kişinin bırakacağı en hayırlı şey, dua eden salih bir çocuktur.","ar":"إِنَّ خَيْرَ مَا يُخَلِّفُهُ الرَّجُلُ وَلَدٌ صَالِحٌ يَدْعُو لَهُ"},"src":{"az":"İbn Macə 241","en":"Ibn Majah 241","ru":"Ибн Маджа 241","tr":"İbn Mâce 241","ar":"ابن ماجه 241"}},{"id":387,"t":{"az":"Kim qardaşına ehtiyacında kömək edərsə, Allah da ona ehtiyacında kömək edər.","en":"Whoever helps his brother in his need, Allah will help him in his need.","ru":"Кто помогает брату в его нужде, тому Аллах поможет в его нужде.","tr":"Kim kardeşine ihtiyacında yardım ederse Allah da ona ihtiyacında yardım eder.","ar":"مَنْ أَعَانَ أَخَاهُ فِي حَاجَتِهِ أَعَانَهُ اللَّهُ فِي حَاجَتِهِ"},"src":{"az":"Muslim 2699","en":"Muslim 2699","ru":"Муслим 2699","tr":"Müslim 2699","ar":"مسلم 2699"}},{"id":391,"t":{"az":"Kim gündə yüz dəfə \"La ilaha illallah vahdahu...\" deyərsə, on qul azad etmişdir.","en":"Whoever says \"La ilaha illallah wahdahu...\" a hundred times a day will have the reward of freeing ten slaves.","ru":"Кто скажет сто раз в день \"Нет бога кроме Аллаха единого...\", получит награду освобождения десяти рабов.","tr":"Kim günde yüz kere \"La ilahe illallah vahdahu...\" derse, on köle azat etmiş gibi sevap kazanır.","ar":"مَنْ قَرَأَ لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ مِائَةَ مَرَّةٍ كَانَتْ لَهُ عَدْلُ عَشْرِ رِقَابٍ"},"src":{"az":"Buxari 3293","en":"Bukhari 3293","ru":"Бухари 3293","tr":"Buhârî 3293","ar":"البخاري 3293"}},{"id":393,"t":{"az":"Allahın 99 adı var; kim onları saya bilsə, cənnətə girər.","en":"Allah has 99 names; whoever memorizes them will enter Paradise.","ru":"У Аллаха 99 имён; кто их перечислит, войдёт в рай.","tr":"Allah'ın 99 ismi vardır; bunları bilen cennete girer.","ar":"الأَسْمَاءُ الْحُسْنَى مَنْ أَحْصَاهَا دَخَلَ الجَنَّةَ"},"src":{"az":"Buxari 2736","en":"Bukhari 2736","ru":"Бухари 2736","tr":"Buhârî 2736","ar":"البخاري 2736"}},{"id":395,"t":{"az":"Azan eşidib bu duanı oxuyana qiyamət günü şəfaət.","en":"Whoever says this supplication upon hearing the adhan will receive intercession.","ru":"Кто произносит эту молитву, услышав азан, получит заступничество.","tr":"Ezan duyunca bu duayı okuyana kıyamet günü şefaat var.","ar":"مَنْ قَالَ حِينَ يَسْمَعُ النِّدَاءَ اللَّهُمَّ رَبَّ هَذِهِ الدَّعْوَةِ التَّامَّةِ"},"src":{"az":"Buxari 614","en":"Bukhari 614","ru":"Бухари 614","tr":"Buhârî 614","ar":"البخاري 614"}},{"id":399,"t":{"az":"Özündən və baxdıqlarından başla.","en":"Begin with yourself and those you are responsible for.","ru":"Начни с себя и тех, о ком ты заботишься.","tr":"Kendinden ve bakmakla yükümlü olduklarından başla.","ar":"ابْدَأْ بِنَفْسِكَ وَمَنْ تَعُولُ"},"src":{"az":"Muslim 997","en":"Muslim 997","ru":"Муслим 997","tr":"Müslim 997","ar":"مسلم 997"}},{"id":405,"t":{"az":"Müsəlmana üzüntü, yorğunluq, xəstəlik, kədər, əziyyət, qəm nə gəlsə — hətta bir tikan batması belə — Allah onunla günahlarını silər.","en":"No hardship, fatigue, illness, grief, harm, or worry befalls a Muslim — even a thorn — except that Allah expiates sins through it.","ru":"Ничто из страданий, усталости, болезни, горя, вреда и тревоги не постигает мусульманина — даже укол шипа — без того чтобы Аллах не простил ему грехи.","tr":"Yorgunluk, hastalık, keder, eziyet, tasa, hatta bir diken batması bile olsa, Allah bununla Müslümanın günahlarını siler.","ar":"مَا يُصِيبُ الْمُسْلِمَ مِنْ وَصَبٍ وَلاَ نَصَبٍ وَلاَ سَقَمٍ وَلاَ حَزَنٍ وَلاَ أَذىً وَلاَ غَمٍّ حَتَّى الشَّوْكَةَ يُشَاكُهَا إِلاَّ كَفَّرَ اللَّهُ بِهَا مِنْ خَطَايَاهُ"},"src":{"az":"Buxari 5641","en":"Bukhari 5641","ru":"Бухари 5641","tr":"Buhârî 5641","ar":"البخاري 5641"}},{"id":407,"t":{"az":"Allah güclü mömini sevər, hər birindən xeyir var.","en":"Allah loves the strong believer, and in each there is good.","ru":"Аллах любит сильного верующего, и в каждом есть благо.","tr":"Allah güçlü mü'mini sever ve her birinde hayır vardır.","ar":"إِنَّ اللَّهَ يُحِبُّ الْمُؤْمِنَ الْقَوِيَّ وَفِي كُلٍّ خَيْرٌ"},"src":{"az":"Muslim 2664","en":"Muslim 2664","ru":"Муслим 2664","tr":"Müslim 2664","ar":"مسلم 2664"}},{"id":411,"t":{"az":"Cənnət əhli yuxarı mərtəbəlilərə ulduzlara baxdıqları kimi baxar.","en":"The people of Paradise will see the people of the lofty rooms as you see stars.","ru":"Обитатели рая будут смотреть на жителей высоких покоев так же, как смотрят на звёзды.","tr":"Cennet ehli üst odalardakilere yıldızlara bakar gibi bakacaklar.","ar":"إِنَّ أَهْلَ الجَنَّةِ يَتَرَاءَوْنَ أَهْلَ الغُرَفِ"},"src":{"az":"Buxari 3256","en":"Bukhari 3256","ru":"Бухари 3256","tr":"Buhârî 3256","ar":"البخاري 3256"}},{"id":415,"t":{"az":"Cənnətə yalnız müsəlman ruhu girər.","en":"None will enter Paradise except a Muslim soul.","ru":"В рай войдёт только мусульманская душа.","tr":"Cennete ancak Müslüman bir can girer.","ar":"لاَ تَدْخُلُ الجَنَّةَ إِلاَّ نَفْسٌ مُسْلِمَةٌ"},"src":{"az":"Buxari 1792","en":"Bukhari 1792","ru":"Бухари 1792","tr":"Buhârî 1792","ar":"البخاري 1792"}},{"id":418,"t":{"az":"Mənə çox salavat göndərin; harada olsanız salavat mənə çatar.","en":"Send much blessings upon me; your blessings reach me wherever you are.","ru":"Чаще благословляйте меня; ваши молитвы достигают меня, где бы вы ни были.","tr":"Bana çokça salavat getirin; nerede olursanız salavat bana ulaşır.","ar":"أَكْثِرُوا الصَّلاَةَ عَلَيَّ فَإِنَّ صَلاَتَكُمْ تَبْلُغُنِي حَيْثُمَا كُنْتُمْ"},"src":{"az":"Əbu Davud 2042","en":"Abu Dawud 2042","ru":"Абу Дауд 2042","tr":"Ebû Dâvûd 2042","ar":"أبو داود 2042"}},{"id":420,"t":{"az":"Evdən çıxanda \"Bismillah, Allaha təvəkkül etdim\" de.","en":"When you leave your house say \"Bismillah, I put my trust in Allah.\"","ru":"Когда выходишь из дома, говори: \"С именем Аллаха, уповаю на Аллаха.\"","tr":"Evden çıktığında \"Bismillah, Allah'a tevekkül ettim\" de.","ar":"إِذَا خَرَجَ الرَّجُلُ مِنْ بَيْتِهِ فَلْيَقُلْ بِسْمِ اللَّهِ تَوَكَّلْتُ عَلَى اللَّهِ"},"src":{"az":"Tirmizi 3426","en":"Tirmidhi 3426","ru":"Тирмизи 3426","tr":"Tirmizî 3426","ar":"الترمذي 3426"}},{"id":423,"t":{"az":"İnsanlardan qorxmaq heç birinizi haqqı söyləməkdən alıkoymasın.","en":"Let not fear of people prevent any of you from speaking the truth.","ru":"Страх перед людьми не должен удерживать никого от того, чтобы говорить правду.","tr":"İnsanlardan korku hiçbirinizi hakkı söylemekten alıkoymasın.","ar":"لاَ يَمْنَعَنَّ أَحَدَكُمْ مَخَافَةُ النَّاسِ أَنْ يَقُولَ حَقًّا"},"src":{"az":"İbn Macə 4007","en":"Ibn Majah 4007","ru":"Ибн Маджа 4007","tr":"İbn Mâce 4007","ar":"ابن ماجه 4007"}},{"id":425,"t":{"az":"Doğruluq yaxşılığa aparar, yaxşılıq da cənnətə.","en":"Truthfulness leads to righteousness, and righteousness leads to Paradise.","ru":"Правдивость ведёт к добродетели, а добродетель ведёт в рай.","tr":"Doğruluk iyiliğe, iyilik de cennete götürür.","ar":"إِنَّ الصِّدْقَ يَهْدِي إِلَى الْبِرِّ وَإِنَّ الْبِرَّ يَهْدِي إِلَى الجَنَّةِ"},"src":{"az":"Buxari 6094","en":"Bukhari 6094","ru":"Бухари 6094","tr":"Buhârî 6094","ar":"البخاري 6094"}},{"id":426,"t":{"az":"İman Mədinəyə yılanın yuvasına sığındığı kimi sığınır.","en":"Faith will gather in Medina as a snake retreats to its hole.","ru":"Вера соберётся в Медине, как змея уходит в нору.","tr":"İman Medine'ye, yılanın yuvasına çekilmesi gibi çekilir.","ar":"إِنَّ الإِيمَانَ لَيَأْرِزُ إِلَى الْمَدِينَةِ كَمَا تَأْرِزُ الْحَيَّةُ إِلَى جُحْرِهَا"},"src":{"az":"Buxari 1876","en":"Bukhari 1876","ru":"Бухари 1876","tr":"Buhârî 1876","ar":"البخاري 1876"}},{"id":431,"t":{"az":"Allah hər işdə yumşaqlığı sevir.","en":"Allah loves gentleness in all matters.","ru":"Аллах любит мягкость во всех делах.","tr":"Allah her işte yumuşaklığı sever.","ar":"إِنَّ اللَّهَ يُحِبُّ الرِّفْقَ فِي الأَمْرِ كُلِّهِ"},"src":{"az":"Buxari 6024","en":"Bukhari 6024","ru":"Бухари 6024","tr":"Buhârî 6024","ar":"البخاري 6024"}},{"id":432,"t":{"az":"Yumşaqlıqdan məhrum olan xeyirdən məhrum olur.","en":"Whoever is deprived of gentleness is deprived of good.","ru":"Кто лишён мягкости, тот лишён блага.","tr":"Yumuşaklıktan mahrum olan hayırdan mahrum olur.","ar":"مَنْ حُرِمَ الرِّفْقَ حُرِمَ الْخَيْرَ"},"src":{"az":"Muslim 2592","en":"Muslim 2592","ru":"Муслим 2592","tr":"Müslim 2592","ar":"مسلم 2592"}},{"id":433,"t":{"az":"Kim Fəcri dərk edərsə, namazı dərk etmişdir.","en":"Whoever catches Fajr has caught the prayer.","ru":"Кто успел на Фаджр, тот успел на молитву.","tr":"Kim Fecri yakalamışsa namazı yakalamış demektir.","ar":"مَنْ أَدْرَكَ الْفَجْرَ فَقَدْ أَدْرَكَ الصَّلاَةَ"},"src":{"az":"Muslim 608","en":"Muslim 608","ru":"Муслим 608","tr":"Müslim 608","ar":"مسلم 608"}},{"id":436,"t":{"az":"Fərzdən başqa ən fəzilətli namaz evdə qılınan namazdır.","en":"The best prayer you can perform is praying in your home, except for the obligatory.","ru":"Лучшая молитва — та, что совершается дома, за исключением обязательной.","tr":"Farz dışında kılacağın en faziletli namaz evinde kıldığındır.","ar":"أَفْضَلُ صَلاَةٍ تُصَلِّيهَا أَنْ تُصَلِّيَهَا فِي بَيْتِكَ إِلاَّ الْمَكْتُوبَةَ"},"src":{"az":"Buxari 731","en":"Bukhari 731","ru":"Бухари 731","tr":"Buhârî 731","ar":"البخاري 731"}},{"id":440,"t":{"az":"İmamla namaz tək başına iyirmi beş namazdan üstündür.","en":"Prayer with the imam is superior to twenty-five prayers prayed alone.","ru":"Молитва с имамом превосходит двадцать пять молитв, совершённых в одиночестве.","tr":"İmamla namaz, tek başına kılınan yirmi beş namazdan üstündür.","ar":"إِنَّ الصَّلاَةَ مَعَ الإِمَامِ أَفْضَلُ مِنْ خَمْسٍ وَعِشْرِينَ صَلاَةً يُصَلِّيهَا وَحْدَهُ"},"src":{"az":"Buxari 645","en":"Bukhari 645","ru":"Бухари 645","tr":"Buhârî 645","ar":"البخاري 645"}},{"id":442,"t":{"az":"Quranı bir ayda oxu.","en":"Recite the Quran in one month.","ru":"Читай Коран за один месяц.","tr":"Kur'an'ı bir ayda oku.","ar":"اقْرَأِ الْقُرْآنَ فِي شَهْرٍ"},"src":{"az":"Buxari 5054","en":"Bukhari 5054","ru":"Бухари 5054","tr":"Buhârî 5054","ar":"البخاري 5054"}},{"id":446,"t":{"az":"Allah qulunun xeyrini istəsə, ölümündən əvvəl onu işlədər.","en":"When Allah desires good for a servant, He employs him before his death.","ru":"Когда Аллах желает блага для раба, Он использует его до смерти.","tr":"Allah bir kulu için hayır dilediğinde onu ölmeden önce (iyilik için) çalıştırır.","ar":"إِذَا أَرَادَ اللَّهُ بِعَبْدٍ خَيْراً اسْتَعْمَلَهُ قَبْلَ مَوْتِهِ"},"src":{"az":"Buxari 7165","en":"Bukhari 7165","ru":"Бухари 7165","tr":"Buhârî 7165","ar":"البخاري 7165"}},{"id":451,"t":{"az":"Kim Ramazanı tutub ardından Şəvvaldan altı gün tutarsa, ömür boyu oruc kimi.","en":"Whoever fasts Ramadan and follows it with six days of Shawwal is as if he fasted the whole year.","ru":"Кто постится в Рамадан, а потом шесть дней Шавваля — словно постился весь год.","tr":"Ramazan orucunu tutup ardından Şevval'dan altı gün tutan ömür boyu oruç tutmuş gibi olur.","ar":"مَنْ صَامَ رَمَضَانَ وَأَتْبَعَهُ سِتًّا مِنْ شَوَّالٍ كَانَ كَصِيَامِ الدَّهْرِ"},"src":{"az":"Muslim 1164","en":"Muslim 1164","ru":"Муслим 1164","tr":"Müslim 1164","ar":"مسلم 1164"}},{"id":456,"t":{"az":"Yoxsula sədəqə bir sədəqədir; qohuma isə iki sədəqədir — sədəqə və sileyi-rəhm.","en":"Charity to the poor is one charity; charity to a relative is two — charity and maintaining ties.","ru":"Садака бедному — одна садака; родственнику — две: садака и поддержание связи.","tr":"Yoksulla sadaka bir sadakadır; akrabaya iki sadakadır — sadaka ve sıla-i rahim.","ar":"الصَّدَقَةُ عَلَى الْمِسْكِينِ صَدَقَةٌ وَهِيَ عَلَى ذِي الرَّحِمِ اثْنَتَانِ"},"src":{"az":"Nəsai 2582","en":"An-Nasa'i 2582","ru":"ан-Насаи 2582","tr":"Nesâî 2582","ar":"النسائي 2582"}},{"id":457,"t":{"az":"İşçiyə teri qurumazdan öncə haqqını ver.","en":"Give the worker his wages before his sweat dries.","ru":"Дай работнику его жалованье, пока не высох его пот.","tr":"İşçiye teri kurumadan ücretini ver.","ar":"أَعْطِ الأَجِيرَ أَجْرَهُ قَبْلَ أَنْ يَجِفَّ عَرَقُهُ"},"src":{"az":"İbn Macə 2443","en":"Ibn Majah 2443","ru":"Ибн Маджа 2443","tr":"İbn Mâce 2443","ar":"ابن ماجه 2443"}},{"id":458,"t":{"az":"Biriniz qardaşına fayda verə bilərsə, versin.","en":"Whoever among you is able to benefit his brother, let him do so.","ru":"Кто из вас может принести пользу своему брату, пусть сделает это.","tr":"Biriniz kardeşine fayda verebiliyorsa, versin.","ar":"مَنِ اسْتَطَاعَ مِنْكُمْ أَنْ يَنْفَعَ أَخَاهُ فَلْيَنْفَعْهُ"},"src":{"az":"Muslim 2199","en":"Muslim 2199","ru":"Муслим 2199","tr":"Müslim 2199","ar":"مسلم 2199"}},{"id":459,"t":{"az":"Ən fəzilətli sədəqə azı olanın verdiyi gücdür.","en":"The best charity is the effort of the one who has little.","ru":"Лучшая садака — это усилие того, у кого мало.","tr":"En faziletli sadaka, azı olanın verdiği gayreti.","ar":"أَفْضَلُ الصَّدَقَةِ جُهْدُ الْمُقِلِّ"},"src":{"az":"Əbu Davud 1677","en":"Abu Dawud 1677","ru":"Абу Дауд 1677","tr":"Ebû Dâvûd 1677","ar":"أبو داود 1677"}},{"id":460,"t":{"az":"Biriniz insanlardan mal istəməsin.","en":"Let none of you ask people for their wealth.","ru":"Пусть никто из вас не просит у людей их имущество.","tr":"Hiçbiriniz insanlardan mal istemesin.","ar":"لاَ يَسْأَلُ أَحَدُكُمُ النَّاسَ مَالَهُمْ"},"src":{"az":"Muslim 1043","en":"Muslim 1043","ru":"Муслим 1043","tr":"Müslim 1043","ar":"مسلم 1043"}},{"id":463,"t":{"az":"\"Subhanallah\" və \"Alhamdulillah\" göylə yer arasını doldurur.","en":"\"SubhanAllah\" and \"Alhamdulillah\" fill what is between the heaven and the earth.","ru":"\"Пречист Аллах\" и \"Хвала Аллаху\" наполняют то, что между небом и землёй.","tr":"\"Sübhanallah\" ve \"Elhamdülillah\" gök ile yer arasını doldurur.","ar":"سُبْحَانَ اللَّهِ وَالْحَمْدُ لِلَّهِ تَمْلآنِ مَا بَيْنَ السَّمَاءِ وَالأَرْضِ"},"src":{"az":"Muslim 223","en":"Muslim 223","ru":"Муслим 223","tr":"Müslim 223","ar":"مسلم 223"}},{"id":464,"t":{"az":"Kim \"Allahı Rəbb olaraq qəbul etdim\" deyərsə, cənnət vacib olur.","en":"Whoever says \"I am pleased with Allah as my Lord,\" Paradise is obligatory for him.","ru":"Кто скажет \"Я доволен Аллахом как Господом\", тому становится обязательным рай.","tr":"\"Allah'ı Rab olarak razı oldum\" diyen için cennet vacip olur.","ar":"مَنْ قَالَ رَضِيتُ بِاللَّهِ رَبًّا وَجَبَتْ لَهُ الجَنَّةُ"},"src":{"az":"Əbu Davud 1529","en":"Abu Dawud 1529","ru":"Абу Дауд 1529","tr":"Ebû Dâvûd 1529","ar":"أبو داود 1529"}},{"id":467,"t":{"az":"Kim müsəlman qardaşının eyblərini örtərsə, Allah da qiyamət günü onun eybini örtər.","en":"Whoever covers the faults of his Muslim brother, Allah will cover his faults on the Day of Judgment.","ru":"Кто скроет недостатки своего мусульманского брата, того Аллах скроет в День Суда.","tr":"Kim Müslüman kardeşinin ayıplarını örterse, Allah da kıyamet günü onun ayıplarını örter.","ar":"مَنْ سَتَرَ عَوْرَةَ أَخِيهِ الْمُسْلِمِ سَتَرَ اللَّهُ عَوْرَتَهُ يَوْمَ الْقِيَامَةِ"},"src":{"az":"İbn Macə 2546","en":"Ibn Majah 2546","ru":"Ибн Маджа 2546","tr":"İbn Mâce 2546","ar":"ابن ماجه 2546"}},{"id":468,"t":{"az":"Ot üzərindəki mülkiyyəti qorumaq üçün artıq suyu saxlamayın.","en":"Do not withhold surplus water in order to prevent others from pasturing.","ru":"Не удерживайте излишки воды, чтобы тем самым не лишать других пастбища.","tr":"Otlağı engellemek için fazla suyu engellemeyin.","ar":"لاَ تَمْنَعُوا فَضْلَ الْمَاءِ لِتَمْنَعُوا بِهِ الكَلأَ"},"src":{"az":"Buxari 2353","en":"Bukhari 2353","ru":"Бухари 2353","tr":"Buhârî 2353","ar":"البخاري 2353"}},{"id":474,"t":{"az":"Allaha layiqincə təvəkkül edin.","en":"Put your trust in Allah as He deserves to be trusted.","ru":"Уповайте на Аллаха, как Он того заслуживает.","tr":"Allah'a hakkıyla tevekkül edin.","ar":"تَوَكَّلُوا عَلَى اللَّهِ حَقَّ تَوَكُّلِهِ"},"src":{"az":"Tirmizi 2344","en":"Tirmidhi 2344","ru":"Тирмизи 2344","tr":"Tirmizî 2344","ar":"الترمذي 2344"}},{"id":480,"t":{"az":"Qiyamət günü ən şiddətli əzaba uğrayanlar Allahın yaratdıqlarına bənzər şeylər düzəldənlərdir.","en":"Among the most severely punished on the Day of Judgment will be those who imitate Allah's creation.","ru":"Среди сильнее всего наказанных в День Суда будут те, кто подражает творению Аллаха.","tr":"Kıyamet günü en şiddetli azabı görecekler arasında Allah'ın yaratığına benzeyenler vardır.","ar":"إِنَّ مِنْ أَشَدِّ النَّاسِ عَذَاباً يَوْمَ الْقِيَامَةِ الَّذِينَ يُشَبِّهُونَ بِخَلْقِ اللَّهِ"},"src":{"az":"Buxari 5954","en":"Bukhari 5954","ru":"Бухари 5954","tr":"Buhârî 5954","ar":"البخاري 5954"}},{"id":481,"t":{"az":"Kim bir şey üzərə ölsə, Allah onu o şey üzərə dirildər.","en":"Whoever dies upon something, Allah will resurrect him upon it.","ru":"Кто умрёт в каком-то состоянии, Аллах воскресит его в этом состоянии.","tr":"Kim bir şey üzere ölürse Allah onu o şey üzere diriltir.","ar":"مَنْ مَاتَ عَلَى شَيْءٍ بَعَثَهُ اللَّهُ عَلَيْهِ"},"src":{"az":"Muslim 2878","en":"Muslim 2878","ru":"Муслим 2878","tr":"Müslim 2878","ar":"مسلم 2878"}},{"id":484,"t":{"az":"Ləzzətləri kəsəni — yəni ölümü — çox xatırlayın.","en":"Increase your remembrance of the destroyer of pleasures — death.","ru":"Чаще поминайте сокрушителя наслаждений — то есть смерть.","tr":"Lezzetleri yıkanı — yani ölümü — çokça hatırlayın.","ar":"أَكْثِرُوا ذِكْرَ هَاذِمِ اللَّذَّاتِ يَعْنِي الْمَوْتَ"},"src":{"az":"Tirmizi 2307","en":"Tirmidhi 2307","ru":"Тирмизи 2307","tr":"Tirmizî 2307","ar":"الترمذي 2307"}},{"id":485,"t":{"az":"Ölü üzərindəki fəryad ucundna qəbirdə əzab çəkər.","en":"The deceased is punished in the grave due to wailing over him.","ru":"Умерший мучается в могиле из-за причитаний над ним.","tr":"Ölü, üzerine yapılan ağıt nedeniyle kabrinde azap çeker.","ar":"الْمَيِّتُ يُعَذَّبُ فِي قَبْرِهِ بِالنِّيَاحَةِ عَلَيْهِ"},"src":{"az":"Buxari 1292","en":"Bukhari 1292","ru":"Бухари 1292","tr":"Buhârî 1292","ar":"البخاري 1292"}},{"id":489,"t":{"az":"Dua etdikdə Allaha həmddən, Peyğəmbərə salavatdan başla.","en":"When you supplicate, begin with praise of Allah and blessings upon the Prophet.","ru":"Когда молишься, начни с восхваления Аллаха и благословения Пророка.","tr":"Dua ettiğinde Allah'a hamdle ve Peygambere salavatla başla.","ar":"إِذَا دَعَوْتَ فَابْدَأْ بِالثَّنَاءِ عَلَى اللَّهِ وَالصَّلاَةِ عَلَى النَّبِيِّ"},"src":{"az":"Tirmizi 3477","en":"Tirmidhi 3477","ru":"Тирмизи 3477","tr":"Tirmizî 3477","ar":"الترمذي 3477"}},{"id":494,"t":{"az":"Qonaq ağırlamaq hər müsəlmana vacib haqdır.","en":"Hospitality is a right obligatory upon every Muslim.","ru":"Гостеприимство — право, обязательное для каждого мусульманина.","tr":"Misafirperverlik her Müslümana vacip bir haktır.","ar":"الضِّيَافَةُ حَقٌّ وَاجِبٌ عَلَى كُلِّ مُسْلِمٍ"},"src":{"az":"Buxari 6135","en":"Bukhari 6135","ru":"Бухари 6135","tr":"Buhârî 6135","ar":"البخاري 6135"}},{"id":496,"t":{"az":"Ən xeyirliniz xeyri umulan, şərindən əmin olunandır.","en":"The best of you is the one from whom good is expected and whose evil is safe from.","ru":"Лучший из вас тот, от кого ожидают блага и от кого в безопасности от вреда.","tr":"En hayırlınız hayrı umulan, şerrinden emin olunan kişidir.","ar":"خَيْرُكُمْ مَنْ يُرْجَى خَيْرُهُ وَيُؤْمَنُ شَرُّهُ"},"src":{"az":"Tirmizi 2263","en":"Tirmidhi 2263","ru":"Тирмизи 2263","tr":"Tirmizî 2263","ar":"الترمذي 2263"}},{"id":497,"t":{"az":"Sizə Allahdan qorxmağı, dinləməyi və itaəti tövsiyə edirəm.","en":"I urge you to have taqwa of Allah and to listen and obey.","ru":"Завещаю вам богобоязненность, слушание и повиновение.","tr":"Size Allah'tan korkmayı, dinlemeyi ve itaat etmeyi tavsiye ederim.","ar":"أُوصِيكُمْ بِتَقْوَى اللَّهِ وَالسَّمْعِ وَالطَّاعَةِ"},"src":{"az":"Tirmizi 2676","en":"Tirmidhi 2676","ru":"Тирмизи 2676","tr":"Tirmizî 2676","ar":"الترمذي 2676"}},{"id":502,"t":{"az":"Allahdan başqa ilah olmadığına və Muhəmmədin Onun qulu və elçisi olduğuna şəhadət edən qula Allah cəhənnəmi haram edər.","en":"No servant testifies that there is no god but Allah and Muhammad is His servant and messenger except that Allah makes the Fire forbidden for him.","ru":"Любой раб, засвидетельствовавший, что нет бога кроме Аллаха и Мухаммад — Его раб и посланник, Аллах сделает для него огонь запретным.","tr":"Allah'tan başka ilah olmadığına ve Muhammed'in O'nun kulu ve elçisi olduğuna şehadet eden her kula Allah cehennemi haram kılar.","ar":"مَا مِنْ عَبْدٍ يَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ إِلَّا حَرَّمَهُ اللَّهُ عَلَى النَّارِ"},"src":{"az":"Muslim 29","en":"Muslim 29","ru":"Муслим 29","tr":"Müslim 29","ar":"مسلم 29"}},{"id":503,"t":{"az":"Qəlbində bir arpa dənəsi qədər xeyir olub \"La ilahə illəllah\" deyən cəhənnəmdən çıxar.","en":"Whoever said \"There is no god but Allah\" and has in his heart goodness the weight of a grain of barley will come out of the Fire.","ru":"Выйдет из огня тот, кто сказал «Нет бога, кроме Аллаха» и в сердце которого есть добро весом с ячменное зёрнышко.","tr":"Kalbinde bir arpa ağırlığında hayır olup da \"La ilahe illallah\" diyen cehennemden çıkar.","ar":"يَخْرُجُ مِنَ النَّارِ مَنْ قَالَ لَا إِلَهَ إِلَّا اللَّهُ وَفِي قَلْبِهِ وَزْنُ شَعِيرَةٍ مِنْ خَيْرٍ"},"src":{"az":"Buxari 44","en":"Bukhari 44","ru":"Бухари 44","tr":"Buhârî 44","ar":"البخاري 44"}},{"id":505,"t":{"az":"Allaha and olsun, iman etməz! Qonşusu onun şərindən əmin olmayan kəs.","en":"By Allah, he does not believe! The one whose neighbor is not safe from his harm.","ru":"Клянусь Аллахом, не уверовал тот, чей сосед не чувствует себя в безопасности от его вреда!","tr":"Vallahi iman etmiş olmaz! Komşusu şerrinden emin olmayan kişi.","ar":"وَاللَّهِ لَا يُؤْمِنُ وَاللَّهِ لَا يُؤْمِنُ وَاللَّهِ لَا يُؤْمِنُ قِيلَ مَنْ يَا رَسُولَ اللَّهِ قَالَ الَّذِي لَا يَأْمَنُ جَارُهُ بَوَائِقَهُ"},"src":{"az":"Buxari 6016","en":"Bukhari 6016","ru":"Бухари 6016","tr":"Buhârî 6016","ar":"البخاري 6016"}},{"id":508,"t":{"az":"Kim Allaha və axirət gününə inanırsa, qonağına ikram etsin.","en":"Whoever believes in Allah and the Last Day, let him honor his guest.","ru":"Кто верует в Аллаха и Последний день, пусть почитает своего гостя.","tr":"Allah'a ve ahiret gününe iman eden misafirine ikram etsin.","ar":"مَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ فَلْيُكْرِمْ ضَيْفَهُ"},"src":{"az":"Buxari 6136","en":"Bukhari 6136","ru":"Бухари 6136","tr":"Buhârî 6136","ar":"البخاري 6136"}},{"id":509,"t":{"az":"Qonşusu şərindən əmin olmayan cənnətə girməz.","en":"He whose neighbor is not safe from his harm will not enter Paradise.","ru":"Не войдёт в рай тот, чей сосед не чувствует себя в безопасности от его зла.","tr":"Komşusu şerrinden emin olmayan kişi cennete giremez.","ar":"لَا يَدْخُلُ الْجَنَّةَ مَنْ لَا يَأْمَنُ جَارُهُ بَوَائِقَهُ"},"src":{"az":"Muslim 46","en":"Muslim 46","ru":"Муслим 46","tr":"Müslim 46","ar":"مسلم 46"}},{"id":510,"t":{"az":"Qəlbində zərrə qədər təkəbbür olan cənnətə girməz.","en":"No one who has the weight of an atom of arrogance in his heart will enter Paradise.","ru":"Не войдёт в рай тот, в чьём сердце есть высокомерие весом с пылинку.","tr":"Kalbinde zerre kadar kibir olan cennete giremez.","ar":"لَا يَدْخُلُ الْجَنَّةَ مَنْ كَانَ فِي قَلْبِهِ مِثْقَالُ ذَرَّةٍ مِنْ كِبْرٍ"},"src":{"az":"Muslim 91","en":"Muslim 91","ru":"Муслим 91","tr":"Müslim 91","ar":"مسلم 91"}},{"id":511,"t":{"az":"Ən xeyirliniz əxlaqı ən gözəl olanıdır.","en":"The best among you are those with the best character.","ru":"Лучшие из вас — обладающие лучшим нравом.","tr":"En hayırlınız ahlakı en güzel olanınızdır.","ar":"إِنَّ مِنْ خِيَارِكُمْ أَحَاسِنَكُمْ أَخْلَاقًا"},"src":{"az":"Buxari 3559","en":"Bukhari 3559","ru":"Бухари 3559","tr":"Buhârî 3559","ar":"البخاري 3559"}},{"id":512,"t":{"az":"Yaxşılıq gözəl əxlaqdır.","en":"Righteousness is good character.","ru":"Благочестие — это хороший нрав.","tr":"İyilik güzel ahlaktır.","ar":"الْبِرُّ حُسْنُ الْخُلُقِ"},"src":{"az":"Muslim 2553","en":"Muslim 2553","ru":"Муслим 2553","tr":"Müslim 2553","ar":"مسلم 2553"}},{"id":514,"t":{"az":"Yalan günahkarlığa, günahkarlıq isə cəhənnəmə aparır.","en":"Lying leads to wickedness and wickedness leads to the Fire.","ru":"Ложь ведёт к нечестию, а нечестие ведёт в огонь.","tr":"Yalan kötülüğe, kötülük de cehenneme götürür.","ar":"وَإِنَّ الْكَذِبَ يَهْدِي إِلَى الْفُجُورِ وَإِنَّ الْفُجُورَ يَهْدِي إِلَى النَّارِ"},"src":{"az":"Buxari 6094","en":"Bukhari 6094","ru":"Бухари 6094","tr":"Buhârî 6094","ar":"البخاري 6094"}},{"id":515,"t":{"az":"Yumşaqlıq nəyə girərsə onu gözəlləşdirər, nədən çıxarsa onu çirkinləşdirər.","en":"Gentleness beautifies everything it is part of and uglifies everything it is removed from.","ru":"Мягкость украшает всё, в чём присутствует, и портит всё, из чего удалена.","tr":"Yumuşaklık bir şeyde bulunursa onu güzelleştirir, bir şeyden çekilirse onu çirkinleştirir.","ar":"مَا كَانَ الرِّفْقُ فِي شَيْءٍ إِلَّا زَانَهُ وَمَا نُزِعَ مِنْ شَيْءٍ إِلَّا شَانَهُ"},"src":{"az":"Muslim 2594","en":"Muslim 2594","ru":"Муслим 2594","tr":"Müslim 2594","ar":"مسلم 2594"}},{"id":517,"t":{"az":"Sui-zəndən çəkinin, çünki sui-zən sözlərin ən yalanıdır.","en":"Beware of suspicion, for suspicion is the most lying form of speech.","ru":"Остерегайтесь подозрений, ибо подозрение — самая лживая речь.","tr":"Zandan sakının, çünkü zan sözlerin en yalanıdır.","ar":"إِيَّاكُمْ وَالظَّنَّ فَإِنَّ الظَّنَّ أَكْذَبُ الْحَدِيثِ"},"src":{"az":"Buxari 6064","en":"Bukhari 6064","ru":"Бухари 6064","tr":"Buhârî 6064","ar":"البخاري 6064"}},{"id":518,"t":{"az":"Həsəd aparmayın, bir-birinizə nifrət etməyin, arxa çevirməyin.","en":"Do not envy each other, do not hate each other, do not turn away from each other.","ru":"Не завидуйте друг другу, не ненавидьте друг друга, не отворачивайтесь друг от друга.","tr":"Birbirinize haset etmeyin, buğz etmeyin, sırt çevirmeyin.","ar":"لَا تَحَاسَدُوا وَلَا تَنَاجَشُوا وَلَا تَبَاغَضُوا وَلَا تَدَابَرُوا"},"src":{"az":"Muslim 2564","en":"Muslim 2564","ru":"Муслим 2564","tr":"Müslim 2564","ar":"مسلم 2564"}},{"id":523,"t":{"az":"Namazın açarı dəstəmazdır, başlanğıcı təkbirdir, bitişi salamdır.","en":"The key to prayer is purification, its beginning is takbir, and its end is taslim.","ru":"Ключ к молитве — очищение, её начало — такбир, её завершение — таслим.","tr":"Namazın anahtarı abdest, başlangıcı tekbir, bitişi selamdır.","ar":"مِفْتَاحُ الصَّلَاةِ الطُّهُورُ وَتَحْرِيمُهَا التَّكْبِيرُ وَتَحْلِيلُهَا التَّسْلِيمُ"},"src":{"az":"Əbu Davud 61","en":"Abu Dawud 61","ru":"Абу Дауд 61","tr":"Ebû Dâvûd 61","ar":"أبو داود 61"}},{"id":527,"t":{"az":"Qiyamət günü qulun hesab verəcəyi ilk əməli namazdır.","en":"The first thing a servant will be held accountable for on the Day of Judgment is his prayer.","ru":"Первое, за что будет спрошен раб в День Суда — это его молитва.","tr":"Kıyamet günü kulun hesaba çekileceği ilk amel namazdır.","ar":"إِنَّ أَوَّلَ مَا يُحَاسَبُ بِهِ الْعَبْدُ يَوْمَ الْقِيَامَةِ مِنْ عَمَلِهِ صَلَاتُهُ"},"src":{"az":"Tirmizi 413","en":"Tirmidhi 413","ru":"Тирмизи 413","tr":"Tirmizî 413","ar":"الترمذي 413"}},{"id":529,"t":{"az":"Qapınızda bir çay axsa, gündə beş dəfə yuyunsanız, kirdən nə qalar? Beş vaxt namaz da belədir.","en":"If there were a river at the door of one of you and he bathed in it five times a day, would any dirt remain? That is the likeness of the five prayers.","ru":"Если бы у двери одного из вас текла река и он купался бы в ней пять раз в день, осталась бы на нём грязь? Таковы пять молитв.","tr":"Kapınızda bir nehir aksa, günde beş kez yıkansanız kir kalır mı? İşte beş vakit namaz da böyledir.","ar":"أَرَأَيْتُمْ لَوْ أَنَّ نَهْرًا بِبَابِ أَحَدِكُمْ يَغْتَسِلُ مِنْهُ كُلَّ يَوْمٍ خَمْسَ مَرَّاتٍ هَلْ يَبْقَى مِنْ دَرَنِهِ شَيْءٌ"},"src":{"az":"Buxari 528","en":"Bukhari 528","ru":"Бухари 528","tr":"Buhârî 528","ar":"البخاري 528"}},{"id":531,"t":{"az":"Quran oxuyun, çünki o qiyamət günü sahiblərinə şəfaətçi gələcək.","en":"Recite the Quran, for it will come on the Day of Judgment as an intercessor for its companions.","ru":"Читайте Коран, ибо он придёт в День Суда заступником за своих обладателей.","tr":"Kur'an okuyun, çünkü o kıyamet günü sahiplerine şefaatçi olarak gelecektir.","ar":"اقْرَءُوا الْقُرْآنَ فَإِنَّهُ يَأْتِي يَوْمَ الْقِيَامَةِ شَفِيعًا لِأَصْحَابِهِ"},"src":{"az":"Muslim 804","en":"Muslim 804","ru":"Муслим 804","tr":"Müslim 804","ar":"مسلم 804"}},{"id":539,"t":{"az":"Məndən bir ayə də olsa çatdırın.","en":"Convey from me even if it is one verse.","ru":"Передавайте от меня, хотя бы один аят.","tr":"Benden bir ayet de olsa tebliğ edin.","ar":"بَلِّغُوا عَنِّي وَلَوْ آيَةً"},"src":{"az":"Buxari 3461","en":"Bukhari 3461","ru":"Бухари 3461","tr":"Buhârî 3461","ar":"البخاري 3461"}},{"id":544,"t":{"az":"Oruc tutanın iki sevinci var: iftar edəndə və Rəbbinə qovuşanda.","en":"The fasting person has two joys: when breaking his fast and when meeting his Lord.","ru":"У постящегося две радости: при разговении и при встрече с Господом.","tr":"Oruçlunun iki sevinci vardır: iftar ettiğinde ve Rabbine kavuştuğunda.","ar":"لِلصَّائِمِ فَرْحَتَانِ فَرْحَةٌ عِنْدَ فِطْرِهِ وَفَرْحَةٌ عِنْدَ لِقَاءِ رَبِّهِ"},"src":{"az":"Buxari 1904","en":"Bukhari 1904","ru":"Бухари 1904","tr":"Buhârî 1904","ar":"البخاري 1904"}},{"id":547,"t":{"az":"Allahın mal verib zəkatını ödəməyən kimsə üçün qiyamət günü keçəl ilan şəklində təmsil olunar.","en":"Whoever Allah gives wealth and he does not pay its zakat, it will appear as a bald serpent on the Day of Judgment.","ru":"Кому Аллах дал имущество, а он не выплатил закят, оно предстанет в виде лысого змея в День Суда.","tr":"Allah'ın mal verip de zekatını ödemeyen kimse için kıyamet günü kel bir yılan suretinde temsil olunur.","ar":"مَنْ آتَاهُ اللَّهُ مَالًا فَلَمْ يُؤَدِّ زَكَاتَهُ مُثِّلَ لَهُ شُجَاعًا أَقْرَعَ"},"src":{"az":"Buxari 1403","en":"Bukhari 1403","ru":"Бухари 1403","tr":"Buhârî 1403","ar":"البخاري 1403"}},{"id":549,"t":{"az":"İki kəlmə var: dilə yüngül, tərəzidə ağır, Rəhmana sevimli: \"Sübhanəllahi və bihəmdihi, Sübhanəllahil-Azim.\"","en":"Two words are light on the tongue, heavy on the scale, beloved to the Most Merciful: \"SubhanAllahi wa bihamdihi, SubhanAllahil-Azim.\"","ru":"Два слова легки на языке, тяжелы на весах и любимы Милостивым: «Субхана-Ллахи ва бихамдихи, Субхана-Ллахиль-Азым».","tr":"İki kelime vardır: dile hafif, mizanda ağır, Rahman'a sevimli: \"Sübhanallahi ve bihamdihi, Sübhanallahil-Azim.\"","ar":"كَلِمَتَانِ خَفِيفَتَانِ عَلَى اللِّسَانِ ثَقِيلَتَانِ فِي الْمِيزَانِ حَبِيبَتَانِ إِلَى الرَّحْمَنِ سُبْحَانَ اللَّهِ وَبِحَمْدِهِ سُبْحَانَ اللَّهِ الْعَظِيمِ"},"src":{"az":"Buxari 6406","en":"Bukhari 6406","ru":"Бухари 6406","tr":"Buhârî 6406","ar":"البخاري 6406"}},{"id":556,"t":{"az":"Müsəlmana gələn hər yorğunluq, xəstəlik, qəm — günahlarına kəffarədir.","en":"No fatigue, illness, or grief befalls a Muslim except that Allah expiates his sins through it.","ru":"Мусульманина не постигнет ни усталость, ни болезнь, ни печаль, кроме как Аллах искупит этим его грехи.","tr":"Müslümanın başına gelen her yorgunluk, hastalık, keder — günahlarına kefarettir.","ar":"مَا يُصِيبُ الْمُسْلِمَ مِنْ نَصَبٍ وَلَا وَصَبٍ وَلَا هَمٍّ وَلَا حُزْنٍ إِلَّا كَفَّرَ اللَّهُ بِهَا مِنْ خَطَايَاهُ"},"src":{"az":"Buxari 5641","en":"Bukhari 5641","ru":"Бухари 5641","tr":"Buhârî 5641","ar":"البخاري 5641"}},{"id":560,"t":{"az":"Həqiqi səbr ilk zərbə anındakıdır.","en":"True patience is at the first stroke of calamity.","ru":"Истинное терпение — при первом ударе.","tr":"Gerçek sabır, ilk darbe anındakidir.","ar":"إِنَّ الصَّبْرَ عِنْدَ الصَّدْمَةِ الْأُولَى"},"src":{"az":"Buxari 1283","en":"Bukhari 1283","ru":"Бухари 1283","tr":"Buhârî 1283","ar":"البخاري 1283"}},{"id":564,"t":{"az":"Dünyaya rəğbətsiz ol, Allah səni sevsin; insanlardakına rəğbətsiz ol, insanlar səni sevsin.","en":"Be indifferent to the world and Allah will love you; be indifferent to what people have and people will love you.","ru":"Будь равнодушен к мирскому — и Аллах полюбит тебя; будь равнодушен к тому, что у людей — и люди полюбят тебя.","tr":"Dünyaya rağbet etme Allah seni sevsin; insanlardakine rağbet etme insanlar seni sevsin.","ar":"ازْهَدْ فِي الدُّنْيَا يُحِبَّكَ اللَّهُ وَازْهَدْ فِيمَا عِنْدَ النَّاسِ يُحِبَّكَ النَّاسُ"},"src":{"az":"İbn Macə 4102","en":"Ibn Majah 4102","ru":"Ибн Маджа 4102","tr":"İbn Mâce 4102","ar":"ابن ماجه 4102"}},{"id":565,"t":{"az":"Mənim dünya ilə nə işim var? Mən ancaq ağac altında kölgələnib sonra gedən yolçu kimiyəm.","en":"What have I to do with the world? I am like a rider who rests under a tree then moves on and leaves it.","ru":"Что мне до мира? Я лишь как путник, укрывшийся в тени дерева, а затем ушедший.","tr":"Benim dünya ile ne işim var? Ben sadece ağaç altında gölgelenen sonra gidip onu bırakan yolcu gibiyim.","ar":"مَا لِي وَلِلدُّنْيَا مَا أَنَا فِي الدُّنْيَا إِلَّا كَرَاكِبٍ اسْتَظَلَّ تَحْتَ شَجَرَةٍ ثُمَّ رَاحَ وَتَرَكَهَا"},"src":{"az":"Tirmizi 2377","en":"Tirmidhi 2377","ru":"Тирмизи 2377","tr":"Tirmizî 2377","ar":"الترمذي 2377"}},{"id":566,"t":{"az":"Ləzzətləri pozan ölümü çox xatırlayın.","en":"Remember often the destroyer of pleasures: death.","ru":"Чаще вспоминайте разрушительницу наслаждений — смерть.","tr":"Lezzetleri yıkan ölümü çokça hatırlayın.","ar":"أَكْثِرُوا ذِكْرَ هَادِمِ اللَّذَّاتِ"},"src":{"az":"Tirmizi 2307","en":"Tirmidhi 2307","ru":"Тирмизи 2307","tr":"Tirmizî 2307","ar":"الترمذي 2307"}},{"id":569,"t":{"az":"Cənnət çətinliklərlə, cəhənnəm isə şəhvətlərlə əhatə olunmuşdur.","en":"Paradise is surrounded by hardships and the Fire is surrounded by desires.","ru":"Рай окружён тяготами, а огонь окружён страстями.","tr":"Cennet zorluklarla, cehennem ise şehvetlerle kuşatılmıştır.","ar":"حُفَّتِ الْجَنَّةُ بِالْمَكَارِهِ وَحُفَّتِ النَّارُ بِالشَّهَوَاتِ"},"src":{"az":"Muslim 2823","en":"Muslim 2823","ru":"Муслим 2823","tr":"Müslim 2823","ar":"مسلم 2823"}},{"id":570,"t":{"az":"Dünyada ən nemətli yaşayan cəhənnəm əhli gətirilib oda bir dəfə batırılar və deyilər: Heç nemət gördünmü? Xeyr, deyər.","en":"The most affluent person of the Fire in this world will be dipped once in the Fire and asked: Did you ever see any good? He will say: No.","ru":"Самый обеспеченный из обитателей ада окунётся в огонь один раз и спросят: «Видел ли ты когда-нибудь благо?» Скажет: «Нет».","tr":"Dünyada en nimetli yaşayan cehennem ehli ateşe bir kez daldırılır ve sorulur: Hiç nimet gördün mü? Hayır, der.","ar":"يُؤْتَى بِأَنْعَمِ أَهْلِ الدُّنْيَا مِنْ أَهْلِ النَّارِ فَيُصْبَغُ فِي النَّارِ صَبْغَةً"},"src":{"az":"Muslim 2807","en":"Muslim 2807","ru":"Муслим 2807","tr":"Müslim 2807","ar":"مسلم 2807"}},{"id":573,"t":{"az":"Xəsis o kəsdir ki, yanında adım çəkilir və mənə salavat gətirmir.","en":"The miser is the one in whose presence I am mentioned and he does not send salawat upon me.","ru":"Скупец — тот, при ком я упомянут, а он не благословил меня.","tr":"Cimri, yanında adım anılıp da bana salavat getirmeyen kişidir.","ar":"الْبَخِيلُ مَنْ ذُكِرْتُ عِنْدَهُ فَلَمْ يُصَلِّ عَلَيَّ"},"src":{"az":"Tirmizi 3546","en":"Tirmidhi 3546","ru":"Тирмизи 3546","tr":"Tirmizî 3546","ar":"الترمذي 3546"}},{"id":575,"t":{"az":"Yanında adım çəkilib salavat gətirməyən kəsin burnu yerlə sürtülsün.","en":"May the nose of the man be rubbed in dust, in whose presence I am mentioned and he does not send blessings upon me.","ru":"Да будет унижен тот, при ком я упомянут, а он не благословил меня.","tr":"Yanında adım anılıp da bana salavat getirmeyen kişinin burnu yere sürtülsün.","ar":"رَغِمَ أَنْفُ رَجُلٍ ذُكِرْتُ عِنْدَهُ فَلَمْ يُصَلِّ عَلَيَّ"},"src":{"az":"Tirmizi 3545","en":"Tirmidhi 3545","ru":"Тирмизи 3545","tr":"Tirmizî 3545","ar":"الترمذي 3545"}},{"id":577,"t":{"az":"Üç nəfər səfərə çıxanda aralarından birini əmir seçsinlər.","en":"When three people set out on a journey, let them appoint one of them as leader.","ru":"Когда трое выходят в путь, пусть назначат одного из них руководителем.","tr":"Üç kişi yolculuğa çıkınca aralarından birini emir tayin etsinler.","ar":"إِذَا خَرَجَ ثَلَاثَةٌ فِي سَفَرٍ فَلْيُؤَمِّرُوا أَحَدَهُمْ"},"src":{"az":"Əbu Davud 2608","en":"Abu Dawud 2608","ru":"Абу Дауд 2608","tr":"Ebû Dâvûd 2608","ar":"أبو داود 2608"}},{"id":578,"t":{"az":"Allahım, səfərin çətinliyindən, dönüşün pisliyindən, mənzərənin kədərindən Sənə sığınıram.","en":"O Allah, I seek refuge in You from the hardship of travel, the sadness of sight, and the evil of return.","ru":"О Аллах, я прибегаю к Тебе от трудностей пути, печального зрелища и дурного возвращения.","tr":"Allah'ım, yolculuğun meşakkatinden, dönüşün kötülüğünden, manzaranın hüznünden Sana sığınırım.","ar":"اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ وَعْثَاءِ السَّفَرِ وَكَآبَةِ الْمَنْظَرِ وَسُوءِ الْمُنْقَلَبِ"},"src":{"az":"Muslim 1342","en":"Muslim 1342","ru":"Муслим 1342","tr":"Müslim 1342","ar":"مسلم 1342"}},{"id":580,"t":{"az":"Allah yanında ən xeyirli yoldaş yoldaşına ən xeyirli olandır; ən xeyirli qonşu qonşusuna ən xeyirli olandır.","en":"The best companion in the sight of Allah is the best to his companion, and the best neighbor is the best to his neighbor.","ru":"Лучший товарищ у Аллаха — лучший для своего товарища, и лучший сосед — лучший для своего соседа.","tr":"Allah katında en hayırlı arkadaş, arkadaşına en hayırlı olandır; en hayırlı komşu, komşusuna en hayırlı olandır.","ar":"خَيْرُ الْأَصْحَابِ عِنْدَ اللَّهِ خَيْرُهُمْ لِصَاحِبِهِ وَخَيْرُ الْجِيرَانِ عِنْدَ اللَّهِ خَيْرُهُمْ لِجَارِهِ"},"src":{"az":"Tirmizi 1944","en":"Tirmidhi 1944","ru":"Тирмизи 1944","tr":"Tirmizî 1944","ar":"الترمذي 1944"}},{"id":582,"t":{"az":"Münafiqin əlaməti üçdür: danışanda yalan deyər, vəd edəndə pozar, əmanət verilsə xəyanət edər.","en":"The signs of a hypocrite are three: when he speaks he lies, when he promises he breaks it, and when entrusted he betrays.","ru":"Признаки лицемера — три: когда говорит — лжёт, когда обещает — нарушает, когда ему доверяют — предаёт.","tr":"Münafığın alameti üçtür: konuşunca yalan söyler, vaat edince bozar, emanete hıyanet eder.","ar":"آيَةُ الْمُنَافِقِ ثَلَاثٌ إِذَا حَدَّثَ كَذَبَ وَإِذَا وَعَدَ أَخْلَفَ وَإِذَا اؤْتُمِنَ خَانَ"},"src":{"az":"Buxari 33","en":"Bukhari 33","ru":"Бухари 33","tr":"Buhârî 33","ar":"البخاري 33"}},{"id":583,"t":{"az":"Bizi aldadan bizdən deyil.","en":"Whoever cheats us is not one of us.","ru":"Кто обманывает нас — не из нас.","tr":"Bizi aldatan bizden değildir.","ar":"مَنْ غَشَّنَا فَلَيْسَ مِنَّا"},"src":{"az":"Muslim 101","en":"Muslim 101","ru":"Муслим 101","tr":"Müslim 101","ar":"مسلم 101"}},{"id":586,"t":{"az":"Qəzəblənmə!","en":"Do not get angry!","ru":"Не гневайся!","tr":"Kızma!","ar":"لَا تَغْضَبْ"},"src":{"az":"Buxari 6116","en":"Bukhari 6116","ru":"Бухари 6116","tr":"Buhârî 6116","ar":"البخاري 6116"}},{"id":588,"t":{"az":"Kim dəstəmaz alıb gözəl şəkildə alsa, sonra iki rükət namaz qılsa, keçmiş günahları bağışlanar.","en":"No Muslim performs ablution well then prays two units except that his past sins are forgiven.","ru":"Если мусульманин совершит омовение хорошо, затем совершит два ракята молитвы, его прежние грехи простятся.","tr":"Güzel bir abdest alıp iki rekat namaz kılan Müslümanın geçmiş günahları bağışlanır.","ar":"مَا مِنْ مُسْلِمٍ يَتَوَضَّأُ فَيُحْسِنُ وُضُوءَهُ ثُمَّ يَقُومُ فَيُصَلِّي رَكْعَتَيْنِ إِلَّا غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ"},"src":{"az":"Muslim 226","en":"Muslim 226","ru":"Муслим 226","tr":"Müslim 226","ar":"مسلم 226"}},{"id":590,"t":{"az":"Fəcrin iki rükət sünnəti dünyadan və dünyada olan hər şeydən xeyirlidir.","en":"The two sunnah units of Fajr are better than the world and everything in it.","ru":"Два суннат-ракята фаджра лучше мира и всего, что в нём.","tr":"Fecrin iki rekat sünneti dünyadan ve içindekilerden hayırlıdır.","ar":"رَكْعَتَا الْفَجْرِ خَيْرٌ مِنَ الدُّنْيَا وَمَا فِيهَا"},"src":{"az":"Muslim 725","en":"Muslim 725","ru":"Муслим 725","tr":"Müslim 725","ar":"مسلم 725"}},{"id":591,"t":{"az":"Kim gündüz və gecə on iki rükət qılarsa, cənnətdə ona bir ev tikilər.","en":"Whoever prays twelve units in a day and night, a house will be built for him in Paradise.","ru":"Кто молится двенадцать ракятов днём и ночью, тому будет построен дом в раю.","tr":"Kim gündüz ve gece on iki rekat kılarsa, cennette ona bir ev yapılır.","ar":"مَنْ صَلَّى اثْنَتَيْ عَشْرَةَ رَكْعَةً فِي يَوْمِهِ وَلَيْلَتِهِ بُنِيَ لَهُ بَيْتٌ فِي الْجَنَّةِ"},"src":{"az":"Muslim 728","en":"Muslim 728","ru":"Муслим 728","tr":"Müslim 728","ar":"مسلم 728"}},{"id":592,"t":{"az":"Namazda məşğuliyyət var (danışmaq olmaz).","en":"In prayer there is enough occupation (i.e., do not speak).","ru":"В молитве достаточно занятия (т.е. не разговаривайте).","tr":"Namazda meşguliyet vardır (konuşulmaz).","ar":"إِنَّ فِي الصَّلَاةِ لَشُغْلًا"},"src":{"az":"Buxari 1199","en":"Bukhari 1199","ru":"Бухари 1199","tr":"Buhârî 1199","ar":"البخاري 1199"}},{"id":594,"t":{"az":"Ancaq iki nəfərə həsəd edilər: Quran verilmiş və gecə-gündüz onu oxuyan kəs...","en":"There is no envy except in two: a man whom Allah gave the Quran and he recites it day and night...","ru":"Можно завидовать лишь двоим: человеку, которому Аллах дал Коран, и он читает его днём и ночью...","tr":"Ancak iki kişiye gıpta edilir: Allah'ın Kur'an verip gece gündüz okuyan kişi...","ar":"لَا حَسَدَ إِلَّا فِي اثْنَتَيْنِ رَجُلٌ آتَاهُ اللَّهُ الْقُرْآنَ فَهُوَ يَقُومُ بِهِ آنَاءَ اللَّيْلِ وَآنَاءَ النَّهَارِ"},"src":{"az":"Buxari 5025","en":"Bukhari 5025","ru":"Бухари 5025","tr":"Buhârî 5025","ar":"البخاري 5025"}},{"id":595,"t":{"az":"Quran sahibinə deyilər: Oxu, yüksəl, dünyada oxuduğun kimi oxu; mənzilin oxuduğun son ayədədir.","en":"It will be said to the companion of the Quran: Read, ascend, and recite as you used to recite in the world; your rank is at the last verse you recite.","ru":"Знатоку Корана скажут: «Читай, поднимайся и читай нараспев, как ты читал в земной жизни; твоё место — у последнего прочитанного аята».","tr":"Kur'an sahibine denilir: Oku, yüksel, dünyada okuduğun gibi oku; makamın okuduğun son ayettedir.","ar":"يُقَالُ لِصَاحِبِ الْقُرْآنِ اقْرَأْ وَارْتَقِ وَرَتِّلْ كَمَا كُنْتَ تُرَتِّلُ فِي الدُّنْيَا"},"src":{"az":"Tirmizi 2914","en":"Tirmidhi 2914","ru":"Тирмизи 2914","tr":"Tirmizî 2914","ar":"الترمذي 2914"}},{"id":598,"t":{"az":"Kim Ramazan orucunu tutub ardınca Şəvvaldan altı gün tutsa, bütöv il oruc tutmuş kimi olar.","en":"Whoever fasts Ramadan then follows it with six days of Shawwal, it is as if he fasted the entire year.","ru":"Кто постился Рамадан, а затем шесть дней Шавваля, будто постился весь год.","tr":"Kim Ramazan orucunu tutup ardından Şevval'den altı gün tutarsa, bütün yıl oruç tutmuş gibi olur.","ar":"مَنْ صَامَ رَمَضَانَ ثُمَّ أَتْبَعَهُ سِتًّا مِنْ شَوَّالٍ كَانَ كَصِيَامِ الدَّهْرِ"},"src":{"az":"Muslim 1164","en":"Muslim 1164","ru":"Муслим 1164","tr":"Müslim 1164","ar":"مسلم 1164"}},{"id":600,"t":{"az":"Qızıl-gümüş sahibi haqqını ödəməzsə, ondan od lövhələri düzəldilib yanar.","en":"No owner of gold or silver who does not pay its due except that plates of fire will be made for him.","ru":"Ни один владелец золота или серебра, не выплативший положенного, кроме как из них будут сделаны пластины огня.","tr":"Altın veya gümüş sahibi hakkını ödemezse, ondan ateş levhaları yapılıp dağlanır.","ar":"مَا مِنْ صَاحِبِ ذَهَبٍ وَلَا فِضَّةٍ لَا يُؤَدِّي مِنْهَا حَقَّهَا إِلَّا صُفِّحَتْ لَهُ صَفَائِحُ مِنْ نَارٍ"},"src":{"az":"Muslim 987","en":"Muslim 987","ru":"Муслим 987","tr":"Müslim 987","ar":"مسلم 987"}},{"id":601,"t":{"az":"\"Sübhanəllah, əlhəmdulillah, la ilahə illəllah, Allahu əkbər\" deməyim günəşin üzərinə doğduğu hər şeydən sevimlidir.","en":"Saying \"SubhanAllah, Alhamdulillah, La ilaha illallah, Allahu Akbar\" is more beloved to me than all that the sun rises over.","ru":"Слова «Субхана-Ллах, Аль-хамду ли-Ллях, Ля иляха илля-Ллах, Аллаху Акбар» мне дороже всего, над чем восходит солнце.","tr":"\"Sübhanallah, Elhamdülillah, La ilahe illallah, Allahu Ekber\" demem güneşin doğduğu her şeyden bana daha sevimlidir.","ar":"لَأَنْ أَقُولَ سُبْحَانَ اللَّهِ وَالْحَمْدُ لِلَّهِ وَلَا إِلَهَ إِلَّا اللَّهُ وَاللَّهُ أَكْبَرُ أَحَبُّ إِلَيَّ مِمَّا طَلَعَتْ عَلَيْهِ الشَّمْسُ"},"src":{"az":"Muslim 2695","en":"Muslim 2695","ru":"Муслим 2695","tr":"Müslim 2695","ar":"مسلم 2695"}},{"id":602,"t":{"az":"Kim gündə yüz dəfə \"Sübhanəllahi və bihəmdihi\" desə, günahları dənizin köpüyü qədər olsa da silinər.","en":"Whoever says \"SubhanAllahi wa bihamdihi\" one hundred times a day, his sins will be erased even if they are like the foam of the sea.","ru":"Кто скажет сто раз в день «Субхана-Ллахи ва бихамдихи», его грехи будут стёрты, даже если их как морская пена.","tr":"Kim günde yüz kere \"Sübhanallahi ve bihamdihi\" derse, günahları deniz köpüğü kadar olsa da silinir.","ar":"مَنْ قَالَ سُبْحَانَ اللَّهِ وَبِحَمْدِهِ فِي يَوْمٍ مِائَةَ مَرَّةٍ حُطَّتْ خَطَايَاهُ وَإِنْ كَانَتْ مِثْلَ زَبَدِ الْبَحْرِ"},"src":{"az":"Buxari 6405","en":"Bukhari 6405","ru":"Бухари 6405","tr":"Buhârî 6405","ar":"البخاري 6405"}},{"id":603,"t":{"az":"Kim gündə yüz dəfə \"La ilahə illəllahu vahdəhu la şərikə ləh...\" desə, on qul azad etmiş kimi olar.","en":"Whoever says \"La ilaha illallahu wahdahu la sharika lah...\" a hundred times a day will have the reward of freeing ten slaves.","ru":"Кто сто раз в день скажет «Ля иляха илля-Ллаху вахдаху ля шарика лях...», получит награду за освобождение десяти рабов.","tr":"Kim günde yüz kez \"La ilahe illallahu vahdehu la şerike leh...\" derse on köle azat etmiş gibi olur.","ar":"مَنْ قَالَ لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ فِي يَوْمٍ مِائَةَ مَرَّةٍ"},"src":{"az":"Buxari 6403","en":"Bukhari 6403","ru":"Бухари 6403","tr":"Buhârî 6403","ar":"البخاري 6403"}},{"id":604,"t":{"az":"Sizə əməllərinizin ən xeyirlisini xəbər verimmi? Zikrullahdır.","en":"Shall I tell you the best of your deeds? It is the remembrance of Allah.","ru":"Не сообщить ли вам о лучшем из ваших дел? Это — поминание Аллаха.","tr":"Size amellerinizin en hayırlısını haber vereyim mi? Allah'ı zikretmektir.","ar":"أَلَا أُنَبِّئُكُمْ بِخَيْرِ أَعْمَالِكُمْ وَأَزْكَاهَا عِنْدَ مَلِيكِكُمْ وَأَرْفَعِهَا فِي دَرَجَاتِكُمْ"},"src":{"az":"Tirmizi 3377","en":"Tirmidhi 3377","ru":"Тирмизи 3377","tr":"Tirmizî 3377","ar":"الترمذي 3377"}},{"id":605,"t":{"az":"Kim çətin vəziyyətdəki borcluya möhlət versə və ya borcunu bağışlasa, Allah onu kölgəsində kölgələndirər.","en":"Whoever gives respite to one in difficulty or forgives his debt, Allah will shade him with His shade.","ru":"Кто даст отсрочку должнику в трудности или простит ему, того Аллах укроет в Своей тени.","tr":"Kim darda olan borçluya mühlet verir veya borcunu bağışlarsa, Allah onu gölgesinde gölgelendirir.","ar":"مَنْ أَنْظَرَ مُعْسِرًا أَوْ وَضَعَ عَنْهُ أَظَلَّهُ اللَّهُ فِي ظِلِّهِ"},"src":{"az":"Muslim 3006","en":"Muslim 3006","ru":"Муслим 3006","tr":"Müslim 3006","ar":"مسلم 3006"}},{"id":609,"t":{"az":"Allah bir qövmü sevdikdə onları imtahan edər.","en":"When Allah loves a people, He tests them.","ru":"Когда Аллах любит народ, Он испытывает его.","tr":"Allah bir toplumu sevdiğinde onları imtihan eder.","ar":"إِنَّ اللَّهَ إِذَا أَحَبَّ قَوْمًا ابْتَلَاهُمْ"},"src":{"az":"Tirmizi 2396","en":"Tirmidhi 2396","ru":"Тирмизи 2396","tr":"Tirmizî 2396","ar":"الترمذي 2396"}},{"id":610,"t":{"az":"Peyğəmbər \"Çoxluqla öyünmək sizi qəflətə saldı\" ayəsini oxuyub buyurdu: İnsanoğlu \"malım-malım\" deyir, lakin malından onun üçün ancaq yeyib tükənən, geyib köhnəldən və verdiyi sədəqə qalar.","en":"The Prophet recited \"Competition diverts you\" and said: Man says \"my wealth\" but from his wealth he only keeps what he ate, wore out, or gave in charity.","ru":"Пророк прочёл «Вас отвлекло приумножение» и сказал: Человек говорит «моё имущество», но из него ему остаётся лишь съеденное, изношенное и розданное.","tr":"Peygamber \"Çokluk yarışı sizi oyaladı\" ayetini okuyup buyurdu: İnsan \"malım-malım\" der, halbuki malından yalnız yiyip tükettiği, giyip eskittiği ve sadaka verdiği kalır.","ar":"أَلْهَاكُمُ التَّكَاثُرُ حَتَّى زُرْتُمُ الْمَقَابِرَ"},"src":{"az":"Nəsai 3613","en":"An-Nasa'i 3613","ru":"ан-Насаи 3613","tr":"Nesâî 3613","ar":"النسائي 3613"}},{"id":614,"t":{"az":"Ölünün ardınca üç şey gedir: ailəsi, malı, əməli. İkisi geri qayıdır, biri qalır — əməli.","en":"Three things follow the deceased: family, wealth, and deeds. Two return and one remains — his deeds.","ru":"За умершим следуют трое: семья, имущество и дела. Двое возвращаются, одно остаётся — его дела.","tr":"Ölünün ardından üç şey gider: ailesi, malı, ameli. İkisi döner, biri kalır — ameli.","ar":"يَتْبَعُ الْمَيِّتَ ثَلَاثَةٌ أَهْلُهُ وَمَالُهُ وَعَمَلُهُ فَيَرْجِعُ اثْنَانِ وَيَبْقَى وَاحِدٌ"},"src":{"az":"Buxari 6514","en":"Bukhari 6514","ru":"Бухари 6514","tr":"Buhârî 6514","ar":"البخاري 6514"}},{"id":617,"t":{"az":"Kim evdən çıxarkən \"Bismillah, təvəkkəltu aləllah\" desə, ona deyilər: hidayət olundun, kifayət olundun, qorunuldun.","en":"Whoever leaves his house saying \"Bismillah, I put my trust in Allah,\" it is said: You are guided, sufficed, and protected.","ru":"Кто выйдет из дома со словами «Бисмиллях, таваккальту аля-Ллах», ему скажут: ты наставлен, тебе достаточно и ты защищён.","tr":"Evinden çıkarken \"Bismillah, tevekkeltü alellah\" diyen kişiye denilir: Hidayet oldun, kifayet oldun, korunuldun.","ar":"مَنْ خَرَجَ مِنْ بَيْتِهِ فَقَالَ بِسْمِ اللَّهِ تَوَكَّلْتُ عَلَى اللَّهِ"},"src":{"az":"Əbu Davud 5095","en":"Abu Dawud 5095","ru":"Абу Дауд 5095","tr":"Ebû Dâvûd 5095","ar":"أبو داود 5095"}},{"id":618,"t":{"az":"Allahı Rəbb, İslamı din, Muhəmmədi Rəsul olaraq razı olan imanın dadını daddı.","en":"He has tasted the sweetness of faith who is pleased with Allah as Lord, Islam as religion, and Muhammad as messenger.","ru":"Вкусил сладость веры тот, кто доволен Аллахом как Господом, Исламом как религией и Мухаммадом как посланником.","tr":"Allah'ı Rab, İslam'ı din, Muhammed'i Resul olarak kabul eden imanın tadını tatmıştır.","ar":"ذَاقَ طَعْمَ الْإِيمَانِ مَنْ رَضِيَ بِاللَّهِ رَبًّا وَبِالْإِسْلَامِ دِينًا وَبِمُحَمَّدٍ رَسُولًا"},"src":{"az":"Muslim 34","en":"Muslim 34","ru":"Муслим 34","tr":"Müslim 34","ar":"مسلم 34"}},{"id":619,"t":{"az":"Ənsarı sevmək imanın əlamətidir, onlara nifrət etmək nifaqın əlamətidir.","en":"Love of the Ansar is a sign of faith, and hatred of them is a sign of hypocrisy.","ru":"Любовь к ансарам — признак веры, ненависть к ним — признак лицемерия.","tr":"Ensar'ı sevmek imanın alameti, onlara buğz etmek nifakın alametidir.","ar":"حُبُّ الْأَنْصَارِ آيَةُ الْإِيمَانِ وَبُغْضُهُمْ آيَةُ النِّفَاقِ"},"src":{"az":"Buxari 17","en":"Bukhari 17","ru":"Бухари 17","tr":"Buhârî 17","ar":"البخاري 17"}},{"id":620,"t":{"az":"Həya imandandır.","en":"Modesty is part of faith.","ru":"Стыдливость — от веры.","tr":"Haya imandandır.","ar":"الْحَيَاءُ مِنَ الْإِيمَانِ"},"src":{"az":"Buxari 24","en":"Bukhari 24","ru":"Бухари 24","tr":"Buhârî 24","ar":"البخاري 24"}},{"id":624,"t":{"az":"Kim Allah üçün bir məscid tikərsə, Allah cənnətdə onun üçün bənzərini tikər.","en":"Whoever builds a mosque for Allah, Allah will build for him something similar in Paradise.","ru":"Кто построит мечеть ради Аллаха, тому Аллах построит подобное в раю.","tr":"Kim Allah için bir mescit yaparsa, Allah cennette ona benzerini yapar.","ar":"مَنْ بَنَى مَسْجِدًا لِلَّهِ بَنَى اللَّهُ لَهُ مِثْلَهُ فِي الْجَنَّةِ"},"src":{"az":"Buxari 450","en":"Bukhari 450","ru":"Бухари 450","tr":"Buhârî 450","ar":"البخاري 450"}},{"id":625,"t":{"az":"Gecə namazı iki-iki rükət qılınar.","en":"Night prayer is two by two units.","ru":"Ночная молитва совершается по два ракята.","tr":"Gece namazı ikişer ikişer kılınır.","ar":"صَلَاةُ اللَّيْلِ مَثْنَى مَثْنَى"},"src":{"az":"Buxari 990","en":"Bukhari 990","ru":"Бухари 990","tr":"Buhârî 990","ar":"البخاري 990"}},{"id":627,"t":{"az":"Quranı mahir oxuyan mələklərlə, çətinliklə oxuyana isə iki qat savab var.","en":"The one skilled in Quran is with the angels; the one who reads it with difficulty gets double reward.","ru":"Искусный в Коране — с ангелами; читающий с трудом получит двойную награду.","tr":"Kur'an'da mahir olan meleklerle, zorlukla okuyana iki kat sevap vardır.","ar":"الْمَاهِرُ بِالْقُرْآنِ مَعَ السَّفَرَةِ الْكِرَامِ الْبَرَرَةِ وَالَّذِي يَقْرَؤُهُ وَيَتَتَعْتَعُ فِيهِ وَهُوَ عَلَيْهِ شَاقٌّ لَهُ أَجْرَانِ"},"src":{"az":"Muslim 798","en":"Muslim 798","ru":"Муслим 798","tr":"Müslim 798","ar":"مسلم 798"}},{"id":628,"t":{"az":"Bəqərə surəsini oxuyun, onu almaq bərəkət, tərk etmək həsrətdir.","en":"Recite Surah al-Baqarah, for taking it is a blessing and leaving it is a regret.","ru":"Читайте суру Аль-Бакара: её чтение — благословение, оставление — сожаление.","tr":"Bakara suresini okuyun, onu almak bereket, terk etmek hasrettir.","ar":"اقْرَءُوا سُورَةَ الْبَقَرَةِ فَإِنَّ أَخْذَهَا بَرَكَةٌ وَتَرْكَهَا حَسْرَةٌ"},"src":{"az":"Muslim 804","en":"Muslim 804","ru":"Муслим 804","tr":"Müslim 804","ar":"مسلم 804"}},{"id":630,"t":{"az":"Kim hidayətə dəvət edərsə, ona tabe olanların savabı qədər savab alar.","en":"Whoever calls to guidance will have a reward like those who follow him.","ru":"Кто призывает к истине, тому награда подобна наградам последовавших за ним.","tr":"Kim hidayete davet ederse, ona tabi olanların sevabı kadar sevap alır.","ar":"مَنْ دَعَا إِلَى هُدًى كَانَ لَهُ مِنَ الْأَجْرِ مِثْلُ أُجُورِ مَنْ تَبِعَهُ"},"src":{"az":"Muslim 2674","en":"Muslim 2674","ru":"Муслим 2674","tr":"Müslim 2674","ar":"مسلم 2674"}},{"id":631,"t":{"az":"Ərəfə günü oruc tutan iki ilin günahından azad olar: əvvəlki il və sonrakı il.","en":"Whoever fasts the Day of Arafah, two years of sins are expiated: the year before and the year after.","ru":"Кто постится в День Арафата, тому прощаются грехи двух лет: предыдущего и следующего.","tr":"Arefe günü oruç tutan iki yılın günahından kurtulur: önceki yıl ve sonraki yıl.","ar":"مَنْ صَامَ يَوْمَ عَرَفَةَ حُطَّ عَنْهُ سَنَتَيْنِ سَنَةٌ قَبْلَهُ وَسَنَةٌ بَعْدَهُ"},"src":{"az":"Muslim 1162","en":"Muslim 1162","ru":"Муслим 1162","tr":"Müslim 1162","ar":"مسلم 1162"}},{"id":633,"t":{"az":"Kim iffətli olmağa çalışarsa Allah onu iffətli edər, kim tox gözlü olarsa Allah onu zəngin edər.","en":"Whoever seeks chastity, Allah will grant it; whoever seeks self-sufficiency, Allah will enrich him.","ru":"Кто стремится к целомудрию, Аллах дарует ему; кто стремится к самодостаточности, Аллах обогатит его.","tr":"Kim iffetli olmaya çalışırsa Allah onu iffetli kılar, kim tok gözlü olursa Allah onu zengin kılar.","ar":"مَنِ اسْتَعَفَّ أَعَفَّهُ اللَّهُ وَمَنِ اسْتَغْنَى أَغْنَاهُ اللَّهُ"},"src":{"az":"Buxari 1469","en":"Bukhari 1469","ru":"Бухари 1469","tr":"Buhârî 1469","ar":"البخاري 1469"}},{"id":634,"t":{"az":"Miskinə sədəqə sədəqədir, qohuma sədəqə isə həm sədəqə, həm qohumluq silasıdır.","en":"Charity to a poor person is charity; charity to a relative is charity and maintaining ties.","ru":"Милостыня бедному — милостыня, а милостыня родственнику — милостыня и поддержание родственных связей.","tr":"Yoksula sadaka sadakadır, akrabaya sadaka hem sadaka hem sıla-i rahimdir.","ar":"الصَّدَقَةُ عَلَى الْمِسْكِينِ صَدَقَةٌ وَهِيَ عَلَى ذِي الرَّحِمِ صَدَقَةٌ وَصِلَةٌ"},"src":{"az":"Nəsai 2582","en":"An-Nasa'i 2582","ru":"ан-Насаи 2582","tr":"Nesâî 2582","ar":"النسائي 2582"}},{"id":635,"t":{"az":"\"La havlə vəla quvvətə illə billəh\" cənnət xəzinələrindən bir xəzinədir.","en":"\"La hawla wa la quwwata illa billah\" is a treasure from the treasures of Paradise.","ru":"«Ля хауля ва ля куввата илля билляхи» — сокровище из сокровищ рая.","tr":"\"La havle vela kuvvete illa billah\" cennet hazinelerinden bir hazinedir.","ar":"لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ كَنْزٌ مِنْ كُنُوزِ الْجَنَّةِ"},"src":{"az":"Buxari 4205","en":"Bukhari 4205","ru":"Бухари 4205","tr":"Buhârî 4205","ar":"البخاري 4205"}},{"id":637,"t":{"az":"Kim çətin vəziyyətdəki birinə asanlaşdırsa, Allah dünyada və axirətdə ona asanlaşdırar.","en":"Whoever makes it easy for someone in difficulty, Allah will make it easy for him in this world and the Hereafter.","ru":"Кто облегчит положение тому, кто в затруднении, тому Аллах облегчит в этом мире и в будущем.","tr":"Kim darda olana kolaylık gösterirse, Allah dünyada ve ahirette ona kolaylık gösterir.","ar":"وَمَنْ يَسَّرَ عَلَى مُعْسِرٍ يَسَّرَ اللَّهُ عَلَيْهِ فِي الدُّنْيَا وَالْآخِرَةِ"},"src":{"az":"Muslim 2699","en":"Muslim 2699","ru":"Муслим 2699","tr":"Müslim 2699","ar":"مسلم 2699"}},{"id":638,"t":{"az":"Ey qullarım, bunlar sizin əməllərinizdir, onları sizin üçün sayıram.","en":"O My servants, they are your deeds which I count for you.","ru":"О рабы Мои, это лишь ваши дела, которые Я учитываю для вас.","tr":"Ey kullarım, bunlar sizin amellerinizdir, onları sizin için sayarım.","ar":"يَا عِبَادِي إِنَّمَا هِيَ أَعْمَالُكُمْ أُحْصِيهَا لَكُمْ"},"src":{"az":"Muslim 2577","en":"Muslim 2577","ru":"Муслим 2577","tr":"Müslim 2577","ar":"مسلم 2577"}},{"id":639,"t":{"az":"Qiyamətdə qulun ayaqları yerindən tərpənməz ki, ömrünü nədə keçirdiyi soruşulsun.","en":"The feet of a servant will not move on the Day of Judgment until he is asked about his life and how he spent it.","ru":"Не сдвинутся ноги раба в День Суда, пока не будет спрошен о жизни — на что потратил.","tr":"Kıyamet günü kulun ayakları yerinden kımıldamaz, tâ ki ömrünü nerede harcadığı soruluncaya kadar.","ar":"لَا تَزُولُ قَدَمَا عَبْدٍ يَوْمَ الْقِيَامَةِ حَتَّى يُسْأَلَ عَنْ عُمُرِهِ فِيمَا أَفْنَاهُ"},"src":{"az":"Tirmizi 2417","en":"Tirmidhi 2417","ru":"Тирмизи 2417","tr":"Tirmizî 2417","ar":"الترمذي 2417"}},{"id":643,"t":{"az":"Allah rüşvət verəni və rüşvət alanı lənətləmişdir.","en":"Allah has cursed the one who gives and the one who takes a bribe.","ru":"Аллах проклял дающего и берущего взятку.","tr":"Allah rüşvet vereni ve rüşvet alanı lanetlemiştir.","ar":"لَعَنَ اللَّهُ الرَّاشِيَ وَالْمُرْتَشِيَ"},"src":{"az":"Əbu Davud 3580","en":"Abu Dawud 3580","ru":"Абу Дауд 3580","tr":"Ebû Dâvûd 3580","ar":"أبو داود 3580"}},{"id":644,"t":{"az":"Kim bir müsəlmanın eyibini örtsə, Allah qiyamətdə onun eyibini örtər.","en":"Whoever conceals the fault of a Muslim, Allah will conceal his faults on the Day of Judgment.","ru":"Кто скроет недостаток мусульманина, того Аллах скроет в День Суда.","tr":"Kim bir Müslümanın ayıbını örterse, Allah kıyamette onun ayıbını örter.","ar":"مَنْ سَتَرَ مُسْلِمًا سَتَرَهُ اللَّهُ يَوْمَ الْقِيَامَةِ"},"src":{"az":"Buxari 2442","en":"Bukhari 2442","ru":"Бухари 2442","tr":"Buhârî 2442","ar":"البخاري 2442"}},{"id":645,"t":{"az":"Müəzzini eşidəndə onun dediyini siz də deyin.","en":"When you hear the muezzin, say what he says.","ru":"Когда слышите муэдзина, повторяйте за ним.","tr":"Müezzini duyduğunuzda onun dediğini siz de söyleyin.","ar":"إِذَا سَمِعْتُمُ الْمُؤَذِّنَ فَقُولُوا مِثْلَ مَا يَقُولُ"},"src":{"az":"Muslim 383","en":"Muslim 383","ru":"Муслим 383","tr":"Müslim 383","ar":"مسلم 383"}},{"id":646,"t":{"az":"Kim Cümə günü qüsl edib erkən gedərsə, imama yaxınlaşarsa, hər addımda bir il oruc-namaz savabı var.","en":"Whoever takes a bath on Friday, goes early, walks and does not ride, and sits close to the imam — for every step he earns a year of fasting and prayer.","ru":"Кто искупается в пятницу, пойдёт рано пешком, сядет близко к имаму — за каждый шаг ему засчитается год поста и молитвы.","tr":"Cuma günü gusül edip erken giden, yürüyen, imama yakın oturan — her adımda bir yıl oruç ve namaz sevabı kazanır.","ar":"مَنْ غَسَّلَ يَوْمَ الْجُمُعَةِ وَاغْتَسَلَ ثُمَّ بَكَّرَ وَابْتَكَرَ وَمَشَى وَلَمْ يَرْكَبْ وَدَنَا مِنَ الْإِمَامِ"},"src":{"az":"Əbu Davud 345","en":"Abu Dawud 345","ru":"Абу Дауд 345","tr":"Ebû Dâvûd 345","ar":"أبو داود 345"}},{"id":648,"t":{"az":"Allah o kəsi nurlandırsın ki, bizdən bir hədis eşidib onu olduğu kimi çatdırar.","en":"May Allah brighten the one who hears a hadith from us, memorizes it, and conveys it.","ru":"Да озарит Аллах лицо того, кто услышал от нас хадис, запомнил и передал его.","tr":"Allah o kişinin yüzünü nurlandırsın ki, bizden bir hadis duyup onu olduğu gibi ulaştırır.","ar":"نَضَّرَ اللَّهُ امْرَأً سَمِعَ مِنَّا حَدِيثًا فَحَفِظَهُ حَتَّى يُبَلِّغَهُ"},"src":{"az":"Tirmizi 2656","en":"Tirmidhi 2656","ru":"Тирмизи 2656","tr":"Tirmizî 2656","ar":"الترمذي 2656"}},{"id":651,"t":{"az":"Sənə cənnətin əkinlərini göstərimmi? Sübhanəllah, əlhəmdulillah, la ilahə illəllah, Allahu əkbər.","en":"Shall I guide you to the plantation of Paradise? SubhanAllah, Alhamdulillah, La ilaha illallah, Allahu Akbar.","ru":"Не указать ли тебе на посев рая? Субхана-Ллах, Аль-хамду ли-Ллях, Ля иляха илля-Ллах, Аллаху Акбар.","tr":"Sana cennet fidanlarını göstereyim mi? Sübhanallah, Elhamdülillah, La ilahe illallah, Allahu Ekber.","ar":"أَلَا أَدُلُّكَ عَلَى غِرَاسِ الْجَنَّةِ سُبْحَانَ اللَّهِ وَالْحَمْدُ لِلَّهِ وَلَا إِلَهَ إِلَّا اللَّهُ وَاللَّهُ أَكْبَرُ"},"src":{"az":"İbn Macə 3807","en":"Ibn Majah 3807","ru":"Ибн Маджа 3807","tr":"İbn Mâce 3807","ar":"ابن ماجه 3807"}},{"id":654,"t":{"az":"Müsəlman olub kifayət qədər ruzi verilən və Allahın verdiyi ilə qane olan nicat tapmışdır.","en":"Successful is one who submits to Islam, is given enough provision, and is content with what Allah gave him.","ru":"Преуспел тот, кто принял Ислам, получил достаточное пропитание и доволен тем, что дал ему Аллах.","tr":"İslam'a girip yeterli rızık verilen ve Allah'ın verdiğine kanaatkâr olan kurtuluşa ermiştir.","ar":"قَدْ أَفْلَحَ مَنْ أَسْلَمَ وَرُزِقَ كَفَافًا وَقَنَّعَهُ اللَّهُ بِمَا آتَاهُ"},"src":{"az":"Muslim 1054","en":"Muslim 1054","ru":"Муслим 1054","tr":"Müslim 1054","ar":"مسلم 1054"}},{"id":655,"t":{"az":"Hər birinizlə Rəbbi danışacaq, arada tərcüməçi olmayacaq.","en":"Each of you will speak to his Lord with no interpreter between them.","ru":"Каждый из вас будет говорить с Господом, без переводчика между ними.","tr":"Her birinizle Rabbi konuşacak, arada tercüman olmayacak.","ar":"مَا مِنْكُمْ مِنْ أَحَدٍ إِلَّا سَيُكَلِّمُهُ رَبُّهُ لَيْسَ بَيْنَهُ وَبَيْنَهُ تُرْجُمَانٌ"},"src":{"az":"Buxari 7443","en":"Bukhari 7443","ru":"Бухари 7443","tr":"Buhârî 7443","ar":"البخاري 7443"}},{"id":657,"t":{"az":"Qul xəstələnəndə və ya səfərə çıxanda, muqim ikən etdiyi əməllərin savabı yazılar.","en":"When a servant falls ill or travels, the reward of what he used to do when healthy and resident is written for him.","ru":"Когда раб болеет или в пути, ему записывается такая же награда, какую он получал, будучи здоровым и на месте.","tr":"Kul hastalanınca veya yolculuk edince, mukim iken yaptığı amellerin sevabı yazılır.","ar":"إِذَا مَرِضَ الْعَبْدُ أَوْ سَافَرَ كُتِبَ لَهُ مِثْلُ مَا كَانَ يَعْمَلُ مُقِيمًا صَحِيحًا"},"src":{"az":"Buxari 2996","en":"Bukhari 2996","ru":"Бухари 2996","tr":"Buhârî 2996","ar":"البخاري 2996"}},{"id":659,"t":{"az":"Allah təqvalı, ehtiyacsız, gözə görünməyən qulu sevir.","en":"Allah loves the servant who is pious, self-sufficient, and unnoticed.","ru":"Аллах любит раба богобоязненного, самодостаточного и незаметного.","tr":"Allah takvalı, zengin gönüllü ve göze görünmeyen kulu sever.","ar":"إِنَّ اللَّهَ يُحِبُّ الْعَبْدَ التَّقِيَّ الْغَنِيَّ الْخَفِيَّ"},"src":{"az":"Muslim 2965","en":"Muslim 2965","ru":"Муслим 2965","tr":"Müslim 2965","ar":"مسلم 2965"}},{"id":660,"t":{"az":"Allah hər şeydə ehsanı (yaxşılığı, gözəlliyi) yazmışdır.","en":"Allah has prescribed excellence in all things.","ru":"Аллах предписал совершенство во всём.","tr":"Allah her şeyde ihsanı yazmıştır.","ar":"إِنَّ اللَّهَ كَتَبَ الْإِحْسَانَ عَلَى كُلِّ شَيْءٍ"},"src":{"az":"Muslim 1955","en":"Muslim 1955","ru":"Муслим 1955","tr":"Müslim 1955","ar":"مسلم 1955"}},{"id":661,"t":{"az":"Kim əsr namazını tərk edərsə, əməli boşa çıxar.","en":"Whoever leaves the Asr prayer, his deeds are nullified.","ru":"Кто оставит предвечернюю молитву, его дела будут тщетны.","tr":"Kim ikindi namazını terk ederse ameli boşa gider.","ar":"مَنْ تَرَكَ صَلَاةَ الْعَصْرِ فَقَدْ حَبِطَ عَمَلُهُ"},"src":{"az":"Buxari 553","en":"Bukhari 553","ru":"Бухари 553","tr":"Buhârî 553","ar":"البخاري 553"}},{"id":662,"t":{"az":"İnsanlar azanın və birinci sıranın fəzilətini bilsəydilər, püşk atmaq lazım olsaydı belə bunu edərdilər.","en":"If people knew the reward of the call to prayer and the first row, and had to draw lots, they would.","ru":"Если бы люди знали о достоинстве азана и первого ряда, они бы бросили жребий.","tr":"İnsanlar ezanın ve ilk safın faziletini bilselerdi, kura çekmek gerekse bile çekerlerdi.","ar":"لَوْ يَعْلَمُ النَّاسُ مَا فِي النِّدَاءِ وَالصَّفِّ الْأَوَّلِ ثُمَّ لَمْ يَجِدُوا إِلَّا أَنْ يَسْتَهِمُوا عَلَيْهِ لَاسْتَهَمُوا"},"src":{"az":"Buxari 615","en":"Bukhari 615","ru":"Бухари 615","tr":"Buhârî 615","ar":"البخاري 615"}},{"id":663,"t":{"az":"İxlas surəsi Quranın üçdə birinə bərabərdir.","en":"Surah al-Ikhlas equals one-third of the Quran.","ru":"Сура Аль-Ихлас равна одной трети Корана.","tr":"İhlas suresi Kur'an'ın üçte birine denktir.","ar":"قُلْ هُوَ اللَّهُ أَحَدٌ تَعْدِلُ ثُلُثَ الْقُرْآنِ"},"src":{"az":"Muslim 811","en":"Muslim 811","ru":"Муслим 811","tr":"Müslim 811","ar":"مسلم 811"}},{"id":664,"t":{"az":"Kim gecə Bəqərə surəsinin son iki ayəsini oxuyarsa, ona kifayət edər.","en":"Whoever recites the last two verses of Surah al-Baqarah at night, they will suffice him.","ru":"Кто прочитает два последних аята суры Аль-Бакара ночью, ему будет достаточно.","tr":"Kim gece Bakara suresinin son iki ayetini okursa, ona yeter.","ar":"مَنْ قَرَأَ الْآيَتَيْنِ مِنْ آخِرِ سُورَةِ الْبَقَرَةِ فِي لَيْلَةٍ كَفَتَاهُ"},"src":{"az":"Buxari 5009","en":"Bukhari 5009","ru":"Бухари 5009","tr":"Buhârî 5009","ar":"البخاري 5009"}},{"id":665,"t":{"az":"Kimdən elm soruşulsa və gizlədərsə, qiyamətdə oddan yüyənlə yüyənlənər.","en":"Whoever is asked about knowledge and conceals it will be bridled with a bridle of fire.","ru":"Кого спросят о знании, а он скроет его, тому наденут огненную узду.","tr":"Kimden ilim sorulur da gizlerse, kıyamette ateşten gemle gemlenir.","ar":"مَنْ سُئِلَ عَنْ عِلْمٍ فَكَتَمَهُ أَلْجَمَهُ اللَّهُ بِلِجَامٍ مِنْ نَارٍ"},"src":{"az":"Əbu Davud 3658","en":"Abu Dawud 3658","ru":"Абу Дауд 3658","tr":"Ebû Dâvûd 3658","ar":"أبو داود 3658"}},{"id":666,"t":{"az":"Oruc Mənimdir və onu Mən mükafatlandıraram — deyə Allah buyurmuşdur.","en":"Fasting is for Me and I shall reward it — says Allah.","ru":"Пост — для Меня, и Я Сам вознагражу за него — говорит Аллах.","tr":"Oruç Benim içindir ve onu Ben mükafatlandırırım — diye Allah buyurmuştur.","ar":"الصَّوْمُ لِي وَأَنَا أَجْزِي بِهِ"},"src":{"az":"Buxari 1904","en":"Bukhari 1904","ru":"Бухари 1904","tr":"Buhârî 1904","ar":"البخاري 1904"}},{"id":670,"t":{"az":"Mömin kişi və qadın canında, övladında, malında bəlaya düçar olmaqda davam edər ki, Allahla günahsız görüşsün.","en":"The believer is afflicted in himself, his children, and his wealth until he meets Allah with no sin upon him.","ru":"Верующий и верующая продолжают подвергаться испытаниям в себе, детях и имуществе, пока не встретят Аллаха без грехов.","tr":"Mümin erkek ve kadın canında, evladında, malında bela ile karşılaşmaya devam eder ki, Allah'a günahsız kavuşsun.","ar":"مَا يَزَالُ الْبَلَاءُ بِالْمُؤْمِنِ وَالْمُؤْمِنَةِ فِي نَفْسِهِ وَوَلَدِهِ وَمَالِهِ حَتَّى يَلْقَى اللَّهَ وَمَا عَلَيْهِ خَطِيئَةٌ"},"src":{"az":"Tirmizi 2399","en":"Tirmidhi 2399","ru":"Тирмизи 2399","tr":"Tirmizî 2399","ar":"الترمذي 2399"}},{"id":671,"t":{"az":"Dünya şirin və yaşıldır; Allah sizi orada xəlifə edib baxar necə əməl edirsiniz.","en":"The world is sweet and green, and Allah has made you stewards in it, so He observes how you act.","ru":"Мир сладок и зелен, и Аллах сделал вас наместниками, наблюдая, как вы действуете.","tr":"Dünya tatlı ve yeşildir; Allah sizi orada halife kılıp nasıl amel edeceğinize bakar.","ar":"إِنَّ الدُّنْيَا حُلْوَةٌ خَضِرَةٌ وَإِنَّ اللَّهَ مُسْتَخْلِفُكُمْ فِيهَا فَيَنْظُرُ كَيْفَ تَعْمَلُونَ"},"src":{"az":"Muslim 2742","en":"Muslim 2742","ru":"Муслим 2742","tr":"Müslim 2742","ar":"مسلم 2742"}},{"id":672,"t":{"az":"Cənnət sizə ayaqqabınızın bağından daha yaxındır, cəhənnəm də elədir.","en":"Paradise is closer to any of you than the strap of his sandal, and so is the Fire.","ru":"Рай ближе к каждому из вас, чем ремешок его обуви, и огонь тоже.","tr":"Cennet sizden birinize ayakkabısının bağından daha yakındır, cehennem de öyle.","ar":"الْجَنَّةُ أَقْرَبُ إِلَى أَحَدِكُمْ مِنْ شِرَاكِ نَعْلِهِ وَالنَّارُ مِثْلُ ذَلِكَ"},"src":{"az":"Buxari 6488","en":"Bukhari 6488","ru":"Бухари 6488","tr":"Buhârî 6488","ar":"البخاري 6488"}},{"id":673,"t":{"az":"Mənə salavat gətirin, harada olsanız salavtınız mənə çatar.","en":"Send blessings upon me, for your blessings reach me wherever you are.","ru":"Благословляйте меня, ибо ваши благословения достигают меня, где бы вы ни были.","tr":"Bana salavat getirin, nerede olursanız olun salavatınız bana ulaşır.","ar":"صَلُّوا عَلَيَّ فَإِنَّ صَلَاتَكُمْ تَبْلُغُنِي حَيْثُ كُنْتُمْ"},"src":{"az":"Əbu Davud 2042","en":"Abu Dawud 2042","ru":"Абу Дауд 2042","tr":"Ebû Dâvûd 2042","ar":"أبو داود 2042"}},{"id":675,"t":{"az":"Halal aydındır, haram aydındır; ikisinin arasında şübhəli şeylər var.","en":"The lawful is clear and the unlawful is clear, and between them are doubtful matters.","ru":"Дозволенное ясно и запретное ясно, а между ними — сомнительное.","tr":"Helal bellidir, haram bellidir; ikisinin arasında şüpheli şeyler vardır.","ar":"الْحَلَالُ بَيِّنٌ وَالْحَرَامُ بَيِّنٌ وَبَيْنَهُمَا أُمُورٌ مُشْتَبِهَاتٌ"},"src":{"az":"Buxari 52","en":"Bukhari 52","ru":"Бухари 52","tr":"Buhârî 52","ar":"البخاري 52"}},{"id":676,"t":{"az":"Şübhəli olanı buraxıb şübhəsiz olana keç.","en":"Leave what makes you doubt for what does not make you doubt.","ru":"Оставь то, что вызывает сомнение, ради того, что не вызывает.","tr":"Şüphelendiren şeyi bırak, şüphelendirmeyene geç.","ar":"دَعْ مَا يَرِيبُكَ إِلَى مَا لَا يَرِيبُكَ"},"src":{"az":"Tirmizi 2518","en":"Tirmidhi 2518","ru":"Тирмизи 2518","tr":"Tirmizî 2518","ar":"الترمذي 2518"}},{"id":677,"t":{"az":"Sənə əmanət edənin əmanətini ver, sənə xəyanət edənə xəyanət etmə.","en":"Return the trust to the one who entrusted you, and do not betray the one who betrayed you.","ru":"Верни доверенное тому, кто тебе доверил, и не предавай того, кто тебя предал.","tr":"Sana emanet edene emanetini ver, sana ihanet edene ihanet etme.","ar":"أَدِّ الْأَمَانَةَ إِلَى مَنِ ائْتَمَنَكَ وَلَا تَخُنْ مَنْ خَانَكَ"},"src":{"az":"Əbu Davud 3535","en":"Abu Dawud 3535","ru":"Абу Дауд 3535","tr":"Ebû Dâvûd 3535","ar":"أبو داود 3535"}},{"id":683,"t":{"az":"Hər aydan üç gün və Ramazan oruc tutmaq bütün ili oruc tutmaq kimidir.","en":"Three days from each month and Ramadan to Ramadan — that is like fasting the entire year.","ru":"Три дня каждого месяца и Рамадан — это подобно посту целого года.","tr":"Her aydan üç gün ve Ramazan'dan Ramazan'a oruç tutmak bütün yıl tutmak gibidir.","ar":"ثَلَاثَةٌ مِنْ كُلِّ شَهْرٍ وَرَمَضَانُ إِلَى رَمَضَانَ فَهَذَا صِيَامُ الدَّهْرِ كُلِّهِ"},"src":{"az":"Muslim 1162","en":"Muslim 1162","ru":"Муслим 1162","tr":"Müslim 1162","ar":"مسلم 1162"}},{"id":684,"t":{"az":"Allah bu ümmətə iki qılınc birləşdirməz: birini özündən, birini düşmənindən.","en":"Allah will not combine two swords against this nation: one from within and one from the enemy.","ru":"Аллах не объединит два меча против этой общины: один изнутри и один от врага.","tr":"Allah bu ümmete iki kılıcı birleştirmez: birini kendi içinden, birini düşmandan.","ar":"لَا يَجْمَعُ اللَّهُ عَلَى هَذِهِ الْأُمَّةِ سَيْفَيْنِ سَيْفًا مِنْهَا وَسَيْفًا مِنْ عَدُوِّهَا"},"src":{"az":"Əbu Davud 4301","en":"Abu Dawud 4301","ru":"Абу Дауд 4301","tr":"Ebû Dâvûd 4301","ar":"أبو داود 4301"}},{"id":685,"t":{"az":"Bir toplum oturub Allahı zikr etsə, mələklər onları əhatə edər.","en":"No group sits remembering Allah except that angels surround them.","ru":"Когда люди собираются, поминая Аллаха, ангелы окружают их.","tr":"Bir topluluk oturup Allah'ı zikrederse, melekler onları kuşatır.","ar":"مَا جَلَسَ قَوْمٌ مَجْلِسًا يَذْكُرُونَ اللَّهَ إِلَّا حَفَّتْهُمُ الْمَلَائِكَةُ"},"src":{"az":"Muslim 2700","en":"Muslim 2700","ru":"Муслим 2700","tr":"Müslim 2700","ar":"مسلم 2700"}},{"id":686,"t":{"az":"Bir xurma parçası ilə olsa da cəhənnəmdən qorunun; tapmayan gözəl söz ilə.","en":"Protect yourselves from the Fire even with half a date; if not, then with a good word.","ru":"Защитите себя от огня хотя бы половинкой финика; если нет — добрым словом.","tr":"Bir hurma parçasıyla da olsa cehennemden korunun; bulamayan güzel bir sözle.","ar":"اتَّقُوا النَّارَ وَلَوْ بِشِقِّ تَمْرَةٍ فَمَنْ لَمْ يَجِدْ فَبِكَلِمَةٍ طَيِّبَةٍ"},"src":{"az":"Buxari 6023","en":"Bukhari 6023","ru":"Бухари 6023","tr":"Buhârî 6023","ar":"البخاري 6023"}},{"id":687,"t":{"az":"Səbr edin; möminin başına gələn qəm, yorğunluq, xəstəlik, hətta tikanlı batsa belə günahlarına kəffarədir.","en":"Be patient; no grief, fatigue, or illness befalls a believer, even a thorn prick, except that it expiates his sins.","ru":"Терпите; верующего не постигнет ни печаль, ни усталость, ни болезнь — даже укол шипа — кроме как они искупят его грехи.","tr":"Sabredin; müminin başına gelen keder, yorgunluk, hastalık, diken batması bile günahlarına kefarettir.","ar":"اصْبِرُوا فَإِنَّهُ لَا يُصِيبُ الْمُؤْمِنَ هَمٌّ وَلَا نَصَبٌ وَلَا سَقَمٌ حَتَّى الشَّوْكَةُ يُشَاكُهَا إِلَّا كُفِّرَتْ بِهَا مِنْ خَطَايَاهُ"},"src":{"az":"Buxari 5641","en":"Bukhari 5641","ru":"Бухари 5641","tr":"Buhârî 5641","ar":"البخاري 5641"}},{"id":688,"t":{"az":"Dünyanın axirətin yanında halı barmağını dənizə batırıb çıxaran kimi qədərdir; bax nə ilə qayıdır.","en":"The world compared to the Hereafter is like dipping your finger in the sea — see what it comes back with.","ru":"Мир по сравнению с будущей жизнью — как если один из вас опустит палец в море; пусть посмотрит, с чем вернётся.","tr":"Dünyanın ahirete oranı, parmağını denize batırıp çıkaran gibidir; bak ne ile dönüyor.","ar":"مَا الدُّنْيَا فِي الْآخِرَةِ إِلَّا مِثْلُ مَا يَجْعَلُ أَحَدُكُمْ إِصْبَعَهُ فِي الْيَمِّ فَلْيَنْظُرْ بِمَ يَرْجِعُ"},"src":{"az":"Muslim 2858","en":"Muslim 2858","ru":"Муслим 2858","tr":"Müslim 2858","ar":"مسلم 2858"}},{"id":689,"t":{"az":"Kim qorxarsa gecədən yola çıxar, gecə yola çıxan mənzilə çatar.","en":"Whoever fears sets out at night, and whoever sets out at night reaches the destination.","ru":"Кто боится — выходит ночью, а кто выходит ночью — достигает места.","tr":"Kim korkarsa gece yola çıkar, gece yola çıkan menzile ulaşır.","ar":"مَنْ خَافَ أَدْلَجَ وَمَنْ أَدْلَجَ بَلَغَ الْمَنْزِلَ"},"src":{"az":"Tirmizi 2450","en":"Tirmidhi 2450","ru":"Тирмизи 2450","tr":"Tirmizî 2450","ar":"الترمذي 2450"}},{"id":691,"t":{"az":"Bir mənzilə endiyinizdə deyin: Allahın tam kəlmələri ilə yaratdığı şeylərin şərindən sığınıram.","en":"When you stop at a place, say: I seek refuge in the perfect words of Allah from the evil of what He created.","ru":"Когда остановитесь где-то, скажите: «Прибегаю к совершенным словам Аллаха от зла того, что Он создал».","tr":"Bir menzile indiğinizde deyin: Allah'ın tam kelimeleriyle yarattıklarının şerrinden sığınırım.","ar":"إِذَا نَزَلْتُمْ مَنْزِلًا فَقُولُوا أَعُوذُ بِكَلِمَاتِ اللَّهِ التَّامَّاتِ مِنْ شَرِّ مَا خَلَقَ"},"src":{"az":"Muslim 2708","en":"Muslim 2708","ru":"Муслим 2708","tr":"Müslim 2708","ar":"مسلم 2708"}},{"id":692,"t":{"az":"İman etməyincə cənnətə girməzsiniz, bir-birinizi sevməyincə iman etməzsiniz.","en":"You will not enter Paradise until you believe, and you will not believe until you love one another.","ru":"Не войдёте в рай, пока не уверуете, и не уверуете, пока не полюбите друг друга.","tr":"İman etmedikçe cennete giremezsiniz, birbirinizi sevmedikçe iman etmiş olmazsınız.","ar":"لَا تَدْخُلُونَ الْجَنَّةَ حَتَّى تُؤْمِنُوا وَلَا تُؤْمِنُوا حَتَّى تَحَابُّوا"},"src":{"az":"Muslim 54","en":"Muslim 54","ru":"Муслим 54","tr":"Müslim 54","ar":"مسلم 54"}},{"id":693,"t":{"az":"Aranızda salamı yayın.","en":"Spread peace among yourselves.","ru":"Распространяйте мир между собой.","tr":"Aranızda selamı yayın.","ar":"أَفْشُوا السَّلَامَ بَيْنَكُمْ"},"src":{"az":"Muslim 54","en":"Muslim 54","ru":"Муслим 54","tr":"Müslim 54","ar":"مسلم 54"}},{"id":694,"t":{"az":"Mömin lənətçi, söyüşçü, çirkin danışan deyildir.","en":"The believer is not one who curses, insults, is vulgar, or uses foul language.","ru":"Верующий не бранит, не проклинает, не груб и не сквернослов.","tr":"Mümin lanetçi, sövücü, çirkin sözlü ve ağzı bozuk değildir.","ar":"لَيْسَ الْمُؤْمِنُ بِالطَّعَّانِ وَلَا اللَّعَّانِ وَلَا الْفَاحِشِ وَلَا الْبَذِيءِ"},"src":{"az":"Tirmizi 1977","en":"Tirmidhi 1977","ru":"Тирмизи 1977","tr":"Tirmizî 1977","ar":"الترمذي 1977"}},{"id":695,"t":{"az":"Allah sizin surətlərinizə, mallarınıza baxmaz; lakin qəlblərinizə və əməllərinizə baxar.","en":"Allah does not look at your appearances or wealth, but He looks at your hearts and deeds.","ru":"Аллах не смотрит на вашу внешность и имущество, но смотрит на ваши сердца и дела.","tr":"Allah sizin suretlerinize ve mallarınıza değil, kalplerinize ve amellerinize bakar.","ar":"إِنَّ اللَّهَ لَا يَنْظُرُ إِلَى صُوَرِكُمْ وَأَمْوَالِكُمْ وَلَكِنْ يَنْظُرُ إِلَى قُلُوبِكُمْ وَأَعْمَالِكُمْ"},"src":{"az":"Muslim 2564","en":"Muslim 2564","ru":"Муслим 2564","tr":"Müslim 2564","ar":"مسلم 2564"}},{"id":696,"t":{"az":"Sıralarınızı düzəldin, çünki sıralarının bərabərləşdirilməsi namazın qurulmasındandır.","en":"Straighten your rows, for straightening the rows is part of establishing the prayer.","ru":"Выравнивайте ряды, ибо это часть совершения молитвы.","tr":"Saflarınızı düzeltin, çünkü safları düzeltmek namazı ikame etmektendir.","ar":"سَوُّوا صُفُوفَكُمْ فَإِنَّ تَسْوِيَةَ الصُّفُوفِ مِنْ إِقَامَةِ الصَّلَاةِ"},"src":{"az":"Buxari 723","en":"Bukhari 723","ru":"Бухари 723","tr":"Buhârî 723","ar":"البخاري 723"}},{"id":697,"t":{"az":"Quranı mütəmadi oxuyun, canım əlində olana and olsun ki, o dəvədən daha tez yaddaşdan çıxar.","en":"Commit yourselves to the Quran, for by the One in whose hand is my soul, it escapes faster than a camel from its rope.","ru":"Будьте верны Корану, ибо клянусь Тем, в чьей Руке моя душа, он ускользает быстрее верблюда из привязи.","tr":"Kur'an'ı sürekli okuyun, canım elinde olana yemin olsun ki o deveden daha çabuk bellekten kaçar.","ar":"تَعَاهَدُوا الْقُرْآنَ فَوَالَّذِي نَفْسِي بِيَدِهِ لَهُوَ أَشَدُّ تَفَلُّتًا مِنَ الْإِبِلِ فِي عُقُلِهَا"},"src":{"az":"Buxari 5033","en":"Bukhari 5033","ru":"Бухари 5033","tr":"Buhârî 5033","ar":"البخاري 5033"}},{"id":698,"t":{"az":"Allahım, fayda verməyən elmdən Sənə sığınıram.","en":"O Allah, I seek refuge in You from knowledge that does not benefit.","ru":"О Аллах, я прибегаю к Тебе от бесполезного знания.","tr":"Allah'ım, fayda vermeyen ilimden Sana sığınırım.","ar":"اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ عِلْمٍ لَا يَنْفَعُ"},"src":{"az":"Muslim 2722","en":"Muslim 2722","ru":"Муслим 2722","tr":"Müslim 2722","ar":"مسلم 2722"}},{"id":699,"t":{"az":"Kim yalan sözü, ona əməl etməyi və cahilliyi tərk etməzsə, Allahın onun yeməyini-içməyini tərk etməsinə ehtiyacı yoxdur.","en":"Whoever does not give up false speech, acting on it, and ignorance — Allah has no need of his leaving food and drink.","ru":"Кто не оставит ложь, действия по ней и невежество — Аллаху не нужно его оставление еды и питья.","tr":"Kim yalan sözü, onunla amel etmeyi ve cahilliği bırakmazsa, Allah'ın onun yeme-içmesini bırakmasına ihtiyacı yoktur.","ar":"مَنْ لَمْ يَدَعْ قَوْلَ الزُّورِ وَالْعَمَلَ بِهِ وَالْجَهْلَ فَلَيْسَ لِلَّهِ حَاجَةٌ أَنْ يَدَعَ طَعَامَهُ وَشَرَابَهُ"},"src":{"az":"Buxari 6057","en":"Bukhari 6057","ru":"Бухари 6057","tr":"Buhârî 6057","ar":"البخاري 6057"}},{"id":701,"t":{"az":"Allah buyurur: Mən qulumun Məni düşündüyü kimiyəm, o Məni zikr edəndə onunlayam.","en":"Allah says: I am as My servant thinks of Me, and I am with him when he remembers Me.","ru":"Аллах говорит: Я такой, каким Мой раб думает обо Мне, и Я с ним, когда он поминает Меня.","tr":"Allah buyurur: Ben kulumun Beni düşündüğü gibiyim, o Beni zikredince onunlayım.","ar":"يَقُولُ اللَّهُ أَنَا عِنْدَ ظَنِّ عَبْدِي بِي وَأَنَا مَعَهُ إِذَا ذَكَرَنِي"},"src":{"az":"Buxari 7405","en":"Bukhari 7405","ru":"Бухари 7405","tr":"Buhârî 7405","ar":"البخاري 7405"}},{"id":704,"t":{"az":"Dünya Allahın yanında ağcaqanadın qanadına dəyərsə, kafirə bir damcı su belə verməzdi.","en":"If the world weighed as much as a mosquito's wing to Allah, He would not give a disbeliever a drop of water.","ru":"Если бы мир стоил у Аллаха крыла комара, Он не дал бы неверному каплю воды.","tr":"Dünya Allah katında sivrisineğin kanadı kadar ağırlığa sahip olsaydı, kâfire bir damla su bile vermezdi.","ar":"لَوْ أَنَّ الدُّنْيَا تَزِنُ عِنْدَ اللَّهِ جَنَاحَ بَعُوضَةٍ مَا سَقَى كَافِرًا مِنْهَا قَطْرَةَ مَاءٍ"},"src":{"az":"Tirmizi 2320","en":"Tirmidhi 2320","ru":"Тирмизи 2320","tr":"Tirmizî 2320","ar":"الترمذي 2320"}},{"id":705,"t":{"az":"Cənnət əhli yuxarı otaq sahiblərini parlaq ulduz gördüyünüz kimi görərlər.","en":"The people of Paradise will see the dwellers of the upper chambers as you see a shining star.","ru":"Обитатели рая будут видеть обладателей комнат, как вы видите яркую звезду.","tr":"Cennet ehli yüksek oda sahiplerini parlak yıldız gördüğünüz gibi görürler.","ar":"إِنَّ أَهْلَ الْجَنَّةِ لَيَتَرَاءَوْنَ أَهْلَ الْغُرَفِ كَمَا تَتَرَاءَوْنَ الْكَوْكَبَ الدُّرِّيَّ"},"src":{"az":"Buxari 3256","en":"Bukhari 3256","ru":"Бухари 3256","tr":"Buhârî 3256","ar":"البخاري 3256"}},{"id":707,"t":{"az":"Kim yatağına girəndə Ayətəl-kürsi oxuyarsa, Allahdan bir qoruyucu onunla olar.","en":"Whoever recites Ayat al-Kursi before sleeping will have a protector from Allah.","ru":"Кто прочитает Аят аль-Курси перед сном, над ним будет хранитель от Аллаха.","tr":"Kim yatağına girdiğinde Ayetel Kürsi okursa, Allah tarafından bir koruyucu onunla olur.","ar":"مَنْ قَرَأَ آيَةَ الْكُرْسِيِّ حِينَ يَأْخُذُ مَضْجَعَهُ لَمْ يَزَلْ عَلَيْهِ مِنَ اللَّهِ حَافِظٌ"},"src":{"az":"Buxari 5010","en":"Bukhari 5010","ru":"Бухари 5010","tr":"Buhârî 5010","ar":"البخاري 5010"}},{"id":709,"t":{"az":"Ən xeyirliniz ailəsinə ən xeyirli olanıdır. Mən ailəmə ən xeyirli olanınızam.","en":"The best of you is the best to his family, and I am the best of you to my family.","ru":"Лучший из вас — лучший к своей семье, и я — лучший из вас к своей семье.","tr":"En hayırlınız ailesine en hayırlı olanıdır. Ben aileme en hayırlı olanınızım.","ar":"خَيْرُكُمْ خَيْرُكُمْ لِأَهْلِهِ وَأَنَا خَيْرُكُمْ لِأَهْلِي"},"src":{"az":"Tirmizi 3895","en":"Tirmidhi 3895","ru":"Тирмизи 3895","tr":"Tirmizî 3895","ar":"الترمذي 3895"}},{"id":710,"t":{"az":"Allah alış-verişdə və tələbdə xoş rəftar edən kəsə rəhmət etsin.","en":"May Allah have mercy on a man who is easy-going when he sells, buys, and asks for payment.","ru":"Да помилует Аллах того, кто мягок при продаже, покупке и взыскании.","tr":"Allah alırken, satarken ve alacak isterken kolaylık gösteren kişiye rahmet etsin.","ar":"رَحِمَ اللَّهُ رَجُلًا سَمْحًا إِذَا بَاعَ وَإِذَا اشْتَرَى وَإِذَا اقْتَضَى"},"src":{"az":"Buxari 2076","en":"Bukhari 2076","ru":"Бухари 2076","tr":"Buhârî 2076","ar":"البخاري 2076"}},{"id":711,"t":{"az":"Kim səhər-axşam məscidə getsə, hər gedişində Allah ona cənnətdə yer hazırlayar.","en":"Whoever goes to the mosque in the morning or evening, Allah prepares for him a place in Paradise each time.","ru":"Кто ходит в мечеть утром или вечером, Аллах готовит ему место в раю каждый раз.","tr":"Kim sabah akşam mescide giderse, her gidişinde Allah cennette ona yer hazırlar.","ar":"مَنْ غَدَا إِلَى الْمَسْجِدِ وَرَاحَ أَعَدَّ اللَّهُ لَهُ نُزُلَهُ مِنَ الْجَنَّةِ كُلَّمَا غَدَا أَوْ رَاحَ"},"src":{"az":"Buxari 662","en":"Bukhari 662","ru":"Бухари 662","tr":"Buhârî 662","ar":"البخاري 662"}},{"id":717,"t":{"az":"Kim səhər-axşam yüz dəfə \"Sübhanəllahi və bihəmdihi\" desə, qiyamət günü ondan üstün gətirən olmaz.","en":"Whoever says \"SubhanAllahi wa bihamdihi\" a hundred times morning and evening, no one will bring anything better on the Day of Judgment.","ru":"Кто утром и вечером скажет «Субхана-Ллахи ва бихамдихи» сто раз, никто не придёт в День Суда с лучшим.","tr":"Kim sabah akşam yüz kere \"Sübhanallahi ve bihamdihi\" derse, kıyamette ondan daha üstün getiren olmaz.","ar":"مَنْ قَالَ حِينَ يُصْبِحُ وَحِينَ يُمْسِي سُبْحَانَ اللَّهِ وَبِحَمْدِهِ مِائَةَ مَرَّةٍ لَمْ يَأْتِ أَحَدٌ يَوْمَ الْقِيَامَةِ بِأَفْضَلَ مِمَّا جَاءَ بِهِ"},"src":{"az":"Muslim 2692","en":"Muslim 2692","ru":"Муслим 2692","tr":"Müslim 2692","ar":"مسلم 2692"}},{"id":719,"t":{"az":"Allahı qoru, Allah səni qoruyar; Allahı qoru, Onu qarşında taparsan.","en":"Be mindful of Allah and He will protect you; be mindful of Allah and you will find Him before you.","ru":"Помни об Аллахе — и Он защитит тебя; помни об Аллахе — и найдёшь Его пред собой.","tr":"Allah'ı koru, Allah seni korur; Allah'ı koru, O'nu karşında bulursun.","ar":"احْفَظِ اللَّهَ يَحْفَظْكَ احْفَظِ اللَّهَ تَجِدْهُ تُجَاهَكَ"},"src":{"az":"Tirmizi 2516","en":"Tirmidhi 2516","ru":"Тирмизи 2516","tr":"Tirmizî 2516","ar":"الترمذي 2516"}},{"id":721,"t":{"az":"Cənnətdə gözün görmədiyi, qulağın eşitmədiyi, insanın qəlbinə gəlməyən şeylər var.","en":"In Paradise there is what no eye has seen, no ear has heard, and no heart has imagined.","ru":"В раю есть то, что глаз не видел, ухо не слышало и сердце человека не представляло.","tr":"Cennette gözün görmediği, kulağın duymadığı, insanın kalbine gelmeyen şeyler vardır.","ar":"إِنَّ فِي الْجَنَّةِ مَا لَا عَيْنٌ رَأَتْ وَلَا أُذُنٌ سَمِعَتْ وَلَا خَطَرَ عَلَى قَلْبِ بَشَرٍ"},"src":{"az":"Muslim 2825","en":"Muslim 2825","ru":"Муслим 2825","tr":"Müslim 2825","ar":"مسلم 2825"}},{"id":724,"t":{"az":"Allah çirkin və yaramaz sözlü kəsi sevməz.","en":"Allah hates the one who is obscene and vulgar.","ru":"Аллах ненавидит сквернослова и грубияна.","tr":"Allah çirkin sözlü ve kaba kişiye buğz eder.","ar":"إِنَّ اللَّهَ يُبْغِضُ الْفَاحِشَ الْبَذِيءَ"},"src":{"az":"Tirmizi 2002","en":"Tirmidhi 2002","ru":"Тирмизи 2002","tr":"Tirmizî 2002","ar":"الترمذي 2002"}},{"id":726,"t":{"az":"Allah pakdır, ancaq pak olanı qəbul edər.","en":"Allah is pure and accepts only what is pure.","ru":"Аллах чист и принимает только чистое.","tr":"Allah temizdir, ancak temiz olanı kabul eder.","ar":"إِنَّ اللَّهَ طَيِّبٌ لَا يَقْبَلُ إِلَّا طَيِّبًا"},"src":{"az":"Muslim 1015","en":"Muslim 1015","ru":"Муслим 1015","tr":"Müslim 1015","ar":"مسلم 1015"}},{"id":733,"t":{"az":"Kim halal qazancdan bir xurma dəyərində sədəqə versə, Allah onu sağ əli ilə alar.","en":"Whoever gives charity equal to a date from honest earnings, Allah takes it with His Right Hand.","ru":"Кто подаст милостыню размером с финик из честного заработка, Аллах примет её Правой Рукой.","tr":"Kim helal kazancından bir hurma değerinde sadaka verirse, Allah onu sağ eliyle alır.","ar":"مَا تَصَدَّقَ أَحَدٌ بِعَدْلِ تَمْرَةٍ مِنْ كَسْبٍ طَيِّبٍ إِلَّا أَخَذَهَا اللَّهُ بِيَمِينِهِ"},"src":{"az":"Buxari 1410","en":"Bukhari 1410","ru":"Бухари 1410","tr":"Buhârî 1410","ar":"البخاري 1410"}},{"id":736,"t":{"az":"Sizə fakirlik yox, dünyanın sizə açılmasından qorxuram.","en":"I do not fear poverty for you, but I fear that the world will be spread open for you.","ru":"Я не боюсь для вас бедности, но боюсь, что мир откроется перед вами.","tr":"Sizin için fakirlikten değil, dünyanın size açılmasından korkarım.","ar":"مَا الْفَقْرَ أَخْشَى عَلَيْكُمْ وَلَكِنِّي أَخْشَى أَنْ تُبْسَطَ عَلَيْكُمُ الدُّنْيَا"},"src":{"az":"Buxari 3158","en":"Bukhari 3158","ru":"Бухари 3158","tr":"Buhârî 3158","ar":"البخاري 3158"}},{"id":737,"t":{"az":"Kim mənə salavatı unutsa, cənnətin yolunu itirər.","en":"Whoever forgets to send blessings upon me has missed the path to Paradise.","ru":"Кто забыл благословить меня, тот сбился с пути в рай.","tr":"Kim bana salavat getirmeyi unutursa, cennetin yolunu kaçırır.","ar":"مَنْ نَسِيَ الصَّلَاةَ عَلَيَّ خَطِئَ طَرِيقَ الْجَنَّةِ"},"src":{"az":"İbn Macə 908","en":"Ibn Majah 908","ru":"Ибн Маджа 908","tr":"İbn Mâce 908","ar":"ابن ماجه 908"}},{"id":738,"t":{"az":"Müsəlman ağac əkər və ya əkin əkərsə, ondan quş, insan və ya heyvan yesə sədəqə olar.","en":"No Muslim plants a tree or sows a crop from which a bird, human, or animal eats except that it is charity for him.","ru":"Если мусульманин сажает дерево или сеет посев, и от него ест птица, человек или животное — это для него милостыня.","tr":"Bir Müslüman ağaç diker veya ekin ekerse, ondan kuş, insan veya hayvan yerse, bu onun için sadaka olur.","ar":"مَا مِنْ مُسْلِمٍ يَغْرِسُ غَرْسًا أَوْ يَزْرَعُ زَرْعًا فَيَأْكُلُ مِنْهُ طَيْرٌ أَوْ إِنْسَانٌ أَوْ بَهِيمَةٌ إِلَّا كَانَ لَهُ بِهِ صَدَقَةٌ"},"src":{"az":"Buxari 2320","en":"Bukhari 2320","ru":"Бухари 2320","tr":"Buhârî 2320","ar":"البخاري 2320"}},{"id":740,"t":{"az":"İnsanın İslamının gözəlliyindən biri ona aid olmayan şeyi tərk etməsidir.","en":"Part of the perfection of one's Islam is leaving what does not concern him.","ru":"Часть совершенства Ислама человека — оставить то, что его не касается.","tr":"Kişinin İslam'ının güzelliğinden biri, onu ilgilendirmeyen şeyi terk etmesidir.","ar":"مَنْ حُسْنِ إِسْلَامِ الْمَرْءِ تَرْكُهُ مَا لَا يَعْنِيهِ"},"src":{"az":"Tirmizi 2317","en":"Tirmidhi 2317","ru":"Тирмизи 2317","tr":"Tirmizî 2317","ar":"الترمذي 2317"}},{"id":747,"t":{"az":"Allahdan bağışlanma diləyin, mən gündə yetmişdən çox dəfə bağışlanma diləyirəm.","en":"Seek forgiveness from Allah, for I seek forgiveness from Allah more than seventy times a day.","ru":"Просите у Аллаха прощения, ибо я прошу прощения более семидесяти раз в день.","tr":"Allah'tan bağışlanma dileyin, ben günde yetmişten fazla istiğfar ederim.","ar":"اسْتَغْفِرُوا اللَّهَ فَإِنِّي أَسْتَغْفِرُ اللَّهَ فِي الْيَوْمِ أَكْثَرَ مِنْ سَبْعِينَ مَرَّةً"},"src":{"az":"Buxari 6307","en":"Bukhari 6307","ru":"Бухари 6307","tr":"Buhârî 6307","ar":"البخاري 6307"}},{"id":748,"t":{"az":"Yer üzündəkilərə rəhm edin ki, göydəki sizə rəhm etsin.","en":"Have mercy on those on earth, and the One in heaven will have mercy on you.","ru":"Милуйте тех, кто на земле, и помилует вас Тот, Кто на небе.","tr":"Yeryüzündekilere merhamet edin ki, gökteki size merhamet etsin.","ar":"اِرْحَمُوا مَنْ فِي الْأَرْضِ يَرْحَمْكُمْ مَنْ فِي السَّمَاءِ"},"src":{"az":"Tirmizi 1924","en":"Tirmidhi 1924","ru":"Тирмизи 1924","tr":"Tirmizî 1924","ar":"الترمذي 1924"}},{"id":749,"t":{"az":"Bil ki, zəfər səbrlə, fərəh kədərlə, hər çətinliklə bir asanlıq gəlir.","en":"Know that victory comes with patience, relief with affliction, and ease with hardship.","ru":"Знай, что победа — с терпением, облегчение — с тяготами, и с трудностями — лёгкость.","tr":"Bil ki zafer sabırla, ferahlık sıkıntıyla, her zorlukla bir kolaylık gelir.","ar":"وَاعْلَمْ أَنَّ النَّصْرَ مَعَ الصَّبْرِ وَأَنَّ الْفَرَجَ مَعَ الْكَرْبِ وَأَنَّ مَعَ الْعُسْرِ يُسْرًا"},"src":{"az":"Əhməd 2803","en":"Ahmad 2803","ru":"Ахмад 2803","tr":"Ahmed 2803","ar":"أحمد 2803"}},{"id":751,"t":{"az":"Cəhənnəm əhlinin ən yüngül əzablısı ayağının altına iki köz qoyulan kəsdir ki, onlardan beyni qaynayar.","en":"The lightest punishment in Hell is having two burning coals under one's feet that cause his brain to boil.","ru":"Самое лёгкое наказание в аду — два угля под ступнями, от которых кипит мозг.","tr":"Cehennemin en hafif azaplısı ayaklarının altına iki köz konulan kişidir ki, beynini kaynatır.","ar":"إِنَّ أَهْوَنَ أَهْلِ النَّارِ عَذَابًا يَوْمَ الْقِيَامَةِ لَرَجُلٌ تُوضَعُ فِي أَخْمَصِ قَدَمَيْهِ جَمْرَتَانِ يَغْلِي مِنْهُمَا دِمَاغُهُ"},"src":{"az":"Buxari 6561","en":"Bukhari 6561","ru":"Бухари 6561","tr":"Buhârî 6561","ar":"البخاري 6561"}},{"id":753,"t":{"az":"Allahın qadın qullarını Allahın məscidlərindən məhrum etməyin.","en":"Do not prevent the female servants of Allah from the mosques of Allah.","ru":"Не запрещайте рабыням Аллаха посещать мечети Аллаха.","tr":"Allah'ın kadın kullarını Allah'ın mescitlerinden men etmeyin.","ar":"لَا تَمْنَعُوا إِمَاءَ اللَّهِ مَسَاجِدَ اللَّهِ"},"src":{"az":"Buxari 900","en":"Bukhari 900","ru":"Бухари 900","tr":"Buhârî 900","ar":"البخاري 900"}},{"id":754,"t":{"az":"Allah qeyrətlidir, mömin də qeyrətlidir. Allahın qeyrəti möminin haramı etməsidir.","en":"Allah has a sense of protective jealousy, as does the believer. Allah's jealousy is when the believer does what He has forbidden.","ru":"Аллах ревностен и верующий ревностен. Ревность Аллаха — когда верующий совершает запретное.","tr":"Allah gayretlidir, mümin de gayretlidir. Allah'ın gayreti müminin haramı yapmasıdır.","ar":"إِنَّ اللَّهَ يَغَارُ وَإِنَّ الْمُؤْمِنَ يَغَارُ وَغَيْرَةُ اللَّهِ أَنْ يَأْتِيَ الْمُؤْمِنُ مَا حَرَّمَ اللَّهُ"},"src":{"az":"Buxari 5223","en":"Bukhari 5223","ru":"Бухари 5223","tr":"Buhârî 5223","ar":"البخاري 5223"}},{"id":755,"t":{"az":"Allaha ən sevimsizkəs inad mübahisəçidir.","en":"The most hateful person to Allah is the most quarrelsome.","ru":"Самый ненавистный Аллаху человек — наиболее упрямый спорщик.","tr":"Allah'a en sevimsiz kişi inatçı tartışmacıdır.","ar":"أَبْغَضُ الرِّجَالِ إِلَى اللَّهِ الْأَلَدُّ الْخَصِمُ"},"src":{"az":"Buxari 2457","en":"Bukhari 2457","ru":"Бухари 2457","tr":"Buhârî 2457","ar":"البخاري 2457"}},{"id":756,"t":{"az":"İnsanın hər oynağı üçün hər gün sədəqə var.","en":"Every joint of a person has a charity due on it every day the sun rises.","ru":"За каждый сустав человека каждый день полагается милостыня.","tr":"İnsanın her eklemi için güneşin doğduğu her gün sadaka vardır.","ar":"كُلُّ سُلَامَى مِنَ النَّاسِ عَلَيْهِ صَدَقَةٌ كُلَّ يَوْمٍ تَطْلُعُ فِيهِ الشَّمْسُ"},"src":{"az":"Buxari 2989","en":"Bukhari 2989","ru":"Бухари 2989","tr":"Buhârî 2989","ar":"البخاري 2989"}},{"id":759,"t":{"az":"Neçə fiqh daşıyıcısı var ki, onu özündən daha fəqih olana çatdırır.","en":"Many a carrier of knowledge conveys it to one more knowledgeable than himself.","ru":"Немало носителей знания передают его тому, кто разумеет больше.","tr":"Nice fıkıh taşıyıcısı onu kendinden daha fakih olana ulaştırır.","ar":"رُبَّ حَامِلِ فِقْهٍ إِلَى مَنْ هُوَ أَفْقَهُ مِنْهُ"},"src":{"az":"Tirmizi 2656","en":"Tirmidhi 2656","ru":"Тирмизи 2656","tr":"Tirmizî 2656","ar":"الترمذي 2656"}},{"id":761,"t":{"az":"İnsanın xərclədiyi ən fəzilətli dinar ailəsinə xərclədiyi dinardır.","en":"The best dinar a man spends is the dinar he spends on his family.","ru":"Лучший динар, что тратит человек — динар, потраченный на семью.","tr":"Kişinin harcadığı en faziletli dinar ailesine harcadığı dinardır.","ar":"أَفْضَلُ دِينَارٍ يُنْفِقُهُ الرَّجُلُ دِينَارٌ يُنْفِقُهُ عَلَى عِيَالِهِ"},"src":{"az":"Muslim 994","en":"Muslim 994","ru":"Муслим 994","tr":"Müslim 994","ar":"مسلم 994"}},{"id":762,"t":{"az":"Kim hər səhər-axşam \"Bismilləhiləzi la yədurru maa ismihi şəyun\" desə, heç bir şey ona zərər verməz.","en":"Whoever says every morning and evening \"In the name of Allah with whose name nothing can harm\" will not be harmed.","ru":"Кто каждое утро и вечер говорит «Именем Аллаха, с именем Которого ничто не вредит», тому ничто не навредит.","tr":"Kim her sabah akşam \"Bismillahillezi la yedurru mea ismihi şeyun\" derse, hiçbir şey ona zarar vermez.","ar":"مَا مِنْ عَبْدٍ يَقُولُ فِي صَبَاحِ كُلِّ يَوْمٍ وَمَسَاءِ كُلِّ لَيْلَةٍ بِسْمِ اللَّهِ الَّذِي لَا يَضُرُّ مَعَ اسْمِهِ شَيْءٌ"},"src":{"az":"Əbu Davud 5088","en":"Abu Dawud 5088","ru":"Абу Дауд 5088","tr":"Ebû Dâvûd 5088","ar":"أبو داود 5088"}},{"id":763,"t":{"az":"Kim bir bıldırçın yuvası qədər kiçik olsa belə məscid tikərsə, Allah cənnətdə ona ev tikər.","en":"Whoever builds a mosque for Allah, even as small as a bird's nest, Allah builds for him a house in Paradise.","ru":"Кто построит мечеть для Аллаха, хотя бы как гнездо куропатки, тому Аллах построит дом в раю.","tr":"Kim bir bıldırcın yuvası kadar küçük de olsa mescit yaparsa, Allah cennette ona ev yapar.","ar":"مَنْ بَنَى مَسْجِدًا لِلَّهِ كَمَفْحَصِ قَطَاةٍ أَوْ أَصْغَرَ بَنَى اللَّهُ لَهُ بَيْتًا فِي الْجَنَّةِ"},"src":{"az":"İbn Macə 738","en":"Ibn Majah 738","ru":"Ибн Маджа 738","tr":"İbn Mâce 738","ar":"ابن ماجه 738"}},{"id":764,"t":{"az":"Başına bəla gəldi deyə heç biriniz ölümü arzulamasın.","en":"None of you should wish for death because of a calamity that befalls him.","ru":"Никто из вас не должен желать смерти из-за постигшего его несчастья.","tr":"Başına gelen beladan dolayı hiçbiriniz ölümü temenni etmesin.","ar":"لَا يَتَمَنَّيَنَّ أَحَدُكُمُ الْمَوْتَ لِضُرٍّ نَزَلَ بِهِ"},"src":{"az":"Buxari 5671","en":"Bukhari 5671","ru":"Бухари 5671","tr":"Buhârî 5671","ar":"البخاري 5671"}},{"id":765,"t":{"az":"Ey Adəm oğlu, artıq olanı vermək sənin üçün xeyirlidir, saxlamaq şərlidir.","en":"O son of Adam, spending the surplus is better for you, and withholding it is worse for you.","ru":"О сын Адама, раздать излишек лучше для тебя, удержать — хуже.","tr":"Ey Ademoğlu, fazlalığı harcamak senin için hayırlıdır, tutmak şerdir.","ar":"يَا ابْنَ آدَمَ إِنَّكَ إِنْ تَبْذُلَ الْفَضْلَ خَيْرٌ لَكَ وَإِنْ تُمْسِكَهُ شَرٌّ لَكَ"},"src":{"az":"Muslim 1036","en":"Muslim 1036","ru":"Муслим 1036","tr":"Müslim 1036","ar":"مسلم 1036"}},{"id":766,"t":{"az":"İnsan oğlunun yandırdığı od cəhənnəm odunun yetmişdə biridir.","en":"Your fire that the son of Adam kindles is one-seventieth of the fire of Hell.","ru":"Ваш огонь, разжигаемый человеком — одна семидесятая огня ада.","tr":"İnsanoğlunun yaktığı ateş, cehennem ateşinin yetmişte biridir.","ar":"نَارُكُمْ هَذِهِ الَّتِي يُوقِدُ ابْنُ آدَمَ جُزْءٌ مِنْ سَبْعِينَ جُزْءًا مِنْ نَارِ جَهَنَّمَ"},"src":{"az":"Buxari 3265","en":"Bukhari 3265","ru":"Бухари 3265","tr":"Buhârî 3265","ar":"البخاري 3265"}},{"id":767,"t":{"az":"Ən fəzilətli günlərdən biri Cümədir; o gün mənə çox salavat gətirin.","en":"Among the best of your days is Friday, so increase your blessings upon me on that day.","ru":"Пятница — один из лучших ваших дней, чаще благословляйте меня в этот день.","tr":"En faziletli günlerden biri Cuma günüdür; o gün bana çokça salavat getirin.","ar":"إِنَّ مِنْ أَفْضَلِ أَيَّامِكُمْ يَوْمَ الْجُمُعَةِ فَأَكْثِرُوا عَلَيَّ مِنَ الصَّلَاةِ فِيهِ"},"src":{"az":"Əbu Davud 1047","en":"Abu Dawud 1047","ru":"Абу Дауд 1047","tr":"Ebû Dâvûd 1047","ar":"أبو داود 1047"}},{"id":769,"t":{"az":"Din asanlıqdır; kim dini çətinləşdirməyə çalışarsa, din ona qalib gələr.","en":"Religion is easy; whoever overburdens himself in religion will be overwhelmed by it.","ru":"Религия легка; кто будет чрезмерно усердствовать, религия одолеет его.","tr":"Din kolaylıktır; kim dini zorlaştırmaya çalışırsa, din ona galip gelir.","ar":"إِنَّ الدِّينَ يُسْرٌ وَلَنْ يُشَادَّ الدِّينَ أَحَدٌ إِلَّا غَلَبَهُ"},"src":{"az":"Buxari 39","en":"Bukhari 39","ru":"Бухари 39","tr":"Buhârî 39","ar":"البخاري 39"}},{"id":770,"t":{"az":"Heç biriniz mən ona atasından, övladından və bütün insanlardan sevimli olmayınca iman etməz.","en":"None of you truly believes until I am more beloved to him than his father, child, and all people.","ru":"Никто из вас не уверует по-настоящему, пока я не стану для него любимее отца, сына и всех людей.","tr":"Hiçbiriniz ben ona babasından, evladından ve bütün insanlardan daha sevimli olmadıkça iman etmiş olmaz.","ar":"لَا يُؤْمِنُ أَحَدُكُمْ حَتَّى أَكُونَ أَحَبَّ إِلَيْهِ مِنْ وَالِدِهِ وَوَلَدِهِ وَالنَّاسِ أَجْمَعِينَ"},"src":{"az":"Buxari 15","en":"Bukhari 15","ru":"Бухари 15","tr":"Buhârî 15","ar":"البخاري 15"}},{"id":773,"t":{"az":"İki parlaq surəni — Bəqərə və Ali-İmranı oxuyun; qiyamət günü iki bulud kimi gələrlər.","en":"Recite the two bright ones — al-Baqarah and Aal Imran — for they will come as two clouds on the Day of Judgment.","ru":"Читайте две сияющие суры — Аль-Бакара и Аль-Имран — ибо они придут двумя облаками в День Суда.","tr":"İki parlak sureyi — Bakara ve Al-i İmran'ı — okuyun; kıyamet günü iki bulut gibi gelirler.","ar":"اقْرَءُوا الزَّهْرَاوَيْنِ الْبَقَرَةَ وَسُورَةَ آلِ عِمْرَانَ فَإِنَّهُمَا تَأْتِيَانِ يَوْمَ الْقِيَامَةِ كَأَنَّهُمَا غَمَامَتَانِ"},"src":{"az":"Muslim 804","en":"Muslim 804","ru":"Муслим 804","tr":"Müslim 804","ar":"مسلم 804"}},{"id":774,"t":{"az":"Allah elmi insanlardan çəkib almaz, lakin alimləri alıb elmi götürər.","en":"Allah does not take knowledge by removing it from servants, but by taking the scholars.","ru":"Аллах не забирает знание, отнимая его у людей, а забирает учёных.","tr":"Allah ilmi insanlardan çekip almaz, alimleri alarak ilmi götürür.","ar":"إِنَّ اللَّهَ لَا يَقْبِضُ الْعِلْمَ انْتِزَاعًا يَنْتَزِعُهُ مِنَ الْعِبَادِ وَلَكِنْ يَقْبِضُ الْعِلْمَ بِقَبْضِ الْعُلَمَاءِ"},"src":{"az":"Buxari 100","en":"Bukhari 100","ru":"Бухари 100","tr":"Buhârî 100","ar":"البخاري 100"}},{"id":775,"t":{"az":"Aşura gününü tutun; Allahdan əvvəlki ilin günahlarını bağışlamasını ümid edirəm.","en":"Fast on Ashura, for I expect Allah to expiate the year before it.","ru":"Поститесь в день Ашура, ибо я надеюсь на Аллаха, что Он простит за год до него.","tr":"Aşure gününü tutun; Allah'tan önceki yılın günahlarını bağışlamasını umarım.","ar":"عَلَيْكُمْ بِصَوْمِ عَاشُورَاءَ فَإِنِّي أَحْتَسِبُ عَلَى اللَّهِ أَنْ يُكَفِّرَ السَّنَةَ الَّتِي قَبْلَهُ"},"src":{"az":"Muslim 1162","en":"Muslim 1162","ru":"Муслим 1162","tr":"Müslim 1162","ar":"مسلم 1162"}},{"id":776,"t":{"az":"Hər gün iki mələk enər: biri xərcləyənə əvəzini istəyər, digəri xəsisə tələf istəyər.","en":"Every day two angels descend: one asks compensation for the spender, the other asks destruction for the miser.","ru":"Каждый день нисходят два ангела: один просит возмещения для расходующего, другой — гибели для скупого.","tr":"Her gün iki melek iner: biri harcayana karşılık ister, diğeri cimriye telef ister.","ar":"مَا مِنْ يَوْمٍ إِلَّا وَمَلَكَانِ يَنْزِلَانِ فَيَقُولُ أَحَدُهُمَا اللَّهُمَّ أَعْطِ مُنْفِقًا خَلَفًا وَيَقُولُ الْآخَرُ اللَّهُمَّ أَعْطِ مُمْسِكًا تَلَفًا"},"src":{"az":"Buxari 1442","en":"Bukhari 1442","ru":"Бухари 1442","tr":"Buhârî 1442","ar":"البخاري 1442"}},{"id":777,"t":{"az":"Hər gün yüz dəfə təsbih edib min savab qazanmaq biriniz üçün çətinmidir?","en":"Is any of you incapable of earning a thousand good deeds daily? Say SubhanAllah a hundred times and a thousand good deeds are recorded.","ru":"Разве не в состоянии кто-то из вас заработать тысячу добрых дел? Скажите «Субхана-Ллах» сто раз — и запишется тысяча.","tr":"Her gün yüz tesbih edip bin sevap kazanmak biriniz için zor mudur?","ar":"أَيَعْجِزُ أَحَدُكُمْ أَنْ يَكْسِبَ كُلَّ يَوْمٍ أَلْفَ حَسَنَةٍ يُسَبِّحُ مِائَةَ تَسْبِيحَةٍ فَيُكْتَبُ لَهُ أَلْفُ حَسَنَةٍ"},"src":{"az":"Muslim 2698","en":"Muslim 2698","ru":"Муслим 2698","tr":"Müslim 2698","ar":"مسلم 2698"}},{"id":778,"t":{"az":"Mömin gözəl əxlaqı ilə gündüz oruc tutan, gecə namaz qılanın dərəcəsinə çatar.","en":"The believer can attain the rank of one who fasts and prays at night through good character.","ru":"Верующий своим хорошим нравом достигает степени постящегося и молящегося ночью.","tr":"Mümin güzel ahlakıyla gündüz oruç tutan, gece namaz kılanın derecesine ulaşır.","ar":"إِنَّ الْمُؤْمِنَ لَيُدْرِكُ بِحُسْنِ خُلُقِهِ دَرَجَةَ الصَّائِمِ الْقَائِمِ"},"src":{"az":"Əbu Davud 4798","en":"Abu Dawud 4798","ru":"Абу Дауд 4798","tr":"Ebû Dâvûd 4798","ar":"أبو داود 4798"}},{"id":780,"t":{"az":"Allah qulunun üzərində nemətinin əsərini görməyi sevir.","en":"Allah loves to see the effect of His blessing on His servant.","ru":"Аллах любит видеть следы Своей милости на Своём рабе.","tr":"Allah kulunun üzerinde nimetinin eserini görmeyi sever.","ar":"إِنَّ اللَّهَ يُحِبُّ أَنْ يَرَى أَثَرَ نِعْمَتِهِ عَلَى عَبْدِهِ"},"src":{"az":"Tirmizi 2819","en":"Tirmidhi 2819","ru":"Тирмизи 2819","tr":"Tirmizî 2819","ar":"الترمذي 2819"}},{"id":781,"t":{"az":"Cənnətə baxdım, əhlinin çoxunun kasıblar olduğunu gördüm.","en":"I looked into Paradise and saw that most of its inhabitants were the poor.","ru":"Я заглянул в рай и увидел, что большинство его обитателей — бедные.","tr":"Cennete baktım, ehlinin çoğunun fakirler olduğunu gördüm.","ar":"اطَّلَعْتُ فِي الْجَنَّةِ فَرَأَيْتُ أَكْثَرَ أَهْلِهَا الْفُقَرَاءَ"},"src":{"az":"Buxari 6546","en":"Bukhari 6546","ru":"Бухари 6546","tr":"Buhârî 6546","ar":"البخاري 6546"}},{"id":782,"t":{"az":"Allahım, Səni zikr etməkdə, şükr etməkdə və gözəl ibadət etməkdə mənə kömək et.","en":"O Allah, help me to remember You, thank You, and worship You beautifully.","ru":"О Аллах, помоги мне поминать Тебя, благодарить Тебя и наилучшим образом поклоняться Тебе.","tr":"Allah'ım, Seni zikretmekte, şükretmekte ve güzel ibadet etmekte bana yardım et.","ar":"اللَّهُمَّ أَعِنِّي عَلَى ذِكْرِكَ وَشُكْرِكَ وَحُسْنِ عِبَادَتِكَ"},"src":{"az":"Əbu Davud 1522","en":"Abu Dawud 1522","ru":"Абу Дауд 1522","tr":"Ebû Dâvûd 1522","ar":"أبو داود 1522"}},{"id":783,"t":{"az":"Yeddi böyük günahdan çəkinin: şirk, sehr, haqsız qətl, yetim malı yemək, riba, döyüşdən qaçmaq, iffətli qadına iftira.","en":"Avoid the seven deadly sins: polytheism, sorcery, unlawful killing, usury, devouring orphans' property, fleeing from battle, slandering chaste women.","ru":"Избегайте семи смертных грехов: многобожия, колдовства, убийства, ростовщичества, поедания имущества сирот, бегства с поля боя, клеветы на целомудренных.","tr":"Yedi helak edici günahtan kaçının: şirk, sihir, haksız öldürme, riba, yetim malı yeme, savaştan kaçma, iffetli kadına iftira.","ar":"اجْتَنِبُوا السَّبْعَ الْمُوبِقَاتِ"},"src":{"az":"Buxari 2766","en":"Bukhari 2766","ru":"Бухари 2766","tr":"Buhârî 2766","ar":"البخاري 2766"}},{"id":784,"t":{"az":"Allaha ən sevimli əməl Zilhiccənin on günündədir.","en":"There are no days in which deeds are more beloved to Allah than the first ten days of Dhul Hijjah.","ru":"Нет дней, в которые дела более любимы Аллахом, чем десять дней Зу-ль-Хиджа.","tr":"Allah katında amelin en sevimli olduğu günler Zilhicce'nin on günüdür.","ar":"مَا مِنْ أَيَّامٍ أَحَبُّ إِلَى اللَّهِ فِيهَا الْعَمَلُ مِنْ هَذِهِ الْأَيَّامِ يَعْنِي أَيَّامَ الْعَشْرِ"},"src":{"az":"Buxari 969","en":"Bukhari 969","ru":"Бухари 969","tr":"Buhârî 969","ar":"البخاري 969"}},{"id":785,"t":{"az":"Kim namaz üçün dəstəmazı tam alar, fərz namaza gedib camaatla qılarsa, günahları bağışlanar.","en":"Whoever performs ablution fully, walks to the obligatory prayer, and prays with the people, his sins are forgiven.","ru":"Кто полностью совершит омовение, пойдёт на обязательную молитву и совершит её с людьми, его грехи будут прощены.","tr":"Kim abdesti tam alır, farz namaza gidip cemaatle kılarsa, günahları bağışlanır.","ar":"مَنْ تَوَضَّأَ لِلصَّلَاةِ فَأَسْبَغَ الْوُضُوءَ ثُمَّ مَشَى إِلَى الصَّلَاةِ الْمَكْتُوبَةِ فَصَلَّاهَا مَعَ النَّاسِ غُفِرَ لَهُ ذُنُوبُهُ"},"src":{"az":"Muslim 232","en":"Muslim 232","ru":"Муслим 232","tr":"Müslim 232","ar":"مسلم 232"}},{"id":788,"t":{"az":"Biriniz oruclu ikən yeməyə dəvət olunsa, \"mən oruc tuturam\" desin.","en":"If one of you is invited to eat while fasting, let him say \"I am fasting.\"","ru":"Если кого-то из вас пригласят поесть, а он постится, пусть скажет: «Я пощусь».","tr":"Biriniz oruçlu iken yemeğe davet edilirse, \"ben oruçluyum\" desin.","ar":"إِذَا دُعِيَ أَحَدُكُمْ إِلَى طَعَامٍ وَهُوَ صَائِمٌ فَلْيَقُلْ إِنِّي صَائِمٌ"},"src":{"az":"Muslim 1150","en":"Muslim 1150","ru":"Муслим 1150","tr":"Müslim 1150","ar":"مسلم 1150"}},{"id":789,"t":{"az":"Ən xeyirli sədəqə zənginlik saxlayandır; əvvəlcə baxdığınız kəslərdən başlayın.","en":"The best charity is what keeps you self-sufficient; start with those you support.","ru":"Лучшая милостыня — та, что оставляет достаток; начинайте с тех, кого содержите.","tr":"En hayırlı sadaka zenginliği koruyan sadakadır; bakmakla yükümlü olduklarınızdan başlayın.","ar":"خَيْرُ الصَّدَقَةِ مَا أَبْقَتْ غِنًى وَابْدَءُوا بِمَنْ تَعُولُونَ"},"src":{"az":"Buxari 1426","en":"Bukhari 1426","ru":"Бухари 1426","tr":"Buhârî 1426","ar":"البخاري 1426"}},{"id":791,"t":{"az":"Ən xeyirli sədəqə zənginlikdən artandır; yuxarıdakı əl aşağıdakından xeyirlidir.","en":"The best charity is from surplus wealth, and the upper hand is better than the lower hand.","ru":"Лучшая милостыня — из излишка; верхняя рука лучше нижней.","tr":"En hayırlı sadaka zenginlikten artandır; üstteki el alttakinden hayırlıdır.","ar":"خَيْرُ الصَّدَقَةِ مَا كَانَ ظَهْرَ غِنًى وَالْيَدُ الْعُلْيَا خَيْرٌ مِنَ الْيَدِ السُّفْلَى"},"src":{"az":"Buxari 1427","en":"Bukhari 1427","ru":"Бухари 1427","tr":"Buhârî 1427","ar":"البخاري 1427"}},{"id":792,"t":{"az":"İnsan dininin gücünə görə imtahan edilər.","en":"A man is tested according to the strength of his religion.","ru":"Человек испытывается в соответствии с силой его религии.","tr":"Kişi dininin gücüne göre imtihan edilir.","ar":"يُبْتَلَى الرَّجُلُ عَلَى حَسَبِ دِينِهِ"},"src":{"az":"Tirmizi 2398","en":"Tirmidhi 2398","ru":"Тирмизи 2398","tr":"Tirmizî 2398","ar":"الترمذي 2398"}},{"id":793,"t":{"az":"Dünya keçici nemətdir; dünyanın ən xeyirli neməti saleh qadındır.","en":"The world is provision, and the best provision of the world is a righteous woman.","ru":"Мир — это блага, а лучшее благо мира — праведная жена.","tr":"Dünya geçici bir nimet; dünyanın en hayırlı nimeti salih bir kadındır.","ar":"الدُّنْيَا مَتَاعٌ وَخَيْرُ مَتَاعِ الدُّنْيَا الْمَرْأَةُ الصَّالِحَةُ"},"src":{"az":"Muslim 1467","en":"Muslim 1467","ru":"Муслим 1467","tr":"Müslim 1467","ar":"مسلم 1467"}},{"id":795,"t":{"az":"Nədən qadağan etdimisə, ondan çəkinin; nə əmr etdimsə, bacardığınız qədər edin.","en":"What I have forbidden, avoid it; and what I have commanded, do as much of it as you can.","ru":"Что я запретил — избегайте, а что повелел — делайте, сколько можете.","tr":"Neyi yasakladıysam ondan kaçının; neyi emrettimse gücünüz yettiği kadar yapın.","ar":"مَا نَهَيْتُكُمْ عَنْهُ فَاجْتَنِبُوهُ وَمَا أَمَرْتُكُمْ بِهِ فَأْتُوا مِنْهُ مَا اسْتَطَعْتُمْ"},"src":{"az":"Buxari 7288","en":"Bukhari 7288","ru":"Бухари 7288","tr":"Buhârî 7288","ar":"البخاري 7288"}},{"id":796,"t":{"az":"Rəhm etməyənə rəhm olunmaz.","en":"Whoever shows no mercy will not be shown mercy.","ru":"Кто не проявляет милосердия, к тому не будет проявлено милосердие.","tr":"Merhamet etmeyene merhamet olunmaz.","ar":"مَنْ لَا يَرْحَمُ لَا يُرْحَمُ"},"src":{"az":"Buxari 5997","en":"Bukhari 5997","ru":"Бухари 5997","tr":"Buhârî 5997","ar":"البخاري 5997"}},{"id":797,"t":{"az":"Dəstəmaz imanın yarısıdır, Əlhəmdulillah tərəzini doldurur.","en":"Ablution is half of faith, and Alhamdulillah fills the scales.","ru":"Омовение — половина веры, а «Аль-хамду ли-Лляхи» заполняет весы.","tr":"Abdest imanın yarısıdır, Elhamdülillah mizanı doldurur.","ar":"الْوُضُوءُ شَطْرُ الْإِيمَانِ وَالْحَمْدُ لِلَّهِ تَمْلَأُ الْمِيزَانَ"},"src":{"az":"Muslim 223","en":"Muslim 223","ru":"Муслим 223","tr":"Müslim 223","ar":"مسلم 223"}},{"id":798,"t":{"az":"Allah qullara beş vaxt namazı yazdı; kim onları qüsursuz qılsa, Allahın cənnətə girizmə vədi var.","en":"Allah has prescribed five prayers on His servants; whoever performs them well has a promise from Allah to enter Paradise.","ru":"Аллах предписал рабам пять молитв; кто выполнит их полностью, тому обещание Аллаха войти в рай.","tr":"Allah kullara beş vakit namazı yazdı; kim onları eksiksiz kılarsa, Allah'ın cennete girme vaadi vardır.","ar":"خَمْسُ صَلَوَاتٍ كَتَبَهُنَّ اللَّهُ عَلَى الْعِبَادِ"},"src":{"az":"Əbu Davud 1420","en":"Abu Dawud 1420","ru":"Абу Дауд 1420","tr":"Ebû Dâvûd 1420","ar":"أبو داود 1420"}},{"id":800,"t":{"az":"Allahın məni göndərdiyi hidayət və elmin misalı torpağa düşən bol yağış kimidir.","en":"The example of guidance and knowledge with which Allah sent me is like abundant rain falling on land.","ru":"Пример руководства и знания, с которыми послал меня Аллах — как обильный дождь, выпавший на землю.","tr":"Allah'ın beni gönderdiği hidayet ve ilmin misali, toprağa düşen bol yağmur gibidir.","ar":"مَثَلُ مَا بَعَثَنِي اللَّهُ بِهِ مِنَ الْهُدَى وَالْعِلْمِ كَمَثَلِ الْغَيْثِ الْكَثِيرِ أَصَابَ أَرْضًا"},"src":{"az":"Buxari 79","en":"Bukhari 79","ru":"Бухари 79","tr":"Buhârî 79","ar":"البخاري 79"}},{"id":802,"t":{"az":"Kim halal qazancdan bir xurma dəyərində sədəqə versə — Allaha ancaq pak olan yüksələr — Allah onu sağ əli ilə qəbul edər.","en":"Whoever gives charity equal to a date from lawful earnings — and only the good ascends to Allah — Allah accepts it with His Right Hand.","ru":"Кто подаст милостыню размером с финик из честного заработка — а к Аллаху восходит только чистое — Аллах примет её Правой Рукой.","tr":"Kim helal kazancından bir hurma değerinde sadaka verirse — Allah'a ancak temiz olan yükselir — Allah onu sağ eliyle kabul eder.","ar":"مَنْ تَصَدَّقَ بِعَدْلِ تَمْرَةٍ مِنْ كَسْبٍ طَيِّبٍ وَلَا يَصْعَدُ إِلَى اللَّهِ إِلَّا الطَّيِّبُ فَإِنَّ اللَّهَ يَتَقَبَّلُهَا بِيَمِينِهِ"},"src":{"az":"Buxari 7430","en":"Bukhari 7430","ru":"Бухари 7430","tr":"Buhârî 7430","ar":"البخاري 7430"}},{"id":805,"t":{"az":"Allahın möminin üçün etdiyi hər qəza onun üçün xeyirdir.","en":"Allah does not decree anything for the believer except that it is good for him.","ru":"Аллах не предопределяет для верующего ничего, кроме блага для него.","tr":"Allah müminin için bir şey takdir etmişse, o mutlaka onun için hayırdır.","ar":"لَا يَقْضِي اللَّهُ لِلْمُؤْمِنِ قَضَاءً إِلَّا كَانَ خَيْرًا لَهُ"},"src":{"az":"Muslim 2999","en":"Muslim 2999","ru":"Муслим 2999","tr":"Müslim 2999","ar":"مسلم 2999"}},{"id":807,"t":{"az":"Kim ruzisinin genişlənməsini və ömrünün uzanmasını istəyirsə, qohumluğunu qorusun.","en":"Whoever wishes for his provision to be expanded and his life extended, let him maintain family ties.","ru":"Кто хочет расширения удела и продления жизни, пусть поддерживает родственные связи.","tr":"Kim rızkının genişlemesini ve ömrünün uzamasını isterse, akrabalık bağlarını korusun.","ar":"مَنْ سَرَّهُ أَنْ يُبْسَطَ لَهُ فِي رِزْقِهِ وَيُنْسَأَ لَهُ فِي أَثَرِهِ فَلْيَصِلْ رَحِمَهُ"},"src":{"az":"Buxari 5986","en":"Bukhari 5986","ru":"Бухари 5986","tr":"Buhârî 5986","ar":"البخاري 5986"}},{"id":809,"t":{"az":"Kimin artıq miniyinivarsa, miniyini olmayan üzərində qaytarsın.","en":"Whoever has an extra mount should lend it to one who has none.","ru":"У кого есть лишнее верховое животное, пусть поделится с тем, у кого его нет.","tr":"Kimin fazla bineği varsa, bineği olmayanlara versin.","ar":"مَنْ كَانَ لَهُ فَضْلُ ظَهْرٍ فَلْيَعُدْ بِهِ عَلَى مَنْ لَا ظَهْرَ لَهُ"},"src":{"az":"Muslim 1728","en":"Muslim 1728","ru":"Муслим 1728","tr":"Müslim 1728","ar":"مسلم 1728"}},{"id":811,"t":{"az":"Cəbrail mənə qonşu haqqında o qədər tövsiyə etdi ki, onu varis edəcəyini zənn etdim.","en":"Gabriel kept advising me about the neighbor until I thought he would make him an heir.","ru":"Джибриль так настоятельно наставлял меня о соседе, что я подумал — он сделает его наследником.","tr":"Cebrail bana komşu hakkında o kadar tavsiyede bulundu ki, onu mirasçı yapacağını zannettim.","ar":"مَا زَالَ جِبْرِيلُ يُوصِينِي بِالْجَارِ حَتَّى ظَنَنْتُ أَنَّهُ سَيُوَرِّثُهُ"},"src":{"az":"Buxari 6014","en":"Bukhari 6014","ru":"Бухари 6014","tr":"Buhârî 6014","ar":"البخاري 6014"}},{"id":812,"t":{"az":"Allaha ən sevimli namaz Davudun namazıdır: gecənin yarısını yatar, üçdə birini ibadət edər, altıda birini yatardı.","en":"The most beloved prayer to Allah is that of David: he slept half the night, prayed a third, and slept a sixth.","ru":"Самая любимая молитва Аллахом — молитва Давуда: спал половину ночи, молился треть, спал шестую часть.","tr":"Allah'a en sevimli namaz Davud'un namazıdır: gecenin yarısını uyur, üçte birini ibadet eder, altıda birini uyurdu.","ar":"أَحَبُّ الصَّلَاةِ إِلَى اللَّهِ صَلَاةُ دَاوُدَ كَانَ يَنَامُ نِصْفَ اللَّيْلِ وَيَقُومُ ثُلُثَهُ وَيَنَامُ سُدُسَهُ"},"src":{"az":"Buxari 1131","en":"Bukhari 1131","ru":"Бухари 1131","tr":"Buhârî 1131","ar":"البخاري 1131"}},{"id":813,"t":{"az":"Beş vaxt namaz, cümədən cüməyə, Ramazandan Ramazana — böyük günahlardan çəkinilsə, aralarındakılara kəffarədir.","en":"The five prayers, Friday to Friday, Ramadan to Ramadan are expiations for what is between them if major sins are avoided.","ru":"Пять молитв, от пятницы до пятницы, от Рамадана до Рамадана — искупление того, что между ними, если избегать больших грехов.","tr":"Beş vakit namaz, cumadan cumaya, Ramazan'dan Ramazan'a — büyük günahlardan kaçınılırsa aralarındakilere kefarettir.","ar":"الصَّلَوَاتُ الْخَمْسُ وَالْجُمُعَةُ إِلَى الْجُمُعَةِ وَرَمَضَانُ إِلَى رَمَضَانَ مُكَفِّرَاتٌ مَا بَيْنَهُنَّ إِذَا اجْتُنِبَتِ الْكَبَائِرُ"},"src":{"az":"Muslim 233","en":"Muslim 233","ru":"Муслим 233","tr":"Müslim 233","ar":"مسلم 233"}},{"id":814,"t":{"az":"Kim Kəhf surəsinin əvvəlindən on ayə əzbərləsə, Dəccaldan qorunar.","en":"Whoever memorizes ten verses from the beginning of Surah al-Kahf will be protected from the Dajjal.","ru":"Кто выучит наизусть десять аятов из начала суры Аль-Кахф, будет защищён от Даджаля.","tr":"Kim Kehf suresinin başından on ayet ezberlerse, Deccal'dan korunur.","ar":"مَنْ حَفِظَ عَشْرَ آيَاتٍ مِنْ أَوَّلِ سُورَةِ الْكَهْفِ عُصِمَ مِنَ الدَّجَّالِ"},"src":{"az":"Muslim 809","en":"Muslim 809","ru":"Муслим 809","tr":"Müslim 809","ar":"مسلم 809"}},{"id":817,"t":{"az":"Miskin ev-ev dolaşıb bir-iki tikə ilə geri dönən deyil; miskin ehtiyacı olub dilənməyəndir.","en":"The poor person is not the one who goes around begging; the poor is the one who has need but does not beg.","ru":"Бедный — не тот, кто обходит людей, получая крошки; бедный — нуждающийся, но не просящий.","tr":"Miskin kapı kapı dolanıp bir iki lokmayla dönen değil; ihtiyacı olup da dilenmeyendir.","ar":"لَيْسَ الْمِسْكِينُ بِهَذَا الطَّوَّافِ الَّذِي يَطُوفُ عَلَى النَّاسِ تَرُدُّهُ اللُّقْمَةُ وَاللُّقْمَتَانِ"},"src":{"az":"Buxari 1479","en":"Bukhari 1479","ru":"Бухари 1479","tr":"Buhârî 1479","ar":"البخاري 1479"}},{"id":819,"t":{"az":"Günəş doğan hər gün hər nəfs üzərində sədəqə yazılıb.","en":"Every soul has charity due on it every day the sun rises.","ru":"На каждую душу каждый день, когда восходит солнце, записана милостыня.","tr":"Güneşin doğduğu her gün her nefse sadaka yazılmıştır.","ar":"كُلُّ نَفْسٍ كُتِبَ عَلَيْهَا الصَّدَقَةُ كُلَّ يَوْمٍ طَلَعَتْ فِيهِ الشَّمْسُ"},"src":{"az":"Buxari 2989","en":"Bukhari 2989","ru":"Бухари 2989","tr":"Buhârî 2989","ar":"البخاري 2989"}},{"id":820,"t":{"az":"Göz yaşarır, qəlb kədərlənir, lakin biz Rəbbimizi razı edən sözlərdən başqa bir şey demirik.","en":"The eye tears, the heart grieves, but we say nothing except what pleases our Lord.","ru":"Глаз плачет, сердце скорбит, но мы говорим лишь то, что угодно нашему Господу.","tr":"Göz yaşarır, kalp hüzünlenir, ama Rabbimizi razı eden sözden başka bir şey söylemeyiz.","ar":"إِنَّ الْعَيْنَ تَدْمَعُ وَالْقَلْبَ يَحْزَنُ وَلَا نَقُولُ إِلَّا مَا يُرْضِي رَبَّنَا"},"src":{"az":"Buxari 1303","en":"Bukhari 1303","ru":"Бухари 1303","tr":"Buhârî 1303","ar":"البخاري 1303"}},{"id":821,"t":{"az":"Allah quluna xeyir istəsə, cəzasını dünyada tezləşdirər.","en":"When Allah wants good for His servant, He hastens his punishment in this world.","ru":"Когда Аллах хочет блага рабу, Он ускоряет его наказание в этом мире.","tr":"Allah kuluna hayır dilediğinde cezasını dünyada hızlandırır.","ar":"إِذَا أَرَادَ اللَّهُ بِعَبْدِهِ الْخَيْرَ عَجَّلَ لَهُ الْعُقُوبَةَ فِي الدُّنْيَا"},"src":{"az":"Tirmizi 2396","en":"Tirmidhi 2396","ru":"Тирмизи 2396","tr":"Tirmizî 2396","ar":"الترمذي 2396"}},{"id":822,"t":{"az":"Mənim bildiyimi bilsəydiniz, az gülər, çox ağlayardınız.","en":"If you knew what I know, you would laugh little and weep much.","ru":"Если бы вы знали то, что знаю я, вы бы мало смеялись и много плакали.","tr":"Benim bildiğimi bilseydiniz, az güler, çok ağlardınız.","ar":"لَوْ تَعْلَمُونَ مَا أَعْلَمُ لَضَحِكْتُمْ قَلِيلًا وَلَبَكَيْتُمْ كَثِيرًا"},"src":{"az":"Buxari 6486","en":"Bukhari 6486","ru":"Бухари 6486","tr":"Buhârî 6486","ar":"البخاري 6486"}},{"id":824,"t":{"az":"Allahım, yeri bizə yığ, səfəri bizə asanlaşdır.","en":"O Allah, fold the earth for us and make travel easy for us.","ru":"О Аллах, сверни для нас землю и облегчи нам путь.","tr":"Allah'ım, yeri bize dür ve yolculuğu bize kolaylaştır.","ar":"اللَّهُمَّ اطْوِ لَنَا الْأَرْضَ وَهَوِّنْ عَلَيْنَا السَّفَرَ"},"src":{"az":"Əbu Davud 2598","en":"Abu Dawud 2598","ru":"Абу Дауд 2598","tr":"Ebû Dâvûd 2598","ar":"أبو داود 2598"}},{"id":825,"t":{"az":"Mənə itaət edən Allaha itaət etmişdir, mənə asi olan Allaha asi olmuşdur.","en":"Whoever obeys me has obeyed Allah, and whoever disobeys me has disobeyed Allah.","ru":"Кто подчинился мне — подчинился Аллаху, кто ослушался меня — ослушался Аллаха.","tr":"Bana itaat eden Allah'a itaat etmiştir, bana asi olan Allah'a asi olmuştur.","ar":"مَنْ أَطَاعَنِي فَقَدْ أَطَاعَ اللَّهَ وَمَنْ عَصَانِي فَقَدْ عَصَى اللَّهَ"},"src":{"az":"Buxari 7137","en":"Bukhari 7137","ru":"Бухари 7137","tr":"Buhârî 7137","ar":"البخاري 7137"}},{"id":826,"t":{"az":"Verilmədən doymuş kimi görünən iki yalan libas geyən kimidir.","en":"The one who pretends to have what he has not been given is like one wearing garments of falsehood.","ru":"Тот, кто делает вид, что обладает тем, чего не получил — словно носящий два одеяния лжи.","tr":"Verilmediği halde verilmiş gibi görünen, iki yalan elbise giymiş gibidir.","ar":"الْمُتَشَبِّعُ بِمَا لَمْ يُعْطَ كَلَابِسِ ثَوْبَيْ زُورٍ"},"src":{"az":"Buxari 5219","en":"Bukhari 5219","ru":"Бухари 5219","tr":"Buhârî 5219","ar":"البخاري 5219"}},{"id":827,"t":{"az":"Biriniz səcdəyə gedəndə dəvə kimi çökməsin, əllərini dizlərindən əvvəl qoysun.","en":"When one of you prostrates, he should not kneel like a camel; let him place his hands before his knees.","ru":"Когда совершаете земной поклон, не опускайтесь как верблюд; ставьте руки прежде коленей.","tr":"Biriniz secdeye gittiğinde deve gibi çökmesin, ellerini dizlerinden önce koysun.","ar":"إِذَا سَجَدَ أَحَدُكُمْ فَلَا يَبْرُكْ كَمَا يَبْرُكُ الْبَعِيرُ وَلْيَضَعْ يَدَيْهِ قَبْلَ رُكْبَتَيْهِ"},"src":{"az":"Əbu Davud 840","en":"Abu Dawud 840","ru":"Абу Дауд 840","tr":"Ebû Dâvûd 840","ar":"أبو داود 840"}},{"id":828,"t":{"az":"Fatihə oxumayan kəsin namazı yoxdur.","en":"There is no prayer for the one who does not recite al-Fatihah.","ru":"Нет молитвы у того, кто не прочитал Аль-Фатиху.","tr":"Fatiha okumayan kişinin namazı yoktur.","ar":"لَا صَلَاةَ لِمَنْ لَمْ يَقْرَأْ بِفَاتِحَةِ الْكِتَابِ"},"src":{"az":"Buxari 756","en":"Bukhari 756","ru":"Бухари 756","tr":"Buhârî 756","ar":"البخاري 756"}},{"id":831,"t":{"az":"Ümrədən ümrəyə aralarındakılara kəffarədir; məbrur həccin mükafatı ancaq cənnətdir.","en":"Umrah to Umrah is expiation for what is between them, and the accepted Hajj has no reward but Paradise.","ru":"Умра до умры — искупление того, что между ними, а безупречный хадж вознаграждается только раем.","tr":"Umreden umreye aralarındakilere kefarettir; makbul haccın karşılığı ancak cennettir.","ar":"الْعُمْرَةُ إِلَى الْعُمْرَةِ كَفَّارَةٌ لِمَا بَيْنَهُمَا وَالْحَجُّ الْمَبْرُورُ لَيْسَ لَهُ جَزَاءٌ إِلَّا الْجَنَّةُ"},"src":{"az":"Buxari 1773","en":"Bukhari 1773","ru":"Бухари 1773","tr":"Buhârî 1773","ar":"البخاري 1773"}},{"id":833,"t":{"az":"Allah buyurur: Qulum Məni zikr edib dodaqları tərpənəndə Mən onunlayam.","en":"Allah says: I am with My servant when he remembers Me and his lips move with My mention.","ru":"Аллах говорит: Я с Моим рабом, когда он поминает Меня и его губы движутся.","tr":"Allah buyurur: Kulum Beni zikredip dudakları kıpırdadığında Ben onunlayım.","ar":"إِنَّ اللَّهَ يَقُولُ أَنَا مَعَ عَبْدِي حِينَ يَذْكُرُنِي وَتَتَحَرَّكُ بِي شَفَتَاهُ"},"src":{"az":"İbn Macə 3792","en":"Ibn Majah 3792","ru":"Ибн Маджа 3792","tr":"İbn Mâce 3792","ar":"ابن ماجه 3792"}},{"id":835,"t":{"az":"Möminin üzərindən bəla çəkilməz ki, yer üzündə günahsız gəzsin.","en":"Trials continue to befall the believer until he walks on the earth with no sin upon him.","ru":"Испытания не прекращаются для верующего, пока он не будет ходить по земле без греха.","tr":"Müminin üzerinden bela kalkmaz, tâ ki yeryüzünde günahsız yürüyünceye kadar.","ar":"لَا يَزَالُ الْبَلَاءُ بِالْمُؤْمِنِ حَتَّى يَمْشِيَ عَلَى الْأَرْضِ وَلَيْسَ عَلَيْهِ خَطِيئَةٌ"},"src":{"az":"Tirmizi 2398","en":"Tirmidhi 2398","ru":"Тирмизи 2398","tr":"Tirmizî 2398","ar":"الترمذي 2398"}},{"id":837,"t":{"az":"Allah yolunda səhər və ya axşam çıxmaq dünyadan və içindəki hər şeydən xeyirlidir.","en":"A morning or evening expedition in the path of Allah is better than the world and all that is in it.","ru":"Утренний или вечерний поход на пути Аллаха лучше мира и всего, что в нём.","tr":"Allah yolunda sabah veya akşam bir çıkış, dünyadan ve içindeki her şeyden hayırlıdır.","ar":"غَدْوَةٌ فِي سَبِيلِ اللَّهِ أَوْ رَوْحَةٌ خَيْرٌ مِنَ الدُّنْيَا وَمَا فِيهَا"},"src":{"az":"Buxari 2792","en":"Bukhari 2792","ru":"Бухари 2792","tr":"Buhârî 2792","ar":"البخاري 2792"}},{"id":838,"t":{"az":"Kim mənə bir dəfə salavat gətirsə, Allah ona on savab yazar.","en":"Whoever sends blessings upon me once, Allah writes for him ten good deeds.","ru":"Кто благословит меня один раз, тому Аллах запишет десять добрых дел.","tr":"Kim bana bir kere salavat getirirse, Allah ona on hasene yazar.","ar":"مَنْ صَلَّى عَلَيَّ مَرَّةً كَتَبَ اللَّهُ لَهُ عَشْرَ حَسَنَاتٍ"},"src":{"az":"Muslim 408","en":"Muslim 408","ru":"Муслим 408","tr":"Müslim 408","ar":"مسلم 408"}},{"id":839,"t":{"az":"Yetimə baxan ilə mən cənnətdə belə olacağıq — (iki barmağını göstərdi).","en":"I and the guardian of the orphan will be in Paradise like this — (he joined his two fingers).","ru":"Я и опекун сироты будем в раю вот так — (он показал два пальца).","tr":"Ben ve yetime bakan kişi cennette böyle olacağız — (iki parmağını gösterdi).","ar":"أَنَا وَكَافِلُ الْيَتِيمِ فِي الْجَنَّةِ هَكَذَا"},"src":{"az":"Buxari 5304","en":"Bukhari 5304","ru":"Бухари 5304","tr":"Buhârî 5304","ar":"البخاري 5304"}},{"id":840,"t":{"az":"Bütün ümmətim cənnətə girər, imtina edən istisnadır. Dedilər: Kim imtina edər? Dedi: Mənə itaət edən girər, asi olan imtina etmişdir.","en":"All my ummah will enter Paradise except those who refuse. They said: Who would refuse? He said: Whoever obeys me enters Paradise; whoever disobeys me has refused.","ru":"Вся моя община войдёт в рай, кроме отказавшихся. Спросили: кто откажется? Ответил: кто подчиняется мне — войдёт, кто ослушается — тот отказался.","tr":"Bütün ümmetim cennete girer, reddeden müstesna. Dediler: Kim reddeder? Dedi: Bana itaat eden girer, asi olan reddetmiştir.","ar":"كُلُّ أُمَّتِي يَدْخُلُونَ الْجَنَّةَ إِلَّا مَنْ أَبَى"},"src":{"az":"Buxari 7280","en":"Bukhari 7280","ru":"Бухари 7280","tr":"Buhârî 7280","ar":"البخاري 7280"}},{"id":841,"t":{"az":"Müsəlmana qardaşı ilə üç gündən çox küsülü olmaq halal deyil.","en":"It is not permissible for a Muslim to forsake his brother for more than three days.","ru":"Мусульманину не дозволено покидать своего брата более трёх дней.","tr":"Bir Müslümanın kardeşiyle üç günden fazla küs durması helal değildir.","ar":"لَا يَحِلُّ لِمُسْلِمٍ أَنْ يَهْجُرَ أَخَاهُ فَوْقَ ثَلَاثٍ"},"src":{"az":"Buxari 6077","en":"Bukhari 6077","ru":"Бухари 6077","tr":"Buhârî 6077","ar":"البخاري 6077"}},{"id":842,"t":{"az":"Misvak ağzı təmizləyir, Rəbbi razı salır.","en":"The siwak purifies the mouth and pleases the Lord.","ru":"Сивак очищает рот и радует Господа.","tr":"Misvak ağzı temizler, Rabbi razı eder.","ar":"السِّوَاكُ مَطْهَرَةٌ لِلْفَمِ مَرْضَاةٌ لِلرَّبِّ"},"src":{"az":"Nəsai 5","en":"An-Nasa'i 5","ru":"ан-Насаи 5","tr":"Nesâî 5","ar":"النسائي 5"}},{"id":843,"t":{"az":"Kim on iki il azan oxuyarsa, ona cənnət vacib olar.","en":"Whoever calls the adhan for twelve years, Paradise becomes obligatory for him.","ru":"Кто призывает на молитву двенадцать лет, тому обязательно будет рай.","tr":"Kim on iki yıl ezan okursa, ona cennet vacip olur.","ar":"مَنْ أَذَّنَ اثْنَتَيْ عَشْرَةَ سَنَةً وَجَبَتْ لَهُ الْجَنَّةُ"},"src":{"az":"İbn Macə 728","en":"Ibn Majah 728","ru":"Ибн Маджа 728","tr":"İbn Mâce 728","ar":"ابن ماجه 728"}},{"id":845,"t":{"az":"Kim İslamda gözəl bir sünnət qoyarsa, ona öz savabı və onunla əməl edənlərin savabı vardır.","en":"Whoever introduces a good practice in Islam will have its reward and the reward of those who act upon it.","ru":"Кто установит хороший обычай в Исламе, тому будет его награда и награда действовавших по нему.","tr":"Kim İslam'da güzel bir sünnet koyarsa, hem kendi sevabı hem de onunla amel edenlerin sevabı ona yazılır.","ar":"مَنْ سَنَّ فِي الْإِسْلَامِ سُنَّةً حَسَنَةً فَلَهُ أَجْرُهَا وَأَجْرُ مَنْ عَمِلَ بِهَا"},"src":{"az":"Muslim 1017","en":"Muslim 1017","ru":"Муслим 1017","tr":"Müslim 1017","ar":"مسلم 1017"}},{"id":846,"t":{"az":"Oruclu ikən unutqanlıqla yeyən orucunu tamamlasın; onu Allah yedirmişdir.","en":"Whoever eats forgetfully while fasting, let him complete his fast, for Allah has fed him.","ru":"Кто по забывчивости поест, постясь, пусть завершит пост — его накормил Аллах.","tr":"Oruçlu iken unutarak yiyen orucunu tamamlasın; onu Allah yedirmiştir.","ar":"مَنْ أَكَلَ نَاسِيًا وَهُوَ صَائِمٌ فَلْيُتِمَّ صَوْمَهُ فَإِنَّمَا أَطْعَمَهُ اللَّهُ وَسَقَاهُ"},"src":{"az":"Buxari 1933","en":"Bukhari 1933","ru":"Бухари 1933","tr":"Buhârî 1933","ar":"البخاري 1933"}},{"id":847,"t":{"az":"Əmr olunduğunu tam, xoşluqla verən əmin xəzinədar da sədəqə verənlərdən biridir.","en":"The trustworthy Muslim treasurer who gives what he is ordered fully and willingly is one of the two givers of charity.","ru":"Надёжный мусульманский казначей, отдающий полностью и с охотой — один из двух благотворителей.","tr":"Emredileni tam ve gönül hoşluğuyla veren güvenilir hazinedar, sadaka verenlerden biridir.","ar":"الْخَازِنُ الْمُسْلِمُ الْأَمِينُ الَّذِي يُعْطِي مَا أُمِرَ بِهِ كَامِلًا مُوَفَّرًا طَيِّبَةً بِهِ نَفْسُهُ أَحَدُ الْمُتَصَدِّقَيْنِ"},"src":{"az":"Buxari 1438","en":"Bukhari 1438","ru":"Бухари 1438","tr":"Buhârî 1438","ar":"البخاري 1438"}},{"id":851,"t":{"az":"Sizin aşağınızdakına baxın, yuxarıdakına baxmayın; bu Allahın nemətini kiçiltməməniz üçün daha münasibdir.","en":"Look at those below you and do not look at those above you; that is more likely to prevent you from belittling Allah's blessings.","ru":"Смотрите на тех, кто ниже вас, и не смотрите на тех, кто выше — так вы не будете пренебрегать милостями Аллаха.","tr":"Aşağınızdakine bakın, yukarıdakine bakmayın; bu Allah'ın nimetini küçümsememeniz için daha uygundur.","ar":"انْظُرُوا إِلَى مَنْ أَسْفَلَ مِنْكُمْ وَلَا تَنْظُرُوا إِلَى مَنْ هُوَ فَوْقَكُمْ فَهُوَ أَجْدَرُ أَنْ لَا تَزْدَرُوا نِعْمَةَ اللَّهِ"},"src":{"az":"Muslim 2963","en":"Muslim 2963","ru":"Муслим 2963","tr":"Müslim 2963","ar":"مسلم 2963"}},{"id":852,"t":{"az":"Kim qəzaya çıxmadan və niyyət etmədən ölsə, nifaqın bir qolunda ölmüşdür.","en":"Whoever dies without having fought or having intended to, dies on a branch of hypocrisy.","ru":"Кто умрёт, не сражаясь и не намереваясь — умрёт на одной из ветвей лицемерия.","tr":"Kim savaşmadan ve niyetlenmeden ölürse, nifakın bir şubesi üzere ölmüştür.","ar":"مَنْ مَاتَ وَلَمْ يَغْزُ وَلَمْ يُحَدِّثْ نَفْسَهُ بِهِ مَاتَ عَلَى شُعْبَةٍ مِنَ النِّفَاقِ"},"src":{"az":"Muslim 1910","en":"Muslim 1910","ru":"Муслим 1910","tr":"Müslim 1910","ar":"مسلم 1910"}},{"id":853,"t":{"az":"Qəbrimi bayram yeri etməyin, mənə salavat gətirin; harada olsanız salavatınız mənə çatar.","en":"Do not make my grave a festival; send blessings upon me, for your blessings reach me wherever you are.","ru":"Не превращайте мою могилу в праздник; благословляйте меня, ибо ваши благословения достигают меня, где бы вы ни были.","tr":"Kabrimi bayram yeri yapmayın; bana salavat getirin, nerede olursanız olun salavatınız bana ulaşır.","ar":"لَا تَجْعَلُوا قَبْرِي عِيدًا وَصَلُّوا عَلَيَّ فَإِنَّ صَلَاتَكُمْ تَبْلُغُنِي حَيْثُمَا كُنْتُمْ"},"src":{"az":"Əbu Davud 2042","en":"Abu Dawud 2042","ru":"Абу Дауд 2042","tr":"Ebû Dâvûd 2042","ar":"أبو داود 2042"}},{"id":854,"t":{"az":"Mühacir Allahın qadağan etdiklərini tərk edəndir.","en":"The emigrant is the one who abandons what Allah has forbidden.","ru":"Мухаджир — тот, кто оставил запрещённое Аллахом.","tr":"Muhacir, Allah'ın yasakladıklarını terk edendir.","ar":"الْمُهَاجِرُ مَنْ هَجَرَ مَا نَهَى اللَّهُ عَنْهُ"},"src":{"az":"Buxari 10","en":"Bukhari 10","ru":"Бухари 10","tr":"Buhârî 10","ar":"البخاري 10"}},{"id":855,"t":{"az":"Oruc, namaz və sədəqənin dərəcəsindən üstün olanı sizə xəbər verimmi? İnsanlar arasını düzəltməkdir.","en":"Shall I tell you of something better than the rank of fasting, prayer, and charity? Reconciling between people.","ru":"Не сообщить ли вам о том, что лучше степени поста, молитвы и милостыни? Примирение между людьми.","tr":"Size oruç, namaz ve sadakanın derecesinden üstün olanı haber vereyim mi? İnsanlar arasını düzeltmek.","ar":"أَلَا أُخْبِرُكُمْ بِأَفْضَلِ مِنْ دَرَجَةِ الصِّيَامِ وَالصَّلَاةِ وَالصَّدَقَةِ إِصْلَاحُ ذَاتِ الْبَيْنِ"},"src":{"az":"Əbu Davud 4919","en":"Abu Dawud 4919","ru":"Абу Дауд 4919","tr":"Ebû Dâvûd 4919","ar":"أبو داود 4919"}},{"id":856,"t":{"az":"Məsləhət alınan əmanət sahibidir.","en":"The one consulted is entrusted.","ru":"Тот, у кого спрашивают совета — доверенное лицо.","tr":"Kendisine danışılan kişi emanetçidir.","ar":"الْمُسْتَشَارُ مُؤْتَمَنٌ"},"src":{"az":"Tirmizi 2822","en":"Tirmidhi 2822","ru":"Тирмизи 2822","tr":"Tirmizî 2822","ar":"الترمذي 2822"}},{"id":857,"t":{"az":"Allah dəstəmaz pozan birinizin dəstəmaz almayınca namazını qəbul etməz.","en":"Allah does not accept the prayer of one who has broken his ablution until he performs ablution again.","ru":"Аллах не примет молитву того, кто нарушил омовение, пока не совершит его вновь.","tr":"Allah abdesti bozulan birinizin abdest almadan namazını kabul etmez.","ar":"لَا يَقْبَلُ اللَّهُ صَلَاةَ أَحَدِكُمْ إِذَا أَحْدَثَ حَتَّى يَتَوَضَّأَ"},"src":{"az":"Buxari 6954","en":"Bukhari 6954","ru":"Бухари 6954","tr":"Buhârî 6954","ar":"البخاري 6954"}},{"id":858,"t":{"az":"Namaza qalxanda təkbir gətir.","en":"When you stand for prayer, say the takbir.","ru":"Когда встаёшь на молитву, произнеси такбир.","tr":"Namaza kalktığında tekbir getir.","ar":"إِذَا قُمْتَ إِلَى الصَّلَاةِ فَكَبِّرْ"},"src":{"az":"Buxari 757","en":"Bukhari 757","ru":"Бухари 757","tr":"Buhârî 757","ar":"البخاري 757"}},{"id":859,"t":{"az":"Sənə nə Tövratda, nə İncildə, nə Zəburda bənzəri enməmiş surəni göstərimmi? Fatihədir.","en":"Shall I guide you to a surah the likes of which has not been revealed in the Torah, Gospel, or Psalms? Al-Fatihah.","ru":"Не указать ли тебе суру, подобной которой не было ниспослано ни в Торе, ни в Евангелии, ни в Псалтыре? Аль-Фатиха.","tr":"Sana ne Tevrat'ta, ne İncil'de, ne Zebur'da benzeri indirilmemiş bir sureyi göstereyim mi? Fatiha'dır.","ar":"أَلَا أَدُلُّكَ عَلَى سُورَةٍ لَمْ يَنْزِلْ فِي التَّوْرَاةِ وَلَا فِي الْإِنْجِيلِ وَلَا فِي الزَّبُورِ مِثْلُهَا الْفَاتِحَةُ"},"src":{"az":"Tirmizi 2875","en":"Tirmidhi 2875","ru":"Тирмизи 2875","tr":"Tirmizî 2875","ar":"الترمذي 2875"}},{"id":861,"t":{"az":"Aşura orucunun əvvəlki ilin günahlarını silməsini Allahdan ümid edirəm.","en":"I expect the fast of Ashura to expiate the sins of the previous year.","ru":"Надеюсь, что пост Ашура искупит грехи предыдущего года.","tr":"Aşure orucunun önceki yılın günahlarını silmesini Allah'tan umarım.","ar":"صَوْمُ يَوْمِ عَاشُورَاءَ أَحْتَسِبُ عَلَى اللَّهِ أَنْ يُكَفِّرَ السَّنَةَ الَّتِي قَبْلَهُ"},"src":{"az":"Muslim 1162","en":"Muslim 1162","ru":"Муслим 1162","tr":"Müslim 1162","ar":"مسلم 1162"}},{"id":862,"t":{"az":"Zəkatını ödəməyən xəzinə sahibinin xəzinəsi cəhənnəm odunda qızdırılar.","en":"No owner of treasure who does not pay its zakat except that it will be heated in the fire of Hell.","ru":"У каждого обладателя сокровища, не выплатившего закят, оно будет раскалено в огне ада.","tr":"Zekatını ödemeyen hazine sahibinin hazinesi cehennem ateşinde kızdırılır.","ar":"مَا مِنْ صَاحِبِ كَنْزٍ لَا يُؤَدِّي زَكَاتَهُ إِلَّا أُحْمِيَ عَلَيْهِ فِي نَارِ جَهَنَّمَ"},"src":{"az":"Buxari 1403","en":"Bukhari 1403","ru":"Бухари 1403","tr":"Buhârî 1403","ar":"البخاري 1403"}},{"id":863,"t":{"az":"Sənə kəlmələr öyrədimmi ki, kim desə bağışlanar: \"Əstağfirullahəlləzi la ilahə illə huvəl-Hayyul-Qayyum.\"","en":"Shall I teach you words — whoever says them is forgiven: \"I seek forgiveness from Allah, there is no god but He, the Living, the Sustainer.\"","ru":"Не научить ли тебя словам — кто скажет их, будет прощён: «Прошу прощения у Аллаха, нет бога кроме Него, Живого, Вседержителя».","tr":"Sana kelimeler öğreteyim mi, kim söylerse bağışlanır: \"Estağfirullahellezi la ilahe illa hüvel-Hayyul-Kayyum.\"","ar":"أَلَا أُعَلِّمُكَ كَلِمَاتٍ مَنْ قَالَهُنَّ غُفِرَ لَهُ وَإِنْ كَانَ فَارًّا مِنَ الزَّحْفِ"},"src":{"az":"Əbu Davud 1517","en":"Abu Dawud 1517","ru":"Абу Дауд 1517","tr":"Ebû Dâvûd 1517","ar":"أبو داود 1517"}},{"id":865,"t":{"az":"Qul malında, canında müsibətə düçar olmağa davam edər ki, Allahla günahsız qovuşsun.","en":"The servant continues to be afflicted in his wealth or self until he meets Allah with no sin upon him.","ru":"Раб продолжает подвергаться испытаниям в имуществе или здоровье, пока не встретит Аллаха без грехов.","tr":"Kul malında veya canında musibete uğramaya devam eder ki, Allah'a günahsız kavuşsun.","ar":"مَا يَزَالُ الْعَبْدُ يُصَابُ بِالْمُصِيبَةِ فِي مَالِهِ أَوْ نَفْسِهِ حَتَّى يَلْقَى اللَّهَ وَمَا عَلَيْهِ خَطِيئَةٌ"},"src":{"az":"Tirmizi 2399","en":"Tirmidhi 2399","ru":"Тирмизи 2399","tr":"Tirmizî 2399","ar":"الترمذي 2399"}},{"id":867,"t":{"az":"Allahın kölgəsindən başqa kölgə olmayan gündə yeddi nəfəri Öz kölgəsində kölgələndirər.","en":"Seven will be shaded by Allah on the day when there is no shade but His shade.","ru":"Семерых Аллах укроет в Своей тени в день, когда не будет тени, кроме Его тени.","tr":"Allah'ın gölgesinden başka gölge olmayan günde yedi kişiyi Kendi gölgesinde gölgelendirir.","ar":"سَبْعَةٌ يُظِلُّهُمُ اللَّهُ تَحْتَ ظِلِّهِ يَوْمَ لَا ظِلَّ إِلَّا ظِلُّهُ"},"src":{"az":"Buxari 660","en":"Bukhari 660","ru":"Бухари 660","tr":"Buhârî 660","ar":"البخاري 660"}},{"id":868,"t":{"az":"Kim həcc edib çirkin söz deməyib günah etməzsə, anasından doğulduğu gün kimi qayıdar.","en":"Whoever performs Hajj without obscenity or sin returns like the day his mother bore him.","ru":"Кто совершил хадж, не допуская непристойности и греха, вернётся как в день рождения.","tr":"Kim hac edip çirkin söz söylemez ve günah işlemezse, anasından doğduğu gün gibi döner.","ar":"مَنْ حَجَّ فَلَمْ يَرْفُثْ وَلَمْ يَفْسُقْ رَجَعَ كَيَوْمِ وَلَدَتْهُ أُمُّهُ"},"src":{"az":"Buxari 1521","en":"Bukhari 1521","ru":"Бухари 1521","tr":"Buhârî 1521","ar":"البخاري 1521"}},{"id":870,"t":{"az":"Kim Cüməyə gəlirsə, qüsl etsin.","en":"Whoever comes to the Friday prayer, let him take a bath.","ru":"Кто идёт на пятничную молитву, пусть совершит полное омовение.","tr":"Kim Cuma namazına gelirse gusül alsın.","ar":"مَنْ أَتَى الْجُمُعَةَ فَلْيَغْتَسِلْ"},"src":{"az":"Buxari 877","en":"Bukhari 877","ru":"Бухари 877","tr":"Buhârî 877","ar":"البخاري 877"}},{"id":871,"t":{"az":"Kişi sıralarının xeyirlisi birincisi, şəri sonuncusudur.","en":"The best of men's rows is the first and the worst is the last.","ru":"Лучшие ряды мужчин — первые, а худшие — последние.","tr":"Erkek saflarının en hayırlısı birincisi, en şerlisi sonuncusudur.","ar":"خَيْرُ صُفُوفِ الرِّجَالِ أَوَّلُهَا وَشَرُّهَا آخِرُهَا"},"src":{"az":"Muslim 440","en":"Muslim 440","ru":"Муслим 440","tr":"Müslim 440","ar":"مسلم 440"}},{"id":872,"t":{"az":"Evlərinizi qəbiristanlığa çevirməyin; şeytan Bəqərə oxunan evdən qaçar.","en":"Do not turn your houses into graveyards; Satan flees from the house in which Surah al-Baqarah is recited.","ru":"Не превращайте дома в кладбища; шайтан бежит из дома, где читают суру Аль-Бакара.","tr":"Evlerinizi mezarlığa çevirmeyin; şeytan Bakara suresi okunan evden kaçar.","ar":"لَا تَجْعَلُوا بُيُوتَكُمْ مَقَابِرَ إِنَّ الشَّيْطَانَ يَنْفِرُ مِنَ الْبَيْتِ الَّذِي تُقْرَأُ فِيهِ سُورَةُ الْبَقَرَةِ"},"src":{"az":"Muslim 780","en":"Muslim 780","ru":"Муслим 780","tr":"Müslim 780","ar":"مسلم 780"}},{"id":874,"t":{"az":"Ümmətimin əməlləri — yaxşısı da, pisi də mənə göstərildi.","en":"The deeds of my ummah — good and bad — were shown to me.","ru":"Мне были показаны дела моей общины — хорошие и плохие.","tr":"Ümmetimin amelleri — iyisi de kötüsü de bana gösterildi.","ar":"عُرِضَتْ عَلَيَّ أَعْمَالُ أُمَّتِي حَسَنُهَا وَسَيِّئُهَا"},"src":{"az":"Muslim 553","en":"Muslim 553","ru":"Муслим 553","tr":"Müslim 553","ar":"مسلم 553"}},{"id":875,"t":{"az":"Allah yolundakı toz ilə cəhənnəm dumanı bir arada olmaz.","en":"The dust of Allah's path and the smoke of Hell will never come together.","ru":"Пыль на пути Аллаха и дым ада никогда не соединятся.","tr":"Allah yolundaki toz ile cehennem dumanı bir arada olmaz.","ar":"لَا يَجْتَمِعُ غُبَارٌ فِي سَبِيلِ اللَّهِ وَدُخَانُ جَهَنَّمَ"},"src":{"az":"Nəsai 3108","en":"An-Nasa'i 3108","ru":"ан-Насаи 3108","tr":"Nesâî 3108","ar":"النسائي 3108"}},{"id":876,"t":{"az":"Kim axşam üç dəfə \"Əuzu bikəlimatillahit-tammati min şərri ma xaləq\" desə, o gecə heç bir zəhərli heyvan ona zərər verməz.","en":"Whoever says three times in the evening \"I seek refuge in the perfect words of Allah from the evil of what He created,\" no poison will harm him that night.","ru":"Кто скажет вечером трижды «Прибегаю к совершенным словам Аллаха от зла того, что Он создал», тому не повредит яд той ночью.","tr":"Kim akşam üç kez \"Euzu bikelimatillahit-tammati min şerri ma halak\" derse, o gece hiçbir zehirli hayvan ona zarar vermez.","ar":"مَنْ قَالَ حِينَ يُمْسِي ثَلَاثَ مَرَّاتٍ أَعُوذُ بِكَلِمَاتِ اللَّهِ التَّامَّاتِ مِنْ شَرِّ مَا خَلَقَ لَمْ تَضُرَّهُ حُمَةٌ تِلْكَ اللَّيْلَةَ"},"src":{"az":"Muslim 2709","en":"Muslim 2709","ru":"Муслим 2709","tr":"Müslim 2709","ar":"مسلم 2709"}},{"id":877,"t":{"az":"İnsanın hər oynağı üçün sədəqə var; iki nəfərin arasını düzəltmək sədəqədir.","en":"Every joint of a person has charity due; reconciling between two people is charity.","ru":"За каждый сустав — милостыня; примирение между двумя людьми — милостыня.","tr":"İnsanın her eklemi için sadaka vardır; iki kişinin arasını düzeltmek sadakadır.","ar":"كُلُّ سُلَامَى مِنَ النَّاسِ عَلَيْهِ صَدَقَةٌ"},"src":{"az":"Muslim 1009","en":"Muslim 1009","ru":"Муслим 1009","tr":"Müslim 1009","ar":"مسلم 1009"}},{"id":880,"t":{"az":"Müsəlman qardaşına gizlicə dua edərsə, mələk deyir: Sənə də eyni olsun.","en":"No Muslim supplicates for his brother in his absence except that the angel says: And for you the same.","ru":"Если мусульманин молится за брата в его отсутствие, ангел говорит: «И тебе то же».","tr":"Müslüman kardeşine gıyabında dua ederse, melek \"sana da aynısı olsun\" der.","ar":"مَا مِنْ عَبْدٍ مُسْلِمٍ يَدْعُو لِأَخِيهِ بِظَهْرِ الْغَيْبِ إِلَّا قَالَ الْمَلَكُ وَلَكَ بِمِثْلٍ"},"src":{"az":"Muslim 2732","en":"Muslim 2732","ru":"Муслим 2732","tr":"Müslim 2732","ar":"مسلم 2732"}},{"id":882,"t":{"az":"Bədəninin sənin üzərində haqqı var.","en":"Your body has a right over you.","ru":"У твоего тела есть право на тебя.","tr":"Bedeninin senin üzerinde hakkı var.","ar":"إِنَّ لِجَسَدِكَ عَلَيْكَ حَقًّا"},"src":{"az":"Buxari 1968","en":"Bukhari 1968","ru":"Бухари 1968","tr":"Buhârî 1968","ar":"البخاري 1968"}},{"id":885,"t":{"az":"Kim iman və ehtisab ilə Qədr gecəsini ibadətlə keçirərsə, keçmiş günahları bağışlanar.","en":"Whoever stands in prayer on the Night of Qadr with faith and hope, his past sins are forgiven.","ru":"Кто выстоит ночную молитву в Ночь Предопределения с верой и надеждой, тому простятся прежние грехи.","tr":"Kim iman ederek ve sevabını umarak Kadir Gecesini ihya ederse geçmiş günahları bağışlanır.","ar":"مَنْ قَامَ لَيْلَةَ الْقَدْرِ إِيمَانًا وَاحْتِسَابًا غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ"},"src":{"az":"Buxari 1901","en":"Bukhari 1901","ru":"Бухари 1901","tr":"Buhârî 1901","ar":"البخاري 1901"}},{"id":891,"t":{"az":"Allaha ən sevimli dörd söz: Sübhanəllah, Əlhəmdulilləh, La ilahə illəllah, Allahu Əkbər.","en":"The most beloved words to Allah are four: SubhanAllah, Alhamdulillah, La ilaha illallah, Allahu Akbar.","ru":"Самые любимые слова Аллаха четыре: Субхана-Ллах, Аль-хамду ли-Ллях, Ля иляха илля-Ллах, Аллаху Акбар.","tr":"Allah'a en sevimli dört söz: Sübhanallah, Elhamdülillah, La ilahe illallah, Allahu Ekber.","ar":"أَحَبُّ الْكَلَامِ إِلَى اللَّهِ أَرْبَعٌ سُبْحَانَ اللَّهِ وَالْحَمْدُ لِلَّهِ وَلَا إِلَهَ إِلَّا اللَّهُ وَاللَّهُ أَكْبَرُ"},"src":{"az":"Muslim 2137","en":"Muslim 2137","ru":"Муслим 2137","tr":"Müslim 2137","ar":"مسلم 2137"}},{"id":892,"t":{"az":"Heç bir yaxşılığı kiçiltmə, qardaşını güləryüzlə qarşılamaq olsa belə.","en":"Do not belittle any good deed, even if it is meeting your brother with a cheerful face.","ru":"Не считай мелким никакое доброе дело, даже если это встреча с братом с приветливым лицом.","tr":"Hiçbir iyiliği küçümseme, kardeşini güler yüzle karşılamak olsa bile.","ar":"لَا تُحَقِّرَنَّ مِنَ الْمَعْرُوفِ شَيْئًا وَلَوْ أَنْ تَلْقَى أَخَاكَ بِوَجْهٍ طَلِقٍ"},"src":{"az":"Muslim 2626","en":"Muslim 2626","ru":"Муслим 2626","tr":"Müslim 2626","ar":"مسلم 2626"}},{"id":893,"t":{"az":"Allah kimə xeyir istəsə, onu sınayar.","en":"Whoever Allah wants good for, He afflicts him.","ru":"Кому Аллах желает блага, того Он испытывает.","tr":"Allah kime hayır dilerse onu imtihan eder.","ar":"مَنْ يُرِدِ اللَّهُ بِهِ خَيْرًا يُصِبْ مِنْهُ"},"src":{"az":"Buxari 5645","en":"Bukhari 5645","ru":"Бухари 5645","tr":"Buhârî 5645","ar":"البخاري 5645"}},{"id":896,"t":{"az":"Salavatınız harada olsanız mənə çatar.","en":"Your blessings reach me wherever you are.","ru":"Ваши благословения достигают меня, где бы вы ни были.","tr":"Salavatınız nerede olursanız olun bana ulaşır.","ar":"صَلَاتُكُمْ عَلَيَّ تَبْلُغُنِي حَيْثُمَا كُنْتُمْ"},"src":{"az":"Əbu Davud 2042","en":"Abu Dawud 2042","ru":"Абу Дауд 2042","tr":"Ebû Dâvûd 2042","ar":"أبو داود 2042"}},{"id":897,"t":{"az":"Qadınlar haqqında bir-birinizə xeyirli tövsiyə edin.","en":"Treat women well.","ru":"Обращайтесь с женщинами по-доброму.","tr":"Kadınlara iyi davranın.","ar":"اسْتَوْصُوا بِالنِّسَاءِ خَيْرًا"},"src":{"az":"Buxari 3331","en":"Bukhari 3331","ru":"Бухари 3331","tr":"Buhârî 3331","ar":"البخاري 3331"}},{"id":900,"t":{"az":"Cənnət əhlini cəhənnəm əhlindən necə tanıyacaqsınız? Gözəl xatırlanma ilə.","en":"You will know the people of Paradise from the people of Fire. They asked: How? He said: By good reputation and bad reputation.","ru":"Вы узнаете обитателей рая от обитателей ада. Спросили: Чем? Ответил: Хорошей и плохой молвой.","tr":"Cennet ehlini cehennem ehlinden nasıl tanıyacaksınız? Güzel anılma ve kötü anılma ile.","ar":"تَعْرِفُونَ أَهْلَ الْجَنَّةِ مِنْ أَهْلِ النَّارِ قَالُوا بِمَ قَالَ بِالثَّنَاءِ الْحَسَنِ وَالثَّنَاءِ السَّيِّئِ"},"src":{"az":"İbn Macə 4221","en":"Ibn Majah 4221","ru":"Ибн Маджа 4221","tr":"İbn Mâce 4221","ar":"ابن ماجه 4221"}},{"id":902,"t":{"az":"Müsəlman müsəlmanın qardaşıdır; ona zülm etməz, onu tərk etməz.","en":"A Muslim is the brother of a Muslim; he does not wrong him nor abandon him.","ru":"Мусульманин — брат мусульманина; он не притесняет его и не оставляет.","tr":"Müslüman Müslümanın kardeşidir; ona zulmetmez ve onu yalnız bırakmaz.","ar":"الْمُسْلِمُ أَخُو الْمُسْلِمِ لاَ يَظْلِمُهُ وَلاَ يُسْلِمُهُ"},"src":{"az":"Buxari 2442","en":"Bukhari 2442","ru":"Бухари 2442","tr":"Buhârî 2442","ar":"البخاري 2442"}},{"id":905,"t":{"az":"Yalandan çəkinin! Yalan günahkarlığa aparır, günahkarlıq isə cəhənnəmə.","en":"Beware of lying! Lying leads to wickedness, and wickedness leads to Hell.","ru":"Остерегайтесь лжи! Ложь ведёт к нечестию, а нечестие — к огню.","tr":"Yalandan sakının! Yalan kötülüğe götürür, kötülük de cehenneme götürür.","ar":"إِيَّاكُمْ وَالْكَذِبَ فَإِنَّ الْكَذِبَ يَهْدِي إِلَى الْفُجُورِ"},"src":{"az":"Buxari 6094","en":"Bukhari 6094","ru":"Бухари 6094","tr":"Buhârî 6094","ar":"البخاري 6094"}},{"id":910,"t":{"az":"Namaz qamət verildikdə qaçaraq deyil, yeriyərək gəlin.","en":"When the prayer is established, do not come running; come walking.","ru":"Когда объявлена молитва, не бегите, а идите спокойно.","tr":"Namaz için kamet getirildiğinde koşarak değil, yürüyerek gelin.","ar":"إِذَا أُقِيمَتِ الصَّلاَةُ فَلاَ تَأْتُوهَا تَسْعَوْنَ وَأْتُوهَا تَمْشُونَ"},"src":{"az":"Buxari 908","en":"Bukhari 908","ru":"Бухари 908","tr":"Buhârî 908","ar":"البخاري 908"}},{"id":922,"t":{"az":"Kim halal qazancından bir xurma dəyərində sədəqə versə, Allah onu sağ əli ilə qəbul edər.","en":"Whoever gives charity equal to a date from lawful earnings, Allah accepts it with His right hand.","ru":"Кто подаст милостыню в размере финика из дозволенного заработка, Аллах примет её Своей правой рукой.","tr":"Kim helal kazancından bir hurma değerinde sadaka verirse, Allah onu sağ eliyle kabul eder.","ar":"مَنْ تَصَدَّقَ بِعَدْلِ تَمْرَةٍ مِنْ كَسْبٍ طَيِّبٍ فَإِنَّ اللَّهَ يَتَقَبَّلُهَا بِيَمِينِهِ"},"src":{"az":"Buxari 1410","en":"Bukhari 1410","ru":"Бухари 1410","tr":"Buhârî 1410","ar":"البخاري 1410"}},{"id":926,"t":{"az":"Qardaşına gülümsəmək sədəqədir, yaxşılığı əmr etmək sədəqədir.","en":"Your smile to your brother is charity, and commanding good is charity.","ru":"Твоя улыбка брату — милостыня, и повеление добра — милостыня.","tr":"Kardeşine gülümsemen sadakadır, iyiliği emretmek sadakadır.","ar":"وَتَبَسُّمُكَ فِي وَجْهِ أَخِيكَ صَدَقَةٌ وَأَمْرُكَ بِالْمَعْرُوفِ صَدَقَةٌ"},"src":{"az":"Tirmizi 1956","en":"Tirmidhi 1956","ru":"Тирмизи 1956","tr":"Tirmizî 1956","ar":"الترمذي 1956"}},{"id":937,"t":{"az":"Rəbbin rizası valideynin rizasındadır, Rəbbin qəzəbi valideynin qəzəbindədir.","en":"The Lord's pleasure is in the parent's pleasure, the Lord's anger is in the parent's anger.","ru":"Довольство Господа — в довольстве родителя, гнев Господа — в гневе родителя.","tr":"Rabbin rızası anne-babanın rızasındadır, Rabbin gazabı anne-babanın gazabındadır.","ar":"رَضَا الرَّبِّ فِي رِضَا الْوَالِدِ وَسَخَطُ الرَّبِّ فِي سَخَطِ الْوَالِدِ"},"src":{"az":"Tirmizi 1899","en":"Tirmidhi 1899","ru":"Тирмизи 1899","tr":"Tirmizî 1899","ar":"الترمذي 1899"}},{"id":940,"t":{"az":"Kim Allah üçün məscid tikərsə, Allah ona cənnətdə bir ev tikər.","en":"Whoever builds a mosque for Allah, Allah will build for him a house in Paradise.","ru":"Кто построит мечеть ради Аллаха, Аллах построит ему дом в раю.","tr":"Kim Allah için bir mescit yaparsa, Allah da ona cennette bir ev yapar.","ar":"مَنْ بَنَى مَسْجِدًا لِلَّهِ بَنَى اللَّهُ لَهُ بَيْتًا فِي الْجَنَّةِ"},"src":{"az":"Muslim 533","en":"Muslim 533","ru":"Муслим 533","tr":"Müslim 533","ar":"مسلم 533"}},{"id":942,"t":{"az":"İnsanları mədənlər kimi taparsınız; cahiliyyədə xeyirli olanlar İslamda da xeyirlidir.","en":"People are like minerals; the best of them in Jahiliyyah are the best of them in Islam.","ru":"Люди — подобны месторождениям; лучшие из них до ислама — лучшие в исламе.","tr":"İnsanları madenler gibi bulursunuz; cahiliyede hayırlı olanlar İslam'da da hayırlıdır.","ar":"تَجِدُونَ النَّاسَ مَعَادِنَ خِيَارُهُمْ فِي الْجَاهِلِيَّةِ خِيَارُهُمْ فِي الإِسْلاَمِ"},"src":{"az":"Buxari 3383","en":"Bukhari 3383","ru":"Бухари 3383","tr":"Buhârî 3383","ar":"البخاري 3383"}},{"id":950,"t":{"az":"Yarım xurma ilə də olsa cəhənnəmdən qorunun; tapa bilməsəniz gözəl bir sözlə.","en":"Protect yourselves from the Fire even with half a date; if you cannot, then with a good word.","ru":"Защитите себя от огня хотя бы половинкой финика; если не найдёте — добрым словом.","tr":"Yarım hurma ile de olsa ateşten korunun; bulamazsanız güzel bir sözle.","ar":"اتَّقُوا النَّارَ وَلَوْ بِشِقِّ تَمْرَةٍ فَإِنْ لَمْ تَجِدُوا فَبِكَلِمَةٍ طَيِّبَةٍ"},"src":{"az":"Buxari 6540","en":"Bukhari 6540","ru":"Бухари 6540","tr":"Buhârî 6540","ar":"البخاري 6540"}},{"id":952,"t":{"az":"Bil ki zəfər səbrlə birgədir, rahatlıq çətinliklə birgədir.","en":"Know that victory comes with patience, and relief comes with hardship.","ru":"Знай, что победа приходит с терпением, а облегчение — с трудностью.","tr":"Bil ki zafer sabırla birliktedir, kolaylık zorlukla birliktedir.","ar":"وَاعْلَمْ أَنَّ النَّصْرَ مَعَ الصَّبْرِ وَأَنَّ الْفَرَجَ مَعَ الْكَرْبِ"},"src":{"az":"Əhməd 2803","en":"Ahmad 2803","ru":"Ахмад 2803","tr":"Ahmed 2803","ar":"أحمد 2803"}},{"id":954,"t":{"az":"Cənnət əhli yüksək otaqların sahiblərini siz ulduzları gördüyünüz kimi görərlər.","en":"The people of Paradise will see the dwellers of the upper rooms as you see a star in the sky.","ru":"Обитатели рая будут видеть жителей верхних горниц, как вы видите звезду на небе.","tr":"Cennet ehli yüksek odaların sahiplerini, sizin yıldızları gördüğünüz gibi göreceklerdir.","ar":"إِنَّ أَهْلَ الْجَنَّةِ يَتَرَاءَوْنَ أَهْلَ الْغُرَفِ كَمَا تَتَرَاءَوْنَ الْكَوْكَبَ"},"src":{"az":"Buxari 3256","en":"Bukhari 3256","ru":"Бухари 3256","tr":"Buhârî 3256","ar":"البخاري 3256"}},{"id":957,"t":{"az":"Kim səhər ya axşam məscidə gedərsə, Allah ona cənnətdə yer hazırlayar.","en":"Whoever goes to the mosque in the morning or evening, Allah prepares for him a place in Paradise.","ru":"Кто ходит в мечеть утром или вечером, Аллах готовит ему место в раю.","tr":"Kim sabah veya akşam mescide giderse, Allah ona cennette bir yer hazırlar.","ar":"مَنْ غَدَا إِلَى الْمَسْجِدِ أَوْ رَاحَ أَعَدَّ اللَّهُ لَهُ نُزُلاً فِي الْجَنَّةِ"},"src":{"az":"Buxari 662","en":"Bukhari 662","ru":"Бухари 662","tr":"Buhârî 662","ar":"البخاري 662"}},{"id":958,"t":{"az":"İslam Allahdan başqa ilah olmadığına və Muhəmmədin Onun elçisi olduğuna şəhadət etməkdir.","en":"Islam is to testify that there is no god but Allah and Muhammad is the Messenger of Allah.","ru":"Ислам — это свидетельство, что нет бога, кроме Аллаха, и что Мухаммад — Посланник Аллаха.","tr":"İslam, Allah'tan başka ilah olmadığına ve Muhammed'in O'nun elçisi olduğuna şehadet etmektir.","ar":"الإِسْلاَمُ أَنْ تَشْهَدَ أَنْ لاَ إِلَهَ إِلاَّ اللَّهُ وَأَنَّ مُحَمَّدًا رَسُولُ اللَّهِ"},"src":{"az":"Muslim 8","en":"Muslim 8","ru":"Муслим 8","tr":"Müslim 8","ar":"مسلم 8"}},{"id":960,"t":{"az":"Birinizin qapısında çay olsa, gündə 5 dəfə yuyunsa, kiri qalarmı? Beş vaxt namaz da belədir.","en":"If there was a river at the door of one of you and he bathed in it five times daily, would any dirt remain? That is the five daily prayers.","ru":"Если бы у двери одного из вас была река и он купался бы в ней пять раз в день, осталась бы грязь? Таковы пять молитв.","tr":"Kapınızın önünde bir nehir olsa günde 5 kez yıkansanız kiri kalır mı? İşte beş vakit namaz böyledir.","ar":"أَرَأَيْتُمْ لَوْ أَنَّ نَهْرًا بِبَابِ أَحَدِكُمْ يَغْتَسِلُ فِيهِ خَمْسَ مَرَّاتٍ"},"src":{"az":"Buxari 528","en":"Bukhari 528","ru":"Бухари 528","tr":"Buhârî 528","ar":"البخاري 528"}},{"id":966,"t":{"az":"Müsəlmana yorğunluq, xəstəlik, qəm-qüssə gəlsə, hətta batırılan tikan belə, Allah bununla günahlarını silər.","en":"No fatigue, illness, worry, or grief befalls a Muslim, not even a thorn that pricks him, except that Allah expiates his sins thereby.","ru":"Мусульманина не постигнет ни усталость, ни болезнь, ни печаль, ни даже укол шипа, чтобы Аллах не искупил этим его грехи.","tr":"Müslümana yorgunluk, hastalık, üzüntü isabet ederse, hatta batan diken bile olsa, Allah bununla günahlarını siler.","ar":"مَا يُصِيبُ الْمُسْلِمَ مِنْ نَصَبٍ وَلاَ وَصَبٍ وَلاَ هَمٍّ وَلاَ حَزَنٍ"},"src":{"az":"Buxari 5641","en":"Bukhari 5641","ru":"Бухари 5641","tr":"Buhârî 5641","ar":"البخاري 5641"}},{"id":973,"t":{"az":"Rəhmli olanlara Rəhman da rəhm edər. Yerdəkilərə rəhm edin ki, göydəki sizə rəhm etsin.","en":"The merciful are shown mercy by the Most Merciful. Be merciful to those on earth, and the One above will be merciful to you.","ru":"К милосердным Милостивый проявляет милость. Будьте милосердны к тем, кто на земле, — и Тот, кто на небе, помилует вас.","tr":"Merhametli olanlara Rahman da merhamet eder. Yerdeki merhamet edin ki, gökteki size merhamet etsin.","ar":"الرَّاحِمُونَ يَرْحَمُهُمُ الرَّحْمَنُ ارْحَمُوا مَنْ فِي الأَرْضِ يَرْحَمْكُمْ مَنْ فِي السَّمَاءِ"},"src":{"az":"Tirmizi 1924","en":"Tirmidhi 1924","ru":"Тирмизи 1924","tr":"Tirmizî 1924","ar":"الترمذي 1924"}},{"id":975,"t":{"az":"Quran sahibinə deyilər: Oxu, yüksəl və tərtil ilə oxu.","en":"It will be said to the companion of the Quran: Read and ascend and recite.","ru":"Спутнику Корана будет сказано: Читай, поднимайся и читай размеренно.","tr":"Kuran sahibine denilecek: Oku, yüksel ve tertil ile oku.","ar":"يُقَالُ لِصَاحِبِ الْقُرْآنِ اقْرَأْ وَارْتَقِ وَرَتِّلْ"},"src":{"az":"Tirmizi 2914","en":"Tirmidhi 2914","ru":"Тирмизи 2914","tr":"Tirmizî 2914","ar":"الترمذي 2914"}},{"id":982,"t":{"az":"Cümə günü mənə salavat göndərin, salavatlarınız mənə çatdırılır.","en":"Send blessings upon me on Friday, for your blessings are presented to me.","ru":"Благословляйте меня в пятницу, ибо ваши благословения представляются мне.","tr":"Cuma günü bana salavat getirin, salavatlarınız bana arz olunur.","ar":"صَلُّوا عَلَيَّ يَوْمَ الْجُمُعَةِ فَإِنَّ صَلاَتَكُمْ مَعْرُوضَةٌ عَلَيَّ"},"src":{"az":"Əbu Davud 1047","en":"Abu Dawud 1047","ru":"Абу Дауд 1047","tr":"Ebû Dâvûd 1047","ar":"أبو داود 1047"}},{"id":983,"t":{"az":"Bol olan yerdə səfər edərkən dəvələrə yerdən payını verin.","en":"When you travel through fertile land, give the camels their share from the earth.","ru":"Когда путешествуете по плодородной земле, давайте верблюдам их долю от земли.","tr":"Bereketli yerde yolculuk ettiğinizde develere yerden payını verin.","ar":"إِذَا سَافَرْتُمْ فِي الْخِصْبِ فَأَعْطُوا الإِبِلَ حَظَّهَا مِنَ الأَرْضِ"},"src":{"az":"Muslim 1926","en":"Muslim 1926","ru":"Муслим 1926","tr":"Müslim 1926","ar":"مسلم 1926"}},{"id":985,"t":{"az":"Cihadın ən fəziləti zalım hökmdar qarşısında haqq söz söyləməkdir.","en":"The best jihad is a word of truth before a tyrant ruler.","ru":"Лучший джихад — слово истины перед несправедливым правителем.","tr":"Cihadın en faziletlisi, zalim sultanın karşısında hak söz söylemektir.","ar":"أَفْضَلُ الْجِهَادِ كَلِمَةُ حَقٍّ عِنْدَ سُلْطَانٍ جَائِرٍ"},"src":{"az":"Tirmizi 2174","en":"Tirmidhi 2174","ru":"Тирмизи 2174","tr":"Tirmizî 2174","ar":"الترمذي 2174"}},{"id":986,"t":{"az":"Doğru olun, hər şeyi saya bilməzsiniz; bilin ki əməllərinizin ən xeyirlisi namazdır.","en":"Be steadfast, though you cannot count it all. And know that the best of your deeds is prayer.","ru":"Будьте прямыми, хотя вам не перечесть всего. И знайте: лучшее из ваших дел — молитва.","tr":"İstikamet üzere olun, her şeyi sayamazsınız; bilin ki amellerinizin en hayırlısı namazdır.","ar":"اسْتَقِيمُوا وَلَنْ تُحْصُوا وَاعْلَمُوا أَنَّ خَيْرَ أَعْمَالِكُمُ الصَّلاَةُ"},"src":{"az":"İbn Macə 277","en":"Ibn Majah 277","ru":"Ибн Маджа 277","tr":"İbn Mâce 277","ar":"ابن ماجه 277"}},{"id":989,"t":{"az":"Qulla küfr arasındakı fərq namazı tərk etməkdir.","en":"Between a servant and disbelief is abandoning prayer.","ru":"Между рабом и неверием — оставление молитвы.","tr":"Kul ile küfür arasındaki fark, namazı terk etmektir.","ar":"بَيْنَ الْعَبْدِ وَبَيْنَ الْكُفْرِ تَرْكُ الصَّلاَةِ"},"src":{"az":"Muslim 82","en":"Muslim 82","ru":"Муслим 82","tr":"Müslim 82","ar":"مسلم 82"}},{"id":992,"t":{"az":"Kim Şəvval ayından altı gün oruc tutarsa, bütün ili oruc tutmuş kimi olar.","en":"Whoever fasts six days of Shawwal, it is as if he fasted the entire year.","ru":"Кто постится шесть дней Шавваля, это как пост целого года.","tr":"Kim Şevval ayından altı gün oruç tutarsa, bütün yıl oruç tutmuş gibi olur.","ar":"مَنْ صَامَ سِتَّةَ أَيَّامٍ مِنْ شَوَّالٍ كَانَ كَصِيَامِ الدَّهْرِ"},"src":{"az":"Muslim 1164","en":"Muslim 1164","ru":"Муслим 1164","tr":"Müslim 1164","ar":"مسلم 1164"}},{"id":999,"t":{"az":"Asanlaşdırın, çətinləşdirməyin; müjdələyin, nifrət etdirməyin.","en":"Make things easy and do not make them difficult; give glad tidings and do not drive people away.","ru":"Облегчайте и не затрудняйте; радуйте и не отталкивайте.","tr":"Kolaylaştırın, zorlaştırmayın; müjdeleyin, nefret ettirmeyin.","ar":"يَسِّرُوا وَلاَ تُعَسِّرُوا وَبَشِّرُوا وَلاَ تُنَفِّرُوا"},"src":{"az":"Buxari 69","en":"Bukhari 69","ru":"Бухари 69","tr":"Buhârî 69","ar":"البخاري 69"}},{"id":1000,"t":{"az":"Allah ümmətimin səhvini, unutmasını və məcbur edildiyi şeyi bağışladı.","en":"Allah has forgiven my ummah for their mistakes, forgetfulness, and what they are forced to do.","ru":"Аллах простил моей умме ошибку, забывчивость и то, к чему их принудили.","tr":"Allah, ümmetimin hatasını, unutmasını ve zorlandığı şeyleri bağışladı.","ar":"إِنَّ اللَّهَ تَجَاوَزَ عَنْ أُمَّتِي الْخَطَأَ وَالنِّسْيَانَ وَمَا اسْتُكْرِهُوا عَلَيْهِ"},"src":{"az":"İbn Macə 2045","en":"Ibn Majah 2045","ru":"Ибн Маджа 2045","tr":"İbn Mâce 2045","ar":"ابن ماجه 2045"}},{"id":1001,"t":{"az":"Qadınlara yaxşılıq edin, çünki onlar qabırğadan yaradılmışdır.","en":"Treat women kindly, for they were created from a rib.","ru":"Обходитесь с женщинами хорошо, ибо они созданы из ребра.","tr":"Kadınlara iyi davranın, çünkü onlar kaburga kemiğinden yaratılmıştır.","ar":"اسْتَوْصُوا بِالنِّسَاءِ خَيْرًا فَإِنَّهُنَّ خُلِقْنَ مِنْ ضِلَعٍ"},"src":{"az":"Buxari 3331","en":"Bukhari 3331","ru":"Бухари 3331","tr":"Buhârî 3331","ar":"البخاري 3331"}},{"id":1003,"t":{"az":"Mömin kişi mömin qadına nifrət etməsin; onun bir xasiyyətini bəyənməsə, digərini bəyənər.","en":"A believing man should not hate a believing woman; if he dislikes one trait, he may like another.","ru":"Верующий мужчина не должен ненавидеть верующую женщину; если ему не нравится одно качество, ему понравится другое.","tr":"Mümin bir erkek mümin bir kadına buğzetmesin; bir huyunu beğenmezse başka bir huyunu beğenir.","ar":"لَا يَفْرَكْ مُؤْمِنٌ مُؤْمِنَةً إِنْ كَرِهَ مِنْهَا خُلُقًا رَضِيَ مِنْهَا آخَرَ"},"src":{"az":"Muslim 1469","en":"Muslim 1469","ru":"Муслим 1469","tr":"Müslim 1469","ar":"مسلم 1469"}},{"id":1005,"t":{"az":"Kim iki qız uşağını yetişdirərsə, Qiyamət günü mənimlə birlikdə gələr.","en":"Whoever raises two girls until they reach maturity, he and I will come on the Day of Judgment like this.","ru":"Кто воспитает двух дочерей до их совершеннолетия, в День Суда мы будем вместе.","tr":"Kim iki kız çocuğunu yetişkinliğe kadar büyütürse, Kıyamet günü o ve ben böyle geliriz.","ar":"مَنْ عَالَ جَارِيَتَيْنِ حَتَّى تَبْلُغَا جَاءَ يَوْمَ الْقِيَامَةِ أَنَا وَهُوَ"},"src":{"az":"Muslim 2631","en":"Muslim 2631","ru":"Муслим 2631","tr":"Müslim 2631","ar":"مسلم 2631"}},{"id":1006,"t":{"az":"Kiçiklərimizə rəhm etməyən və böyüklərimizin haqqını tanımayan bizdən deyil.","en":"He is not one of us who does not show mercy to our young and recognize the rights of our elders.","ru":"Не из нас тот, кто не милосерден к нашим младшим и не признаёт права наших старших.","tr":"Küçüklerimize merhamet etmeyen ve büyüklerimizin hakkını tanımayan bizden değildir.","ar":"لَيْسَ مِنَّا مَنْ لَمْ يَرْحَمْ صَغِيرَنَا وَيَعْرِفْ حَقَّ كَبِيرِنَا"},"src":{"az":"Tirmizi 1920","en":"Tirmidhi 1920","ru":"Тирмизи 1920","tr":"Tirmizî 1920","ar":"الترمذي 1920"}},{"id":1007,"t":{"az":"Bir müsəlman bir ağac əkərsə, ondan yeyilən hər şey ona sədəqə olar.","en":"No Muslim plants a tree except that whatever is eaten from it is charity for him.","ru":"Каждый мусульманин, посадивший дерево, получает награду за всё, что с него съедено.","tr":"Bir Müslüman ağaç dikerse, ondan yenen her şey kendisi için sadaka olur.","ar":"مَا مِنْ مُسْلِمٍ يَغْرِسُ غَرْسًا إِلَّا كَانَ مَا أُكِلَ مِنْهُ لَهُ صَدَقَةً"},"src":{"az":"Muslim 1553","en":"Muslim 1553","ru":"Муслим 1553","tr":"Müslim 1553","ar":"مسلم 1553"}},{"id":1011,"t":{"az":"Rəsulullah faiz yeyəni, yedirəni, yazanı və şahidlərini lənətlədi.","en":"The Messenger of Allah cursed the one who consumes usury, the one who pays it, the one who writes it, and its two witnesses.","ru":"Посланник Аллаха проклял берущего ростовщичество, дающего его, записывающего и двух свидетелей.","tr":"Resulullah faiz yiyeni, yedireni, yazanı ve iki şahidini lanetledi.","ar":"لَعَنَ رَسُولُ اللَّهِ آكِلَ الرِّبَا وَمُؤْكِلَهُ وَكَاتِبَهُ وَشَاهِدَيْهِ"},"src":{"az":"Muslim 1598","en":"Muslim 1598","ru":"Муслим 1598","tr":"Müslim 1598","ar":"مسلم 1598"}},{"id":1012,"t":{"az":"Rəsulullah rüşvət verəni və alanı lənətlədi.","en":"The Messenger of Allah cursed the one who gives a bribe and the one who takes it.","ru":"Посланник Аллаха проклял дающего взятку и берущего её.","tr":"Resulullah rüşvet vereni ve alanı lanetledi.","ar":"لَعَنَ رَسُولُ اللَّهِ الرَّاشِيَ وَالْمُرْتَشِيَ"},"src":{"az":"Əbu Davud 3580","en":"Abu Dawud 3580","ru":"Абу Дауд 3580","tr":"Ebû Dâvûd 3580","ar":"أبو داود 3580"}},{"id":1016,"t":{"az":"Zənginin borcunu gecikdirməsi zülmdür.","en":"The delay of a rich person in paying a debt is injustice.","ru":"Задержка богатым выплаты долга — это несправедливость.","tr":"Zenginin borcunu geciktirmesi zulümdür.","ar":"مَطْلُ الْغَنِيِّ ظُلْمٌ"},"src":{"az":"Buxari 2287","en":"Bukhari 2287","ru":"Бухари 2287","tr":"Buhârî 2287","ar":"البخاري 2287"}},{"id":1017,"t":{"az":"Möminin ruhu borcu ödənənə qədər asılı qalar.","en":"The soul of the believer is held back by his debt until it is paid off.","ru":"Душа верующего привязана к его долгу, пока он не будет выплачен.","tr":"Müminin ruhu borcu ödenene kadar bağlı kalır.","ar":"نَفْسُ الْمُؤْمِنِ مُعَلَّقَةٌ بِدَيْنِهِ حَتَّى يُقْضَى عَنْهُ"},"src":{"az":"Tirmizi 1078","en":"Tirmidhi 1078","ru":"Тирмизи 1078","tr":"Tirmizî 1078","ar":"الترمذي 1078"}},{"id":1018,"t":{"az":"Hamınız çobansınız və hamınız sürünüzdən məsulsunuz.","en":"Each of you is a shepherd and each of you is responsible for his flock.","ru":"Каждый из вас пастырь, и каждый из вас ответственен за свою паству.","tr":"Hepiniz çobansınız ve hepiniz sürünüzden sorumlusunuz.","ar":"كُلُّكُمْ رَاعٍ وَكُلُّكُمْ مَسْئُولٌ عَنْ رَعِيَّتِهِ"},"src":{"az":"Buxari 893","en":"Bukhari 893","ru":"Бухари 893","tr":"Buhârî 893","ar":"البخاري 893"}},{"id":1019,"t":{"az":"Əmanət zay edildikdə Qiyaməti gözlə.","en":"When trust is lost, then await the Hour.","ru":"Когда утрачено доверие — жди Часа.","tr":"Emanet zayi edildiğinde kıyameti bekle.","ar":"إِذَا ضُيِّعَتِ الأَمَانَةُ فَانْتَظِرِ السَّاعَةَ"},"src":{"az":"Buxari 6496","en":"Bukhari 6496","ru":"Бухари 6496","tr":"Buhârî 6496","ar":"البخاري 6496"}},{"id":1020,"t":{"az":"Allah bir bəndəni xalqın başına qoyar, o da xalqını aldadaraq ölərsə, Allah ona cənnəti haram edər.","en":"Any ruler whom Allah has entrusted with people, if he dies cheating them, Allah will forbid him Paradise.","ru":"Любой правитель, которому Аллах вверил подданных, если он умрёт, обманывая их, Аллах запретит ему Рай.","tr":"Allah\\'ın kendisine tebaa verdiği bir yönetici, onları aldatarak ölürse, Allah ona cenneti haram kılar.","ar":"مَا مِنْ عَبْدٍ يَسْتَرْعِيهِ اللَّهُ رَعِيَّةً يَمُوتُ يَوْمَ يَمُوتُ وَهُوَ غَاشٌّ لِرَعِيَّتِهِ إِلَّا حَرَّمَ اللَّهُ عَلَيْهِ الْجَنَّةَ"},"src":{"az":"Muslim 142","en":"Muslim 142","ru":"Муслим 142","tr":"Müslim 142","ar":"مسلم 142"}},{"id":1023,"t":{"az":"Canım əlində olana and olsun, əgər günah etməsəydiniz, Allah sizi aparar, günah edib bağışlanma diləyən bir qövm gətirərdi.","en":"By the One in Whose hand is my soul, if you did not sin, Allah would replace you with people who sin and then seek forgiveness.","ru":"Клянусь Тем, в Чьей руке моя душа, если бы вы не грешили, Аллах заменил бы вас теми, кто грешит и просит прощения.","tr":"Nefsim elinde olana yemin ederim, günah işlemeseydiniz Allah sizi giderir, günah işleyip bağışlanma dileyen bir topluluk getirirdi.","ar":"وَالَّذِي نَفْسِي بِيَدِهِ لَوْ لَمْ تُذْنِبُوا لَذَهَبَ اللَّهُ بِكُمْ وَلَجَاءَ بِقَوْمٍ يُذْنِبُونَ فَيَسْتَغْفِرُونَ"},"src":{"az":"Muslim 2749","en":"Muslim 2749","ru":"Муслим 2749","tr":"Müslim 2749","ar":"مسلم 2749"}},{"id":1024,"t":{"az":"Kim \"Əstəğfirullahəl-azim\" desə, döyüşdən qaçmış olsa belə bağışlanar.","en":"Whoever says \"I seek forgiveness from Allah the Almighty\" — he will be forgiven even if he fled from battle.","ru":"Кто скажет «Прошу прощения у Аллаха Великого» — будет прощён, даже если бежал с поля боя.","tr":"Kim \"Estağfirullahel-azîm\" derse, savaştan kaçmış olsa bile bağışlanır.","ar":"مَنْ قَالَ أَسْتَغْفِرُ اللَّهَ الْعَظِيمَ الَّذِي لَا إِلَهَ إِلَّا هُوَ الْحَيَّ الْقَيُّومَ وَأَتُوبُ إِلَيْهِ غُفِرَ لَهُ وَإِنْ كَانَ فَرَّ مِنَ الزَّحْفِ"},"src":{"az":"Tirmizi 3577","en":"Tirmidhi 3577","ru":"Тирмизи 3577","tr":"Tirmizî 3577","ar":"الترمذي 3577"}},{"id":1025,"t":{"az":"İstiğfarın ən üstünü budur: Allahım, Sən mənim Rəbbimsən, Səndən başqa ilah yoxdur.","en":"The master of seeking forgiveness is to say: O Allah, You are my Lord, there is no god but You.","ru":"Лучшая мольба о прощении: О Аллах, Ты мой Господь, нет бога кроме Тебя.","tr":"İstiğfarın efendisi şöyle demektir: Allah\\'ım, Sen benim Rabbimsin, Senden başka ilah yoktur.","ar":"سَيِّدُ الِاسْتِغْفَارِ أَنْ تَقُولَ اللَّهُمَّ أَنْتَ رَبِّي لَا إِلَهَ إِلَّا أَنْتَ"},"src":{"az":"Buxari 6306","en":"Bukhari 6306","ru":"Бухари 6306","tr":"Buhârî 6306","ar":"البخاري 6306"}},{"id":1028,"t":{"az":"Rəbbimiz hər gecə axırıncı üçdə bir qaldıqda dünya səmasına enər.","en":"Our Lord descends every night to the lowest heaven when the last third of the night remains.","ru":"Наш Господь нисходит каждую ночь к ближайшему небу, когда остаётся последняя треть ночи.","tr":"Rabbimiz her gece, gecenin son üçte biri kaldığında dünya semasına iner.","ar":"يَنْزِلُ رَبُّنَا تَبَارَكَ وَتَعَالَى كُلَّ لَيْلَةٍ إِلَى السَّمَاءِ الدُّنْيَا حِينَ يَبْقَى ثُلُثُ اللَّيْلِ الآخِرُ"},"src":{"az":"Buxari 1145","en":"Bukhari 1145","ru":"Бухари 1145","tr":"Buhârî 1145","ar":"البخاري 1145"}},{"id":1029,"t":{"az":"Sizə qəbirləri ziyarət etməyi qadağan etmişdim, indi ziyarət edin, çünki o axirəti xatırladır.","en":"I had forbidden you from visiting graves; now visit them, for they remind you of the Hereafter.","ru":"Я запрещал вам посещать могилы — теперь посещайте их, ибо они напоминают о вечности.","tr":"Size kabirleri ziyaret etmeyi yasaklamıştım; artık ziyaret edin, çünkü ahireti hatırlatır.","ar":"كُنْتُ نَهَيْتُكُمْ عَنْ زِيَارَةِ الْقُبُورِ أَلَا فَزُورُوهَا فَإِنَّهَا تُذَكِّرُ الْآخِرَةَ"},"src":{"az":"Muslim 977","en":"Muslim 977","ru":"Муслим 977","tr":"Müslim 977","ar":"مسلم 977"}},{"id":1030,"t":{"az":"Salam olsun sizə, ey möminlərin diyarı! İnşaallah biz də sizə qovuşacağıq.","en":"Peace be upon you, O inhabitants of the abodes from among the believers; we shall, Allah willing, join you.","ru":"Мир вам, о обитатели могил из числа верующих; мы, если пожелает Аллах, присоединимся к вам.","tr":"Selam size, ey müminlerin diyarının ehli! İnşaallah biz de size katılacağız.","ar":"السَّلَامُ عَلَيْكُمْ أَهْلَ الدِّيَارِ مِنَ الْمُؤْمِنِينَ وَإِنَّا إِنْ شَاءَ اللَّهُ بِكُمْ لَاحِقُونَ"},"src":{"az":"Muslim 975","en":"Muslim 975","ru":"Муслим 975","tr":"Müslim 975","ar":"مسلم 975"}},{"id":1031,"t":{"az":"Müsəlmana gələn yorğunluq, xəstəlik, qəm və kədər — hətta batan tikan belə — günahlarına kəffarə olar.","en":"No fatigue, illness, anxiety, sorrow, or even a thorn prick afflicts a Muslim but Allah expiates his sins thereby.","ru":"Мусульманина не постигнет ни усталость, ни болезнь, ни печаль — даже укол колючки — без того, чтобы Аллах не искупил этим его грехи.","tr":"Müslümana isabet eden yorgunluk, hastalık, üzüntü — hatta batan diken bile — günahlarına kefaret olur.","ar":"مَا يُصِيبُ الْمُسْلِمَ مِنْ نَصَبٍ وَلَا وَصَبٍ وَلَا هَمٍّ وَلَا حَزَنٍ حَتَّى الشَّوْكَةِ يُشَاكُهَا إِلَّا كَفَّرَ اللَّهُ بِهَا مِنْ خَطَايَاهُ"},"src":{"az":"Buxari 5641","en":"Bukhari 5641","ru":"Бухари 5641","tr":"Buhârî 5641","ar":"البخاري 5641"}},{"id":1034,"t":{"az":"Bir müsəlman səhər vaxtı xəstə müsəlmanı ziyarət edərsə, axşama qədər yetmiş min mələk ona dua edər.","en":"If a Muslim visits a sick Muslim in the morning, seventy thousand angels pray for him until evening.","ru":"Если мусульманин навещает больного утром, семьдесят тысяч ангелов молятся за него до вечера.","tr":"Bir Müslüman sabah vakti hasta bir Müslümanı ziyaret ederse, akşama kadar yetmiş bin melek ona dua eder.","ar":"مَا مِنْ مُسْلِمٍ يَعُودُ مُسْلِمًا غُدْوَةً إِلَّا صَلَّى عَلَيْهِ سَبْعُونَ أَلْفَ مَلَكٍ حَتَّى يُمْسِيَ"},"src":{"az":"Tirmizi 969","en":"Tirmidhi 969","ru":"Тирмизи 969","tr":"Tirmizî 969","ar":"الترمذي 969"}},{"id":1035,"t":{"az":"Gözəl yuxu Allahdandır, pis yuxu şeytandandır.","en":"A good dream is from Allah and a bad dream is from Satan.","ru":"Хороший сон от Аллаха, а дурной сон от шайтана.","tr":"Güzel rüya Allah\\'tandır, kötü rüya şeytandandır.","ar":"الرُّؤْيَا الصَّالِحَةُ مِنَ اللَّهِ وَالْحُلُمُ مِنَ الشَّيْطَانِ"},"src":{"az":"Buxari 6984","en":"Bukhari 6984","ru":"Бухари 6984","tr":"Buhârî 6984","ar":"البخاري 6984"}},{"id":1036,"t":{"az":"Peyğəmbərlikdən yalnız müjdəçilər qaldı: saleh yuxu.","en":"Nothing remains of prophethood except glad tidings — the righteous dream.","ru":"От пророчества осталось лишь благие вести — праведный сон.","tr":"Peygamberlikten sadece müjdeciler kaldı: salih rüya.","ar":"لَمْ يَبْقَ مِنَ النُّبُوَّةِ إِلَّا الْمُبَشِّرَاتُ"},"src":{"az":"Buxari 6990","en":"Bukhari 6990","ru":"Бухари 6990","tr":"Buhârî 6990","ar":"البخاري 6990"}},{"id":1037,"t":{"az":"Günəşin doğduğu ən xeyirli gün Cümə günüdür.","en":"The best day on which the sun rises is Friday.","ru":"Лучший день, в который восходит солнце — пятница.","tr":"Güneşin doğduğu en hayırlı gün Cuma günüdür.","ar":"خَيْرُ يَوْمٍ طَلَعَتْ عَلَيْهِ الشَّمْسُ يَوْمُ الْجُمُعَةِ"},"src":{"az":"Muslim 854","en":"Muslim 854","ru":"Муслим 854","tr":"Müslim 854","ar":"مسلم 854"}},{"id":1038,"t":{"az":"Cümə günündə elə bir saat var ki, müsəlman o vaxt Allahdan nə istəsə ona verilər.","en":"On Friday there is an hour during which a Muslim does not ask Allah for anything but it is given to him.","ru":"В пятницу есть час, в который мусульманин не попросит Аллаха ни о чём, не получив этого.","tr":"Cuma gününde bir saat vardır ki, Müslüman o saatte Allah\\'tan ne isterse ona verilir.","ar":"إِنَّ فِي الْجُمُعَةِ لَسَاعَةً لَا يُوَافِقُهَا عَبْدٌ مُسْلِمٌ يَسْأَلُ اللَّهَ فِيهَا شَيْئًا إِلَّا أَعْطَاهُ إِيَّاهُ"},"src":{"az":"Buxari 935","en":"Bukhari 935","ru":"Бухари 935","tr":"Buhârî 935","ar":"البخاري 935"}},{"id":1041,"t":{"az":"Kim bizim namazımızı qılıb bizim kimi qurban kəsərsə, o qurbanını doğru kəsmişdir.","en":"Whoever prays as we pray and sacrifices as we sacrifice has observed the rite correctly.","ru":"Кто молится нашей молитвой и совершает нашу жертву, тот правильно совершил обряд.","tr":"Kim bizim namazımızı kılıp bizim gibi kurban keserse, kurbanını doğru yapmıştır.","ar":"مَنْ صَلَّى صَلاَتَنَا وَنَسَكَ نُسُكَنَا فَقَدْ أَصَابَ النُّسُكَ"},"src":{"az":"Buxari 5562","en":"Bukhari 5562","ru":"Бухари 5562","tr":"Buhârî 5562","ar":"البخاري 5562"}},{"id":1042,"t":{"az":"Kim and içib sonra başqa bir şeyin daha xeyirli olduğunu görsə, andının kəffarəsini versin.","en":"Whoever takes an oath then sees something better, let him expiate his oath and do what is better.","ru":"Кто поклялся, а потом увидел лучшее — пусть искупит клятву и сделает лучшее.","tr":"Kim yemin edip sonra daha hayırlısını görürse, yemininin kefaretini versin ve hayırlı olanı yapsın.","ar":"مَنْ حَلَفَ عَلَى يَمِينٍ فَرَأَى غَيْرَهَا خَيْرًا مِنْهَا فَلْيُكَفِّرْ عَنْ يَمِينِهِ وَلْيَفْعَلِ الَّذِي هُوَ خَيْرٌ"},"src":{"az":"Muslim 1650","en":"Muslim 1650","ru":"Муслим 1650","tr":"Müslim 1650","ar":"مسلم 1650"}},{"id":1044,"t":{"az":"Bir qadın pişiyə görə cəhənnəmə girdi: onu bağladı, yedirtmədi, yerin həşəratından yeməyə də buraxmadı.","en":"A woman entered Hell because of a cat she tied up; she did not feed it or let it eat from the earth.","ru":"Женщина попала в ад из-за кошки, которую привязала: не кормила и не отпускала есть.","tr":"Bir kadın, bağladığı bir kedi yüzünden cehenneme girdi; onu beslemedi, yerin haşeratından yemeye de bırakmadı.","ar":"دَخَلَتِ امْرَأَةٌ النَّارَ فِي هِرَّةٍ رَبَطَتْهَا فَلَمْ تُطْعِمْهَا وَلَمْ تَدَعْهَا تَأْكُلُ مِنْ خَشَاشِ الأَرْضِ"},"src":{"az":"Buxari 3318","en":"Bukhari 3318","ru":"Бухари 3318","tr":"Buhârî 3318","ar":"البخاري 3318"}},{"id":1045,"t":{"az":"Bir adam susamış bir itə su verdi, Allah da onu bağışladı.","en":"A man gave water to a thirsty dog, and Allah forgave him for that.","ru":"Человек напоил жаждущую собаку, и Аллах простил его за это.","tr":"Bir adam susuz bir köpeğe su verdi, Allah da onu bundan dolayı bağışladı.","ar":"بَيْنَمَا رَجُلٌ يَمْشِي بِطَرِيقٍ اشْتَدَّ عَلَيْهِ الْعَطَشُ فَوَجَدَ بِئْرًا فَنَزَلَ فِيهَا فَشَرِبَ ثُمَّ خَرَجَ فَإِذَا كَلْبٌ يَلْهَثُ"},"src":{"az":"Buxari 2363","en":"Bukhari 2363","ru":"Бухари 2363","tr":"Buhârî 2363","ar":"البخاري 2363"}},{"id":1046,"t":{"az":"Allah hər şeydə ehsanı vacib etmişdir. Öldürəndə yaxşı öldürün, kəsəndə yaxşı kəsin.","en":"Allah has prescribed excellence in everything. When you kill, kill well; when you slaughter, slaughter well.","ru":"Аллах предписал совершенство во всём. Если убиваете — убивайте хорошо, если закалываете — закалывайте хорошо.","tr":"Allah her şeyde ihsanı farz kılmıştır. Öldürdüğünüzde güzel öldürün, kestiğinizde güzel kesin.","ar":"إِنَّ اللَّهَ كَتَبَ الْإِحْسَانَ عَلَى كُلِّ شَيْءٍ فَإِذَا قَتَلْتُمْ فَأَحْسِنُوا الْقِتْلَةَ وَإِذَا ذَبَحْتُمْ فَأَحْسِنُوا الذِّبْحَةَ"},"src":{"az":"Muslim 1955","en":"Muslim 1955","ru":"Муслим 1955","tr":"Müslim 1955","ar":"مسلم 1955"}},{"id":1047,"t":{"az":"Alıcı və satıcı ayrılmadıqca seçim haqqına malikdir.","en":"The buyer and seller have the option to cancel as long as they have not parted.","ru":"Продавец и покупатель имеют право выбора, пока не расстанутся.","tr":"Alıcı ve satıcı ayrılmadıkça muhayyerdirler.","ar":"الْبَيِّعَانِ بِالْخِيَارِ مَا لَمْ يَتَفَرَّقَا"},"src":{"az":"Buxari 2107","en":"Bukhari 2107","ru":"Бухари 2107","tr":"Buhârî 2107","ar":"البخاري 2107"}},{"id":1050,"t":{"az":"Siz mənə mübahisə gətirirsiniz; bəziniz dəlilini digərindən daha gözəl ifadə edə bilər.","en":"You bring your disputes to me, and perhaps one of you is more eloquent in his argument than another.","ru":"Вы приходите ко мне со спорами; возможно, кто-то из вас красноречивее другого в доводах.","tr":"Siz davalarınızı bana getiriyorsunuz; belki biriniz hüccetini diğerinden daha güzel ifade eder.","ar":"إِنَّكُمْ تَخْتَصِمُونَ إِلَيَّ وَلَعَلَّ بَعْضَكُمْ أَنْ يَكُونَ أَلْحَنَ بِحُجَّتِهِ مِنْ بَعْضٍ"},"src":{"az":"Buxari 7169","en":"Bukhari 7169","ru":"Бухари 7169","tr":"Buhârî 7169","ar":"البخاري 7169"}},{"id":1053,"t":{"az":"Hər sərxoşedici haramdır.","en":"Every intoxicant is forbidden.","ru":"Каждое опьяняющее средство запретно.","tr":"Her sarhoş edici haramdır.","ar":"كُلُّ مُسْكِرٍ حَرَامٌ"},"src":{"az":"Buxari 5585","en":"Bukhari 5585","ru":"Бухари 5585","tr":"Buhârî 5585","ar":"البخاري 5585"}},{"id":1054,"t":{"az":"Allah içkini, onu içəni, süzəni, satanı, alanı, sıxanı lənətlədi.","en":"Allah has cursed wine, its drinker, its server, its seller, its buyer, and its presser.","ru":"Аллах проклял вино, того, кто его пьёт, подаёт, продаёт, покупает и выжимает.","tr":"Allah, içkiyi, onu içeni, sunani, satanı, alanı ve sıkanı lanetlemiştir.","ar":"لَعَنَ اللَّهُ الْخَمْرَ وَشَارِبَهَا وَسَاقِيَهَا وَبَائِعَهَا وَمُبْتَاعَهَا وَعَاصِرَهَا"},"src":{"az":"Əbu Davud 3674","en":"Abu Dawud 3674","ru":"Абу Дауд 3674","tr":"Ebû Dâvûd 3674","ar":"أبو داود 3674"}},{"id":1058,"t":{"az":"Günahsız və qohumluq pozmayan dua edən müsəlmana Allah üç şeydən birini verər.","en":"No Muslim supplicates without sin or severing kinship except Allah gives him one of three things.","ru":"Мусульманин, просящий без греха и разрыва родства, получает одно из трёх.","tr":"Günah ve akraba ilişkisini kesme olmayan dua eden Müslümana Allah üçünden birini verir.","ar":"مَا مِنْ مُسْلِمٍ يَدْعُو بِدَعْوَةٍ لَيْسَ فِيهَا إِثْمٌ وَلَا قَطِيعَةُ رَحِمٍ إِلَّا أَعْطَاهُ اللَّهُ بِهَا إِحْدَى ثَلَاثٍ"},"src":{"az":"Əhməd 11133","en":"Ahmad 11133","ru":"Ахмад 11133","tr":"Ahmed 11133","ar":"أحمد 11133"}},{"id":1059,"t":{"az":"Bunu bizə ram edəni təsbih edirik, yoxsa biz buna güc çatdıra bilməzdik.","en":"Glory be to Him who has subjected this to us, for we could not have done it ourselves.","ru":"Пречист Тот, Кто подчинил нам это, ведь мы сами не смогли бы.","tr":"Bunu bizim hizmetimize vereni tenzih ederiz, yoksa biz buna güç yetiremezdik.","ar":"سُبْحَانَ الَّذِي سَخَّرَ لَنَا هَذَا وَمَا كُنَّا لَهُ مُقْرِنِينَ"},"src":{"az":"Muslim 1342","en":"Muslim 1342","ru":"Муслим 1342","tr":"Müslim 1342","ar":"مسلم 1342"}},{"id":1060,"t":{"az":"Allahım, bu səfərimizdə Səndən yaxşılıq və təqva istəyirik.","en":"O Allah, we ask You in this journey of ours for righteousness and piety.","ru":"О Аллах, мы просим Тебя в этом нашем путешествии о благочестии и богобоязненности.","tr":"Allah\\'ım, bu seferimizde Senden birr ve takva isteriz.","ar":"اللَّهُمَّ إِنَّا نَسْأَلُكَ فِي سَفَرِنَا هَذَا الْبِرَّ وَالتَّقْوَى"},"src":{"az":"Muslim 1342","en":"Muslim 1342","ru":"Муслим 1342","tr":"Müslim 1342","ar":"مسلم 1342"}},{"id":1061,"t":{"az":"Allahım, faydalı yağış yağdır.","en":"O Allah, let it be a beneficial rain.","ru":"О Аллах, пошли нам полезный дождь.","tr":"Allah\\'ım, faydalı bir yağmur yağdır.","ar":"اللَّهُمَّ صَيِّبًا نَافِعًا"},"src":{"az":"Buxari 1032","en":"Bukhari 1032","ru":"Бухари 1032","tr":"Buhârî 1032","ar":"البخاري 1032"}},{"id":1062,"t":{"az":"Allahın lütfü və rəhməti ilə yağış yağdırıldıq.","en":"We have been given rain by the grace and mercy of Allah.","ru":"Нам был дарован дождь по милости и милосердию Аллаха.","tr":"Allah\\'ın lütfu ve rahmetiyle yağmura kavuştuk.","ar":"مُطِرْنَا بِفَضْلِ اللَّهِ وَرَحْمَتِهِ"},"src":{"az":"Buxari 1038","en":"Bukhari 1038","ru":"Бухари 1038","tr":"Buhârî 1038","ar":"البخاري 1038"}},{"id":1063,"t":{"az":"Yatağına gələndə namaz dəstəmazı kimi dəstəmaz al, sonra sağ tərəfinə uzan.","en":"When you go to bed, perform ablution as for prayer, then lie on your right side.","ru":"Когда ложишься спать, соверши омовение как для молитвы, затем ляг на правый бок.","tr":"Yatağına geldiğinde namaz abdesti gibi abdest al, sonra sağ tarafına uzan.","ar":"إِذَا أَتَيْتَ مَضْجَعَكَ فَتَوَضَّأْ وُضُوءَكَ لِلصَّلاَةِ ثُمَّ اضْطَجِعْ عَلَى شِقِّكَ الأَيْمَنِ"},"src":{"az":"Buxari 247","en":"Bukhari 247","ru":"Бухари 247","tr":"Buhârî 247","ar":"البخاري 247"}},{"id":1064,"t":{"az":"Allahım, Sənin adınla ölür və dirilirim.","en":"In Your name, O Allah, I die and I live.","ru":"С именем Твоим, о Аллах, я умираю и живу.","tr":"Allah\\'ım, Senin adınla ölür ve dirilirim.","ar":"بِاسْمِكَ اللَّهُمَّ أَمُوتُ وَأَحْيَا"},"src":{"az":"Buxari 6324","en":"Bukhari 6324","ru":"Бухари 6324","tr":"Buhârî 6324","ar":"البخاري 6324"}},{"id":1065,"t":{"az":"Rəbbim, Sənin adınla yanımı qoydum və Səninlə qaldıracağam.","en":"In Your name, my Lord, I lay my side and by You I raise it.","ru":"С именем Твоим, Господь мой, я положил бок и с Тобой подниму его.","tr":"Rabbim, Senin adınla yanımı koydum ve Seninle kaldıracağım.","ar":"بِاسْمِكَ رَبِّي وَضَعْتُ جَنْبِي وَبِكَ أَرْفَعُهُ"},"src":{"az":"Buxari 6320","en":"Bukhari 6320","ru":"Бухари 6320","tr":"Buhârî 6320","ar":"البخاري 6320"}},{"id":1066,"t":{"az":"Allahın adını çək, sağ əlinlə ye və önündəkindən ye.","en":"Say the name of Allah, eat with your right hand, and eat from what is nearest to you.","ru":"Произнеси имя Аллаха, ешь правой рукой и ешь то, что ближе к тебе.","tr":"Allah\\'ın adını an, sağ elinle ye ve önündekinden ye.","ar":"سَمِّ اللَّهَ وَكُلْ بِيَمِينِكَ وَكُلْ مِمَّا يَلِيكَ"},"src":{"az":"Buxari 5376","en":"Bukhari 5376","ru":"Бухари 5376","tr":"Buhârî 5376","ar":"البخاري 5376"}},{"id":1067,"t":{"az":"Adəm oğlu mədəsindən daha pis bir qab doldurmamışdır.","en":"The son of Adam does not fill a vessel worse than his stomach.","ru":"Сын Адама не наполнял сосуда хуже, чем свой желудок.","tr":"Âdemoğlu, midesinden daha kötü bir kap doldurmamıştır.","ar":"مَا مَلأَ آدَمِيٌّ وِعَاءً شَرًّا مِنْ بَطْنٍ"},"src":{"az":"Tirmizi 2380","en":"Tirmidhi 2380","ru":"Тирмизи 2380","tr":"Tirmizî 2380","ar":"الترمذي 2380"}},{"id":1069,"t":{"az":"Ağ paltar geyin, çünki o paltarlarınızın ən xeyirlisidir.","en":"Wear white garments, for they are among the best of your clothes.","ru":"Носите белую одежду, ибо она лучшая из ваших одежд.","tr":"Beyaz elbise giyin, çünkü elbiselerinizin en hayırlısıdır.","ar":"الْبَسُوا الْبَيَاضَ مِنْ ثِيَابِكُمْ فَإِنَّهَا مِنْ خَيْرِ ثِيَابِكُمْ"},"src":{"az":"Tirmizi 994","en":"Tirmidhi 994","ru":"Тирмизи 994","tr":"Tirmizî 994","ar":"الترمذي 994"}},{"id":1070,"t":{"az":"Allahım, bunun xeyirini və bunun üçün hazırlananın xeyirini Səndən istəyirəm.","en":"O Allah, I ask You for its goodness and the goodness for which it was made.","ru":"О Аллах, я прошу Тебя о благе этой одежды и благе того, для чего она создана.","tr":"Allah\\'ım, bunun hayrını ve bunun için yapılanın hayrını Senden isterim.","ar":"اللَّهُمَّ إِنِّي أَسْأَلُكَ خَيْرَهُ وَخَيْرَ مَا صُنِعَ لَهُ"},"src":{"az":"Əbu Davud 4020","en":"Abu Dawud 4020","ru":"Абу Дауд 4020","tr":"Ebû Dâvûd 4020","ar":"أبو داود 4020"}},{"id":1072,"t":{"az":"Qadın dörd şeyə görə alınır: malına, soyuna, gözəlliyinə və dininə. Dindar olanı seç.","en":"A woman is married for four things: wealth, lineage, beauty, and religion. Choose the religious one.","ru":"На женщине женятся ради четырёх вещей: богатства, происхождения, красоты и религии. Выбирай религиозную.","tr":"Kadın dört şey için nikâhlanır: malı, soyu, güzelliği ve dini. Sen dindar olanı seç.","ar":"تُنْكَحُ الْمَرْأَةُ لأَرْبَعٍ لِمَالِهَا وَلِحَسَبِهَا وَلِجَمَالِهَا وَلِدِينِهَا فَاظْفَرْ بِذَاتِ الدِّينِ"},"src":{"az":"Buxari 5090","en":"Bukhari 5090","ru":"Бухари 5090","tr":"Buhârî 5090","ar":"البخاري 5090"}},{"id":1073,"t":{"az":"Allah sənə bərəkət versin, sənin üzərinə bərəkət endirsin və ikinizi xeyirdə birləşdirsin.","en":"May Allah bless you and bestow blessings upon you, and unite you both in goodness.","ru":"Да благословит тебя Аллах, да ниспошлёт благословение на тебя и соединит вас обоих в благе.","tr":"Allah sana bereket versin, üzerine bereket indirsin ve ikinizi hayırda birleştirsin.","ar":"بَارَكَ اللَّهُ لَكَ وَبَارَكَ عَلَيْكَ وَجَمَعَ بَيْنَكُمَا فِي خَيْرٍ"},"src":{"az":"Tirmizi 1091","en":"Tirmidhi 1091","ru":"Тирмизи 1091","tr":"Tirmizî 1091","ar":"الترمذي 1091"}},{"id":1076,"t":{"az":"Qeybin nə olduğunu bilirsinizmi? Qardaşını xoşlamadığı şeylə xatırlamaqdır.","en":"Do you know what backbiting is? It is mentioning your brother with what he dislikes.","ru":"Знаете ли вы, что такое злословие? Это когда ты упоминаешь о брате то, что ему неприятно.","tr":"Gıybetin ne olduğunu biliyor musunuz? Kardeşini hoşlanmadığı şeyle anmandır.","ar":"أَتَدْرُونَ مَا الْغِيبَةُ ذِكْرُكَ أَخَاكَ بِمَا يَكْرَهُ"},"src":{"az":"Muslim 2589","en":"Muslim 2589","ru":"Муслим 2589","tr":"Müslim 2589","ar":"مسلم 2589"}},{"id":1077,"t":{"az":"Ey dili ilə iman edib qəlbinə iman daxil olmayanlar, müsəlmanların qeybətini etməyin.","en":"O you who believe with your tongues but faith has not entered your hearts, do not backbite Muslims.","ru":"О те, кто уверовал языком, но вера не вошла в сердце, не злословьте о мусульманах.","tr":"Ey diliyle iman edip kalplerine iman girmeyen topluluk, Müslümanları gıybet etmeyin.","ar":"يَا مَعْشَرَ مَنْ آمَنَ بِلِسَانِهِ وَلَمْ يَدْخُلِ الإِيمَانُ قَلْبَهُ لَا تَغْتَابُوا الْمُسْلِمِينَ"},"src":{"az":"Əbu Davud 4880","en":"Abu Dawud 4880","ru":"Абу Дауд 4880","tr":"Ebû Dâvûd 4880","ar":"أبو داود 4880"}},{"id":1079,"t":{"az":"Allah gecə əlini açar ki, gündüz günah edən tövbə etsin, gündüz əlini açar ki, gecə günah edən tövbə etsin.","en":"Allah extends His hand at night for the sinner of the day to repent, and extends His hand by day for the sinner of the night to repent.","ru":"Аллах простирает руку ночью, чтобы согрешивший днём покаялся, и простирает руку днём, чтобы согрешивший ночью покаялся.","tr":"Allah, gündüz günah işleyenin tövbe etmesi için geceleyin elini açar; gece günah işleyenin tövbe etmesi için gündüz elini açar.","ar":"إِنَّ اللَّهَ يَبْسُطُ يَدَهُ بِاللَّيْلِ لِيَتُوبَ مُسِيءُ النَّهَارِ وَيَبْسُطُ يَدَهُ بِالنَّهَارِ لِيَتُوبَ مُسِيءُ اللَّيْلِ"},"src":{"az":"Muslim 2759","en":"Muslim 2759","ru":"Муслим 2759","tr":"Müslim 2759","ar":"مسلم 2759"}},{"id":1080,"t":{"az":"Allahın qulunun tövbəsinə sevinci, səhrada dəvəsini itirən sonra tapan adamın sevincindən böyükdür.","en":"Allah is more delighted with the repentance of His servant than one of you who finds his lost camel in a desert.","ru":"Аллах радуется покаянию Своего раба больше, чем один из вас, нашедший потерянного верблюда в пустыне.","tr":"Allah, kulunun tövbesine, çölde devesini kaybedip sonra bulan birinizden daha çok sevinir.","ar":"لَلَّهُ أَشَدُّ فَرَحًا بِتَوْبَةِ عَبْدِهِ مِنْ أَحَدِكُمْ سَقَطَ عَلَى بَعِيرِهِ وَقَدْ أَضَلَّهُ فِي أَرْضِ فَلاَةٍ"},"src":{"az":"Muslim 2747","en":"Muslim 2747","ru":"Муслим 2747","tr":"Müslim 2747","ar":"مسلم 2747"}},{"id":1081,"t":{"az":"Allaha layiqincə təvəkkül etsəydiniz, sizi quşları ruzilədəndiyi kimi ruziləndirərdi: ac gedər, tox qayıdar.","en":"If you relied on Allah with true reliance, He would provide for you as He provides for birds — they go out hungry and return full.","ru":"Если бы вы уповали на Аллаха истинным упованием, Он кормил бы вас, как кормит птиц — выходят голодными, возвращаются сытыми.","tr":"Allah\\'a hakkıyla tevekkül etseydiniz, sizi kuşları rızıklandırdığı gibi rızıklandırırdı: aç giderler, tok dönerler.","ar":"لَوْ أَنَّكُمْ تَتَوَكَّلُونَ عَلَى اللَّهِ حَقَّ تَوَكُّلِهِ لَرَزَقَكُمْ كَمَا يَرْزُقُ الطَّيْرَ تَغْدُو خِمَاصًا وَتَرُوحُ بِطَانًا"},"src":{"az":"Tirmizi 2344","en":"Tirmidhi 2344","ru":"Тирмизи 2344","tr":"Tirmizî 2344","ar":"الترمذي 2344"}},{"id":1083,"t":{"az":"Elm azalmadıqca, zəlzələlər çoxalmadıqca Qiyamət qopmaz.","en":"The Hour will not come until knowledge is taken away and earthquakes increase.","ru":"Час не наступит, пока не будет забрано знание и не участятся землетрясения.","tr":"İlim azalmadıkça, depremler çoğalmadıkça kıyamet kopmaz.","ar":"لاَ تَقُومُ السَّاعَةُ حَتَّى يُقْبَضَ الْعِلْمُ وَتَكْثُرَ الزَّلاَزِلُ"},"src":{"az":"Buxari 1036","en":"Bukhari 1036","ru":"Бухари 1036","tr":"Buhârî 1036","ar":"البخاري 1036"}},{"id":1084,"t":{"az":"Qaranlıq gecə parçaları kimi fitnələrdən əvvəl əməllərə tələsin.","en":"Hasten to do good deeds before tribulations come like pieces of a dark night.","ru":"Спешите с делами до смут, подобных кускам тёмной ночи.","tr":"Karanlık gece parçaları gibi fitneler gelmeden amellere koşun.","ar":"بَادِرُوا بِالأَعْمَالِ فِتَنًا كَقِطَعِ اللَّيْلِ الْمُظْلِمِ"},"src":{"az":"Muslim 118","en":"Muslim 118","ru":"Муслим 118","tr":"Müslim 118","ar":"مسلم 118"}},{"id":1085,"t":{"az":"Adəmin yaradılışından Qiyamətə qədər Dəccaldan böyük bir iş yoxdur.","en":"From the creation of Adam until the Hour, there is no matter greater than the Dajjal.","ru":"От сотворения Адама до Часа нет ничего более великого, чем Даджаль.","tr":"Âdem\\'in yaratılışından kıyamete kadar Deccal\\'dan büyük bir hadise yoktur.","ar":"مَا بَيْنَ خَلْقِ آدَمَ إِلَى قِيَامِ السَّاعَةِ أَمْرٌ أَكْبَرُ مِنَ الدَّجَّالِ"},"src":{"az":"Muslim 2946","en":"Muslim 2946","ru":"Муслим 2946","tr":"Müslim 2946","ar":"مسلم 2946"}},{"id":1087,"t":{"az":"Qiyamət günü yer ilk olaraq mənim üstümdən yarılacaq.","en":"I am the first for whom the earth will split open on the Day of Resurrection.","ru":"Я первый, над кем разверзнется земля в День Воскресения.","tr":"Kıyamet günü yer ilk olarak benim üzerimden yarılacaktır.","ar":"أَنَا أَوَّلُ مَنْ تَنْشَقُّ عَنْهُ الأَرْضُ يَوْمَ الْقِيَامَةِ"},"src":{"az":"Muslim 2278","en":"Muslim 2278","ru":"Муслим 2278","tr":"Müslim 2278","ar":"مسلم 2278"}},{"id":1088,"t":{"az":"Mən Qiyamət günü Adəm oğlunun əfəndisiyəm, qəbri ilk açılan, ilk şəfaət edən və ilk şəfaəti qəbul olunanam.","en":"I am the master of the children of Adam on the Day of Judgment, the first to be resurrected, the first to intercede, and the first whose intercession is accepted.","ru":"Я — господин сынов Адама в День Суда, первый, кто воскреснет, первый заступник и первый, чьё заступничество будет принято.","tr":"Ben Kıyamet günü Âdemoğlunun efendisiyim, kabri ilk açılan, ilk şefaat eden ve ilk şefaati kabul edilenim.","ar":"أَنَا سَيِّدُ وَلَدِ آدَمَ يَوْمَ الْقِيَامَةِ وَأَوَّلُ مَنْ يَنْشَقُّ عَنْهُ الْقَبْرُ وَأَوَّلُ شَافِعٍ وَأَوَّلُ مُشَفَّعٍ"},"src":{"az":"Muslim 2278","en":"Muslim 2278","ru":"Муслим 2278","tr":"Müslim 2278","ar":"مسلم 2278"}},{"id":1090,"t":{"az":"Cənnətdə elə bir ağac var ki, atlı onun kölgəsində yüz il getsə belə onu kəsib keçə bilməz.","en":"In Paradise there is a tree under whose shade a rider would travel for a hundred years without passing it.","ru":"В Раю есть дерево, в тени которого всадник скачет сто лет, не выходя из неё.","tr":"Cennette bir ağaç vardır ki, atlı gölgesinde yüz yıl gitse onu geçemez.","ar":"إِنَّ فِي الْجَنَّةِ شَجَرَةً يَسِيرُ الرَّاكِبُ فِي ظِلِّهَا مِائَةَ عَامٍ لاَ يَقْطَعُهَا"},"src":{"az":"Buxari 3251","en":"Bukhari 3251","ru":"Бухари 3251","tr":"Buhârî 3251","ar":"البخاري 3251"}},{"id":1094,"t":{"az":"Allah bir qulu sevdikdə Cəbraildən onu sevməsini istəyər.","en":"When Allah loves a servant, He calls Jibreel and says: I love so-and-so, so love him.","ru":"Когда Аллах любит раба, Он зовёт Джибриля: Аллах любит такого-то, полюби его.","tr":"Allah bir kulu sevdiğinde Cebrail\\'e seslenir: Allah falanı seviyor, onu sev.","ar":"إِذَا أَحَبَّ اللَّهُ عَبْدًا نَادَى جِبْرِيلَ إِنَّ اللَّهَ يُحِبُّ فُلاَنًا فَأَحِبَّهُ"},"src":{"az":"Buxari 3209","en":"Bukhari 3209","ru":"Бухари 3209","tr":"Buhârî 3209","ar":"البخاري 3209"}},{"id":1096,"t":{"az":"Bil ki, sənə çatan şey səni ötüb keçə bilməzdi, səni ötüb keçən şey sənə çata bilməzdi.","en":"Know that what has reached you was not going to miss you, and what missed you was not going to reach you.","ru":"Знай: то, что тебя постигло, не могло миновать тебя, а то, что миновало, не могло постигнуть.","tr":"Bil ki, sana isabet eden seni es geçecek değildi; seni es geçen de sana isabet edecek değildi.","ar":"وَاعْلَمْ أَنَّ مَا أَصَابَكَ لَمْ يَكُنْ لِيُخْطِئَكَ وَمَا أَخْطَأَكَ لَمْ يَكُنْ لِيُصِيبَكَ"},"src":{"az":"Tirmizi 2144","en":"Tirmidhi 2144","ru":"Тирмизи 2144","tr":"Tirmizî 2144","ar":"الترمذي 2144"}},{"id":1097,"t":{"az":"Qələmlər qaldırılmış və səhifələr qurumuşdur.","en":"The pens have been lifted and the pages have dried.","ru":"Перья подняты и страницы высохли.","tr":"Kalemler kaldırılmış ve sayfalar kurumuştur.","ar":"رُفِعَتِ الأَقْلاَمُ وَجَفَّتِ الصُّحُفُ"},"src":{"az":"Tirmizi 2516","en":"Tirmidhi 2516","ru":"Тирмизи 2516","tr":"Tirmizî 2516","ar":"الترمذي 2516"}},{"id":1100,"t":{"az":"Biriniz yatağına uzandığında izarının iç tərəfi ilə yatağını silkələsin.","en":"When one of you goes to bed, let him dust off his bed with the inside of his garment.","ru":"Когда один из вас ложится в постель, пусть стряхнёт её краем одежды.","tr":"Biriniz yatağına uzandığında, elbisesinin iç tarafıyla yatağını silkelesin.","ar":"إِذَا أَوَى أَحَدُكُمْ إِلَى فِرَاشِهِ فَلْيَنْفُضْ فِرَاشَهُ بِدَاخِلَةِ إِزَارِهِ"},"src":{"az":"Buxari 6320","en":"Bukhari 6320","ru":"Бухари 6320","tr":"Buhârî 6320","ar":"البخاري 6320"}},{"id":1101,"t":{"az":"Allahım, mənə rəhmət qapılarını aç.","en":"O Allah, open for me the gates of Your mercy.","ru":"О Аллах, открой для меня врата Твоей милости.","tr":"Allah\\'ım, bana rahmet kapılarını aç.","ar":"اللَّهُمَّ افْتَحْ لِي أَبْوَابَ رَحْمَتِكَ"},"src":{"az":"Muslim 713","en":"Muslim 713","ru":"Муслим 713","tr":"Müslim 713","ar":"مسلم 713"}},{"id":1102,"t":{"az":"Allahım, Səndən fəzlini istəyirəm.","en":"O Allah, I ask You of Your bounty.","ru":"О Аллах, я прошу Тебя о Твоей щедрости.","tr":"Allah\\'ım, Senden fazlını isterim.","ar":"اللَّهُمَّ إِنِّي أَسْأَلُكَ مِنْ فَضْلِكَ"},"src":{"az":"Muslim 713","en":"Muslim 713","ru":"Муслим 713","tr":"Müslim 713","ar":"مسلم 713"}},{"id":1112,"t":{"az":"Aşura günü orucunun əvvəlki ilin günahlarına kəffarə olacağını Allahdan umuram.","en":"Fasting the day of Ashura — I hope Allah will expiate the sins of the year before it.","ru":"Пост в день Ашура — я надеюсь, что Аллах искупит грехи прошлого года.","tr":"Aşure günü orucunun, önceki yılın günahlarına kefaret olacağını Allah\\'tan umarım.","ar":"صِيَامُ يَوْمِ عَاشُورَاءَ أَحْتَسِبُ عَلَى اللَّهِ أَنْ يُكَفِّرَ السَّنَةَ الَّتِي قَبْلَهُ"},"src":{"az":"Muslim 1162","en":"Muslim 1162","ru":"Муслим 1162","tr":"Müslim 1162","ar":"مسلم 1162"}},{"id":1113,"t":{"az":"Kim Ərəfə günü oruc tutarsa, əvvəlki və sonrakı ilin günahları bağışlanar.","en":"Whoever fasts the day of Arafah, his sins of the previous and following year will be forgiven.","ru":"Кто постится в день Арафа, тому простятся грехи прошлого и следующего года.","tr":"Kim Arefe günü oruç tutarsa, önceki ve sonraki yılın günahları bağışlanır.","ar":"مَنْ صَامَ يَوْمَ عَرَفَةَ غُفِرَ لَهُ سَنَةٌ أَمَامَهُ وَسَنَةٌ خَلْفَهُ"},"src":{"az":"Muslim 1162","en":"Muslim 1162","ru":"Муслим 1162","tr":"Müslim 1162","ar":"مسلم 1162"}},{"id":1114,"t":{"az":"Allaha ən sevimli oruc Davudun orucudur: bir gün tutar, bir gün tutmazdı.","en":"The most beloved fasting to Allah is the fasting of David: he fasted one day and broke his fast the next.","ru":"Самый любимый Аллахом пост — пост Давида: он постился через день.","tr":"Allah\\'a en sevimli oruç Davud\\'un orucudur: bir gün tutar, bir gün tutmazdı.","ar":"أَحَبُّ الصِّيَامِ إِلَى اللَّهِ صِيَامُ دَاوُدَ كَانَ يَصُومُ يَوْمًا وَيُفْطِرُ يَوْمًا"},"src":{"az":"Buxari 1131","en":"Bukhari 1131","ru":"Бухари 1131","tr":"Buhârî 1131","ar":"البخاري 1131"}},{"id":1139,"t":{"az":"Bir müsəlmanın qardaşı ilə üç gecədən artıq küsülü qalması halal deyil.","en":"It is not permissible for a Muslim to shun his brother for more than three nights.","ru":"Мусульманину нельзя бойкотировать брата более трёх ночей.","tr":"Bir Müslümanın kardeşiyle üç geceden fazla küs kalması helal değildir.","ar":"لاَ يَحِلُّ لِمُسْلِمٍ أَنْ يَهْجُرَ أَخَاهُ فَوْقَ ثَلاَثِ لَيَالٍ"},"src":{"az":"Buxari 6077","en":"Bukhari 6077","ru":"Бухари 6077","tr":"Buhârî 6077","ar":"البخاري 6077"}},{"id":1141,"t":{"az":"Məzlumun duasından çəkinin, çünki onunla Allah arasında pərdə yoxdur.","en":"Fear the supplication of the oppressed, for there is no veil between it and Allah.","ru":"Бойтесь мольбы угнетённого, ибо между ней и Аллахом нет преграды.","tr":"Mazlumun duasından sakının, çünkü onunla Allah arasında perde yoktur.","ar":"اتَّقُوا دَعْوَةَ الْمَظْلُومِ فَإِنَّهَا لَيْسَ بَيْنَهَا وَبَيْنَ اللَّهِ حِجَابٌ"},"src":{"az":"Buxari 1496","en":"Bukhari 1496","ru":"Бухари 1496","tr":"Buhârî 1496","ar":"البخاري 1496"}},{"id":1142,"t":{"az":"Qardaşına zalım da olsa, məzlum da olsa kömək et.","en":"Help your brother whether he is an oppressor or oppressed.","ru":"Помоги своему брату, будь он притеснителем или притеснённым.","tr":"Kardeşine zalim de olsa mazlum da olsa yardım et.","ar":"انْصُرْ أَخَاكَ ظَالِمًا أَوْ مَظْلُومًا"},"src":{"az":"Buxari 2444","en":"Bukhari 2444","ru":"Бухари 2444","tr":"Buhârî 2444","ar":"البخاري 2444"}},{"id":1147,"t":{"az":"Möminlər sevgi və rəhmdə bir bədən kimidirlər.","en":"The believers in their mutual love and compassion are like one body.","ru":"Верующие в их взаимной любви и сострадании подобны одному телу.","tr":"Müminler sevgi ve merhamette bir beden gibidirler.","ar":"مَثَلُ الْمُؤْمِنِينَ فِي تَوَادِّهِمْ وَتَرَاحُمِهِمْ كَمَثَلِ الْجَسَدِ"},"src":{"az":"Muslim 2586","en":"Muslim 2586","ru":"Муслим 2586","tr":"Müslim 2586","ar":"مسلم 2586"}},{"id":1156,"t":{"az":"Qızıl və gümüşün haqqını verməyənin Qiyamət günü oddan lövhələr qızdırılacaq.","en":"No owner of gold or silver who does not pay their due right except on the Day of Judgment plates of fire will be heated for him.","ru":"Кто владеет золотом и серебром и не выплачивает должное — в День Суда для него раскалят пластины из огня.","tr":"Altın ve gümüşün hakkını vermeyen kişi için Kıyamet günü ateşten levhalar kızdırılacaktır.","ar":"مَا مِنْ صَاحِبِ ذَهَبٍ وَلاَ فِضَّةٍ لاَ يُؤَدِّي مِنْهَا حَقَّهَا إِلاَّ إِذَا كَانَ يَوْمُ الْقِيَامَةِ صُفِّحَتْ لَهُ صَفَائِحُ مِنْ نَارٍ"},"src":{"az":"Muslim 987","en":"Muslim 987","ru":"Муслим 987","tr":"Müslim 987","ar":"مسلم 987"}},{"id":1160,"t":{"az":"Dünyanın ən rahat yaşayan cəhənnəm əhli gətirilər, bir dəfə oda batırılar.","en":"The most affluent person of Hell\\'s people will be dipped once in the Fire.","ru":"Самого благополучного из обитателей ада окунут в огонь один раз.","tr":"Dünya ehlinden cehennem ehlinin en nimetlisi getirilip bir kere ateşe daldırılır.","ar":"يُؤْتَى بِأَنْعَمِ أَهْلِ الدُّنْيَا مِنْ أَهْلِ النَّارِ يَوْمَ الْقِيَامَةِ فَيُصْبَغُ فِي النَّارِ صَبْغَةً"},"src":{"az":"Muslim 2807","en":"Muslim 2807","ru":"Муслим 2807","tr":"Müslim 2807","ar":"مسلم 2807"}},{"id":1165,"t":{"az":"Kim məscidə gedir-gəlirsə, Allah ona hər gedişində cənnətdə bir ziyafət hazırlayar.","en":"Whoever goes to the mosque in the morning or evening, Allah prepares hospitality for him in Paradise each time.","ru":"Кто ходит в мечеть утром или вечером, Аллах готовит ему угощение в Раю каждый раз.","tr":"Kim mescide sabah veya akşam gidip gelirse, Allah her gidişinde ona cennette bir ziyafet hazırlar.","ar":"مَنْ غَدَا إِلَى الْمَسْجِدِ أَوْ رَاحَ أَعَدَّ اللَّهُ لَهُ فِي الْجَنَّةِ نُزُلاً كُلَّمَا غَدَا أَوْ رَاحَ"},"src":{"az":"Buxari 662","en":"Bukhari 662","ru":"Бухари 662","tr":"Buhârî 662","ar":"البخاري 662"}},{"id":1167,"t":{"az":"Hər gün fərzdən başqa on iki rükət nafilə qılan müsəlmana Allah cənnətdə ev tikər.","en":"No Muslim servant prays twelve voluntary units daily besides the obligatory except Allah builds for him a house in Paradise.","ru":"Мусульманин, совершающий ежедневно двенадцать добровольных ракаатов помимо обязательных — Аллах построит ему дом в Раю.","tr":"Farzın dışında her gün on iki rekât nafile kılan Müslüman kula Allah cennette bir ev inşa eder.","ar":"مَا مِنْ عَبْدٍ مُسْلِمٍ يُصَلِّي لِلَّهِ كُلَّ يَوْمٍ ثِنْتَيْ عَشْرَةَ رَكْعَةً تَطَوُّعًا غَيْرَ فَرِيضَةٍ إِلاَّ بَنَى اللَّهُ لَهُ بَيْتًا فِي الْجَنَّةِ"},"src":{"az":"Muslim 728","en":"Muslim 728","ru":"Муслим 728","tr":"Müslim 728","ar":"مسلم 728"}},{"id":1170,"t":{"az":"Allaha və Axirət gününə iman edən qonşusuna yaxşılıq etsin.","en":"Whoever believes in Allah and the Last Day, let him be good to his neighbor.","ru":"Кто верит в Аллаха и Последний День — пусть хорошо относится к соседу.","tr":"Allah\\'a ve ahiret gününe iman eden komşusuna iyilik etsin.","ar":"مَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الآخِرِ فَلْيُحْسِنْ إِلَى جَارِهِ"},"src":{"az":"Muslim 47","en":"Muslim 47","ru":"Муслим 47","tr":"Müslim 47","ar":"مسلم 47"}},{"id":1174,"t":{"az":"Əməllər niyyətlərə görədir, hər kəsə niyyət etdiyi şey qalır.","en":"Actions are judged by intentions, and everyone will be rewarded according to what he intended.","ru":"Дела оцениваются по намерениям, и каждому — то, что он намеревался.","tr":"Ameller niyetlere göredir, herkese niyet ettiği şey vardır.","ar":"إِنَّمَا الأَعْمَالُ بِالنِّيَّاتِ وَإِنَّمَا لِكُلِّ امْرِئٍ مَا نَوَى"},"src":{"az":"Buxari 1","en":"Bukhari 1","ru":"Бухари 1","tr":"Buhârî 1","ar":"البخاري 1"}},{"id":1175,"t":{"az":"Kim bu işimizə (dinimizə) onda olmayan bir şey əlavə edərsə, o rədd olunur.","en":"Whoever introduces into this matter of ours what is not part of it, it is rejected.","ru":"Кто привнесёт в наше дело то, что к нему не относится — оно будет отвергнуто.","tr":"Kim bu işimize (dinimize) onda olmayan bir şey icat ederse, o reddedilir.","ar":"مَنْ أَحْدَثَ فِي أَمْرِنَا هَذَا مَا لَيْسَ مِنْهُ فَهُوَ رَدٌّ"},"src":{"az":"Buxari 2697","en":"Bukhari 2697","ru":"Бухари 2697","tr":"Buhârî 2697","ar":"البخاري 2697"}},{"id":1177,"t":{"az":"Məscidimdə bir namaz başqa məscidlərdə qılınan min namazdan xeyirlidir, Məscidul-Haram istisna olmaqla.","en":"A prayer in my mosque is better than a thousand prayers in any other mosque except Al-Masjid Al-Haram.","ru":"Молитва в моей мечети лучше тысячи молитв в любой другой, кроме Заповедной мечети.","tr":"Mescidimde kılınan bir namaz, Mescid-i Haram hariç başka mescitlerde kılınan bin namazdan daha hayırlıdır.","ar":"صَلاَةٌ فِي مَسْجِدِي هَذَا خَيْرٌ مِنْ أَلْفِ صَلاَةٍ فِيمَا سِوَاهُ إِلاَّ الْمَسْجِدَ الْحَرَامَ"},"src":{"az":"Buxari 1190","en":"Bukhari 1190","ru":"Бухари 1190","tr":"Buhârî 1190","ar":"البخاري 1190"}},{"id":1180,"t":{"az":"Kim zöhrdən əvvəl dörd, sonra dörd rükət qılmağa davam edərsə, Allah onu oda haram edər.","en":"Whoever consistently prays four before Dhuhr and four after it, Allah will forbid the Fire for him.","ru":"Кто постоянно совершает четыре ракаата до зухра и четыре после — Аллах запретит ему огонь.","tr":"Kim öğleden önce dört, sonra dört rekât kılmaya devam ederse, Allah onu ateşe haram kılar.","ar":"مَنْ حَافَظَ عَلَى أَرْبَعِ رَكَعَاتٍ قَبْلَ الظُّهْرِ وَأَرْبَعٍ بَعْدَهَا حَرَّمَهُ اللَّهُ عَلَى النَّارِ"},"src":{"az":"Tirmizi 428","en":"Tirmidhi 428","ru":"Тирмизи 428","tr":"Tirmizî 428","ar":"الترمذي 428"}},{"id":1188,"t":{"az":"Gözəl söz sədəqədir.","en":"A good word is charity.","ru":"Доброе слово — милостыня.","tr":"Güzel söz sadakadır.","ar":"الْكَلِمَةُ الطَّيِّبَةُ صَدَقَةٌ"},"src":{"az":"Buxari 2989","en":"Bukhari 2989","ru":"Бухари 2989","tr":"Buhârî 2989","ar":"البخاري 2989"}},{"id":1192,"t":{"az":"Allahı məxluqatının sayı, Özünün razılığı, ərşinin ağırlığı və kəlmələrinin müddəti qədər təsbih edirəm.","en":"Glory be to Allah and His praise, by the number of His creation, His pleasure, the weight of His Throne, and the extent of His words.","ru":"Пречист Аллах, и хвала Ему — по числу Его творений, Его довольству, весу Его Трона и бесконечности Его слов.","tr":"Allah\\'ı mahlûkatının sayısı, kendisinin rızası, arşının ağırlığı ve kelimelerinin mürekkebi kadar tespih ederim.","ar":"سُبْحَانَ اللَّهِ وَبِحَمْدِهِ عَدَدَ خَلْقِهِ وَرِضَا نَفْسِهِ وَزِنَةَ عَرْشِهِ وَمِدَادَ كَلِمَاتِهِ"},"src":{"az":"Muslim 2726","en":"Muslim 2726","ru":"Муслим 2726","tr":"Müslim 2726","ar":"مسلم 2726"}},{"id":1194,"t":{"az":"Sizdən kim bir pislik görsə, onu əli ilə dəyişdirsin; bacarmasa dili ilə, bacarmasa qəlbi ilə.","en":"Whoever among you sees an evil, let him change it with his hand; if unable, then with his tongue; if unable, then with his heart.","ru":"Кто из вас увидит зло — пусть изменит его рукой; если не может — языком; если не может — сердцем.","tr":"Sizden kim bir kötülük görürse onu eliyle değiştirsin; gücü yetmezse diliyle, yetmezse kalbiyle.","ar":"مَنْ رَأَى مِنْكُمْ مُنْكَرًا فَلْيُغَيِّرْهُ بِيَدِهِ فَإِنْ لَمْ يَسْتَطِعْ فَبِلِسَانِهِ فَإِنْ لَمْ يَسْتَطِعْ فَبِقَلْبِهِ"},"src":{"az":"Muslim 49","en":"Muslim 49","ru":"Муслим 49","tr":"Müslim 49","ar":"مسلم 49"}},{"id":1196,"t":{"az":"Sahur yeməyi bərəkətdir, onu tərk etməyin.","en":"The pre-dawn meal is blessed, so do not leave it.","ru":"Предрассветная трапеза благословенна, не оставляйте её.","tr":"Sahur yemeği berekettir, onu bırakmayın.","ar":"السَّحُورُ أَكْلُهُ بَرَكَةٌ فَلاَ تَدَعُوهُ"},"src":{"az":"Əhməd 11086","en":"Ahmad 11086","ru":"Ахмад 11086","tr":"Ahmed 11086","ar":"أحمد 11086"}},{"id":1198,"t":{"az":"Allahın rizası üçün xərclədiklərin sənə savab qazandırar, hətta arvadının ağzına qoyduğun loğma belə.","en":"You will be rewarded for anything you spend for the sake of Allah, even the morsel you put in your wife\\'s mouth.","ru":"Ты будешь вознаграждён за всё, что потратишь ради Аллаха, даже за кусочек, который положишь в рот жены.","tr":"Allah rızası için harcadığın her şeyden sevap alırsın, hatta hanımının ağzına koyduğun lokmadan bile.","ar":"إِنَّكَ لَنْ تُنْفِقَ نَفَقَةً تَبْتَغِي بِهَا وَجْهَ اللَّهِ إِلاَّ أُجِرْتَ بِهَا حَتَّى مَا تَجْعَلُ فِي فِي امْرَأَتِكَ"},"src":{"az":"Buxari 56","en":"Bukhari 56","ru":"Бухари 56","tr":"Buhârî 56","ar":"البخاري 56"}},{"id":1204,"t":{"az":"Kim namazdan sonra 33 dəfə təsbih, 33 dəfə həmd, 33 dəfə təkbir desə, günahları dəniz köpüyü qədər olsa belə bağışlanar.","en":"Whoever says SubhanAllah 33 times, Alhamdulillah 33 times, and Allahu Akbar 33 times after prayer, his sins will be forgiven even if like sea foam.","ru":"Кто после молитвы скажет 33 раза Субхан Аллах, 33 раза Альхамдулиллах, 33 раза Аллаху Акбар — его грехи простятся, даже если их как морская пена.","tr":"Kim namazdan sonra 33 kere Sübhanallah, 33 kere Elhamdülillah, 33 kere Allahu Ekber derse, günahları deniz köpüğü kadar olsa bile bağışlanır.","ar":"مَنْ قَالَ سُبْحَانَ اللَّهِ ثَلاَثًا وَثَلاَثِينَ وَحَمِدَ اللَّهَ ثَلاَثًا وَثَلاَثِينَ وَكَبَّرَ اللَّهَ ثَلاَثًا وَثَلاَثِينَ"},"src":{"az":"Muslim 597","en":"Muslim 597","ru":"Муслим 597","tr":"Müslim 597","ar":"مسلم 597"}},{"id":1205,"t":{"az":"Fitnələr hasır kimi çubuq-çubuq qəlblərə ərz olunur.","en":"Trials are presented to the hearts like a mat, straw by straw.","ru":"Искушения представляются сердцам как циновка, соломинка за соломинкой.","tr":"Fitneler hasır gibi çubuk çubuk kalplere arz olunur.","ar":"تَعْرِضُ الْفِتَنُ عَلَى الْقُلُوبِ كَالْحَصِيرِ عُودًا عُودًا"},"src":{"az":"Muslim 144","en":"Muslim 144","ru":"Муслим 144","tr":"Müslim 144","ar":"مسلم 144"}},{"id":1208,"t":{"az":"İnsanlar Qiyamət günü yalınayaq, çılpaq və sünnətsiz həşr olunacaq.","en":"People will be gathered on the Day of Judgment barefoot, naked, and uncircumcised.","ru":"Люди будут собраны в День Суда босыми, нагими и необрезанными.","tr":"İnsanlar Kıyamet günü yalınayak, çıplak ve sünnetsiz haşrolunacaklardır.","ar":"يُحْشَرُ النَّاسُ يَوْمَ الْقِيَامَةِ حُفَاةً عُرَاةً غُرْلاً"},"src":{"az":"Buxari 6527","en":"Bukhari 6527","ru":"Бухари 6527","tr":"Buhârî 6527","ar":"البخاري 6527"}},{"id":1214,"t":{"az":"Qapınızın önündə bir çay olsa, gündə beş dəfə yuyunsanız, kiriniz qalarmı?","en":"If there were a river at your door and you bathed in it five times a day, would any dirt remain on you?","ru":"Если бы у ваших дверей текла река и вы купались в ней пять раз в день, остался бы на вас какой-нибудь грязь?","tr":"Kapınızın önünde bir nehir olsa, günde beş kez yıkansanız, kiriniz kalır mı?","ar":"أَرَأَيْتُمْ لَوْ أَنَّ نَهْرًا بِبَابِ أَحَدِكُمْ يَغْتَسِلُ فِيهِ كُلَّ يَوْمٍ خَمْسًا هَلْ يَبْقَى مِنْ دَرَنِهِ شَيْءٌ"},"src":{"az":"Buxari 528","en":"Bukhari 528","ru":"Бухари 528","tr":"Buhârî 528","ar":"البخاري 528"}},{"id":1217,"t":{"az":"Oruc qalxandır. Oruclunuz çirkin söz söyləməsin, cahillik etməsin.","en":"Fasting is a shield, so the fasting person should not use obscene language or act ignorantly.","ru":"Пост — это щит. Постящийся не должен сквернословить и вести себя невежественно.","tr":"Oruç kalkandır. Oruçlu çirkin söz söylemesin, cahillik etmesin.","ar":"الصِّيَامُ جُنَّةٌ فَلاَ يَرْفُثْ وَلاَ يَجْهَلْ"},"src":{"az":"Buxari 1894","en":"Bukhari 1894","ru":"Бухари 1894","tr":"Buhârî 1894","ar":"البخاري 1894"}},{"id":1225,"t":{"az":"Kim evindən çıxanda \"Bismillah, təvəkkəltu aləllah\" desə, ona yetər, qorunar, şeytan ondan uzaqlaşar.","en":"Whoever leaves his house saying \"In the name of Allah, I rely on Allah, there is no power except by Allah\" will be guided and protected.","ru":"Кто выйдет из дома со словами «Бисмиллях, таваккальту аляллах» — будет направлен и защищён.","tr":"Kim evinden çıkarken \"Bismillah, tevekkeltü alellah\" derse, hidayet edilir ve korunur.","ar":"مَنْ خَرَجَ مِنْ بَيْتِهِ فَقَالَ بِسْمِ اللَّهِ تَوَكَّلْتُ عَلَى اللَّهِ لاَ حَوْلَ وَلاَ قُوَّةَ إِلاَّ بِاللَّهِ"},"src":{"az":"Tirmizi 3426","en":"Tirmidhi 3426","ru":"Тирмизи 3426","tr":"Tirmizî 3426","ar":"الترمذي 3426"}},{"id":1228,"t":{"az":"Kim Cümə günü qüsl edib erkən gedərsə və yürüyərsə, hər addımına bir il oruc və qiyam savabı yazılar.","en":"Whoever performs ghusl on Friday, goes early walking, and does not ride, for every step is a year of fasting and prayer.","ru":"Кто совершит полное омовение в пятницу, пойдёт рано пешком — за каждый шаг год поста и молитвы.","tr":"Kim Cuma günü gusül abdesti alıp erken giderse ve yürürse, her adımına bir yıllık oruç ve namaz sevabı yazılır.","ar":"مَنْ غَسَّلَ يَوْمَ الْجُمُعَةِ وَاغْتَسَلَ ثُمَّ بَكَّرَ وَابْتَكَرَ وَمَشَى وَلَمْ يَرْكَبْ"},"src":{"az":"Tirmizi 496","en":"Tirmidhi 496","ru":"Тирмизи 496","tr":"Tirmizî 496","ar":"الترمذي 496"}},{"id":1235,"t":{"az":"Arvadına yedirtdiyin sənin üçün sədəqədir.","en":"Whatever you feed your wife is charity for you.","ru":"То, чем ты кормишь свою жену — милостыня для тебя.","tr":"Hanımına yedirdiğin senin için sadakadır.","ar":"مَا أَطْعَمْتَ زَوْجَتَكَ فَهُوَ لَكَ صَدَقَةٌ"},"src":{"az":"Buxari 56","en":"Bukhari 56","ru":"Бухари 56","tr":"Buhârî 56","ar":"البخاري 56"}},{"id":1239,"t":{"az":"Allahım, İbrahimə salavat gətirdiyin kimi Muhəmmədə və ailəsinə salavat gətir.","en":"O Allah, send blessings upon Muhammad and upon the family of Muhammad, as You sent blessings upon Ibrahim.","ru":"О Аллах, благослови Мухаммада и род Мухаммада, как Ты благословил Ибрагима.","tr":"Allah\\'ım, İbrahim\\'e salât ettiğin gibi Muhammed\\'e ve ailesine de salât et.","ar":"اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ كَمَا صَلَّيْتَ عَلَى إِبْرَاهِيمَ"},"src":{"az":"Buxari 3370","en":"Bukhari 3370","ru":"Бухари 3370","tr":"Buhârî 3370","ar":"البخاري 3370"}},{"id":1240,"t":{"az":"Allahım, meyvəmizə bərəkət ver, şəhərimizə bərəkət ver.","en":"O Allah, bless our fruits and bless our city.","ru":"О Аллах, благослови наши плоды и благослови наш город.","tr":"Allah\\'ım, meyvelerimize bereket ver, şehrimize bereket ver.","ar":"اللَّهُمَّ بَارِكْ لَنَا فِي ثَمَرِنَا وَبَارِكْ لَنَا فِي مَدِينَتِنَا"},"src":{"az":"Muslim 1373","en":"Muslim 1373","ru":"Муслим 1373","tr":"Müslim 1373","ar":"مسلم 1373"}},{"id":1241,"t":{"az":"Kim Allah üçün təvazö edərsə, Allah onu ucaldar.","en":"Whoever humbles himself for Allah, Allah will raise him.","ru":"Кто смирится ради Аллаха, того Аллах возвысит.","tr":"Kim Allah için tevazu gösterirse, Allah onu yükseltir.","ar":"مَنْ تَوَاضَعَ لِلَّهِ رَفَعَهُ اللَّهُ"},"src":{"az":"Muslim 2588","en":"Muslim 2588","ru":"Муслим 2588","tr":"Müslim 2588","ar":"مسلم 2588"}},{"id":1243,"t":{"az":"Allah gözəldir, gözəlliyi sevir.","en":"Allah is beautiful and loves beauty.","ru":"Аллах прекрасен и любит красоту.","tr":"Allah güzeldir, güzelliği sever.","ar":"إِنَّ اللَّهَ جَمِيلٌ يُحِبُّ الْجَمَالَ"},"src":{"az":"Muslim 91","en":"Muslim 91","ru":"Муслим 91","tr":"Müslim 91","ar":"مسلم 91"}},{"id":1247,"t":{"az":"Adəm oğlunun hər əməli özünündür, oruc istisna, çünki o Mənimdir və Mən onu mükafatlandıraram.","en":"Every deed of the son of Adam is for him except fasting; it is for Me and I shall reward it.","ru":"Каждое дело сына Адама для него, кроме поста — он для Меня, и Я воздам за него.","tr":"Âdemoğlunun her ameli kendinindir, oruç hariç; çünkü o Benim içindir ve onu Ben mükâfatlandırırım.","ar":"كُلُّ عَمَلِ ابْنِ آدَمَ لَهُ إِلاَّ الصِّيَامَ فَإِنَّهُ لِي وَأَنَا أَجْزِي بِهِ"},"src":{"az":"Buxari 1904","en":"Bukhari 1904","ru":"Бухари 1904","tr":"Buhârî 1904","ar":"البخاري 1904"}},{"id":1255,"t":{"az":"Kim bir yerdə qonaraq \"Əuzu bi kəlimatillahit-tamməti\" desə, oradan köçənə qədər heç bir şey ona zərər verməz.","en":"Whoever stops at a place and says \"I seek refuge in the complete words of Allah from evil of what He created\" nothing will harm him until he leaves.","ru":"Кто остановится в месте и скажет «Прибегаю к совершенным словам Аллаха от зла того, что Он создал» — ничто не навредит ему, пока не уедет.","tr":"Kim bir yere konup \"Eûzu bi kelimâtillâhi\\'t-tâmmâti\" derse, oradan ayrılana kadar ona hiçbir şey zarar vermez.","ar":"مَنْ نَزَلَ مَنْزِلاً فَقَالَ أَعُوذُ بِكَلِمَاتِ اللَّهِ التَّامَّاتِ مِنْ شَرِّ مَا خَلَقَ لَمْ يَضُرَّهُ شَيْءٌ حَتَّى يَرْتَحِلَ"},"src":{"az":"Muslim 2708","en":"Muslim 2708","ru":"Муслим 2708","tr":"Müslim 2708","ar":"مسلم 2708"}},{"id":1257,"t":{"az":"Heç biriniz mən ona övladından, atasından və bütün insanlardan daha sevimli olmayınca iman etmiş olmaz.","en":"None of you truly believes until I am more beloved to him than his child, his parent, and all people.","ru":"Никто из вас не уверует, пока я не стану для него любимее его ребёнка, родителя и всех людей.","tr":"Sizden hiçbiriniz, ben ona evladından, babasından ve tüm insanlardan daha sevimli olmadıkça iman etmiş olmaz.","ar":"لاَ يُؤْمِنُ أَحَدُكُمْ حَتَّى أَكُونَ أَحَبَّ إِلَيْهِ مِنْ وَلَدِهِ وَوَالِدِهِ وَالنَّاسِ أَجْمَعِينَ"},"src":{"az":"Buxari 15","en":"Bukhari 15","ru":"Бухари 15","tr":"Buhârî 15","ar":"البخاري 15"}},{"id":1259,"t":{"az":"Namaza qalxanda dəstəmazı kamil al, sonra qibləyə dön və təkbir al.","en":"When you stand for prayer, complete the ablution, face the qiblah, and say the takbir.","ru":"Когда встаёшь на молитву, соверши полное омовение, повернись к кибле и произнеси такбир.","tr":"Namaza kalktığında abdesti tam al, kıbleye dön ve tekbir getir.","ar":"إِذَا قُمْتَ إِلَى الصَّلاَةِ فَأَسْبِغِ الْوُضُوءَ ثُمَّ اسْتَقْبِلِ الْقِبْلَةَ فَكَبِّرْ"},"src":{"az":"Buxari 757","en":"Bukhari 757","ru":"Бухари 757","tr":"Buhârî 757","ar":"البخاري 757"}},{"id":1265,"t":{"az":"Kim Allah üçün bağırtlağın yuvası boyda belə məscid tikərsə, Allah ona cənnətdə ev tikər.","en":"Whoever builds a mosque for Allah, even as small as a bird\\'s nest, Allah will build for him a house in Paradise.","ru":"Кто построит мечеть ради Аллаха, хотя бы с гнездо куропатки, Аллах построит ему дом в Раю.","tr":"Kim Allah için bıldırcın yuvası kadar bile olsa mescit yaparsa, Allah ona cennette bir ev yapar.","ar":"مَنْ بَنَى لِلَّهِ مَسْجِدًا وَلَوْ كَمَفْحَصِ قَطَاةٍ بَنَى اللَّهُ لَهُ بَيْتًا فِي الْجَنَّةِ"},"src":{"az":"İbn Macə 738","en":"Ibn Majah 738","ru":"Ибн Маджа 738","tr":"İbn Mâce 738","ar":"ابن ماجه 738"}},{"id":1269,"t":{"az":"Qəbrimi bayram yerinə çevirməyin, mənə salavat gətirin, çünki salatınız mənə çatar.","en":"Do not make my grave a place of celebration, but send blessings upon me, for your blessings reach me.","ru":"Не превращайте мою могилу в место празднества, но посылайте на меня благословения — они до меня доходят.","tr":"Kabrimi bayram yeri yapmayın, bana salavat getirin, çünkü salavatınız bana ulaşır.","ar":"لاَ تَجْعَلُوا قَبْرِي عِيدًا وَصَلُّوا عَلَيَّ فَإِنَّ صَلاَتَكُمْ تَبْلُغُنِي"},"src":{"az":"Əbu Davud 2042","en":"Abu Dawud 2042","ru":"Абу Дауд 2042","tr":"Ebû Dâvûd 2042","ar":"أبو داود 2042"}},{"id":1270,"t":{"az":"Peyğəmbər səfərə çıxmaq istədikdə həyat yoldaşları arasında püşk atardı.","en":"When the Prophet wanted to travel, he would draw lots among his wives.","ru":"Когда Пророк хотел отправиться в путешествие, он бросал жребий между жёнами.","tr":"Peygamber sefere çıkmak istediğinde hanımları arasında kura çekerdi.","ar":"كَانَ النَّبِيُّ إِذَا أَرَادَ سَفَرًا أَقْرَعَ بَيْنَ نِسَائِهِ"},"src":{"az":"Buxari 2593","en":"Bukhari 2593","ru":"Бухари 2593","tr":"Buhârî 2593","ar":"البخاري 2593"}},{"id":1271,"t":{"az":"Ey qullarım, Mən zülmü Özümə haram etdim, onu aranızda da haram etdim.","en":"O My servants, I have forbidden oppression for Myself and made it forbidden among you.","ru":"О рабы Мои, Я запретил несправедливость Себе и сделал её запретной среди вас.","tr":"Ey kullarım, zulmü Kendime haram ettim, onu aranızda da haram kıldım.","ar":"يَا عِبَادِي إِنِّي حَرَّمْتُ الظُّلْمَ عَلَى نَفْسِي وَجَعَلْتُهُ بَيْنَكُمْ مُحَرَّمًا"},"src":{"az":"Muslim 2577","en":"Muslim 2577","ru":"Муслим 2577","tr":"Müslim 2577","ar":"مسلم 2577"}},{"id":1274,"t":{"az":"Yemək hazır olduğunda namaz yoxdur, iki pis şey sıxışdıranda da.","en":"There is no prayer in the presence of food, nor when one is pressed by the two urges.","ru":"Нет молитвы при наличии еды и когда теснят две нужды.","tr":"Yemek hazırken namaz olmaz, iki sıkıntı bastırdığında da.","ar":"لاَ صَلاَةَ بِحَضْرَةِ طَعَامٍ وَلاَ هُوَ يُدَافِعُهُ الأَخْبَثَانِ"},"src":{"az":"Muslim 560","en":"Muslim 560","ru":"Муслим 560","tr":"Müslim 560","ar":"مسلم 560"}},{"id":1276,"t":{"az":"Ümmətimin bir qrupu həmişə haqq üzrə galibiyyətdə olacaq.","en":"A group of my ummah will always be victorious upon the truth.","ru":"Группа из моей уммы всегда будет торжествовать на истине.","tr":"Ümmetimden bir topluluk daima hak üzere galip olacaktır.","ar":"لاَ تَزَالُ طَائِفَةٌ مِنْ أُمَّتِي عَلَى الْحَقِّ ظَاهِرِينَ"},"src":{"az":"Muslim 1920","en":"Muslim 1920","ru":"Муслим 1920","tr":"Müslim 1920","ar":"مسلم 1920"}},{"id":1277,"t":{"az":"Ramazanda ümrə həccə bərabərdir.","en":"Umrah in Ramadan is equal to Hajj.","ru":"Умра в Рамадан равна хаджу.","tr":"Ramazan\\'da umre, hacca denktir.","ar":"عُمْرَةٌ فِي رَمَضَانَ تَعْدِلُ حَجَّةً"},"src":{"az":"Buxari 1863","en":"Bukhari 1863","ru":"Бухари 1863","tr":"Buhârî 1863","ar":"البخاري 1863"}},{"id":1279,"t":{"az":"Qovulmuş şeytandan Eşidən, Bilən Allaha sığınıram.","en":"I seek refuge in Allah, the All-Hearing, the All-Knowing, from the accursed Satan.","ru":"Прибегаю к Аллаху Слышащему, Знающему от проклятого шайтана.","tr":"İşiten ve Bilen Allah\\'a, kovulmuş şeytandan sığınırım.","ar":"أَعُوذُ بِاللَّهِ السَّمِيعِ الْعَلِيمِ مِنَ الشَّيْطَانِ الرَّجِيمِ"},"src":{"az":"Əbu Davud 775","en":"Abu Dawud 775","ru":"Абу Дауд 775","tr":"Ebû Dâvûd 775","ar":"أبو داود 775"}},{"id":1280,"t":{"az":"Çətinlikdə olana möhlət verən və ya borcunu bağışlayanı, Allah Qiyamət günü ərşinin kölgəsində kölgələndirər.","en":"Whoever gives respite to one in hardship or waives his debt, Allah will shade him under His Throne on the Day of Judgment.","ru":"Кто даст отсрочку должнику в затруднении или простит долг — Аллах укроет его тенью Своего Трона в День Суда.","tr":"Darda kalana mühlet veren veya borcunu bağışlayanı, Allah Kıyamet günü arşının gölgesinde gölgelendirir.","ar":"مَنْ أَنْظَرَ مُعْسِرًا أَوْ وَضَعَ لَهُ أَظَلَّهُ اللَّهُ يَوْمَ الْقِيَامَةِ تَحْتَ ظِلِّ عَرْشِهِ"},"src":{"az":"Tirmizi 1306","en":"Tirmidhi 1306","ru":"Тирмизи 1306","tr":"Tirmizî 1306","ar":"الترمذي 1306"}},{"id":1286,"t":{"az":"Zərər vermək və zərərlə cavab vermək yoxdur.","en":"There is no causing harm nor reciprocating harm.","ru":"Нет причинения вреда и нет ответа вредом.","tr":"Zarar vermek ve zarara zararla karşılık vermek yoktur.","ar":"لاَ ضَرَرَ وَلاَ ضِرَارَ"},"src":{"az":"İbn Macə 2340","en":"Ibn Majah 2340","ru":"Ибн Маджа 2340","tr":"İbn Mâce 2340","ar":"ابن ماجه 2340"}},{"id":1294,"t":{"az":"Allahım, qəm-qüssədən, acizlikdən, tənbəllikdən Sənə sığınıram.","en":"O Allah, I seek refuge in You from worry, grief, helplessness, and laziness.","ru":"О Аллах, я прибегаю к Тебе от беспокойства, печали, бессилия и лени.","tr":"Allah\\'ım, gam ve kederden, acizlik ve tembellikten Sana sığınırım.","ar":"اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ وَالْعَجْزِ وَالْكَسَلِ"},"src":{"az":"Buxari 6369","en":"Bukhari 6369","ru":"Бухари 6369","tr":"Buhârî 6369","ar":"البخاري 6369"}},{"id":1300,"t":{"az":"Allaha və Axirət gününə iman edən qadının bir gecə-gündüzlük yolu məhrəmsiz səfər etməsi halal deyil.","en":"It is not permissible for a woman who believes in Allah and the Last Day to travel a day and night\\'s journey without a mahram.","ru":"Женщине, верующей в Аллаха и Последний День, не дозволено путешествовать день и ночь без махрама.","tr":"Allah\\'a ve ahiret gününe iman eden bir kadının, yanında mahremi olmadan bir gece-gündüzlük yol yolculuk yapması helal değildir.","ar":"لاَ يَحِلُّ لاِمْرَأَةٍ تُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الآخِرِ أَنْ تُسَافِرَ مَسِيرَةَ يَوْمٍ وَلَيْلَةٍ إِلاَّ مَعَ ذِي مَحْرَمٍ"},"src":{"az":"Buxari 1088","en":"Bukhari 1088","ru":"Бухари 1088","tr":"Buhârî 1088","ar":"البخاري 1088"}},{"id":1303,"t":{"az":"Biriniz əsnəyəndə əli ilə ağzını tutsun.","en":"When one of you yawns, let him place his hand over his mouth.","ru":"Когда один из вас зевает, пусть прикроет рот рукой.","tr":"Biriniz esnerken eliyle ağzını tutsun.","ar":"إِذَا تَثَاءَبَ أَحَدُكُمْ فَلْيُمْسِكْ بِيَدِهِ عَلَى فِيهِ"},"src":{"az":"Muslim 2995","en":"Muslim 2995","ru":"Муслим 2995","tr":"Müslim 2995","ar":"مسلم 2995"}},{"id":1306,"t":{"az":"Kim Allahın rizası üçün öyrəniləsi elmi dünya malı üçün öyrənsə, cənnətin iyini duymaz.","en":"Whoever learns knowledge meant for Allah\\'s sake only for worldly gain will not smell the fragrance of Paradise.","ru":"Кто изучит знание, предназначенное ради Аллаха, лишь для мирской выгоды — не почувствует аромата Рая.","tr":"Kim Allah rızası için öğrenilecek ilmi dünya menfaati için öğrenirse, cennetin kokusunu alamaz.","ar":"مَنْ تَعَلَّمَ عِلْمًا مِمَّا يُبْتَغَى بِهِ وَجْهُ اللَّهِ لاَ يَتَعَلَّمُهُ إِلاَّ لِيُصِيبَ بِهِ عَرَضًا مِنَ الدُّنْيَا لَمْ يَجِدْ عَرْفَ الْجَنَّةِ"},"src":{"az":"Əbu Davud 3664","en":"Abu Dawud 3664","ru":"Абу Дауд 3664","tr":"Ebû Dâvûd 3664","ar":"أبو داود 3664"}},{"id":1308,"t":{"az":"Hər yaş ciyərə (canlıya) verilən suda savab var.","en":"There is reward in every moist liver (every living creature given water).","ru":"За каждую живую печень (существо, которому дали воду) — награда.","tr":"Her canlıya (yaş ciğere) verilen suda sevap vardır.","ar":"فِي كُلِّ كَبِدٍ رَطْبَةٍ أَجْرٌ"},"src":{"az":"Buxari 2466","en":"Bukhari 2466","ru":"Бухари 2466","tr":"Buhârî 2466","ar":"البخاري 2466"}},{"id":1309,"t":{"az":"Allahım, fayda verməyən elmdən və huşu etməyən qəlbdən Sənə sığınıram.","en":"O Allah, I seek refuge in You from knowledge that does not benefit and a heart that does not humble itself.","ru":"О Аллах, я прибегаю к Тебе от бесполезного знания и от сердца, которое не смиряется.","tr":"Allah\\'ım, fayda vermeyen ilimden ve huşu duymayan kalpten Sana sığınırım.","ar":"اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ عِلْمٍ لاَ يَنْفَعُ وَمِنْ قَلْبٍ لاَ يَخْشَعُ"},"src":{"az":"Muslim 2722","en":"Muslim 2722","ru":"Муслим 2722","tr":"Müslim 2722","ar":"مسلم 2722"}},{"id":1312,"t":{"az":"İnsana günah olaraq eşitdiyi hər şeyi danışması kifayətdir.","en":"It is enough of a sin for a person to narrate everything he hears.","ru":"Достаточно человеку греха в том, что он передаёт всё, что слышит.","tr":"Kişiye günah olarak duyduğu her şeyi söylemesi yeter.","ar":"كَفَى بِالْمَرْءِ إِثْمًا أَنْ يُحَدِّثَ بِكُلِّ مَا سَمِعَ"},"src":{"az":"Əbu Davud 4992","en":"Abu Dawud 4992","ru":"Абу Дауд 4992","tr":"Ebû Dâvûd 4992","ar":"أبو داود 4992"}},{"id":1313,"t":{"az":"Öz kölgəsindən başqa kölgə olmayan gün Allah yeddi nəfəri kölgəsində kölgələndirər.","en":"Seven will be shaded by Allah on the Day when there is no shade except His.","ru":"Семерых Аллах укроет в Своей тени в День, когда не будет иной тени.","tr":"Kendi gölgesinden başka gölge olmayan gün Allah yedi kişiyi gölgesinde gölgelendirecektir.","ar":"سَبْعَةٌ يُظِلُّهُمُ اللَّهُ فِي ظِلِّهِ يَوْمَ لاَ ظِلَّ إِلاَّ ظِلُّهُ"},"src":{"az":"Buxari 660","en":"Bukhari 660","ru":"Бухари 660","tr":"Buhârî 660","ar":"البخاري 660"}},{"id":1318,"t":{"az":"Namazlarınızın bir qismini evlərinizdə qılın, evlərinizi qəbrə çevirməyin.","en":"Pray some of your prayers in your homes and do not make them graves.","ru":"Совершайте часть молитв дома и не превращайте дома в могилы.","tr":"Namazlarınızın bir kısmını evlerinizde kılın, evlerinizi kabirlere çevirmeyin.","ar":"اجْعَلُوا مِنْ صَلاَتِكُمْ فِي بُيُوتِكُمْ وَلاَ تَتَّخِذُوهَا قُبُورًا"},"src":{"az":"Buxari 432","en":"Bukhari 432","ru":"Бухари 432","tr":"Buhârî 432","ar":"البخاري 432"}},{"id":1324,"t":{"az":"Allahım, etdiyim və etmədiyim şeylərin şərindən Sənə sığınıram.","en":"O Allah, I seek refuge in You from the evil of what I have done and the evil of what I have not done.","ru":"О Аллах, я прибегаю к Тебе от зла того, что я сделал, и от зла того, что не сделал.","tr":"Allah\\'ım, yaptığım ve yapmadığım şeylerin şerrinden Sana sığınırım.","ar":"اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ شَرِّ مَا عَمِلْتُ وَمِنْ شَرِّ مَا لَمْ أَعْمَلْ"},"src":{"az":"Muslim 2716","en":"Muslim 2716","ru":"Муслим 2716","tr":"Müslim 2716","ar":"مسلم 2716"}},{"id":1334,"t":{"az":"Beş vaxt namaz və Cümədən Cüməyə aralarındakı günahlara kəffarədir.","en":"The five daily prayers and Friday to Friday are expiation for what is between them.","ru":"Пять ежедневных молитв и пятница до пятницы — искупление того, что между ними.","tr":"Beş vakit namaz ve Cuma\\'dan Cuma\\'ya aralarındaki günahlara kefarettir.","ar":"الصَّلَوَاتُ الْخَمْسُ وَالْجُمُعَةُ إِلَى الْجُمُعَةِ كَفَّارَاتٌ لِمَا بَيْنَهُنَّ"},"src":{"az":"Muslim 233","en":"Muslim 233","ru":"Муслим 233","tr":"Müslim 233","ar":"مسلم 233"}},{"id":1336,"t":{"az":"Mücahid Allaha itaət yolunda nəfsi ilə cihad edəndir.","en":"The mujahid is the one who strives against his soul in obedience to Allah.","ru":"Муджахид тот, кто борется со своей душой в покорности Аллаху.","tr":"Mücahid, Allah\\'a itaat yolunda nefsiyle cihad edendir.","ar":"الْمُجَاهِدُ مَنْ جَاهَدَ نَفْسَهُ فِي طَاعَةِ اللَّهِ"},"src":{"az":"Tirmizi 1621","en":"Tirmidhi 1621","ru":"Тирмизи 1621","tr":"Tirmizî 1621","ar":"الترمذي 1621"}},{"id":1337,"t":{"az":"Kim orucluyəkn unutub yeyib-içsə, orucunu tamamlasın; onu Allah yedirib-içirmişdir.","en":"If someone forgets while fasting and eats or drinks, let him complete his fast, for Allah has fed and given him drink.","ru":"Кто забудет во время поста и поест или попьёт — пусть завершит пост: его накормил и напоил Аллах.","tr":"Kim oruçluyken unutarak yeyip içerse, orucunu tamamlasın; onu Allah yedirip içirmiştir.","ar":"مَنْ نَسِيَ وَهُوَ صَائِمٌ فَأَكَلَ أَوْ شَرِبَ فَلْيُتِمَّ صَوْمَهُ فَإِنَّمَا أَطْعَمَهُ اللَّهُ وَسَقَاهُ"},"src":{"az":"Buxari 1933","en":"Bukhari 1933","ru":"Бухари 1933","tr":"Buhârî 1933","ar":"البخاري 1933"}},{"id":1338,"t":{"az":"Sədəqə heç bir qulun malını əskiltməz.","en":"No servant\\'s wealth is decreased by charity.","ru":"Милостыня не уменьшает имущества раба.","tr":"Sadaka hiçbir kulun malını eksiltmez.","ar":"مَا نَقَصَ مَالُ عَبْدٍ مِنْ صَدَقَةٍ"},"src":{"az":"Tirmizi 2325","en":"Tirmidhi 2325","ru":"Тирмизи 2325","tr":"Tirmizî 2325","ar":"الترمذي 2325"}},{"id":1339,"t":{"az":"Allahım, Səninlə sabahladıq, Səninlə axşamladıq, Səninlə yaşayır, Səninlə ölürük, dönüş Sənədir.","en":"O Allah, by You we enter the morning, by You we enter the evening, by You we live, by You we die, and to You is the resurrection.","ru":"О Аллах, с Тобой мы встретили утро, с Тобой встретили вечер, с Тобой живём, с Тобой умираем, и к Тебе воскресение.","tr":"Allah\\'ım, Seninle sabahladık, Seninle akşamladık, Seninle yaşıyoruz, Seninle ölüyoruz ve dönüş Sanadır.","ar":"اللَّهُمَّ بِكَ أَصْبَحْنَا وَبِكَ أَمْسَيْنَا وَبِكَ نَحْيَا وَبِكَ نَمُوتُ وَإِلَيْكَ النُّشُورُ"},"src":{"az":"Tirmizi 3391","en":"Tirmidhi 3391","ru":"Тирмизи 3391","tr":"Tirmizî 3391","ar":"الترمذي 3391"}},{"id":1340,"t":{"az":"Qardaşına gülümsəməyin sədəqədir, yaxşılığı əmr etməyin sədəqədir.","en":"Smiling at your brother is charity, commanding good and forbidding evil is charity.","ru":"Улыбка брату — милостыня, повеление одобряемого и запрещение порицаемого — милостыня.","tr":"Kardeşine gülümsemen sadakadır, iyiliği emredip kötülükten nehyetmen sadakadır.","ar":"تَبْسُمُكَ فِي وَجْهِ أَخِيكَ صَدَقَةٌ وَأَمْرُكَ بِالْمَعْرُوفِ وَنَهْيُكَ عَنِ الْمُنْكَرِ صَدَقَةٌ"},"src":{"az":"Tirmizi 1956","en":"Tirmidhi 1956","ru":"Тирмизи 1956","tr":"Tirmizî 1956","ar":"الترمذي 1956"}},{"id":1343,"t":{"az":"Ey qullarım, sizin ilkiniz, sonuncunuz, insanınız və cinniniz bir yerdə duraraq Məndən istəsəydi, bu Mənim mülkümdən zərrə qədər əskiltməzdi.","en":"O My servants, if the first and last of you, humans and jinn, stood and asked Me, it would not diminish My dominion at all.","ru":"О рабы Мои, если первые и последние из вас, люди и джинны, встали и попросили Меня — это не уменьшит Моего владычества ни на йоту.","tr":"Ey kullarım, ilkiniz, sonuncunuz, insanınız ve cinniniz bir arada durup Benden isteseydi, bu mülkümden zerre kadar eksiltmezdi.","ar":"يَا عِبَادِي لَوْ أَنَّ أَوَّلَكُمْ وَآخِرَكُمْ وَإِنْسَكُمْ وَجِنَّكُمْ قَامُوا فِي صَعِيدٍ وَاحِدٍ فَسَأَلُونِي"},"src":{"az":"Muslim 2577","en":"Muslim 2577","ru":"Муслим 2577","tr":"Müslim 2577","ar":"مسلم 2577"}},{"id":1345,"t":{"az":"Kimin üç qızı olub onlara səbr etsə, yedirsə, içirsə, geydirsə — onlar ona oddan sipər olar.","en":"Whoever has three daughters and is patient with them, feeds, clothes them from his means — they will be a shield from the Fire.","ru":"У кого три дочери, и он терпелив с ними, кормит и одевает из своего достатка — они станут для него защитой от огня.","tr":"Kimin üç kızı olup onlara sabreder, yedirir, içirir ve giydirirse — onlar ona ateşten perde olurlar.","ar":"مَنْ كَانَ لَهُ ثَلاَثُ بَنَاتٍ فَصَبَرَ عَلَيْهِنَّ وَأَطْعَمَهُنَّ وَسَقَاهُنَّ وَكَسَاهُنَّ مِنْ جِدَتِهِ كُنَّ لَهُ حِجَابًا مِنَ النَّارِ"},"src":{"az":"İbn Macə 3669","en":"Ibn Majah 3669","ru":"Ибн Маджа 3669","tr":"İbn Mâce 3669","ar":"ابن ماجه 3669"}},{"id":1347,"t":{"az":"Allah mülayimdir və hər işdə mülayimliyi sevər.","en":"Allah is gentle and loves gentleness in all matters.","ru":"Аллах мягок и любит мягкость во всём.","tr":"Allah yumuşaktır ve her işte yumuşaklığı sever.","ar":"إِنَّ اللَّهَ رَفِيقٌ يُحِبُّ الرِّفْقَ فِي الأَمْرِ كُلِّهِ"},"src":{"az":"Buxari 6927","en":"Bukhari 6927","ru":"Бухари 6927","tr":"Buhârî 6927","ar":"البخاري 6927"}},{"id":1354,"t":{"az":"Allahım, Səndən dünyada və axirətdə əfv və afiyət istəyirəm.","en":"O Allah, I ask You for pardon and well-being in this world and the Hereafter.","ru":"О Аллах, я прошу Тебя о прощении и благополучии в этой жизни и в вечности.","tr":"Allah\\'ım, Senden dünyada ve ahirette af ve afiyet isterim.","ar":"اللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَفْوَ وَالْعَافِيَةَ فِي الدُّنْيَا وَالآخِرَةِ"},"src":{"az":"İbn Macə 3871","en":"Ibn Majah 3871","ru":"Ибн Маджа 3871","tr":"İbn Mâce 3871","ar":"ابن ماجه 3871"}},{"id":1355,"t":{"az":"Qadın evinin yeməyindən xərab etmədən infaq edərsə, savabı onundur.","en":"If a woman spends from the food of her house without waste, she will have her reward.","ru":"Если женщина расходует из еды своего дома без расточительства, ей полагается награда.","tr":"Kadın evinin yemeğinden bozmadan infak ederse, sevabı onundur.","ar":"إِذَا أَنْفَقَتِ الْمَرْأَةُ مِنْ طَعَامِ بَيْتِهَا غَيْرَ مُفْسِدَةٍ كَانَ لَهَا أَجْرُهَا"},"src":{"az":"Buxari 1437","en":"Bukhari 1437","ru":"Бухари 1437","tr":"Buhârî 1437","ar":"البخاري 1437"}},{"id":1356,"t":{"az":"Kim səbr etsə, Allah onu sabırlı edər, heç kəsə səbrdən geniş nemət verilməyib.","en":"Whoever endures patiently, Allah will make him patient, and no one is given a gift better than patience.","ru":"Кто терпит — Аллах дарует ему терпение, и никому не дано дара лучше терпения.","tr":"Kim sabrederse, Allah onu sabırlı kılar; kimseye sabırdan geniş bir nimet verilmemiştir.","ar":"مَنْ يَصْبِرْ يُصَبِّرْهُ اللَّهُ وَمَا أُعْطِيَ أَحَدٌ عَطَاءً خَيْرًا وَأَوْسَعَ مِنَ الصَّبْرِ"},"src":{"az":"Buxari 1469","en":"Bukhari 1469","ru":"Бухари 1469","tr":"Buhârî 1469","ar":"البخاري 1469"}},{"id":1357,"t":{"az":"Axirət həyatından başqa həyat yoxdur.","en":"There is no life except the life of the Hereafter.","ru":"Нет жизни, кроме жизни вечной.","tr":"Ahiret hayatından başka hayat yoktur.","ar":"لاَ عَيْشَ إِلاَّ عَيْشُ الآخِرَةِ"},"src":{"az":"Buxari 6413","en":"Bukhari 6413","ru":"Бухари 6413","tr":"Buhârî 6413","ar":"البخاري 6413"}},{"id":1360,"t":{"az":"Biriniz miniyə mindi mi, Allahın adını çəksin.","en":"When one of you mounts his riding animal, let him say the name of Allah.","ru":"Когда один из вас садится на верховое животное, пусть произнесёт имя Аллаха.","tr":"Biriniz bineğine bindiğinde Allah\\'ın adını ansın.","ar":"إِذَا رَكِبَ أَحَدُكُمُ الدَّابَّةَ فَلْيُسَمِّ اللَّهَ"},"src":{"az":"Əbu Davud 2602","en":"Abu Dawud 2602","ru":"Абу Дауд 2602","tr":"Ebû Dâvûd 2602","ar":"أبو داود 2602"}},{"id":1361,"t":{"az":"Əməllərin ən xeyirlisi vaxtında qılınan namazdır.","en":"The best of deeds is prayer performed on time.","ru":"Лучшее из дел — молитва, совершённая вовремя.","tr":"Amellerin en hayırlısı vaktinde kılınan namazdır.","ar":"خَيْرُ الأَعْمَالِ الصَّلاَةُ عَلَى وَقْتِهَا"},"src":{"az":"Buxari 527","en":"Bukhari 527","ru":"Бухари 527","tr":"Buhârî 527","ar":"البخاري 527"}},{"id":1362,"t":{"az":"Mülayimlik bir şeydə olarsa onu gözəlləşdirər, bir şeydən çıxarsa onu çirkinləşdirər.","en":"Gentleness beautifies whatever it is in, and its absence makes things ugly.","ru":"Мягкость украшает всё, в чём она есть, и портит всё, из чего она изъята.","tr":"Yumuşaklık bir şeyde bulunursa onu güzelleştirir, bir şeyden çıkarılırsa onu çirkinleştirir.","ar":"إِنَّ الرِّفْقَ لاَ يَكُونُ فِي شَيْءٍ إِلاَّ زَانَهُ وَلاَ يُنْزَعُ مِنْ شَيْءٍ إِلاَّ شَانَهُ"},"src":{"az":"Muslim 2594","en":"Muslim 2594","ru":"Муслим 2594","tr":"Müslim 2594","ar":"مسلم 2594"}},{"id":1363,"t":{"az":"Kim imamla birlikdə o gedənə qədər qalarsa, bütün gecə qiyam etmiş kimi yazılar.","en":"Whoever stays with the imam until he leaves, it will be recorded as standing the whole night.","ru":"Кто останется с имамом до его ухода — ему запишется стояние целой ночи.","tr":"Kim imamla birlikte o ayrılana kadar kalırsa, bütün gece namaz kılmış gibi yazılır.","ar":"مَنْ قَامَ مَعَ الإِمَامِ حَتَّى يَنْصَرِفَ كُتِبَ لَهُ قِيَامُ لَيْلَةٍ"},"src":{"az":"Tirmizi 806","en":"Tirmidhi 806","ru":"Тирмизи 806","tr":"Tirmizî 806","ar":"الترمذي 806"}},{"id":1366,"t":{"az":"Allahım, mənə öyrətdiyinlə fayda ver, mənə faydalı olanı öyrət, elmimi artır.","en":"O Allah, benefit me with what You have taught me, teach me what benefits me, and increase me in knowledge.","ru":"О Аллах, дай мне пользу от того, чему Ты научил меня, научи меня полезному и приумножь мне знание.","tr":"Allah\\'ım, bana öğrettiğinle beni faydalandır, bana faydalı olanı öğret ve ilmimi artır.","ar":"اللَّهُمَّ انْفَعْنِي بِمَا عَلَّمْتَنِي وَعَلِّمْنِي مَا يَنْفَعُنِي وَزِدْنِي عِلْمًا"},"src":{"az":"Tirmizi 3599","en":"Tirmidhi 3599","ru":"Тирмизи 3599","tr":"Tirmizî 3599","ar":"الترمذي 3599"}},{"id":1367,"t":{"az":"Kim gecədən oruca niyyət etməzsə, onun orucu yoxdur.","en":"Whoever does not intend to fast from the night before has no fast.","ru":"Кто не намеревался поститься с ночи — нет ему поста.","tr":"Kim geceden oruç niyetini belirlemezse, onun orucu yoktur.","ar":"مَنْ لَمْ يُبَيِّتِ الصِّيَامَ مِنَ اللَّيْلِ فَلاَ صِيَامَ لَهُ"},"src":{"az":"Nəsai 2334","en":"An-Nasa'i 2334","ru":"ан-Насаи 2334","tr":"Nesâî 2334","ar":"النسائي 2334"}},{"id":1368,"t":{"az":"Allah onlara zənginlərindən alınıb kasıblarına verilən sədəqə fərz etmişdir.","en":"Allah has enjoined upon them a charity taken from their rich and given to their poor.","ru":"Аллах предписал им милостыню, которая берётся у богатых и отдаётся бедным.","tr":"Allah, zenginlerinden alınıp fakirlerine verilen bir sadaka farz kılmıştır.","ar":"إِنَّ اللَّهَ فَرَضَ عَلَيْهِمْ صَدَقَةً تُؤْخَذُ مِنْ أَغْنِيَائِهِمْ فَتُرَدُّ عَلَى فُقَرَائِهِمْ"},"src":{"az":"Buxari 1395","en":"Bukhari 1395","ru":"Бухари 1395","tr":"Buhârî 1395","ar":"البخاري 1395"}},{"id":1369,"t":{"az":"Allahın tam kəlmələri ilə yaratdığının şərindən sığınıram.","en":"I seek refuge in the perfect words of Allah from the evil of what He has created.","ru":"Прибегаю к совершенным словам Аллаха от зла того, что Он создал.","tr":"Allah\\'ın tam kelimelerine sığınırım, yarattıklarının şerrinden.","ar":"أَعُوذُ بِكَلِمَاتِ اللَّهِ التَّامَّاتِ مِنْ شَرِّ مَا خَلَقَ"},"src":{"az":"Muslim 2708","en":"Muslim 2708","ru":"Муслим 2708","tr":"Müslim 2708","ar":"مسلم 2708"}},{"id":1371,"t":{"az":"Kim razı olsa, razılıq onundur; kim narazı olsa, narazılıq onundur.","en":"Whoever is content will have contentment, and whoever is discontent will have discontent.","ru":"Кто доволен — тому довольство, кто недоволен — тому недовольство.","tr":"Kim razı olursa, rıza onundur; kim öfkelirse, öfke onundur.","ar":"مَنْ رَضِيَ فَلَهُ الرِّضَا وَمَنْ سَخِطَ فَلَهُ السَّخَطُ"},"src":{"az":"Tirmizi 2396","en":"Tirmidhi 2396","ru":"Тирмизи 2396","tr":"Tirmizî 2396","ar":"الترمذي 2396"}},{"id":1372,"t":{"az":"Allahım, Muhəmməd ailəsinin ruzisini kifayət qədər et.","en":"O Allah, make the provision of the family of Muhammad sufficient.","ru":"О Аллах, сделай пропитание семьи Мухаммада достаточным.","tr":"Allah\\'ım, Muhammed ailesinin rızkını yeterli kıl.","ar":"اللَّهُمَّ اجْعَلْ رِزْقَ آلِ مُحَمَّدٍ قُوتًا"},"src":{"az":"Buxari 6460","en":"Bukhari 6460","ru":"Бухари 6460","tr":"Buhârî 6460","ar":"البخاري 6460"}},{"id":1373,"t":{"az":"Ölü qəbrə qoyulanda dönüb gedənlərin ayaq səslərini eşidir.","en":"When the dead is placed in his grave, he hears the footsteps of those leaving.","ru":"Когда мёртвого кладут в могилу, он слышит шаги уходящих.","tr":"Ölü kabrine konulduğunda, dönüp gidenlerin ayak seslerini duyar.","ar":"إِذَا وُضِعَ الْمَيِّتُ فِي قَبْرِهِ إِنَّهُ لَيَسْمَعُ قَرْعَ نِعَالِهِمْ حِينَ يُوَلُّونَ عَنْهُ"},"src":{"az":"Buxari 1338","en":"Bukhari 1338","ru":"Бухари 1338","tr":"Buhârî 1338","ar":"البخاري 1338"}},{"id":1378,"t":{"az":"Kim dəstəmazını gözəl alıb Cüməyə gəlib dinləsə, iki Cümə arasındakı günahları bağışlanar.","en":"Whoever performs ablution well, comes to Friday prayer, listens and is silent — his sins between the two Fridays are forgiven.","ru":"Кто совершит омовение наилучшим образом, придёт на пятничную молитву, будет слушать и молчать — ему простятся грехи между двумя пятницами.","tr":"Kim abdestini güzelce alıp Cuma\\'ya gelir, dinler ve susarsa, iki Cuma arasındaki günahları bağışlanır.","ar":"مَنْ تَوَضَّأَ فَأَحْسَنَ الْوُضُوءَ ثُمَّ أَتَى الْجُمُعَةَ فَاسْتَمَعَ وَأَنْصَتَ غُفِرَ لَهُ مَا بَيْنَهُ وَبَيْنَ الْجُمُعَةِ"},"src":{"az":"Muslim 857","en":"Muslim 857","ru":"Муслим 857","tr":"Müslim 857","ar":"مسلم 857"}},{"id":1379,"t":{"az":"Gecə namazının sonunun vitr olmasını təmin edin.","en":"Make the last of your night prayer witr.","ru":"Сделайте последнюю ночную молитву витром.","tr":"Gece namazınızın sonunu vitir yapın.","ar":"اجْعَلُوا آخِرَ صَلاَتِكُمْ بِاللَّيْلِ وِتْرًا"},"src":{"az":"Buxari 998","en":"Bukhari 998","ru":"Бухари 998","tr":"Buhârî 998","ar":"البخاري 998"}},{"id":1382,"t":{"az":"Ramazan ayından sonra ən fəzilətli oruc Allahın Məhərrəm ayının orucudur.","en":"The best fasting after the month of Ramadan is fasting in the month of Allah, Muharram.","ru":"Лучший пост после месяца Рамадан — пост в месяце Аллаха Мухарраме.","tr":"Ramazan ayından sonra en faziletli oruç, Allah\\'ın Muharrem ayının orucudur.","ar":"أَفْضَلُ الصِّيَامِ بَعْدَ شَهْرِ رَمَضَانَ صِيَامُ شَهْرِ اللَّهِ الْمُحَرَّمِ"},"src":{"az":"Muslim 1163","en":"Muslim 1163","ru":"Муслим 1163","tr":"Müslim 1163","ar":"مسلم 1163"}},{"id":1383,"t":{"az":"Allahın ən çox qul azad etdiyi gün Ərəfə günüdür.","en":"There is no day on which Allah frees more people from the Fire than the Day of Arafah.","ru":"Нет дня, в который Аллах освобождает больше рабов от огня, чем в день Арафа.","tr":"Allah\\'ın en çok kul azat ettiği gün Arefe günüdür.","ar":"مَا مِنْ يَوْمٍ أَكْثَرَ مِنْ أَنْ يُعْتِقَ اللَّهُ فِيهِ عَبْدًا مِنَ النَّارِ مِنْ يَوْمِ عَرَفَةَ"},"src":{"az":"Muslim 1348","en":"Muslim 1348","ru":"Муслим 1348","tr":"Müslim 1348","ar":"مسلم 1348"}},{"id":1384,"t":{"az":"Allahım, Səndən hidayət, təqva, iffət və zənginlik istəyirəm.","en":"O Allah, I ask You for guidance, piety, chastity, and self-sufficiency.","ru":"О Аллах, я прошу Тебя о руководстве, богобоязненности, целомудрии и достатке.","tr":"Allah\\'ım, Senden hidayet, takva, iffet ve zenginlik isterim.","ar":"اللَّهُمَّ إِنِّي أَسْأَلُكَ الْهُدَى وَالتُّقَى وَالْعَفَافَ وَالْغِنَى"},"src":{"az":"Muslim 2721","en":"Muslim 2721","ru":"Муслим 2721","tr":"Müslim 2721","ar":"مسلم 2721"}},{"id":1390,"t":{"az":"Kim bu ağacdan (sarımsaq, soğan) yeyərsə, məscidimizə yaxınlaşmasın.","en":"Whoever eats from this tree (garlic, onion), let him not approach our mosque.","ru":"Кто поест от этого дерева (чеснок, лук) — пусть не приближается к нашей мечети.","tr":"Kim bu ağaçtan (sarımsak, soğan) yerse, mescidimize yaklaşmasın.","ar":"مَنْ أَكَلَ مِنْ هَذِهِ الشَّجَرَةِ فَلاَ يَقْرَبَنَّ مَسْجِدَنَا"},"src":{"az":"Buxari 855","en":"Bukhari 855","ru":"Бухари 855","tr":"Buhârî 855","ar":"البخاري 855"}},{"id":1391,"t":{"az":"Hər peyğəmbərin qəbul olunan bir duası var. Mən duamı ümmətimə şəfaət üçün saxladım.","en":"Every prophet had a supplication that was answered. I have reserved mine as intercession for my ummah.","ru":"У каждого пророка была принятая мольба. Я сохранил свою как заступничество для моей уммы.","tr":"Her peygamberin kabul olunan bir duası vardır. Ben duamı ümmetim için şefaat olarak sakladım.","ar":"مَا مِنْ نَبِيٍّ إِلاَّ لَهُ دَعْوَةٌ مُسْتَجَابَةٌ فَتَعَجَّلَ كُلُّ نَبِيٍّ دَعْوَتَهُ وَإِنِّي اخْتَبَأْتُ دَعْوَتِي شَفَاعَةً لأُمَّتِي"},"src":{"az":"Muslim 199","en":"Muslim 199","ru":"Муслим 199","tr":"Müslim 199","ar":"مسلم 199"}},{"id":1398,"t":{"az":"Kim insanlardan çoxaltmaq üçün mal istəyirsə, köz istəyir.","en":"Whoever asks people for their wealth to accumulate more is asking for burning coals.","ru":"Кто просит у людей имущество ради накопления — просит лишь горящие угли.","tr":"Kim insanlardan çoğaltmak için mal isterse, ancak kor ister.","ar":"مَنْ سَأَلَ النَّاسَ أَمْوَالَهُمْ تَكَثُّرًا فَإِنَّمَا يَسْأَلُ جَمْرًا"},"src":{"az":"Muslim 1041","en":"Muslim 1041","ru":"Муслим 1041","tr":"Müslim 1041","ar":"مسلم 1041"}},{"id":1399,"t":{"az":"Allahım, xəsislikdən və qorxaqlıqdan Sənə sığınıram.","en":"O Allah, I seek refuge in You from miserliness and cowardice.","ru":"О Аллах, я прибегаю к Тебе от скупости и трусости.","tr":"Allah\\'ım, cimrilikten ve korkaklıktan Sana sığınırım.","ar":"اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْبُخْلِ وَأَعُوذُ بِكَ مِنَ الْجُبْنِ"},"src":{"az":"Buxari 6374","en":"Bukhari 6374","ru":"Бухари 6374","tr":"Buhârî 6374","ar":"البخاري 6374"}},{"id":1400,"t":{"az":"Sədəqənin ən xeyirlisi zənginlikdən artan qisimdir, əvvəl öz ailənlə başla.","en":"The best charity is from surplus, and start with those you support.","ru":"Лучшая милостыня — из достатка, и начинай с тех, кого содержишь.","tr":"Sadakanın en hayırlısı zenginliğin artanıdır, önce bakmakla yükümlü olduklarından başla.","ar":"خَيْرُ الصَّدَقَةِ مَا كَانَتْ عَنْ ظَهْرِ غِنًى وَابْدَأْ بِمَنْ تَعُولُ"},"src":{"az":"Buxari 1426","en":"Bukhari 1426","ru":"Бухари 1426","tr":"Buhârî 1426","ar":"البخاري 1426"}},{"id":1401,"t":{"az":"Ey oğlan, sənə kəlmələr öyrədirəm: Allahı qoru ki, O da səni qorusun.","en":"O boy, I will teach you some words: Be mindful of Allah and He will protect you.","ru":"О мальчик, я научу тебя словам: Храни Аллаха — и Он сохранит тебя.","tr":"Ey oğul, sana bazı kelimeler öğreteceğim: Allah\\'ı koru ki O da seni korusun.","ar":"يَا غُلاَمُ إِنِّي أُعَلِّمُكَ كَلِمَاتٍ احْفَظِ اللَّهَ يَحْفَظْكَ"},"src":{"az":"Tirmizi 2516","en":"Tirmidhi 2516","ru":"Тирмизи 2516","tr":"Tirmizî 2516","ar":"الترمذي 2516"}},{"id":1402,"t":{"az":"Sizdn aşağıda olana baxın, üstünüzdə olana baxmayın.","en":"Look at those below you and do not look at those above you.","ru":"Смотрите на тех, кто ниже вас, и не смотрите на тех, кто выше.","tr":"Sizden aşağıda olana bakın, üstünüzde olana bakmayın.","ar":"انْظُرُوا إِلَى مَنْ هُوَ أَسْفَلَ مِنْكُمْ وَلاَ تَنْظُرُوا إِلَى مَنْ هُوَ فَوْقَكُمْ"},"src":{"az":"Muslim 2963","en":"Muslim 2963","ru":"Муслим 2963","tr":"Müslim 2963","ar":"مسلم 2963"}},{"id":1405,"t":{"az":"Qadın yalnız məhrəmi ilə səfər etsin.","en":"A woman should not travel except with a mahram.","ru":"Женщина не должна путешествовать без махрама.","tr":"Kadın ancak mahremiyle sefere çıksın.","ar":"لاَ تُسَافِرِ الْمَرْأَةُ إِلاَّ مَعَ ذِي مَحْرَمٍ"},"src":{"az":"Buxari 1862","en":"Bukhari 1862","ru":"Бухари 1862","tr":"Buhârî 1862","ar":"البخاري 1862"}},{"id":1406,"t":{"az":"Allahım, işimin qoruyucusu olan dinimi islah et.","en":"O Allah, rectify for me my religion which is the safeguard of my affair.","ru":"О Аллах, исправь мне мою религию, которая является защитой моих дел.","tr":"Allah\\'ım, işimin koruyucusu olan dinimi ıslah et.","ar":"اللَّهُمَّ أَصْلِحْ لِي دِينِي الَّذِي هُوَ عِصْمَةُ أَمْرِي"},"src":{"az":"Muslim 2720","en":"Muslim 2720","ru":"Муслим 2720","tr":"Müslim 2720","ar":"مسلم 2720"}},{"id":1408,"t":{"az":"Biriniz məscidə girdikdə oturmazdan əvvəl iki rükət qılsın.","en":"When one of you enters the mosque, let him pray two units before sitting down.","ru":"Когда один из вас войдёт в мечеть, пусть совершит два ракаата, прежде чем сесть.","tr":"Biriniz mescide girdiğinde oturmadan önce iki rekât kılsın.","ar":"إِذَا دَخَلَ أَحَدُكُمُ الْمَسْجِدَ فَلْيَرْكَعْ رَكْعَتَيْنِ قَبْلَ أَنْ يَجْلِسَ"},"src":{"az":"Buxari 444","en":"Bukhari 444","ru":"Бухари 444","tr":"Buhârî 444","ar":"البخاري 444"}},{"id":1409,"t":{"az":"Kim fərz namazını camaatla qılmağa yürüyərsə, bir həcc savabı kimidir.","en":"Whoever walks to a prescribed prayer in congregation, it is like Hajj.","ru":"Кто идёт на обязательную молитву в общине — это как хадж.","tr":"Kim farz namazını cemaatle kılmaya yürürse, bir hac gibidir.","ar":"مَنْ مَشَى إِلَى صَلاَةٍ مَكْتُوبَةٍ فِي الْجَمَاعَةِ فَهِيَ كَحَجَّةٍ"},"src":{"az":"Əhməd 22304","en":"Ahmad 22304","ru":"Ахмад 22304","tr":"Ahmed 22304","ar":"أحمد 22304"}},{"id":1411,"t":{"az":"Bədəndə bir ət parçası var, o düzələrsə bütün bədən düzələr; pozularsa bütün bədən pozular. O, qəlbdir.","en":"In the body there is a piece of flesh; if it is sound, the whole body is sound. It is the heart.","ru":"В теле есть кусочек плоти; если он здоров — здорово всё тело. Это — сердце.","tr":"Bedende bir et parçası vardır; o düzelirse bütün beden düzelir. O, kalptir.","ar":"إِنَّ فِي الْجَسَدِ مُضْغَةً إِذَا صَلَحَتْ صَلَحَ الْجَسَدُ كُلُّهُ وَإِذَا فَسَدَتْ فَسَدَ الْجَسَدُ كُلُّهُ أَلاَ وَهِيَ الْقَلْبُ"},"src":{"az":"Buxari 52","en":"Bukhari 52","ru":"Бухари 52","tr":"Buhârî 52","ar":"البخاري 52"}},{"id":1413,"t":{"az":"Sədəqə dəlildir.","en":"Charity is a proof.","ru":"Милостыня — доказательство.","tr":"Sadaka burhandır (delildir).","ar":"الصَّدَقَةُ بُرْهَانٌ"},"src":{"az":"Muslim 223","en":"Muslim 223","ru":"Муслим 223","tr":"Müslim 223","ar":"مسلم 223"}},{"id":1415,"t":{"az":"Sədəqə verən Qiyamət günü sədəqəsinin kölgəsində olacaq.","en":"The one who gives charity will be in the shade of his charity on the Day of Judgment.","ru":"Дающий милостыню будет в тени своей милостыни в День Суда.","tr":"Sadaka veren, Kıyamet günü sadakasının gölgesinde olacaktır.","ar":"إِنَّ الْمُتَصَدِّقَ فِي ظِلِّ صَدَقَتِهِ يَوْمَ الْقِيَامَةِ"},"src":{"az":"Əhməd 17333","en":"Ahmad 17333","ru":"Ахмад 17333","tr":"Ahmed 17333","ar":"أحمد 17333"}},{"id":1420,"t":{"az":"Peyğəmbər səfərdən qayıdanda \"Dönənlər, tövbə edənlər, ibadət edənlər, Rəbbimizə həmd edənlər\" deyərdi.","en":"When the Prophet returned from a journey, he would say: We return repentant, worshipping, praising our Lord.","ru":"Когда Пророк возвращался из поездки, он говорил: Возвращаемся, каясь, поклоняясь, восхваляя нашего Господа.","tr":"Peygamber seferden döndüğünde: Dönenler, tövbe edenler, ibadet edenler, Rabbimize hamd edenleriz, derdi.","ar":"كَانَ النَّبِيُّ إِذَا قَفَلَ مِنْ سَفَرٍ قَالَ آيِبُونَ تَائِبُونَ عَابِدُونَ لِرَبِّنَا حَامِدُونَ"},"src":{"az":"Buxari 1797","en":"Bukhari 1797","ru":"Бухари 1797","tr":"Buhârî 1797","ar":"البخاري 1797"}},{"id":1422,"t":{"az":"Mülayimlikdən məhrum olan bütün xeyirdən məhrum olar.","en":"Whoever is deprived of gentleness is deprived of all good.","ru":"Кто лишён мягкости — лишён всего блага.","tr":"Yumuşaklıktan mahrum olan, tüm hayırdan mahrum olur.","ar":"مَنْ حُرِمَ الرِّفْقَ حُرِمَ الْخَيْرَ كُلَّهُ"},"src":{"az":"Muslim 2592","en":"Muslim 2592","ru":"Муслим 2592","tr":"Müslim 2592","ar":"مسلم 2592"}},{"id":1423,"t":{"az":"Allaha ən sevimli yerlər məscidlərdir.","en":"The most beloved places to Allah are the mosques.","ru":"Самые любимые Аллахом места — мечети.","tr":"Allah\\'a en sevimli yerler mescitlerdir.","ar":"أَحَبُّ الْبِلاَدِ إِلَى اللَّهِ مَسَاجِدُهَا"},"src":{"az":"Muslim 671","en":"Muslim 671","ru":"Муслим 671","tr":"Müslim 671","ar":"مسلم 671"}},{"id":1424,"t":{"az":"Allaha ən mənfur yerlər bazarlarıdır.","en":"The most hated places to Allah are the markets.","ru":"Самые ненавистные Аллаху места — рынки.","tr":"Allah\\'a en sevimsiz yerler çarşılarıdır.","ar":"وَأَبْغَضُ الْبِلاَدِ إِلَى اللَّهِ أَسْوَاقُهَا"},"src":{"az":"Muslim 671","en":"Muslim 671","ru":"Муслим 671","tr":"Müslim 671","ar":"مسلم 671"}},{"id":1428,"t":{"az":"Dəfinədə beşdə bir (xüms) var.","en":"In buried treasure, one-fifth is due.","ru":"В кладе — пятая часть.","tr":"Definede beşte bir (humus) vardır.","ar":"فِي الرِّكَازِ الْخُمُسُ"},"src":{"az":"Buxari 1499","en":"Bukhari 1499","ru":"Бухари 1499","tr":"Buhârî 1499","ar":"البخاري 1499"}},{"id":1429,"t":{"az":"Allahım, nəfsimə çox zülm etdim, günahları yalnız Sən bağışlayarsan.","en":"O Allah, I have greatly wronged myself and none forgives sins but You.","ru":"О Аллах, я много притеснил себя, и никто не прощает грехи, кроме Тебя.","tr":"Allah\\'ım, nefsime çok zulmettim, günahları ancak Sen bağışlarsın.","ar":"اللَّهُمَّ إِنِّي ظَلَمْتُ نَفْسِي ظُلْمًا كَثِيرًا وَلاَ يَغْفِرُ الذُّنُوبَ إِلاَّ أَنْتَ"},"src":{"az":"Buxari 834","en":"Bukhari 834","ru":"Бухари 834","tr":"Buhârî 834","ar":"البخاري 834"}},{"id":1430,"t":{"az":"Qul qardaşına kömək etdikcə Allah da ona kömək edər.","en":"Allah continues to help the servant as long as the servant helps his brother.","ru":"Аллах помогает рабу, пока тот помогает своему брату.","tr":"Kul kardeşine yardım ettiği sürece Allah da ona yardım eder.","ar":"مَا يَزَالُ اللَّهُ فِي عَوْنِ الْعَبْدِ مَا كَانَ الْعَبْدُ فِي عَوْنِ أَخِيهِ"},"src":{"az":"Muslim 2699","en":"Muslim 2699","ru":"Муслим 2699","tr":"Müslim 2699","ar":"مسلم 2699"}},{"id":1432,"t":{"az":"Adəm oğluna belini dik tutan bir neçə loğma kifayətdir.","en":"It is enough for the son of Adam to eat a few morsels to keep his back straight.","ru":"Сыну Адама достаточно нескольких кусочков, чтобы поддержать спину.","tr":"Âdemoğluna belini dik tutan birkaç lokma yeter.","ar":"مَا مَلَأَ ابْنُ آدَمَ وِعَاءً شَرًّا مِنْ بَطْنِهِ بِحَسْبِ ابْنِ آدَمَ لُقَيْمَاتٌ يُقِمْنَ صُلْبَهُ"},"src":{"az":"Tirmizi 2380","en":"Tirmidhi 2380","ru":"Тирмизи 2380","tr":"Tirmizî 2380","ar":"الترمذي 2380"}},{"id":1433,"t":{"az":"Cənnət əhli cənnətə girdikdə Allah deyər: Bir şey istəyirsiniz ki, artırım?","en":"When the people of Paradise enter Paradise, Allah will say: Do you want anything more?","ru":"Когда обитатели Рая войдут в Рай, Аллах скажет: Хотите ли чего-то, что Я вам прибавлю?","tr":"Cennet ehli cennete girdiğinde Allah: Bir şey daha ister misiniz ki artırayım? der.","ar":"إِذَا دَخَلَ أَهْلُ الْجَنَّةِ الْجَنَّةَ يَقُولُ اللَّهُ تُرِيدُونَ شَيْئًا أَزِيدُكُمْ"},"src":{"az":"Muslim 2829","en":"Muslim 2829","ru":"Муслим 2829","tr":"Müslim 2829","ar":"مسلم 2829"}},{"id":1441,"t":{"az":"Yalnız iki şeydə qibtə var: Allahın mal verib haqq yolda xərcləyən adam.","en":"There is no envy except in two cases: a man whom Allah gave wealth and he spends it righteously.","ru":"Завидовать можно лишь двоим: тому, кому Аллах дал имущество и он тратит его на истину.","tr":"Yalnızca iki şeyde gıpta vardır: Allah\\'ın mal verip onu hak yolda harcayan adam.","ar":"لاَ حَسَدَ إِلاَّ فِي اثْنَتَيْنِ رَجُلٌ آتَاهُ اللَّهُ مَالاً فَسُلِّطَ عَلَى هَلَكَتِهِ فِي الْحَقِّ"},"src":{"az":"Buxari 73","en":"Bukhari 73","ru":"Бухари 73","tr":"Buhârî 73","ar":"البخاري 73"}},{"id":1442,"t":{"az":"Oruc Mənimdir, Mən onu mükafatlandıraram; qulum Mənim üçün şəhvətini və yeməyini tərk edir.","en":"Fasting is for Me and I reward it; he leaves his desires and food for My sake.","ru":"Пост — для Меня, и Я воздам за него; раб оставляет свои желания и еду ради Меня.","tr":"Oruç Benimdir, onu Ben mükâfatlandırırım; kulum Benim için şehvetini ve yemeğini bırakır.","ar":"الصَّوْمُ لِي وَأَنَا أَجْزِي بِهِ يَدَعُ شَهْوَتَهُ وَطَعَامَهُ مِنْ أَجْلِي"},"src":{"az":"Buxari 1894","en":"Bukhari 1894","ru":"Бухари 1894","tr":"Buhârî 1894","ar":"البخاري 1894"}},{"id":1443,"t":{"az":"Miskin bir-iki loğma ilə geri qaytarılan dilənçi deyil.","en":"The needy is not the one who is turned away by a morsel or two.","ru":"Бедняк — не тот, кого отправляют прочь с кусочком-двумя.","tr":"Miskin, bir iki lokmayla geri çevrilen dilenci değildir.","ar":"لَيْسَ الْمِسْكِينُ بِالطَّوَّافِ الَّذِي تَرُدُّهُ اللُّقْمَةُ وَاللُّقْمَتَانِ"},"src":{"az":"Buxari 1479","en":"Bukhari 1479","ru":"Бухари 1479","tr":"Buhârî 1479","ar":"البخاري 1479"}},{"id":1448,"t":{"az":"Ölüm alaca qoç şəklində gətirilər və cənnətlə cəhənnəm arasında kəsilər.","en":"Death will be brought in the form of a spotted ram and slaughtered between Paradise and Hell.","ru":"Смерть будет приведена в образе пёстрого барана и зарезана между Раем и адом.","tr":"Ölüm alacalı bir koç şeklinde getirilip cennetle cehennem arasında kesilir.","ar":"يُؤْتَى بِالْمَوْتِ كَهَيْئَةِ كَبْشٍ أَمْلَحَ فَيُذْبَحُ بَيْنَ الْجَنَّةِ وَالنَّارِ"},"src":{"az":"Buxari 6548","en":"Bukhari 6548","ru":"Бухари 6548","tr":"Buhârî 6548","ar":"البخاري 6548"}},{"id":1451,"t":{"az":"İki xüsusiyyət münafiqda birləşməz: gözəl görünüş və dində fiqh.","en":"Two traits never combine in a hypocrite: good conduct and understanding of the religion.","ru":"Две черты не совместимы в лицемере: благопристойность и понимание религии.","tr":"İki özellik münafıkta bir araya gelmez: güzel semt ve dinde fıkıh.","ar":"خَصْلَتَانِ لاَ تَجْتَمِعَانِ فِي مُنَافِقٍ حُسْنُ سَمْتٍ وَلاَ فِقْهٌ فِي الدِّينِ"},"src":{"az":"Tirmizi 2684","en":"Tirmidhi 2684","ru":"Тирмизи 2684","tr":"Tirmizî 2684","ar":"الترمذي 2684"}},{"id":1452,"t":{"az":"İnsana yalan olaraq eşitdiyi hər şeyi söyləməsi kifayətdir.","en":"It is enough for a person to be a liar that he narrates everything he hears.","ru":"Человеку достаточно лжи — передавать всё, что слышит.","tr":"Kişiye yalancılık olarak duyduğu her şeyi söylemesi yeter.","ar":"كَفَى بِالْمَرْءِ كَذِبًا أَنْ يُحَدِّثَ بِكُلِّ مَا سَمِعَ"},"src":{"az":"Muslim, Müqəddimə 5","en":"Muslim, Muqaddimah 5","ru":"Муслим, Мукаддима 5","tr":"Müslim, Mukaddime 5","ar":"مسلم، المقدمة 5"}},{"id":1453,"t":{"az":"Namaz qılan Rəbbi ilə münacaat edir.","en":"The one praying is in private conversation with his Lord.","ru":"Молящийся ведёт сокровенную беседу со своим Господом.","tr":"Namaz kılan kişi Rabbiyle münacaat eder.","ar":"إِنَّ الْمُصَلِّيَ يُنَاجِي رَبَّهُ"},"src":{"az":"Buxari 531","en":"Bukhari 531","ru":"Бухари 531","tr":"Buhârî 531","ar":"البخاري 531"}},{"id":1454,"t":{"az":"Kimin əsr namazı qaçarsa, sanki ailəsi və malı əlindən alınmışdır.","en":"Whoever misses the Asr prayer, it is as if his family and wealth were taken.","ru":"Кто пропустил молитву Аср — как будто лишился семьи и имущества.","tr":"Kimin ikindi namazı kaçarsa, sanki ailesi ve malı elinden alınmıştır.","ar":"مَنْ فَاتَتْهُ صَلاَةُ الْعَصْرِ فَكَأَنَّمَا وُتِرَ أَهْلَهُ وَمَالَهُ"},"src":{"az":"Buxari 552","en":"Bukhari 552","ru":"Бухари 552","tr":"Buhârî 552","ar":"البخاري 552"}},{"id":1459,"t":{"az":"Allahım, Səndən faydalı elm, pak ruzi və qəbul olunan əməl istəyirəm.","en":"O Allah, I ask You for beneficial knowledge, wholesome provision, and accepted deeds.","ru":"О Аллах, я прошу Тебя о полезном знании, благом пропитании и принятом деле.","tr":"Allah\\'ım, Senden faydalı ilim, temiz rızık ve makbul amel isterim.","ar":"اللَّهُمَّ إِنِّي أَسْأَلُكَ عِلْمًا نَافِعًا وَرِزْقًا طَيِّبًا وَعَمَلاً مُتَقَبَّلاً"},"src":{"az":"İbn Macə 925","en":"Ibn Majah 925","ru":"Ибн Маджа 925","tr":"İbn Mâce 925","ar":"ابن ماجه 925"}},{"id":1460,"t":{"az":"Kim öz yetimini və ya başqasının yetimini himayə edərsə, mən onunla cənnətdə belə olacağıq.","en":"Whoever sponsors an orphan, his or another\\'s, we will be like these two in Paradise.","ru":"Кто возьмёт на попечение сироту, своего или чужого — мы будем в Раю как эти два.","tr":"Kim kendi yetimini veya başkasının yetimini himaye ederse, cennette ben ve o böyle olacağız.","ar":"مَنْ كَفَلَ يَتِيمًا لَهُ أَوْ لِغَيْرِهِ أَنَا وَهُوَ كَهَاتَيْنِ فِي الْجَنَّةِ"},"src":{"az":"Muslim 2983","en":"Muslim 2983","ru":"Муслим 2983","tr":"Müslim 2983","ar":"مسلم 2983"}},{"id":1462,"t":{"az":"Sizin üçün ən çox qorxduğum şey dünyanın sizə açılmasıdır.","en":"What I fear most for you is that the world will be spread before you.","ru":"Больше всего я боюсь для вас того, что мир раскроется перед вами.","tr":"Sizin için en çok korktuğum şey, dünyanın önünüze serilmesidir.","ar":"إِنَّ أَخْوَفَ مَا أَخَافُ عَلَيْكُمْ أَنْ تُبْسَطَ عَلَيْكُمُ الدُّنْيَا"},"src":{"az":"Buxari 3158","en":"Bukhari 3158","ru":"Бухари 3158","tr":"Buhârî 3158","ar":"البخاري 3158"}},{"id":1465,"t":{"az":"Yağış gördüyünüzdə \"Allahım, faydalı yağış yağdır\" deyin.","en":"When you see rain, say: O Allah, make it a beneficial rain.","ru":"Когда увидите дождь, говорите: О Аллах, пошли полезный дождь.","tr":"Yağmur gördüğünüzde \"Allah\\'ım, faydalı bir yağmur yağdır\" deyin.","ar":"إِذَا رَأَيْتُمُ الْمَطَرَ فَقُولُوا اللَّهُمَّ صَيِّبًا نَافِعًا"},"src":{"az":"Buxari 1032","en":"Bukhari 1032","ru":"Бухари 1032","tr":"Buhârî 1032","ar":"البخاري 1032"}},{"id":1467,"t":{"az":"Yaxşılıq gözəl əxlaqdir, günah isə vicdanını narahat edən və insanların bilməsini istəmədiyindir.","en":"Righteousness is good character, and sin is what disturbs your soul and you hate for people to know about.","ru":"Праведность — это хороший нрав, а грех — то, что беспокоит душу и что ты не хочешь, чтобы люди узнали.","tr":"İyilik güzel ahlaktır, günah ise içini rahatsız eden ve insanların bilmesini istemediğindir.","ar":"الْبِرُّ حُسْنُ الْخُلُقِ وَالإِثْمُ مَا حَاكَ فِي نَفْسِكَ وَكَرِهْتَ أَنْ يَطَّلِعَ عَلَيْهِ النَّاسُ"},"src":{"az":"Muslim 2553","en":"Muslim 2553","ru":"Муслим 2553","tr":"Müslim 2553","ar":"مسلم 2553"}},{"id":1468,"t":{"az":"Kim namazda abdəsti pozularsa, burnunu tutsun və çıxsın.","en":"Whoever breaks his ablution during prayer, let him hold his nose and leave.","ru":"Кто нарушит омовение во время молитвы, пусть прикроет нос и выйдет.","tr":"Kim namazda abdesti bozulursa, burnunu tutsun ve çıksın.","ar":"مَنْ أَحْدَثَ فِي صَلاَتِهِ فَلْيُمْسِكْ عَلَى أَنْفِهِ ثُمَّ لْيَنْصَرِفْ"},"src":{"az":"Əbu Davud 1114","en":"Abu Dawud 1114","ru":"Абу Дауд 1114","tr":"Ebû Dâvûd 1114","ar":"أبو داود 1114"}},{"id":1469,"t":{"az":"Biriniz namazda uyuqlasa, uyxusu gedənə qədər yatsın.","en":"If one of you becomes drowsy during prayer, let him sleep until the drowsiness leaves.","ru":"Если один из вас задремал во время молитвы, пусть поспит, пока сонливость не пройдёт.","tr":"Biriniz namazda uyuklarsa, uykusu gidinceye kadar uyusun.","ar":"إِذَا نَعَسَ أَحَدُكُمْ فِي الصَّلاَةِ فَلْيَنَمْ حَتَّى يَذْهَبَ عَنْهُ النَّوْمُ"},"src":{"az":"Buxari 212","en":"Bukhari 212","ru":"Бухари 212","tr":"Buhârî 212","ar":"البخاري 212"}},{"id":1473,"t":{"az":"Heç biriniz özü üçün istədiyi xeyri qardaşı üçün istəmədikçə imanı kamil olmaz.","en":"None of you will reach full faith until he loves for his brother what he loves for himself of good.","ru":"Никто не достигнет полной веры, пока не пожелает брату того блага, что желает себе.","tr":"Sizden biriniz kendisi için istediği hayrı kardeşi için istemedikçe imanı kâmil olmaz.","ar":"لَنْ يَبْلُغَ أَحَدُكُمُ الْإِيمَانَ حَتَّى يُحِبَّ لأَخِيهِ مَا يُحِبُّ لِنَفْسِهِ مِنَ الْخَيْرِ"},"src":{"az":"Nəsai 5017","en":"An-Nasa'i 5017","ru":"ан-Насаи 5017","tr":"Nesâî 5017","ar":"النسائي 5017"}},{"id":1474,"t":{"az":"Allahım, günahlarımın hamısını, kiçik və böyüyünü, birincisini və sonuncusunu bağışla.","en":"O Allah, forgive all my sins, small and great, first and last.","ru":"О Аллах, прости мне все мои грехи, малые и великие, первые и последние.","tr":"Allah\\'ım, günahlarımın tamamını, küçüğünü ve büyüğünü, ilkini ve sonuncusunu bağışla.","ar":"اللَّهُمَّ اغْفِرْ لِي ذَنْبِي كُلَّهُ دِقَّهُ وَجِلَّهُ وَأَوَّلَهُ وَآخِرَهُ"},"src":{"az":"Muslim 483","en":"Muslim 483","ru":"Муслим 483","tr":"Müslim 483","ar":"مسلم 483"}},{"id":1477,"t":{"az":"Kim Rəbb olaraq Allahdan, din olaraq İslamdan, Rəsul olaraq Muhəmməddən razı olsa, imanın dadını dadar.","en":"Whoever is pleased with Allah as Lord, Islam as religion, and Muhammad as Messenger has tasted faith.","ru":"Кто доволен Аллахом как Господом, Исламом как религией и Мухаммадом как Посланником — вкусил сладость веры.","tr":"Kim Rab olarak Allah\\'tan, din olarak İslam\\'dan, Resul olarak Muhammed\\'den razı olursa, imanın tadını tatmıştır.","ar":"مَنْ رَضِيَ بِاللَّهِ رَبًّا وَبِالإِسْلاَمِ دِينًا وَبِمُحَمَّدٍ رَسُولاً ذَاقَ طَعْمَ الإِيمَانِ"},"src":{"az":"Muslim 34","en":"Muslim 34","ru":"Муслим 34","tr":"Müslim 34","ar":"مسلم 34"}},{"id":1478,"t":{"az":"Cənnət əhli üstdəki köşklərdəkiləri ulduz gördüyünüz kimi görər.","en":"The people of Paradise will see those in the upper rooms as you see the stars.","ru":"Обитатели Рая будут видеть тех, кто в верхних покоях, как вы видите звёзды.","tr":"Cennet ehli üstlerindeki köşklerin ehlini, yıldızı gördüğünüz gibi görür.","ar":"إِنَّ أَهْلَ الْجَنَّةِ لَيَتَرَاءَوْنَ أَهْلَ الْغُرَفِ مِنْ فَوْقِهِمْ كَمَا تَتَرَاءَوْنَ الْكَوْكَبَ"},"src":{"az":"Buxari 3256","en":"Bukhari 3256","ru":"Бухари 3256","tr":"Buhârî 3256","ar":"البخاري 3256"}},{"id":1479,"t":{"az":"Allahın dolaşan mələkləri var, ümmətimin salamını mənə çatdırırlar.","en":"Allah has roaming angels who convey the greetings of my ummah to me.","ru":"У Аллаха есть странствующие ангелы, передающие мне приветствия от моей уммы.","tr":"Allah\\'ın dolaşan melekleri vardır, ümmetimin selamını bana ulaştırırlar.","ar":"إِنَّ لِلَّهِ مَلاَئِكَةً سَيَّاحِينَ يُبَلِّغُونِي عَنْ أُمَّتِي السَّلاَمَ"},"src":{"az":"Nəsai 1282","en":"An-Nasa'i 1282","ru":"ан-Насаи 1282","tr":"Nesâî 1282","ar":"النسائي 1282"}},{"id":1480,"t":{"az":"Allah səfər edəndən orucu və namazın yarısını qaldırmışdır.","en":"Allah has relieved the traveler of fasting and half the prayer.","ru":"Аллах снял с путешественника пост и половину молитвы.","tr":"Allah, yolcudan orucu ve namazın yarısını kaldırmıştır.","ar":"إِنَّ اللَّهَ وَضَعَ عَنِ الْمُسَافِرِ الصَّوْمَ وَشَطْرَ الصَّلاَةِ"},"src":{"az":"Tirmizi 715","en":"Tirmidhi 715","ru":"Тирмизи 715","tr":"Tirmizî 715","ar":"الترمذي 715"}},{"id":1481,"t":{"az":"Müsəlman insanların dilindən və əlindən salamat olduğu, mühacir Allahın qadağan etdiyini tərk edəndir.","en":"A Muslim is one from whose tongue and hand people are safe, and the emigrant is one who abandons what Allah forbade.","ru":"Мусульманин — тот, от языка и рук которого люди в безопасности, переселенец — тот, кто оставил запретное.","tr":"Müslüman, insanların dilinden ve elinden selamette olduğu kişidir; muhacir, Allah\\'ın yasakladığını terk edendir.","ar":"الْمُسْلِمُ مَنْ سَلِمَ النَّاسُ مِنْ لِسَانِهِ وَيَدِهِ وَالْمُهَاجِرُ مَنْ هَجَرَ مَا نَهَى اللَّهُ عَنْهُ"},"src":{"az":"Buxari 10","en":"Bukhari 10","ru":"Бухари 10","tr":"Buhârî 10","ar":"البخاري 10"}},{"id":1487,"t":{"az":"Hər aydan üç gün və Ramazandan Ramazana oruc bütün ömrü oruc tutmaqdır.","en":"Three days from each month and Ramadan to Ramadan — that is fasting the entire year.","ru":"Три дня каждого месяца и от Рамадана до Рамадана — это пост всей жизни.","tr":"Her aydan üç gün ve Ramazandan Ramazana oruç, bütün yıl oruç tutmaktır.","ar":"ثَلاَثٌ مِنْ كُلِّ شَهْرٍ وَرَمَضَانُ إِلَى رَمَضَانَ فَهَذَا صِيَامُ الدَّهْرِ"},"src":{"az":"Muslim 1162","en":"Muslim 1162","ru":"Муслим 1162","tr":"Müslim 1162","ar":"مسلم 1162"}},{"id":1490,"t":{"az":"Kimin artıq miniyə var, miniyə olmayana versin.","en":"Whoever has an extra mount, let him give it to one who has none.","ru":"У кого есть лишнее верховое животное — пусть даст тому, у кого нет.","tr":"Kimin fazla bineği varsa, bineği olmayana versin.","ar":"مَنْ كَانَ مَعَهُ فَضْلُ ظَهْرٍ فَلْيَعُدْ بِهِ عَلَى مَنْ لاَ ظَهْرَ لَهُ"},"src":{"az":"Muslim 1728","en":"Muslim 1728","ru":"Муслим 1728","tr":"Müslim 1728","ar":"مسلم 1728"}},{"id":1493,"t":{"az":"Hər birinizin cəhənnəm və cənnətdəki yeri yazılmışdır.","en":"There is no one among you whose seat in Hell and seat in Paradise has not been written.","ru":"Нет среди вас того, чьё место в аду и место в Раю не было бы записано.","tr":"Her birinizin cehennemdeki ve cennetteki yeri yazılmıştır.","ar":"مَا مِنْكُمْ مِنْ أَحَدٍ إِلاَّ وَقَدْ كُتِبَ مَقْعَدُهُ مِنَ النَّارِ وَمَقْعَدُهُ مِنَ الْجَنَّةِ"},"src":{"az":"Buxari 4949","en":"Bukhari 4949","ru":"Бухари 4949","tr":"Buhârî 4949","ar":"البخاري 4949"}},{"id":1494,"t":{"az":"Evlərinizi qəbrə çevirməyin, qəbrimi bayram etməyin, mənə salavat gətirin.","en":"Do not turn your houses into graves, do not make my grave a festival, and send blessings upon me.","ru":"Не превращайте дома в могилы, не делайте мою могилу праздником, а посылайте на меня благословения.","tr":"Evlerinizi kabirlere çevirmeyin, kabrimi bayram yapmayın, bana salavat getirin.","ar":"لاَ تَجْعَلُوا بُيُوتَكُمْ قُبُورًا وَلاَ تَجْعَلُوا قَبْرِي عِيدًا وَصَلُّوا عَلَيَّ"},"src":{"az":"Əbu Davud 2042","en":"Abu Dawud 2042","ru":"Абу Дауд 2042","tr":"Ebû Dâvûd 2042","ar":"أبو داود 2042"}},{"id":1495,"t":{"az":"Kim namazını yatıb qalsa və ya unudsa, xatırladığı zaman qılsın.","en":"Whoever sleeps through a prayer or forgets it, let him pray it when he remembers.","ru":"Кто проспал молитву или забыл её — пусть совершит, когда вспомнит.","tr":"Kim namazını uyuyarak veya unutarak kaçırırsa, hatırladığında kılsın.","ar":"مَنْ نَامَ عَنْ صَلاَةٍ أَوْ نَسِيَهَا فَلْيُصَلِّهَا إِذَا ذَكَرَهَا"},"src":{"az":"Buxari 597","en":"Bukhari 597","ru":"Бухари 597","tr":"Buhârî 597","ar":"البخاري 597"}},{"id":1496,"t":{"az":"Allah təala buyurur: Mən qulumun Mənim haqqımdakı zənni yanındayam, istədiyini zənn etsin.","en":"Allah says: I am as My servant thinks of Me, so let him think of Me what he wishes.","ru":"Аллах говорит: Я таков, как думает обо Мне Мой раб, пусть думает обо Мне, что хочет.","tr":"Allah Teâlâ buyurur: Ben kulumun Benim hakkımdaki zannı yanındayım, Benim hakkımda ne dilerse zannetsin.","ar":"إِنَّ اللَّهَ تَعَالَى يَقُولُ أَنَا عِنْدَ ظَنِّ عَبْدِي بِي فَلْيَظُنَّ بِي مَا شَاءَ"},"src":{"az":"Əhməd 16016","en":"Ahmad 16016","ru":"Ахмад 16016","tr":"Ahmed 16016","ar":"أحمد 16016"}},{"id":1497,"t":{"az":"İnsanlarla qarışıb əziyyətlərinə səbr edən mömin daha çox savab qazanar.","en":"The believer who mixes with people and endures their harm has a greater reward.","ru":"Верующий, который общается с людьми и терпит их обиды — у того великая награда.","tr":"İnsanlarla karışıp eziyetlerine sabreden mümin, daha büyük sevap kazanır.","ar":"الْمُؤْمِنُ الَّذِي يُخَالِطُ النَّاسَ وَيَصْبِرُ عَلَى أَذَاهُمْ أَعْظَمُ أَجْرًا"},"src":{"az":"İbn Macə 4032","en":"Ibn Majah 4032","ru":"Ибн Маджа 4032","tr":"İbn Mâce 4032","ar":"ابن ماجه 4032"}},{"id":1499,"t":{"az":"Kim beş vaxt namazı dəstəmazı və vaxtları ilə qoruyarsa, Allahın onu bağışlayacağına dair əhdi var.","en":"Whoever preserves the five prayers with their ablution and times, he has a covenant with Allah for forgiveness.","ru":"Кто хранит пять молитв с их омовением и временем — у того завет с Аллахом о прощении.","tr":"Kim beş vakit namazı abdestiyle ve vakitleriyle muhafaza ederse, Allah katında bağışlanacağına dair ahdi vardır.","ar":"مَنْ حَافَظَ عَلَى الصَّلَوَاتِ الْخَمْسِ عَلَى وُضُوئِهِنَّ وَمَوَاقِيتِهِنَّ كَانَ لَهُ عِنْدَ اللَّهِ عَهْدٌ أَنْ يَغْفِرَ لَهُ"},"src":{"az":"Əbu Davud 425","en":"Abu Dawud 425","ru":"Абу Дауд 425","tr":"Ebû Dâvûd 425","ar":"أبو داود 425"}},{"id":1501,"t":{"az":"Biriniz asqırdıqda \"Əlhəmdulilləh\" desin, qardaşı və ya dostu ona \"Yərhamukəllah\" desin. O da \"Yəhdikumullahu və yuslihu baləkum\" desin.","en":"When one of you sneezes, let him say \"Alhamdulillah,\" and let his brother or companion say \"Yarhamukallah.\" Then let him say \"Yahdikumullah wa yuslih balakum.\"","ru":"Когда кто-то из вас чихнёт, пусть скажет «Альхамдулиллях», а его брат или товарищ пусть скажет ему «Ярхамукаллах». Тогда пусть он скажет «Яхдикумуллаху ва юслих балякум».","tr":"Biriniz aksırdığında \"Elhamdülillah\" desin, kardeşi veya arkadaşı da \"Yerhamükallah\" desin. O da \"Yehdîkümullahu ve yuslihu bâleküm\" desin.","ar":"إِذَا عَطَسَ أَحَدُكُمْ فَلْيَقُلْ الْحَمْدُ لِلَّهِ وَلْيَقُلْ لَهُ أَخُوهُ أَوْ صَاحِبُهُ يَرْحَمُكَ اللَّهُ فَإِذَا قَالَ لَهُ يَرْحَمُكَ اللَّهُ فَلْيَقُلْ يَهْدِيكُمُ اللَّهُ وَيُصْلِحُ بَالَكُمْ"},"src":{"az":"Buxari, Ədəb 126","en":"Bukhari, Adab 126","ru":"Бухари, Адаб 126","tr":"Buhârî, Edeb 126","ar":"البخاري، الأدب 126"}},{"id":1503,"t":{"az":"Allah asqırığı sevər, əsnəməni isə xoşlamaz. Kim asqırıb Allaha həmd etsə, eşidən hər müsəlmanın ona dua etməsi vacibdir. Əsnəmə isə şeytandandır, bacardıqca onu geri qaytarsın.","en":"Allah loves sneezing and dislikes yawning. When one sneezes and praises Allah, it is the duty of every Muslim who hears him to respond. As for yawning, it is from Satan, so one should suppress it as much as possible.","ru":"Аллах любит чихание и не любит зевоту. Когда кто-то чихнёт и восхвалит Аллаха, каждый мусульманин, который это слышит, обязан ответить ему. Что касается зевоты, она от шайтана, и пусть подавляет её, насколько может.","tr":"Allah aksırmayı sever, esnemeden hoşlanmaz. Kim aksırıp Allah'a hamd ederse onu duyan her Müslümanın ona dua etmesi vaciptir. Esnemeye gelince o şeytandandır, gücü yettiğince onu engellesin.","ar":"إِنَّ اللَّهَ يُحِبُّ الْعُطَاسَ وَيَكْرَهُ التَّثَاؤُبَ فَإِذَا عَطَسَ فَحَمِدَ اللَّهَ فَحَقٌّ عَلَى كُلِّ مُسْلِمٍ سَمِعَهُ أَنْ يُشَمِّتَهُ وَأَمَّا التَّثَاؤُبُ فَإِنَّمَا هُوَ مِنَ الشَّيْطَانِ فَلْيَرُدَّهُ مَا اسْتَطَاعَ"},"src":{"az":"Buxari, Ədəb 128","en":"Bukhari, Adab 128","ru":"Бухари, Адаб 128","tr":"Buhârî, Edeb 128","ar":"البخاري، الأدب 128"}},{"id":1504,"t":{"az":"Biriniz əsnədikdə əli ilə ağzını tutsun, çünki şeytan içəri girər.","en":"When one of you yawns, let him hold his hand over his mouth, for Satan enters.","ru":"Когда кто-то из вас зевает, пусть прикроет рот рукой, ибо шайтан входит.","tr":"Biriniz esnediğinde eliyle ağzını tutsun, çünkü şeytan girer.","ar":"إِذَا تَثَاءَبَ أَحَدُكُمْ فَلْيُمْسِكْ بِيَدِهِ عَلَى فِيهِ فَإِنَّ الشَّيْطَانَ يَدْخُلُ"},"src":{"az":"Muslim, Zühd 56","en":"Muslim, Zuhd 56","ru":"Муслим, Зухд 56","tr":"Müslim, Zühd 56","ar":"مسلم، الزهد 56"}},{"id":1506,"t":{"az":"Minən piyadaya, piyada oturana, azlıq çoxluğa salam verər.","en":"The rider should greet the pedestrian, the pedestrian should greet the one sitting, and the smaller group should greet the larger group.","ru":"Всадник приветствует пешего, пеший приветствует сидящего, и меньшая группа приветствует большую.","tr":"Binici yayaya, yaya oturana, azınlık çoğunluğa selam verir.","ar":"يُسَلِّمُ الرَّاكِبُ عَلَى الْمَاشِي وَالْمَاشِي عَلَى الْقَاعِدِ وَالْقَلِيلُ عَلَى الْكَثِيرِ"},"src":{"az":"Buxari, İsti'zan 5","en":"Bukhari, Isti'dhan 5","ru":"Бухари, Истизан 5","tr":"Buhârî, İsti'zân 5","ar":"البخاري، الاستئذان 5"}},{"id":1507,"t":{"az":"İnsanların Allaha ən yaxın olanı salam verməyə birinci başlayandır.","en":"The closest of people to Allah is the one who initiates the greeting of peace.","ru":"Ближе всех к Аллаху тот, кто первым приветствует.","tr":"İnsanların Allah'a en yakın olanı selama ilk başlayandır.","ar":"أَوْلَى النَّاسِ بِاللَّهِ مَنْ بَدَأَهُمْ بِالسَّلاَمِ"},"src":{"az":"Əbu Davud 5197","en":"Abu Dawud 5197","ru":"Абу Дауд 5197","tr":"Ebû Dâvûd 5197","ar":"أبو داود 5197"}},{"id":1508,"t":{"az":"İman etməyincə Cənnətə girməzsiniz, bir-birinizi sevməyincə iman etmiş olmazsınız. Sizə bir şey göstərimmi ki, etdiyinizdə bir-birinizi sevəsiniz? Aranızda salamı yayın.","en":"You will not enter Paradise until you believe, and you will not believe until you love one another. Shall I tell you something which, if you do it, you will love one another? Spread salam among yourselves.","ru":"Вы не войдёте в Рай, пока не уверуете, и не уверуете, пока не полюбите друг друга. Не указать ли мне вам на то, что если вы будете делать, то полюбите друг друга? Распространяйте салям между собой.","tr":"İman etmedikçe Cennete giremezsiniz, birbirinizi sevmedikçe iman etmiş olmazsınız. Size bir şey göstereyim mi ki yaptığınızda birbirinizi seversiniz? Aranızda selamı yayın.","ar":"لاَ تَدْخُلُونَ الْجَنَّةَ حَتَّى تُؤْمِنُوا وَلاَ تُؤْمِنُوا حَتَّى تَحَابُّوا أَوَلاَ أَدُلُّكُمْ عَلَى شَيْءٍ إِذَا فَعَلْتُمُوهُ تَحَابَبْتُمْ أَفْشُوا السَّلاَمَ بَيْنَكُمْ"},"src":{"az":"Muslim, İman 93","en":"Muslim, Iman 93","ru":"Муслим, Иман 93","tr":"Müslim, İman 93","ar":"مسلم، الإيمان 93"}},{"id":1509,"t":{"az":"Biriniz məclisə çatdıqda salam versin. Qalxmaq istədikdə də salam versin. Birinci salam axırıncıdan daha haqlı deyildir.","en":"When one of you arrives at a gathering, let him give salam. When he wants to leave, let him give salam. The first is not more deserving than the last.","ru":"Когда кто-то из вас придёт в собрание, пусть поприветствует. Когда захочет уйти, тоже пусть поприветствует. Первое приветствие не важнее последнего.","tr":"Biriniz meclise vardığında selam versin. Kalkmak istediğinde de selam versin. İlk selam sonuncudan daha haklı değildir.","ar":"إِذَا انْتَهَى أَحَدُكُمْ إِلَى الْمَجْلِسِ فَلْيُسَلِّمْ فَإِذَا أَرَادَ أَنْ يَقُومَ فَلْيُسَلِّمْ فَلَيْسَتِ الأُولَى بِأَحَقَّ مِنَ الآخِرَةِ"},"src":{"az":"Əbu Davud 5208","en":"Abu Dawud 5208","ru":"Абу Дауд 5208","tr":"Ebû Dâvûd 5208","ar":"أبو داود 5208"}},{"id":1510,"t":{"az":"Heç biriniz bir adamı yerindən qaldırıb onun yerinə oturmasın, əksinə genişlənin və yer açın.","en":"None of you should make a man get up from his seat and then sit in it. Rather, make room and spread out.","ru":"Никто из вас не должен поднимать человека с его места, а затем садиться на него. Напротив, расступитесь и дайте место.","tr":"Hiçbiriniz bir adamı yerinden kaldırıp onun yerine oturmasın, aksine genişleyin ve yer açın.","ar":"لاَ يُقِيمَنَّ أَحَدُكُمْ رَجُلاً مِنْ مَجْلِسِهِ ثُمَّ يَجْلِسُ فِيهِ وَلَكِنْ تَوَسَّعُوا وَتَفَسَّحُوا"},"src":{"az":"Buxari, İsti'zan 31","en":"Bukhari, Isti'dhan 31","ru":"Бухари, Истизан 31","tr":"Buhârî, İsti'zân 31","ar":"البخاري، الاستئذان 31"}},{"id":1511,"t":{"az":"Biriniz yerindən qalxıb sonra geri qayıtsa, o yerə daha çox haqqı var.","en":"When one of you gets up from his seat and then returns to it, he has more right to it.","ru":"Когда кто-то из вас встанет со своего места, а затем вернётся к нему, он имеет больше прав на него.","tr":"Biriniz yerinden kalkıp sonra geri dönerse o yere daha çok hakkı vardır.","ar":"إِذَا قَامَ أَحَدُكُمْ مِنْ مَجْلِسِهِ ثُمَّ رَجَعَ إِلَيْهِ فَهُوَ أَحَقُّ بِهِ"},"src":{"az":"Muslim, Salam 30","en":"Muslim, Salam 30","ru":"Муслим, Салям 30","tr":"Müslim, Selâm 30","ar":"مسلم، السلام 30"}},{"id":1512,"t":{"az":"Üç nəfər olduqda ikisi üçüncünü kənara qoyub pıçıldaşmasın, çünki bu onu kədərləndirir.","en":"When there are three people, two should not whisper to each other excluding the third, for that would sadden him.","ru":"Когда их трое, двое не должны шептаться, исключая третьего, ибо это опечалит его.","tr":"Üç kişi olduklarında ikisi üçüncüyü dışlayarak fısıldaşmasın, çünkü bu onu üzer.","ar":"إِذَا كَانُوا ثَلاَثَةً فَلاَ يَتَنَاجَى اثْنَانِ دُونَ الثَّالِثِ فَإِنَّ ذَلِكَ يُحْزِنُهُ"},"src":{"az":"Buxari, İsti'zan 45","en":"Bukhari, Isti'dhan 45","ru":"Бухари, Истизан 45","tr":"Buhârî, İsti'zân 45","ar":"البخاري، الاستئذان 45"}},{"id":1514,"t":{"az":"Bir qövm bir yerdə oturub Allahı zikr etməz və Peyğəmbərlərinə salavat gətirməzsə, bu onlar üçün əskiklik olar. Allah istəsə onlara əzab verər, istəsə bağışlayar.","en":"No people sit in a gathering without remembering Allah and sending blessings upon their Prophet except it will be a source of regret for them. If He wills, He will punish them, and if He wills, He will forgive them.","ru":"Когда люди сидят в собрании, не поминая Аллаха и не благословляя своего Пророка, это будет для них сожалением. Если пожелает, накажет их, если пожелает, простит.","tr":"Bir topluluk bir yerde oturup Allah'ı zikretmez ve Peygamberlerine salat getirmezlerse bu onlar için bir eksiklik olur. Allah dilerse azap eder, dilerse bağışlar.","ar":"مَا جَلَسَ قَوْمٌ مَجْلِسًا لَمْ يَذْكُرُوا اللَّهَ فِيهِ وَلَمْ يُصَلُّوا عَلَى نَبِيِّهِمْ إِلاَّ كَانَ عَلَيْهِمْ تِرَةً فَإِنْ شَاءَ عَذَّبَهُمْ وَإِنْ شَاءَ غَفَرَ لَهُمْ"},"src":{"az":"Tirmizi 3380","en":"Tirmidhi 3380","ru":"Тирмизи 3380","tr":"Tirmizî 3380","ar":"الترمذي 3380"}},{"id":1515,"t":{"az":"Məclisin kəffarəsi \"Subhanəkə Allahummə və bihəmdikə, əşhədu ən la ilahə illə əntə, əstağfirukə və ətubu ileyk\" deməkdir.","en":"The expiation for a gathering is to say: \"Glory be to You, O Allah, and praise be to You. I bear witness that there is no god but You. I seek Your forgiveness and repent to You.\"","ru":"Искупление собрания — сказать: «Пречист Ты, о Аллах, и хвала Тебе. Свидетельствую, что нет бога, кроме Тебя. Прошу Твоего прощения и каюсь пред Тобой».","tr":"Meclisin kefareti \"Sübhaneke Allahümme ve bihamdike eşhedü en la ilahe illa ente estağfiruke ve etubü ileyke\" demektir.","ar":"كَفَّارَةُ الْمَجْلِسِ أَنْ يَقُولَ سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ أَشْهَدُ أَنْ لاَ إِلَهَ إِلاَّ أَنْتَ أَسْتَغْفِرُكَ وَأَتُوبُ إِلَيْكَ"},"src":{"az":"Əbu Davud 4859","en":"Abu Dawud 4859","ru":"Абу Дауд 4859","tr":"Ebû Dâvûd 4859","ar":"أبو داود 4859"}},{"id":1518,"t":{"az":"Yolların kənarında oturmaqdan çəkinin.","en":"Beware of sitting on the roadsides.","ru":"Остерегайтесь сидения на обочинах дорог.","tr":"Yol kenarlarında oturmaktan sakının.","ar":"إِيَّاكُمْ وَالْجُلُوسَ بِالطُّرُقَاتِ"},"src":{"az":"Muslim, Libas 32","en":"Muslim, Libas 32","ru":"Муслим, Либас 32","tr":"Müslim, Libâs 32","ar":"مسلم، اللباس 32"}},{"id":1519,"t":{"az":"Xəstəni ziyarət edin, acı doydurun və əsiri azad edin.","en":"Visit the sick, feed the hungry, and free the captive.","ru":"Навещайте больного, кормите голодного и освобождайте пленника.","tr":"Hastayı ziyaret edin, açı doyurun ve esiri serbest bırakın.","ar":"عُودُوا الْمَرِيضَ وَأَطْعِمُوا الْجَائِعَ وَفُكُّوا الْعَانِيَ"},"src":{"az":"Buxari, Mərdha 4","en":"Bukhari, Marda 4","ru":"Бухари, Марда 4","tr":"Buhârî, Merdâ 4","ar":"البخاري، المرضى 4"}},{"id":1520,"t":{"az":"Bir müsəlman səhər çağı başqa müsəlmanı ziyarət etsə, axşama qədər yetmiş min mələk ona dua edər. Axşam ziyarət etsə, səhərə qədər yetmiş min mələk ona dua edər.","en":"No Muslim visits a sick Muslim in the morning except that seventy thousand angels pray for him until evening. And if he visits in the evening, seventy thousand angels pray for him until morning.","ru":"Если мусульманин навестит больного мусульманина утром, семьдесят тысяч ангелов будут молиться за него до вечера. А если навестит вечером, семьдесят тысяч ангелов будут молиться за него до утра.","tr":"Bir Müslüman sabahleyin hasta bir Müslümanı ziyaret ederse akşama kadar yetmiş bin melek ona dua eder. Akşam ziyaret ederse sabaha kadar yetmiş bin melek ona dua eder.","ar":"مَا مِنْ مُسْلِمٍ يَعُودُ مُسْلِمًا غُدْوَةً إِلاَّ صَلَّى عَلَيْهِ سَبْعُونَ أَلْفَ مَلَكٍ حَتَّى يُمْسِيَ وَإِنْ عَادَهُ عَشِيَّةً إِلاَّ صَلَّى عَلَيْهِ سَبْعُونَ أَلْفَ مَلَكٍ حَتَّى يُصْبِحَ"},"src":{"az":"Tirmizi 969","en":"Tirmidhi 969","ru":"Тирмизи 969","tr":"Tirmizî 969","ar":"الترمذي 969"}},{"id":1521,"t":{"az":"Bir adam müsəlman qardaşını ziyarət etdikdə oturana qədər Cənnət meyvələri arasında gəzər, oturduqda isə onu rəhmət bürüyər.","en":"When a man visits his sick Muslim brother, he walks among the fruits of Paradise until he sits down, and when he sits, mercy envelops him.","ru":"Когда человек навещает своего больного мусульманского брата, он идёт среди плодов Рая, пока не сядет, а когда сядет, его окутает милость.","tr":"Bir adam hasta Müslüman kardeşini ziyaret ettiğinde oturana kadar Cennet meyveleri arasında yürür, oturduğunda onu rahmet kaplar.","ar":"إِذَا عَادَ الرَّجُلُ أَخَاهُ الْمُسْلِمَ مَشَى فِي خَرَافَةِ الْجَنَّةِ حَتَّى يَجْلِسَ فَإِذَا جَلَسَ غَمَرَتْهُ الرَّحْمَةُ"},"src":{"az":"İbn Macə 1442","en":"Ibn Majah 1442","ru":"Ибн Маджа 1442","tr":"İbn Mâce 1442","ar":"ابن ماجه 1442"}},{"id":1524,"t":{"az":"Ölmək üzrə olanlarınıza \"La ilahə illəllah\" kəlməsini təlqin edin.","en":"Prompt your dying ones to say \"La ilaha illallah.\"","ru":"Подсказывайте вашим умирающим слова «Ля иляха илляллах».","tr":"Ölmek üzere olanlarınıza \"La ilahe illallah\" kelimesini telkin edin.","ar":"لَقِّنُوا مَوْتَاكُمْ لاَ إِلَهَ إِلاَّ اللَّهُ"},"src":{"az":"Muslim, Cənaiz 1","en":"Muslim, Jana'iz 1","ru":"Муслим, Джанаиз 1","tr":"Müslim, Cenâiz 1","ar":"مسلم، الجنائز 1"}},{"id":1526,"t":{"az":"Cənazəni tez aparın. Əgər saleh idisə, onu xeyrə tez çatdırmış olarsınız. Əgər başqa cür idisə, şərri boyunlarınızdan tez endirmiş olarsınız.","en":"Hasten with the funeral. If the deceased was righteous, you are sending it to good. If otherwise, you are putting down evil from your necks.","ru":"Торопитесь с похоронами. Если покойный был праведным, вы несёте его к благу. Если нет, то снимаете зло со своих шей.","tr":"Cenazeyi hızlandırın. Eğer salih idiyse onu hayra çabuk ulaştırmış olursunuz. Değilse şerri omuzlarınızdan çabuk indirmiş olursunuz.","ar":"أَسْرِعُوا بِالْجَنَازَةِ فَإِنْ تَكُ صَالِحَةً فَخَيْرٌ تُقَدِّمُونَهَا إِلَيْهِ وَإِنْ يَكُ سِوَى ذَلِكَ فَشَرٌّ تَضَعُونَهُ عَنْ رِقَابِكُمْ"},"src":{"az":"Buxari, Cənaiz 51","en":"Bukhari, Jana'iz 51","ru":"Бухари, Джанаиз 51","tr":"Buhârî, Cenâiz 51","ar":"البخاري، الجنائز 51"}},{"id":1527,"t":{"az":"Kim cənazə namazına qatılsa, bir qirat savab qazanar. Kim dəfn olunana qədər qalsa, iki qirat qazanar. Soruşdular: İki qirat nədir? Buyurdu: İki böyük dağ qədərdir.","en":"Whoever attends the funeral prayer gets one qirat of reward. Whoever stays until burial gets two qirats. They asked: What are two qirats? He said: Like two great mountains.","ru":"Кто присутствует на погребальной молитве, получит один кират награды. Кто останется до погребения, получит два кирата. Спросили: Что такое два кирата? Он сказал: Как две великие горы.","tr":"Kim cenaze namazına katılırsa bir kırat sevap kazanır. Kim defnedilene kadar kalırsa iki kırat kazanır. Sordular: İki kırat nedir? Buyurdu: İki büyük dağ gibidir.","ar":"مَنْ شَهِدَ الْجَنَازَةَ حَتَّى يُصَلَّى عَلَيْهَا فَلَهُ قِيرَاطٌ وَمَنْ شَهِدَهَا حَتَّى تُدْفَنَ فَلَهُ قِيرَاطَانِ قِيلَ وَمَا الْقِيرَاطَانِ قَالَ مِثْلُ الْجَبَلَيْنِ الْعَظِيمَيْنِ"},"src":{"az":"Buxari, Cənaiz 59","en":"Bukhari, Jana'iz 59","ru":"Бухари, Джанаиз 59","tr":"Buhârî, Cenâiz 59","ar":"البخاري، الجنائز 59"}},{"id":1531,"t":{"az":"Ölü üstündə ağlayıb fəryad edildikdə qəbirdə əzab görər.","en":"The deceased is punished in his grave for the wailing done over him.","ru":"Покойный подвергается наказанию в могиле за плач по нему.","tr":"Ölü, üzerinde feryat edilmesi sebebiyle kabrinde azap görür.","ar":"الْمَيِّتُ يُعَذَّبُ فِي قَبْرِهِ بِمَا نِيحَ عَلَيْهِ"},"src":{"az":"Buxari, Cənaiz 33","en":"Bukhari, Jana'iz 33","ru":"Бухари, Джанаиз 33","tr":"Buhârî, Cenâiz 33","ar":"البخاري، الجنائز 33"}},{"id":1532,"t":{"az":"Cənazə keçdikdə ayağa qalxın, çünki ölüm dəhşətlidir.","en":"Stand up for the funeral, for death is terrifying.","ru":"Вставайте перед похоронной процессией, ибо смерть ужасна.","tr":"Cenaze geçtiğinde ayağa kalkın, çünkü ölüm dehşetlidir.","ar":"قُومُوا لِلْجَنَازَةِ فَإِنَّ الْمَوْتَ فَزَعٌ"},"src":{"az":"Buxari, Cənaiz 48","en":"Bukhari, Jana'iz 48","ru":"Бухари, Джанаиз 48","tr":"Buhârî, Cenâiz 48","ar":"البخاري، الجنائز 48"}},{"id":1533,"t":{"az":"Sizə qəbir ziyarətini qadağan etmişdim, indi ziyarət edin, çünki o sizə axirəti xatırladır.","en":"I had forbidden you from visiting graves, but now visit them, for they remind you of the Hereafter.","ru":"Я запрещал вам посещать могилы, но теперь посещайте их, ибо они напоминают вам о загробной жизни.","tr":"Size kabir ziyaretini yasaklamıştım, artık ziyaret edin, çünkü o size ahireti hatırlatır.","ar":"كُنْتُ نَهَيْتُكُمْ عَنْ زِيَارَةِ الْقُبُورِ فَزُورُوهَا فَإِنَّهَا تُذَكِّرُكُمُ الآخِرَةَ"},"src":{"az":"Muslim, Cənaiz 106","en":"Muslim, Jana'iz 106","ru":"Муслим, Джанаиз 106","tr":"Müslim, Cenâiz 106","ar":"مسلم، الجنائز 106"}},{"id":1534,"t":{"az":"Ey mömin və müsəlman diyar əhli, sizə salam olsun. İnşallah biz də sizə qovuşacağıq. Özümüz və sizin üçün Allahdan afiyət diləyirik.","en":"Peace be upon you, O inhabitants of these abodes, from the believers and Muslims. Indeed, we shall, God willing, join you. We ask Allah for well-being for us and for you.","ru":"Мир вам, о обитатели этих мест из числа верующих и мусульман. Поистине, мы, если пожелает Аллах, присоединимся к вам. Просим Аллаха благополучия для нас и для вас.","tr":"Ey mümin ve Müslüman diyar ahalisi, size selam olsun. İnşallah biz de size katılacağız. Kendimiz ve sizin için Allah'tan afiyet dileriz.","ar":"السَّلاَمُ عَلَيْكُمْ أَهْلَ الدِّيَارِ مِنَ الْمُؤْمِنِينَ وَالْمُسْلِمِينَ وَإِنَّا إِنْ شَاءَ اللَّهُ بِكُمْ لاَحِقُونَ نَسْأَلُ اللَّهَ لَنَا وَلَكُمُ الْعَافِيَةَ"},"src":{"az":"Muslim, Cənaiz 104","en":"Muslim, Jana'iz 104","ru":"Муслим, Джанаиз 104","tr":"Müslim, Cenâiz 104","ar":"مسلم، الجنائز 104"}},{"id":1535,"t":{"az":"Qəbirlərin üzərində oturmayın və onlara tərəf namaz qılmayın.","en":"Do not sit on graves and do not pray facing them.","ru":"Не сидите на могилах и не молитесь в их сторону.","tr":"Kabirlerin üzerine oturmayın ve onlara doğru namaz kılmayın.","ar":"لاَ تَجْلِسُوا عَلَى الْقُبُورِ وَلاَ تُصَلُّوا إِلَيْهَا"},"src":{"az":"Muslim, Cənaiz 96","en":"Muslim, Jana'iz 96","ru":"Муслим, Джанаиз 96","tr":"Müslim, Cenâiz 96","ar":"مسلم، الجنائز 96"}},{"id":1537,"t":{"az":"Saleh adamın gözəl röyası peyğəmbərliyin qırx altıda bir hissəsidir.","en":"The good dream of a righteous man is one of forty-six parts of prophethood.","ru":"Хороший сон праведного человека — одна из сорока шести частей пророчества.","tr":"Salih kişinin güzel rüyası peygamberliğin kırk altıda bir parçasıdır.","ar":"الرُّؤْيَا الْحَسَنَةُ مِنَ الرَّجُلِ الصَّالِحِ جُزْءٌ مِنْ سِتَّةٍ وَأَرْبَعِينَ جُزْءًا مِنَ النُّبُوَّةِ"},"src":{"az":"Buxari, Tə'bir 2","en":"Bukhari, Ta'bir 2","ru":"Бухари, Табир 2","tr":"Buhârî, Ta'bîr 2","ar":"البخاري، التعبير 2"}},{"id":1538,"t":{"az":"Ən doğru röya görəniniz ən doğru danışanınızdır.","en":"The truest of you in dreams is the truest of you in speech.","ru":"Самый правдивый из вас в снах — самый правдивый из вас в речи.","tr":"En doğru rüya göreniniz en doğru konuşanınızdır.","ar":"أَصْدَقُكُمْ رُؤْيَا أَصْدَقُكُمْ حَدِيثًا"},"src":{"az":"Muslim, Rü'ya 6","en":"Muslim, Ru'ya 6","ru":"Муслим, Руйа 6","tr":"Müslim, Rü'yâ 6","ar":"مسلم، الرؤيا 6"}},{"id":1539,"t":{"az":"Peyğəmbərlikdən yalnız müjdəçilər qalmışdır. Dedilər: Müjdəçilər nədir? Buyurdu: Saleh röyadır.","en":"Nothing remains of prophethood except glad tidings. They asked: What are glad tidings? He said: Righteous dreams.","ru":"От пророчества осталось только радостные вести. Спросили: Что такое радостные вести? Сказал: Праведные сны.","tr":"Peygamberlikten yalnız müjdeciler kalmıştır. Dediler: Müjdeciler nedir? Buyurdu: Salih rüyalardır.","ar":"لَمْ يَبْقَ مِنَ النُّبُوَّةِ إِلاَّ الْمُبَشِّرَاتُ قَالُوا وَمَا الْمُبَشِّرَاتُ قَالَ الرُّؤْيَا الصَّالِحَةُ"},"src":{"az":"Buxari, Tə'bir 5","en":"Bukhari, Ta'bir 5","ru":"Бухари, Табир 5","tr":"Buhârî, Ta'bîr 5","ar":"البخاري، التعبير 5"}},{"id":1540,"t":{"az":"Məni yuxuda görən həqiqətən məni görmüşdür, çünki şeytan mənim surətimə girə bilməz.","en":"Whoever sees me in a dream has truly seen me, for Satan cannot take my form.","ru":"Кто увидит меня во сне, тот действительно увидел меня, ибо шайтан не может принять мой облик.","tr":"Beni rüyada gören gerçekten beni görmüştür, çünkü şeytan benim suretime giremez.","ar":"مَنْ رَآنِي فِي الْمَنَامِ فَقَدْ رَآنِي فَإِنَّ الشَّيْطَانَ لاَ يَتَمَثَّلُ بِي"},"src":{"az":"Buxari, Tə'bir 10","en":"Bukhari, Ta'bir 10","ru":"Бухари, Табир 10","tr":"Buhârî, Ta'bîr 10","ar":"البخاري، التعبير 10"}},{"id":1541,"t":{"az":"Biriniz bir işə niyyət etdikdə fərz olmayan iki rəkət namaz qılsın, sonra desin: Allahım, Sənin elminlə Səndən xeyir istəyirəm, qüdrətinlə Səndən güc istəyirəm və böyük lütfündən diləyirəm.","en":"When one of you intends to do something, let him pray two rak'ahs of non-obligatory prayer, then say: O Allah, I seek Your guidance through Your knowledge, and I seek ability through Your power, and I ask You from Your immense bounty.","ru":"Когда кто-то из вас намеревается что-то сделать, пусть совершит два ракаата дополнительной молитвы, затем скажет: О Аллах, я прошу Твоего руководства через Твоё знание, и прошу способности через Твою мощь, и прошу Тебя из Твоей великой милости.","tr":"Biriniz bir işe niyet ettiğinde farz olmayan iki rekat namaz kılsın, sonra desin: Allahım, ilminle Senden hayır istiyorum, kudretinle Senden güç istiyorum ve büyük lütfünden diliyorum.","ar":"إِذَا هَمَّ أَحَدُكُمْ بِالأَمْرِ فَلْيَرْكَعْ رَكْعَتَيْنِ مِنْ غَيْرِ الْفَرِيضَةِ ثُمَّ لِيَقُلِ اللَّهُمَّ إِنِّي أَسْتَخِيرُكَ بِعِلْمِكَ وَأَسْتَقْدِرُكَ بِقُدْرَتِكَ وَأَسْأَلُكَ مِنْ فَضْلِكَ الْعَظِيمِ"},"src":{"az":"Buxari, Təhəccüd 25","en":"Bukhari, Tahajjud 25","ru":"Бухари, Тахаджуд 25","tr":"Buhârî, Teheccüd 25","ar":"البخاري، التهجد 25"}},{"id":1542,"t":{"az":"Peyğəmbər (s.a.s) küsuf namazını iki rəkət qılardı, hər rəkətdə iki rüku edərdi.","en":"The Prophet (peace be upon him) would pray the eclipse prayer as two rak'ahs, with two bowings in each rak'ah.","ru":"Пророк (мир ему) совершал молитву затмения в два ракаата, с двумя поясными поклонами в каждом ракаате.","tr":"Peygamber (s.a.s) küsuf namazını iki rekat kılardı, her rekatta iki rüku yapardı.","ar":"كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي صَلاَةَ الْكُسُوفِ رَكْعَتَيْنِ فِي كُلِّ رَكْعَةٍ رَكْعَتَيْنِ"},"src":{"az":"Buxari, Küsuf 5","en":"Bukhari, Kusuf 5","ru":"Бухари, Кусуф 5","tr":"Buhârî, Küsûf 5","ar":"البخاري، الكسوف 5"}},{"id":1543,"t":{"az":"Günəş və ay Allahın ayələrindəndir. Heç kimin ölümü və ya həyatı üçün tutulmazlar. Bunu gördükdə namaz qılın və dua edin.","en":"The sun and moon are two signs among the signs of Allah. They do not eclipse for the death or life of anyone. When you see that, pray and supplicate until it clears.","ru":"Солнце и луна — два знамения из знамений Аллаха. Они не затмеваются из-за смерти или жизни кого-либо. Когда увидите это, молитесь и взывайте, пока не прояснится.","tr":"Güneş ve ay Allah'ın ayetlerindendir. Hiç kimsenin ölümü veya hayatı için tutulmazlar. Bunu gördüğünüzde namaz kılın ve dua edin.","ar":"إِنَّ الشَّمْسَ وَالْقَمَرَ آيَتَانِ مِنْ آيَاتِ اللَّهِ لاَ يَنْكَسِفَانِ لِمَوْتِ أَحَدٍ وَلاَ لِحَيَاتِهِ فَإِذَا رَأَيْتُمْ ذَلِكَ فَصَلُّوا وَادْعُوا حَتَّى يَنْكَشِفَ مَا بِكُمْ"},"src":{"az":"Buxari, Küsuf 1","en":"Bukhari, Kusuf 1","ru":"Бухари, Кусуф 1","tr":"Buhârî, Küsûf 1","ar":"البخاري، الكسوف 1"}},{"id":1544,"t":{"az":"Rəsulullah (s.a.s) yağışı gördükdə \"Allahummə sayyibən nafiən\" (Allahım, faydalı yağış ver) deyərdi.","en":"When the Messenger of Allah saw rain, he would say: \"O Allah, make it a beneficial rain.\"","ru":"Когда Посланник Аллаха видел дождь, он говорил: «О Аллах, сделай его полезным дождём».","tr":"Rasulullah (s.a.s) yağmuru gördüğünde \"Allahümme sayyiben nafian\" (Allah'ım, faydalı yağmur ver) derdi.","ar":"كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا رَأَى الْمَطَرَ قَالَ اللَّهُمَّ صَيِّبًا نَافِعًا"},"src":{"az":"Buxari, İstisqa 23","en":"Bukhari, Istisqa' 23","ru":"Бухари, Истиска 23","tr":"Buhârî, İstiskâ 23","ar":"البخاري، الاستسقاء 23"}},{"id":1545,"t":{"az":"Allahım, bizə kömək edən, sağlam, faydalı, zərərsiz, tez gələn yağış ver.","en":"O Allah, give us rain that is helpful, wholesome, productive, beneficial, not harmful, soon and not delayed.","ru":"О Аллах, напои нас дождём, спасительным, приятным, плодотворным, полезным, не вредным, скорым, не запоздалым.","tr":"Allah'ım, bize yardım eden, sağlıklı, verimli, faydalı, zararsız, gecikmeden gelen yağmur ver.","ar":"اللَّهُمَّ اسْقِنَا غَيْثًا مُغِيثًا مَرِيئًا مَرِيعًا نَافِعًا غَيْرَ ضَارٍّ عَاجِلاً غَيْرَ آجِلٍ"},"src":{"az":"Əbu Davud 1169","en":"Abu Dawud 1169","ru":"Абу Дауд 1169","tr":"Ebû Dâvûd 1169","ar":"أبو داود 1169"}},{"id":1546,"t":{"az":"Üfüqdən bulud gəldiyini gördükdə, namazda belə olsa, hər şeyi buraxıb ona tərəf dönər və deyərdi: Allahım, içindəki şərdən Sənə sığınıram.","en":"When he saw clouds approaching from any direction, he would leave what he was doing, even if in prayer, face them and say: O Allah, I seek refuge in You from the evil sent in them.","ru":"Когда он видел облако, приближающееся с какой-либо стороны, он оставлял всё, даже молитву, поворачивался к нему и говорил: О Аллах, я прибегаю к Тебе от зла, что в нём.","tr":"Ufuktan bulut geldiğini gördüğünde namazda bile olsa her şeyi bırakıp ona döner ve derdi: Allah'ım, içindeki şerden Sana sığınırım.","ar":"كَانَ إِذَا رَأَى سَحَابًا مُقْبِلاً مِنْ أُفُقٍ مِنَ الآفَاقِ تَرَكَ مَا هُوَ فِيهِ وَإِنْ كَانَ فِي صَلاَتِهِ حَتَّى يَسْتَقْبِلَهُ فَيَقُولَ اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ شَرِّ مَا أُرْسِلَ فِيهِ"},"src":{"az":"İbn Macə 3889","en":"Ibn Majah 3889","ru":"Ибн Маджа 3889","tr":"İbn Mâce 3889","ar":"ابن ماجه 3889"}},{"id":1547,"t":{"az":"İki dua rədd olunmaz və ya nadirən rədd olunur: azan zamanı edilən dua və döyüş vaxtı edilən dua.","en":"Two supplications are not rejected, or are rarely rejected: supplication at the time of the call to prayer and at the time of battle when fighters engage.","ru":"Две мольбы не отвергаются или редко отвергаются: мольба во время призыва к молитве и мольба во время сражения, когда бойцы сходятся.","tr":"İki dua reddedilmez veya nadiren reddedilir: ezan vaktinde yapılan dua ve savaş zamanı yapılan dua.","ar":"ثِنْتَانِ لاَ تُرَدَّانِ أَوْ قَلَّمَا تُرَدَّانِ الدُّعَاءُ عِنْدَ النِّدَاءِ وَعِنْدَ الْبَأْسِ حِينَ يُلْحِمُ بَعْضُهُمْ بَعْضًا"},"src":{"az":"Əbu Davud 2540","en":"Abu Dawud 2540","ru":"Абу Дауд 2540","tr":"Ebû Dâvûd 2540","ar":"أبو داود 2540"}},{"id":1548,"t":{"az":"Biriniz məscidə girdikdə \"Allahım, mənə rəhmət qapılarını aç\" desin. Çıxdıqda isə \"Allahım, Səndən lütfünü istəyirəm\" desin.","en":"When one of you enters the mosque, let him say: \"O Allah, open for me the gates of Your mercy.\" And when he leaves, let him say: \"O Allah, I ask You of Your bounty.\"","ru":"Когда кто-то из вас входит в мечеть, пусть скажет: «О Аллах, открой мне врата Твоей милости». А когда выходит: «О Аллах, я прошу Тебя из Твоей щедрости».","tr":"Biriniz mescide girdiğinde \"Allahım, bana rahmet kapılarını aç\" desin. Çıktığında ise \"Allahım, Senden lütfünü istiyorum\" desin.","ar":"إِذَا دَخَلَ أَحَدُكُمُ الْمَسْجِدَ فَلْيَقُلِ اللَّهُمَّ افْتَحْ لِي أَبْوَابَ رَحْمَتِكَ وَإِذَا خَرَجَ فَلْيَقُلِ اللَّهُمَّ إِنِّي أَسْأَلُكَ مِنْ فَضْلِكَ"},"src":{"az":"Muslim, Müsafirin 68","en":"Muslim, Musafirin 68","ru":"Муслим, Мусафирин 68","tr":"Müslim, Müsâfirîn 68","ar":"مسلم، صلاة المسافرين 68"}},{"id":1549,"t":{"az":"Bir adam evdən çıxarkən \"Bismilləh, təvəkkəltu aləllah, la havlə və la quvvətə illə billəh\" desə, ona deyilər: Hidayət olundun, sənə kifayət edildi və qorundun. Şeytanlar ondan uzaqlaşar.","en":"When a man leaves his house and says \"In the name of Allah, I place my trust in Allah, there is no power nor strength except with Allah,\" it is said to him: You have been guided, sufficed, and protected, and Satan distances himself from him.","ru":"Когда человек выходит из дома и говорит «Именем Аллаха, уповаю на Аллаха, нет силы и мощи кроме как у Аллаха», ему говорится: Ты наставлен, тебе достаточно, ты защищён. И шайтаны отдаляются от него.","tr":"Bir adam evinden çıkarken \"Bismillah, tevekkeltü alellah, la havle ve la kuvvete illa billah\" derse ona denir: Hidayet olundun, sana yetildi ve korundu. Şeytanlar ondan uzaklaşır.","ar":"إِذَا خَرَجَ الرَّجُلُ مِنْ بَيْتِهِ فَقَالَ بِسْمِ اللَّهِ تَوَكَّلْتُ عَلَى اللَّهِ لاَ حَوْلَ وَلاَ قُوَّةَ إِلاَّ بِاللَّهِ قَالَ يُقَالُ حِينَئِذٍ هُدِيتَ وَكُفِيتَ وَوُقِيتَ فَتَتَنَحَّى لَهُ الشَّيَاطِينُ"},"src":{"az":"Əbu Davud 5095","en":"Abu Dawud 5095","ru":"Абу Дауд 5095","tr":"Ebû Dâvûd 5095","ar":"أبو داود 5095"}},{"id":1550,"t":{"az":"Bir adam evinə girib Allahı zikr etsə və yeməkdə Allahı zikr etsə, şeytan deyər: Sizə nə gecələmək, nə də şam yeməyi var.","en":"When a man enters his house and mentions Allah upon entering and upon eating, Satan says: You have no lodging and no dinner here.","ru":"Когда человек входит в свой дом и поминает Аллаха при входе и при еде, шайтан говорит: Нет вам здесь ни ночлега, ни ужина.","tr":"Bir adam evine girdiğinde Allah'ı zikreder ve yemeğinde Allah'ı zikrederse şeytan der ki: Size ne geceleme ne de akşam yemeği var.","ar":"إِذَا دَخَلَ الرَّجُلُ بَيْتَهُ فَذَكَرَ اللَّهَ عِنْدَ دُخُولِهِ وَعِنْدَ طَعَامِهِ قَالَ الشَّيْطَانُ لاَ مَبِيتَ لَكُمْ وَلاَ عَشَاءَ"},"src":{"az":"Muslim, Əşribə 103","en":"Muslim, Ashribah 103","ru":"Муслим, Ашриба 103","tr":"Müslim, Eşribe 103","ar":"مسلم، الأشربة 103"}},{"id":1552,"t":{"az":"Biriniz yatağına girdikdə paltarının içi ilə yatağını silkələsin, çünki arxasından nə gəldiyini bilməz. Sonra desin: Rəbbim, Sənin adınla yanımı qoydum və Səninlə qaldıracağam.","en":"When one of you goes to bed, let him dust off his bed with the inside of his garment, for he does not know what came on it after him. Then say: \"In Your name, my Lord, I lay my side, and by You I raise it.\"","ru":"Когда кто-то из вас ложится в постель, пусть стряхнёт её изнанкой своей одежды, ибо он не знает, что было на ней после него. Затем пусть скажет: «Именем Твоим, Господь мой, я положил свой бок, и Тобой подниму его».","tr":"Biriniz yatağına girdiğinde elbisesinin içiyle yatağını silkesin, çünkü arkasından ne geldiğini bilmez. Sonra desin: Rabbim, Senin adınla yanımı koydum ve Seninle kaldıracağım.","ar":"إِذَا أَوَى أَحَدُكُمْ إِلَى فِرَاشِهِ فَلْيَنْفُضْ فِرَاشَهُ بِدَاخِلَةِ إِزَارِهِ فَإِنَّهُ لاَ يَدْرِي مَا خَلَفَهُ عَلَيْهِ ثُمَّ يَقُولُ بِاسْمِكَ رَبِّي وَضَعْتُ جَنْبِي وَبِكَ أَرْفَعُهُ"},"src":{"az":"Buxari, Dəavat 13","en":"Bukhari, Da'awat 13","ru":"Бухари, Даават 13","tr":"Buhârî, Deavât 13","ar":"البخاري، الدعوات 13"}},{"id":1556,"t":{"az":"Felaq və Nas surələri ilə sığınan heç bir sığınan bunlardan daha yaxşısı ilə sığınmamışdır.","en":"No seeker of refuge has sought refuge with anything like Surah al-Falaq and Surah an-Nas.","ru":"Никто не искал защиты лучше, чем сурами аль-Фаляк и ан-Нас.","tr":"Felak ve Nas sureleri ile sığınan hiçbir sığınan bunlardan daha iyisi ile sığınmamıştır.","ar":"قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ وَقُلْ أَعُوذُ بِرَبِّ النَّاسِ مَا تَعَوَّذَ مُتَعَوِّذٌ بِمِثْلِهِمَا"},"src":{"az":"Əbu Davud 1463","en":"Abu Dawud 1463","ru":"Абу Дауд 1463","tr":"Ebû Dâvûd 1463","ar":"أبو داود 1463"}},{"id":1557,"t":{"az":"Peyğəmbər (s.a.s) hər gecə yatağına girəndə əllərini birləşdirib üfürər, İxlas, Felaq və Nas surələrini oxuyar, sonra əlləri ilə bədəninin bacardığı qədər hər yerini sığallayardı.","en":"Every night when the Prophet went to bed, he would cup his hands, blow into them, recite Surah al-Ikhlas, al-Falaq, and an-Nas, then wipe over as much of his body as he could.","ru":"Каждую ночь, когда Пророк ложился спать, он складывал ладони, дул в них, читал суры аль-Ихлас, аль-Фаляк и ан-Нас, затем проводил руками по всему телу, насколько мог.","tr":"Peygamber (s.a.s) her gece yatağına girdiğinde ellerini birleştirir, üfler, İhlas, Felak ve Nas surelerini okur, sonra elleriyle vücudunun ulaşabildiği her yerini sıvazlardı.","ar":"كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا أَوَى إِلَى فِرَاشِهِ كُلَّ لَيْلَةٍ جَمَعَ كَفَّيْهِ ثُمَّ نَفَثَ فِيهِمَا فَقَرَأَ فِيهِمَا قُلْ هُوَ اللَّهُ أَحَدٌ وَقُلْ أَعُوذُ بِرَبِّ الْفَلَقِ وَقُلْ أَعُوذُ بِرَبِّ النَّاسِ ثُمَّ يَمْسَحُ بِهِمَا مَا اسْتَطَاعَ مِنْ جَسَدِهِ"},"src":{"az":"Buxari, Fəzailul-Quran 14","en":"Bukhari, Fada'il al-Qur'an 14","ru":"Бухари, Фадаиль аль-Куран 14","tr":"Buhârî, Fezâilü'l-Kur'ân 14","ar":"البخاري، فضائل القرآن 14"}},{"id":1559,"t":{"az":"Kim bir yerə ensa və \"Allahın tam kəlmələri ilə yaratdıqlarının şərindən sığınıram\" desə, oradan ayrılana qədər heç nə ona zərər verməz.","en":"Whoever stops at a place and says \"I seek refuge in the perfect words of Allah from the evil of what He has created,\" nothing will harm him until he leaves that place.","ru":"Кто остановится в каком-либо месте и скажет: «Прибегаю к совершенным словам Аллаха от зла того, что Он создал», ничто не навредит ему, пока он не покинет это место.","tr":"Kim bir yere konaklar ve \"Allah'ın tam kelimeleriyle yarattıklarının şerrinden sığınırım\" derse oradan ayrılana kadar hiçbir şey ona zarar vermez.","ar":"مَنْ نَزَلَ مَنْزِلاً ثُمَّ قَالَ أَعُوذُ بِكَلِمَاتِ اللَّهِ التَّامَّاتِ مِنْ شَرِّ مَا خَلَقَ لَمْ يَضُرَّهُ شَيْءٌ حَتَّى يَرْتَحِلَ مِنْ مَنْزِلِهِ ذَلِكَ"},"src":{"az":"Muslim, Zikr 54","en":"Muslim, Dhikr 54","ru":"Муслим, Зикр 54","tr":"Müslim, Zikir 54","ar":"مسلم، الذكر 54"}},{"id":1560,"t":{"az":"Nəzər (göz dəyməsi) haqdır. Əgər bir şey qədəri keçə bilsəydi, onu nəzər keçərdi. Yuyunmanız istənildikdə yuyunun.","en":"The evil eye is real. If anything could outrun destiny, it would be the evil eye. And when you are asked to wash, then wash.","ru":"Сглаз — реальность. Если бы что-то могло опередить предопределение, это был бы сглаз. И когда вас просят омыться, омывайтесь.","tr":"Nazar (göz değmesi) haktır. Eğer bir şey kaderi geçebilseydi onu nazar geçerdi. Yıkanmanız istenildiğinde yıkanın.","ar":"الْعَيْنُ حَقٌّ وَلَوْ كَانَ شَيْءٌ سَابَقَ الْقَدَرَ سَبَقَتْهُ الْعَيْنُ وَإِذَا اسْتُغْسِلْتُمْ فَاغْسِلُوا"},"src":{"az":"Muslim, Salam 42","en":"Muslim, Salam 42","ru":"Муслим, Салям 42","tr":"Müslim, Selâm 42","ar":"مسلم، السلام 42"}},{"id":1561,"t":{"az":"Ruqyələrdə şirk olmadıqca onlarda heç bir beis yoxdur.","en":"There is nothing wrong with ruqyah (spiritual healing recitation) as long as it does not involve shirk (polytheism).","ru":"Нет ничего плохого в рукье (заклинании), если в ней нет ширка (многобожия).","tr":"Rukyelerde şirk olmadıkça onlarda hiçbir sakınca yoktur.","ar":"لاَ بَأْسَ بِالرُّقَى مَا لَمْ يَكُنْ فِيهَا شِرْكٌ"},"src":{"az":"Muslim, Salam 64","en":"Muslim, Salam 64","ru":"Муслим, Салям 64","tr":"Müslim, Selâm 64","ar":"مسلم، السلام 64"}},{"id":1562,"t":{"az":"Ruqyələrinizi mənə göstərin. Şirk olmadıqca ruqyədə heç bir qəbahət yoxdur.","en":"Show me your incantations. There is nothing wrong with incantations as long as they do not involve shirk.","ru":"Покажите мне ваши заклинания. Нет ничего дурного в заклинаниях, если в них нет ширка.","tr":"Rukyelerinizi bana gösterin. Şirk olmadıkça rukyede hiçbir sakınca yoktur.","ar":"اعْرِضُوا عَلَيَّ رُقَاكُمْ لاَ بَأْسَ بِالرُّقَى مَا لَمْ يَكُنْ فِيهِ شِرْكٌ"},"src":{"az":"Muslim, Salam 64","en":"Muslim, Salam 64","ru":"Муслим, Салям 64","tr":"Müslim, Selâm 64","ar":"مسلم، السلام 64"}},{"id":1563,"t":{"az":"Allahın adı ilə sənə ruqyə edirəm, sənə əziyyət verən hər şeydən, hər nəfsin şərindən və həsədçi gözün şərindən. Allah sənə şəfa versin. Allahın adı ilə sənə ruqyə edirəm.","en":"In the name of Allah I perform ruqyah on you, from everything that harms you, from the evil of every soul or envious eye. May Allah heal you. In the name of Allah I perform ruqyah on you.","ru":"Именем Аллаха совершаю рукью над тобой от всего, что причиняет тебе вред, от зла каждой души или завистливого глаза. Аллах исцелит тебя. Именем Аллаха совершаю рукью над тобой.","tr":"Allah'ın adıyla sana rukye ediyorum, sana eziyet veren her şeyden, her nefsin şerrinden ve hasetçi gözün şerrinden. Allah sana şifa versin. Allah'ın adıyla sana rukye ediyorum.","ar":"بِسْمِ اللَّهِ أَرْقِيكَ مِنْ كُلِّ شَيْءٍ يُؤْذِيكَ مِنْ شَرِّ كُلِّ نَفْسٍ أَوْ عَيْنِ حَاسِدٍ اللَّهُ يَشْفِيكَ بِسْمِ اللَّهِ أَرْقِيكَ"},"src":{"az":"Muslim, Salam 40","en":"Muslim, Salam 40","ru":"Муслим, Салям 40","tr":"Müslim, Selâm 40","ar":"مسلم، السلام 40"}},{"id":1564,"t":{"az":"Müsəlman bir kişinin malı onun könül razılığı olmadan halal olmaz.","en":"The wealth of a Muslim is not permissible except with his willing consent.","ru":"Имущество мусульманина не дозволено, кроме как с его добровольного согласия.","tr":"Müslüman bir kişinin malı onun gönül rızası olmadan helal olmaz.","ar":"لاَ يَحِلُّ مَالُ امْرِئٍ مُسْلِمٍ إِلاَّ بِطِيبِ نَفْسٍ مِنْهُ"},"src":{"az":"Əhməd 20695","en":"Ahmad 20695","ru":"Ахмад 20695","tr":"Ahmed 20695","ar":"أحمد 20695"}},{"id":1567,"t":{"az":"Alıcı və satıcı ayrılmadıqca ixtiyar sahibidir. Əgər doğru danışıb açıqlasalar, alış-verişləri bərəkətli olar. Gizlədib yalan söyləsələr, alış-verişlərinin bərəkəti itər.","en":"The buyer and seller have the option to cancel as long as they have not parted. If they are truthful and transparent, their transaction is blessed. If they conceal and lie, the blessing of their transaction is erased.","ru":"Покупатель и продавец имеют право выбора, пока не разойдутся. Если они правдивы и всё разъясняют, их сделка благословлена. Если скрывают и лгут, благословение их сделки стирается.","tr":"Alıcı ve satıcı ayrılmadıkça muhayyerdirler. Doğru söyleyip açıklarlarsa alışverişleri bereketli olur. Gizler ve yalan söylerlerse alışverişlerinin bereketi gider.","ar":"الْبَيِّعَانِ بِالْخِيَارِ مَا لَمْ يَتَفَرَّقَا فَإِنْ صَدَقَا وَبَيَّنَا بُورِكَ لَهُمَا فِي بَيْعِهِمَا وَإِنْ كَتَمَا وَكَذَبَا مُحِقَتْ بَرَكَةُ بَيْعِهِمَا"},"src":{"az":"Buxari, Büyu' 19","en":"Bukhari, Buyu' 19","ru":"Бухари, Буйу 19","tr":"Buhârî, Büyû' 19","ar":"البخاري، البيوع 19"}},{"id":1568,"t":{"az":"Rəsulullah (s.a.s) faiz yeyəni, yedirəni, yazanı və şahidlərini lənətlədi və buyurdu: Onlar eynidir.","en":"The Messenger of Allah cursed the one who consumes interest, the one who pays it, the one who records it, and its two witnesses, and said: They are all equal.","ru":"Посланник Аллаха проклял берущего проценты, дающего их, записывающего и двух свидетелей и сказал: Они все равны.","tr":"Rasulullah (s.a.s) faiz yiyeni, yedireni, yazanı ve şahitlerini lanetledi ve buyurdu: Onlar eşittir.","ar":"لَعَنَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ آكِلَ الرِّبَا وَمُوكِلَهُ وَكَاتِبَهُ وَشَاهِدَيْهِ وَقَالَ هُمْ سَوَاءٌ"},"src":{"az":"Muslim, Müsaqat 106","en":"Muslim, Musaqah 106","ru":"Муслим, Мусака 106","tr":"Müslim, Müsâkât 106","ar":"مسلم، المساقاة 106"}},{"id":1569,"t":{"az":"Sədəqə malı əskiltməz. Allah bağışlayan qulun ancaq izzətini artırar. Kim Allah üçün təvazö göstərsə, Allah onu yüksəldər.","en":"Charity does not decrease wealth. Allah increases the one who forgives in honor. And whoever humbles himself for Allah, Allah will elevate him.","ru":"Милостыня не уменьшает имущество. Аллах увеличивает честь прощающего. И кто смирится ради Аллаха, Аллах возвысит его.","tr":"Sadaka malı eksiltmez. Allah affeden kulun ancak izzetini artırır. Kim Allah için tevazu gösterirse Allah onu yükseltir.","ar":"مَا نَقَصَتْ صَدَقَةٌ مِنْ مَالٍ وَمَا زَادَ اللَّهُ عَبْدًا بِعَفْوٍ إِلاَّ عِزًّا وَمَا تَوَاضَعَ أَحَدٌ لِلَّهِ إِلاَّ رَفَعَهُ اللَّهُ"},"src":{"az":"Muslim, Birr 69","en":"Muslim, Birr 69","ru":"Муслим, Бирр 69","tr":"Müslim, Birr 69","ar":"مسلم، البر والصلة 69"}},{"id":1571,"t":{"az":"Vəli yetimin işinə və malına baxandır. Onun malından uyğun şəkildə yesin, israf etməsin.","en":"The guardian is the one who takes care of the orphan's affairs and wealth. He may eat from it reasonably and not extravagantly.","ru":"Опекун — тот, кто ведёт дела сироты и его имущество. Пусть ест из него разумно и не расточает.","tr":"Veli yetimin işine ve malına bakandır. Onun malından uygun şekilde yesin, israf etmesin.","ar":"الْوَلِيُّ هُوَ الَّذِي يَلِي أَمْرَ الْيَتِيمِ وَمَالَهُ فَلْيَأْكُلْ مِنْهُ بِالْمَعْرُوفِ وَلاَ يُسْرِفْ"},"src":{"az":"Buxari, Vəsaya 23 (təfsir)","en":"Bukhari, Wasaya 23 (tafsir)","ru":"Бухари, Васая 23 (тафсир)","tr":"Buhârî, Vesâyâ 23 (tefsir)","ar":"البخاري، الوصايا 23 (تفسير)"}},{"id":1572,"t":{"az":"Kim Allah yolunda imanla və savab ümidi ilə bir at saxlasa, onun yeməsi, suyu, peyini və sidiyi Qiyamət günü tərəzisində olacaq.","en":"Whoever keeps a horse for the cause of Allah out of faith and seeking reward, its food, water, dung, and urine will be in his scale on the Day of Judgment.","ru":"Кто содержит коня на пути Аллаха с верой и надеждой на награду, его корм, питьё, навоз и моча будут на его весах в День Суда.","tr":"Kim Allah yolunda imanla ve sevap umarak bir at tutarsa onun yemesi, suyu, gübresi ve idrarı Kıyamet günü terazisinde olacaktır.","ar":"مَنْ حَبَسَ فَرَسًا فِي سَبِيلِ اللَّهِ إِيمَانًا وَاحْتِسَابًا فَإِنَّ شِبَعَهُ وَرِيَّهُ وَرَوْثَهُ وَبَوْلَهُ فِي مِيزَانِهِ يَوْمَ الْقِيَامَةِ"},"src":{"az":"Buxari, Cihad 45","en":"Bukhari, Jihad 45","ru":"Бухари, Джихад 45","tr":"Buhârî, Cihâd 45","ar":"البخاري، الجهاد 45"}},{"id":1573,"t":{"az":"Kim bir əmlakını və ya torpağını vəqf etsə, onun əsli satılmaz, bağışlanmaz, miras verilməz, lakin meyvəsi xərclənər.","en":"Whoever endows his property or land as waqf, its original cannot be sold, gifted, or inherited, but its produce is spent.","ru":"Кто сделает вакф из своей недвижимости или земли, её основа не продаётся, не дарится, не наследуется, но её плоды расходуются.","tr":"Kim bir mülkünü veya arazisini vakfederse onun aslı satılmaz, bağışlanmaz, miras bırakılmaz, fakat meyvesi harcanır.","ar":"مَنْ وَقَفَ عَقَارًا لَهُ أَوْ أَرْضًا لاَ يُبَاعُ أَصْلُهَا وَلاَ يُوهَبُ وَلاَ يُورَثُ وَلَكِنْ يُنْفَقُ ثَمَرَتُهَا"},"src":{"az":"Buxari, Şürut 19 (İbn Ömər rəvayəti)","en":"Bukhari, Shurut 19 (narrated by Ibn Umar)","ru":"Бухари, Шурут 19 (передал Ибн Умар)","tr":"Buhârî, Şurût 19 (İbn Ömer rivayeti)","ar":"البخاري، الشروط 19 (رواية ابن عمر)"}},{"id":1576,"t":{"az":"Qiyamət qopsa və birinizin əlində bir xurma fidanı olsa, onu əkməyə macal tapsa əksin.","en":"If the Hour is about to be established and one of you has a palm seedling in his hand, if he is able to plant it before it happens, let him plant it.","ru":"Если наступит Час и в руке одного из вас будет саженец пальмы, и он сможет посадить его до этого, пусть посадит.","tr":"Kıyamet kopsa ve birinizin elinde bir hurma fidanı olsa, onu dikmeye fırsat bulursa diksin.","ar":"إِنْ قَامَتِ السَّاعَةُ وَفِي يَدِ أَحَدِكُمْ فَسِيلَةٌ فَإِنِ اسْتَطَاعَ أَنْ لاَ تَقُومَ حَتَّى يَغْرِسَهَا فَلْيَغْرِسْهَا"},"src":{"az":"Əhməd 12981","en":"Ahmad 12981","ru":"Ахмад 12981","tr":"Ahmed 12981","ar":"أحمد 12981"}},{"id":1577,"t":{"az":"Bir müsəlman ağac əksə, ondan yeyilən ona sədəqədir, oğurlanan da sədəqədir, yırtıcı heyvanın yediyi də sədəqədir. Kimsə ondan bir şey əskiltməz ki, bu ona sədəqə olmasın.","en":"No Muslim plants a tree except that what is eaten from it is charity for him, what is stolen is charity, what wild animals eat is charity, and no one takes from it except that it is charity for him.","ru":"Каждый мусульманин, посадивший дерево — съеденное из него будет милостыней, украденное — милостыней, съеденное хищниками — милостыней, и никто не уменьшит его, чтобы это не было милостыней.","tr":"Bir Müslüman ağaç dikerse ondan yenilen ona sadakadır, çalınan da sadakadır, yırtıcı hayvanın yediği de sadakadır. Kimse ondan bir şey eksiltmez ki bu ona sadaka olmasın.","ar":"مَا مِنْ مُسْلِمٍ يَغْرِسُ غَرْسًا إِلاَّ كَانَ مَا أُكِلَ مِنْهُ لَهُ صَدَقَةٌ وَمَا سُرِقَ مِنْهُ لَهُ صَدَقَةٌ وَمَا أَكَلَ السَّبُعُ مِنْهُ فَهُوَ لَهُ صَدَقَةٌ وَلاَ يَرْزَؤُهُ أَحَدٌ إِلاَّ كَانَ لَهُ صَدَقَةٌ"},"src":{"az":"Muslim, Müsaqat 10","en":"Muslim, Musaqah 10","ru":"Муслим, Мусака 10","tr":"Müslim, Müsâkât 10","ar":"مسلم، المساقاة 10"}},{"id":1578,"t":{"az":"Yoldan əziyyət verəni götürmək sədəqədir.","en":"Removing harm from the road is charity.","ru":"Устранение вреда с дороги — милостыня.","tr":"Yoldan eziyet vereni kaldırmak sadakadır.","ar":"إِمَاطَةُ الأَذَى عَنِ الطَّرِيقِ صَدَقَةٌ"},"src":{"az":"Buxari, Məzalim 24","en":"Bukhari, Mazalim 24","ru":"Бухари, Мазалим 24","tr":"Buhârî, Mezâlim 24","ar":"البخاري، المظالم 24"}},{"id":1579,"t":{"az":"Bir adam yolda gedərkən tikanlı bir budaq tapdı, onu götürdü. Allah ona şükr etdi və onu bağışladı.","en":"A man was walking along a road and found a thorny branch, so he removed it. Allah thanked him and forgave him.","ru":"Один человек шёл по дороге и нашёл колючую ветку, убрал её. Аллах поблагодарил его и простил его.","tr":"Bir adam yolda yürürken dikenli bir dal buldu, onu kaldırdı. Allah ona şükretti ve onu bağışladı.","ar":"بَيْنَمَا رَجُلٌ يَمْشِي بِطَرِيقٍ وَجَدَ غُصْنَ شَوْكٍ فَأَخَذَهُ فَشَكَرَ اللَّهُ لَهُ فَغَفَرَ لَهُ"},"src":{"az":"Buxari, Ədəb 33","en":"Bukhari, Adab 33","ru":"Бухари, Адаб 33","tr":"Buhârî, Edeb 33","ar":"البخاري، الأدب 33"}},{"id":1581,"t":{"az":"Kim ölü (boş) bir torpağı canlandırsa, o torpaq onundur.","en":"Whoever revives dead (barren) land, it belongs to him.","ru":"Кто оживит мёртвую (пустынную) землю, она принадлежит ему.","tr":"Kim ölü (boş) bir araziyi ihya ederse o arazi onundur.","ar":"مَنْ أَحْيَا أَرْضًا مَيِّتَةً فَهِيَ لَهُ"},"src":{"az":"Tirmizi 1379","en":"Tirmidhi 1379","ru":"Тирмизи 1379","tr":"Tirmizî 1379","ar":"الترمذي 1379"}},{"id":1582,"t":{"az":"İnsanlar üç şeydə ortaqdır: su, otlaq və od.","en":"People are partners in three things: water, pasture, and fire.","ru":"Люди — партнёры в трёх вещах: воде, пастбищах и огне.","tr":"İnsanlar üç şeyde ortaktır: su, otlak ve ateş.","ar":"النَّاسُ شُرَكَاءُ فِي ثَلاَثٍ فِي الْمَاءِ وَالْكَلإِ وَالنَّارِ"},"src":{"az":"Əbu Davud 3477","en":"Abu Dawud 3477","ru":"Абу Дауд 3477","tr":"Ebû Dâvûd 3477","ar":"أبو داود 3477"}},{"id":1585,"t":{"az":"Bir it susuzluqdan ölmək üzrə ikən bir quyunun ətrafında dolanırdı. Bəni İsraildən günahkar bir qadın onu gördü, ayaqqabısını çıxarıb onunla su verdi. Bu əməlinə görə bağışlandı.","en":"A dog was circling a well nearly dying of thirst when a sinful woman from the Children of Israel saw it, removed her shoe, and gave it water. She was forgiven because of that.","ru":"Собака, умирая от жажды, кружила вокруг колодца. Грешная женщина из сынов Израиля увидела её, сняла свою обувь и напоила её. Она была прощена за это.","tr":"Bir köpek susuzluktan ölmek üzereyken bir kuyunun etrafında dönüyordu. İsrailoğullarından günahkâr bir kadın onu görüp ayakkabısını çıkararak su verdi. Bu ameli sebebiyle bağışlandı.","ar":"بَيْنَمَا كَلْبٌ يُطِيفُ بِرَكِيَّةٍ كَادَ يَقْتُلُهُ الْعَطَشُ إِذْ رَأَتْهُ بَغِيٌّ مِنْ بَغَايَا بَنِي إِسْرَائِيلَ فَنَزَعَتْ مُوقَهَا فَسَقَتْهُ فَغُفِرَ لَهَا بِهِ"},"src":{"az":"Buxari, Ənbiya 54","en":"Bukhari, Anbiya' 54","ru":"Бухари, Анбия 54","tr":"Buhârî, Enbiyâ 54","ar":"البخاري، أحاديث الأنبياء 54"}},{"id":1586,"t":{"az":"Allah hər şeydə ehsanı (yaxşılığı) vacib etmişdir. Öldürdüyünüzdə yaxşı öldürün, kəsdiyinizdə yaxşı kəsin. Biriniz bıçağını itiləsin və kəsdiyi heyvana rahatlıq versin.","en":"Allah has prescribed excellence in all things. When you kill, kill well. When you slaughter, slaughter well. Let one of you sharpen his blade and give comfort to his animal.","ru":"Аллах предписал доброе отношение ко всему. Когда убиваете, убивайте хорошо. Когда забиваете, забивайте хорошо. Пусть каждый наточит свой нож и облегчит страдания своего животного.","tr":"Allah her şeyde ihsanı (iyiliği) farz kılmıştır. Öldürdüğünüzde iyi öldürün, kestiğinizde iyi kesin. Biriniz bıçağını bilesin ve kestiği hayvana rahatlık versin.","ar":"إِنَّ اللَّهَ كَتَبَ الإِحْسَانَ عَلَى كُلِّ شَيْءٍ فَإِذَا قَتَلْتُمْ فَأَحْسِنُوا الْقِتْلَةَ وَإِذَا ذَبَحْتُمْ فَأَحْسِنُوا الذَّبْحَةَ وَلْيُحِدَّ أَحَدُكُمْ شَفْرَتَهُ وَلْيُرِحْ ذَبِيحَتَهُ"},"src":{"az":"Muslim, Sayd 57","en":"Muslim, Sayd 57","ru":"Муслим, Сайд 57","tr":"Müslim, Sayd 57","ar":"مسلم، الصيد 57"}},{"id":1587,"t":{"az":"Canlı heyvanları hədəf olaraq istifadə etməyin.","en":"Do not take anything with a soul as a target.","ru":"Не используйте живых существ в качестве мишени.","tr":"Canlı hayvanları hedef olarak kullanmayın.","ar":"لاَ تَتَّخِذُوا شَيْئًا فِيهِ الرُّوحُ غَرَضًا"},"src":{"az":"Muslim, Sayd 59","en":"Muslim, Sayd 59","ru":"Муслим, Сайд 59","tr":"Müslim, Sayd 59","ar":"مسلم، الصيد 59"}},{"id":1589,"t":{"az":"Kim ihramda ikən ov öldürsə, bunun cəzasını verməlidir.","en":"Whoever kills game while in a state of ihram must pay its penalty.","ru":"Кто убьёт дичь, находясь в состоянии ихрама, должен заплатить за неё.","tr":"Kim ihramlıyken av öldürürse bunun cezasını vermelidir.","ar":"مَنْ قَتَلَ صَيْدًا وَهُوَ مُحْرِمٌ فَعَلَيْهِ جَزَاؤُهُ"},"src":{"az":"Buxari, Cəza əs-Sayd 10 (Quran ayəsi ilə)","en":"Bukhari, Jaza' as-Sayd 10 (with a Quran verse)","ru":"Бухари, Джаза ас-Сайд 10 (с аятом Корана)","tr":"Buhârî, Cezâü's-Sayd 10 (Kur'an ayetiyle)","ar":"البخاري، جزاء الصيد 10 (مع آية من القرآن)"}},{"id":1590,"t":{"az":"Öyrədilmiş itini göndərdikdə Allahın adını çək. Əgər sənin üçün tutarsa və sən onu diri taparsan, kəs. Əgər öldürübsə və ondan yeməyibsə, ye.","en":"When you send your trained dog, mention the name of Allah. If it catches the prey for you and you find it alive, slaughter it. If it has killed it and not eaten from it, eat.","ru":"Когда посылаешь свою обученную собаку, упомяни имя Аллаха. Если она поймает для тебя и ты найдёшь добычу живой, зарежь её. Если она убила и не ела из неё, ешь.","tr":"Eğitilmiş köpeğini gönderdiğinde Allah'ın adını an. Eğer senin için tutarsa ve onu diri bulursan kes. Eğer öldürmüşse ve ondan yememişse ye.","ar":"إِذَا أَرْسَلْتَ كَلْبَكَ الْمُعَلَّمَ فَاذْكُرِ اسْمَ اللَّهِ عَلَيْهِ فَإِنْ أَمْسَكَ عَلَيْكَ فَأَدْرَكْتَهُ حَيًّا فَاذْبَحْهُ وَإِنْ أَدْرَكْتَهُ قَدْ قَتَلَ وَلَمْ يَأْكُلْ مِنْهُ فَكُلْ"},"src":{"az":"Buxari, Zəbaih 4","en":"Bukhari, Dhaba'ih 4","ru":"Бухари, Забаих 4","tr":"Buhârî, Zebâih 4","ar":"البخاري، الذبائح والصيد 4"}},{"id":1592,"t":{"az":"Ümmətimə çətinlik verməsəydim, hər namazda misvak istifadə etmələrini əmr edərdim.","en":"Were it not that I would make things difficult for my ummah, I would have ordered them to use the miswak with every prayer.","ru":"Если бы я не боялся обременить свою общину, я бы повелел им пользоваться сиваком при каждой молитве.","tr":"Ümmetime zorluk vermeseydi her namazda misvak kullanmalarını emrederdim.","ar":"لَوْلاَ أَنْ أَشُقَّ عَلَى أُمَّتِي لأَمَرْتُهُمْ بِالسِّوَاكِ عِنْدَ كُلِّ صَلاَةٍ"},"src":{"az":"Buxari, Cümə 8","en":"Bukhari, Jumu'ah 8","ru":"Бухари, Джума 8","tr":"Buhârî, Cuma 8","ar":"البخاري، الجمعة 8"}},{"id":1594,"t":{"az":"Biriniz ayaqyoluna girdikdə desin: Allahım, cin kişilərdən və cin qadınlardan Sənə sığınıram.","en":"When one of you enters the toilet, let him say: \"O Allah, I seek refuge in You from male and female evil spirits.\"","ru":"Когда кто-то из вас входит в уборную, пусть скажет: «О Аллах, я прибегаю к Тебе от мужских и женских злых духов».","tr":"Biriniz tuvalete girdiğinde desin: Allah'ım, erkek ve dişi şeytanlardan Sana sığınırım.","ar":"إِذَا دَخَلَ أَحَدُكُمُ الْخَلاَءَ فَلْيَقُلِ اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْخُبُثِ وَالْخَبَائِثِ"},"src":{"az":"Buxari, Vüdu 9","en":"Bukhari, Wudu 9","ru":"Бухари, Вуду 9","tr":"Buhârî, Vudû 9","ar":"البخاري، الوضوء 9"}},{"id":1595,"t":{"az":"Peyğəmbər (s.a.s) ayaqyolundan çıxdıqda \"Ğufranəkə\" (bağışlamanı diləyirəm) deyərdi.","en":"When the Prophet (peace be upon him) came out of the toilet, he would say \"Ghufranaka\" (I seek Your forgiveness).","ru":"Когда Пророк (мир ему) выходил из уборной, он говорил «Гуфранака» (прошу Твоего прощения).","tr":"Peygamber (s.a.s) tuvaletten çıktığında \"Ğufraneke\" (bağışlamanı diliyorum) derdi.","ar":"كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا خَرَجَ مِنَ الْخَلاَءِ قَالَ غُفْرَانَكَ"},"src":{"az":"Tirmizi 7","en":"Tirmidhi 7","ru":"Тирмизи 7","tr":"Tirmizî 7","ar":"الترمذي 7"}},{"id":1596,"t":{"az":"Peyğəmbər (s.a.s) kişinin qadının artıq dəstəmaz suyu ilə dəstəmaz almasını qadağan etdi.","en":"The Prophet (peace be upon him) forbade a man from performing wudu with the leftover water of a woman's wudu.","ru":"Пророк (мир ему) запретил мужчине совершать омовение оставшейся водой после омовения женщины.","tr":"Peygamber (s.a.s) erkeğin kadının artık abdest suyuyla abdest almasını yasakladı.","ar":"نَهَى النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يَتَوَضَّأَ الرَّجُلُ بِفَضْلِ وَضُوءِ الْمَرْأَةِ"},"src":{"az":"Əbu Davud 82","en":"Abu Dawud 82","ru":"Абу Дауд 82","tr":"Ebû Dâvûd 82","ar":"أبو داود 82"}},{"id":1597,"t":{"az":"Biriniz dəstəmaz aldıqda burnuna su çəksin, sonra onu çıxarsın.","en":"When one of you performs wudu, let him put water in his nose and then blow it out.","ru":"Когда кто-то из вас совершает омовение, пусть втянет воду в нос, а затем выдует её.","tr":"Biriniz abdest aldığında burnuna su çeksin, sonra onu çıkarsın.","ar":"إِذَا تَوَضَّأَ أَحَدُكُمْ فَلْيَجْعَلْ فِي أَنْفِهِ مَاءً ثُمَّ لِيَسْتَنْثِرْ"},"src":{"az":"Buxari, Vüdu 26","en":"Bukhari, Wudu 26","ru":"Бухари, Вуду 26","tr":"Buhârî, Vudû 26","ar":"البخاري، الوضوء 26"}},{"id":1598,"t":{"az":"Kim dəstəmaz alıb gözəl dəstəmaz alsa, günahları bədənindən çıxar, hətta dırnaqlarının altından belə çıxar.","en":"Whoever performs wudu well, his sins leave his body until they come out from under his nails.","ru":"Кто совершит омовение хорошо, его грехи выйдут из тела, даже из-под ногтей.","tr":"Kim abdest alıp güzel abdest alırsa günahları vücudundan çıkar, hatta tırnaklarının altından bile çıkar.","ar":"مَنْ تَوَضَّأَ فَأَحْسَنَ الْوُضُوءَ خَرَجَتْ خَطَايَاهُ مِنْ جَسَدِهِ حَتَّى تَخْرُجَ مِنْ تَحْتِ أَظْفَارِهِ"},"src":{"az":"Muslim, Taharat 33","en":"Muslim, Taharah 33","ru":"Муслим, Тахара 33","tr":"Müslim, Tahâret 33","ar":"مسلم، الطهارة 33"}},{"id":1599,"t":{"az":"Allahın günahları sildiyi və dərəcələri yüksəltdiyi şeyi sizə göstərimmi? Çətin vaxtlarda dəstəmazı kamil almaq, məscidlərə çox addım atmaq və namazdan sonra namazı gözləmək. Budur ribat!","en":"Shall I tell you what Allah erases sins and raises ranks by? Performing wudu thoroughly despite difficulty, taking many steps to the mosques, and waiting for prayer after prayer. That is ribat (guarding the frontiers of faith)!","ru":"Не указать ли вам на то, чем Аллах стирает грехи и возвышает степени? Совершение полного омовения в тяжёлых условиях, множество шагов к мечетям и ожидание молитвы после молитвы. Это и есть рибат!","tr":"Allah'ın günahları sildiği ve dereceleri yükselttiği şeyi size göstereyim mi? Zorluklarda abdesti tam almak, mescitlere çok adım atmak ve namazdan sonra namazı beklemek. İşte ribat budur!","ar":"أَلاَ أَدُلُّكُمْ عَلَى مَا يَمْحُو اللَّهُ بِهِ الْخَطَايَا وَيَرْفَعُ بِهِ الدَّرَجَاتِ إِسْبَاغُ الْوُضُوءِ عَلَى الْمَكَارِهِ وَكَثْرَةُ الْخُطَا إِلَى الْمَسَاجِدِ وَانْتِظَارُ الصَّلاَةِ بَعْدَ الصَّلاَةِ فَذَلِكُمُ الرِّبَاطُ"},"src":{"az":"Muslim, Taharat 41","en":"Muslim, Taharah 41","ru":"Муслим, Тахара 41","tr":"Müslim, Tahâret 41","ar":"مسلم، الطهارة 41"}},{"id":1600,"t":{"az":"Təmiz torpaq müsəlmanın təmizləyicisidir, on il su tapmasa belə. Su tapdıqda isə onu dərisinə dəydirsin.","en":"Clean earth is the Muslim's purifier, even if he does not find water for ten years. When he finds water, let him apply it to his skin.","ru":"Чистая земля — очищение мусульманина, даже если он не найдёт воды десять лет. Когда найдёт воду, пусть коснётся ею своей кожи.","tr":"Temiz toprak Müslümanın temizleyicisidir, on yıl su bulamasa bile. Su bulduğunda onu derisine değdirsin.","ar":"إِنَّ الصَّعِيدَ الطَّيِّبَ طَهُورُ الْمُسْلِمِ وَإِنْ لَمْ يَجِدِ الْمَاءَ عَشْرَ سِنِينَ فَإِذَا وَجَدَ الْمَاءَ فَلْيُمِسَّهُ بَشَرَتَهُ"},"src":{"az":"Tirmizi 124","en":"Tirmidhi 124","ru":"Тирмизи 124","tr":"Tirmizî 124","ar":"الترمذي 124"}},{"id":1602,"t":{"az":"Rəsulullah (s.a.s) bir sa' su ilə qüsl alır, bir müdd su ilə dəstəmaz alırdı.","en":"The Messenger of Allah would perform ghusl with a sa' of water and wudu with a mudd of water.","ru":"Посланник Аллаха совершал полное омовение одним саа воды и малое омовение одним муддом воды.","tr":"Rasulullah (s.a.s) bir sa' su ile gusül alır, bir müdd su ile abdest alırdı.","ar":"كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَغْتَسِلُ بِالصَّاعِ وَيَتَوَضَّأُ بِالْمُدِّ"},"src":{"az":"Muslim, Hayz 51","en":"Muslim, Hayd 51","ru":"Муслим, Хайд 51","tr":"Müslim, Hayız 51","ar":"مسلم، الحيض 51"}},{"id":1604,"t":{"az":"Heyz gördüyün günlər qədər namazı burax, sonra qüsl al və namaz qıl.","en":"Leave prayer for the days you used to menstruate, then perform ghusl and pray.","ru":"Оставь молитву на дни, когда у тебя были месячные, затем соверши полное омовение и молись.","tr":"Adet gördüğün günler kadar namazı bırak, sonra gusül al ve namaz kıl.","ar":"دَعِي عَنْكِ الصَّلاَةَ قَدْرَ الأَيَّامِ الَّتِي كُنْتِ تَحِيضِينَ فِيهَا ثُمَّ اغْتَسِلِي وَصَلِّي"},"src":{"az":"Buxari, Hayz 19","en":"Bukhari, Hayd 19","ru":"Бухари, Хайд 19","tr":"Buhârî, Hayız 19","ar":"البخاري، الحيض 19"}},{"id":1605,"t":{"az":"Heyzli qadın orucu qəza edər, lakin namazı qəza etməz.","en":"The menstruating woman makes up fasting but does not make up prayers.","ru":"Менструирующая женщина восполняет пост, но не восполняет молитвы.","tr":"Adetli kadın orucu kaza eder, fakat namazı kaza etmez.","ar":"الْحَائِضُ تَقْضِي الصَّوْمَ وَلاَ تَقْضِي الصَّلاَةَ"},"src":{"az":"Muslim, Hayz 69","en":"Muslim, Hayd 69","ru":"Муслим, Хайд 69","tr":"Müslim, Hayız 69","ar":"مسلم، الحيض 69"}},{"id":1606,"t":{"az":"Rəsulullah (s.a.s) vəfatına qədər Ramazanın son on günündə etikaf edərdi.","en":"The Messenger of Allah used to observe i'tikaf in the last ten days of Ramadan until he passed away.","ru":"Посланник Аллаха совершал и'тикаф в последние десять дней Рамадана до своей кончины.","tr":"Rasulullah (s.a.s) vefatına kadar Ramazan'ın son on gününde itikaf yapardı.","ar":"كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَعْتَكِفُ الْعَشْرَ الأَوَاخِرَ مِنْ رَمَضَانَ حَتَّى تَوَفَّاهُ اللَّهُ"},"src":{"az":"Buxari, İ'tikaf 1","en":"Bukhari, I'tikaf 1","ru":"Бухари, Итикаф 1","tr":"Buhârî, İ'tikâf 1","ar":"البخاري، الاعتكاف 1"}},{"id":1607,"t":{"az":"E'tikaf yalnız cami məsciddə olar.","en":"There is no i'tikaf except in a congregational mosque.","ru":"И'тикаф совершается только в соборной мечети.","tr":"İtikaf yalnızca cami mescitte olur.","ar":"لاَ اعْتِكَافَ إِلاَّ فِي مَسْجِدٍ جَامِعٍ"},"src":{"az":"Əbu Davud 2473","en":"Abu Dawud 2473","ru":"Абу Дауд 2473","tr":"Ebû Dâvûd 2473","ar":"أبو داود 2473"}},{"id":1608,"t":{"az":"Rəsulullah (s.a.s) fitrə zəkatını bir sa' xurma və ya bir sa' arpa olaraq, qul-azad, kişi-qadın hər müsəlmana fərz etdi.","en":"The Messenger of Allah made Zakat al-Fitr obligatory: a sa' of dates or barley, upon every Muslim, slave or free, male or female.","ru":"Посланник Аллаха обязал закят аль-фитр: один саа фиников или ячменя с каждого мусульманина — раба и свободного, мужчины и женщины.","tr":"Rasulullah (s.a.s) fıtır zekatını bir sa' hurma veya arpa olarak köle-hür, erkek-kadın her Müslümana farz kıldı.","ar":"فَرَضَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ زَكَاةَ الْفِطْرِ صَاعًا مِنْ تَمْرٍ أَوْ صَاعًا مِنْ شَعِيرٍ عَلَى الْعَبْدِ وَالْحُرِّ وَالذَّكَرِ وَالأُنْثَى"},"src":{"az":"Buxari, Zəkat 76","en":"Bukhari, Zakat 76","ru":"Бухари, Закят 76","tr":"Buhârî, Zekât 76","ar":"البخاري، الزكاة 76"}},{"id":1609,"t":{"az":"Fitrə zəkatını insanlar namaza çıxmadan əvvəl verin.","en":"Pay Zakat al-Fitr before the people go out to the Eid prayer.","ru":"Выплачивайте закят аль-фитр до выхода людей на праздничную молитву.","tr":"Fıtır zekatını insanlar namaza çıkmadan önce verin.","ar":"أَدُّوا زَكَاةَ الْفِطْرِ قَبْلَ خُرُوجِ النَّاسِ إِلَى الصَّلاَةِ"},"src":{"az":"Buxari, Zəkat 77","en":"Bukhari, Zakat 77","ru":"Бухари, Закят 77","tr":"Buhârî, Zekât 77","ar":"البخاري، الزكاة 77"}},{"id":1610,"t":{"az":"Kim ölsə və üzərində oruc borcu olsa, onun əvəzinə vəlisi tutar.","en":"Whoever dies with fasting days owed, his guardian should fast on his behalf.","ru":"Кто умрёт, имея невосполненный пост, пусть его опекун постится за него.","tr":"Kim ölür ve üzerinde oruç borcu olursa onun yerine velisi tutar.","ar":"مَنْ مَاتَ وَعَلَيْهِ صِيَامٌ صَامَ عَنْهُ وَلِيُّهُ"},"src":{"az":"Buxari, Savm 42","en":"Bukhari, Sawm 42","ru":"Бухари, Саум 42","tr":"Buhârî, Savm 42","ar":"البخاري، الصوم 42"}},{"id":1611,"t":{"az":"Kim oruc tutmağa qadir olmasa, hər gün üçün bir yoxsulu yedirməlidir.","en":"Whoever is unable to fast must feed a needy person for each day.","ru":"Кто не может поститься, должен кормить бедняка за каждый день.","tr":"Kim oruç tutmaya güç yetiremezse her gün için bir yoksula yedirmelidir.","ar":"مَنْ لَمْ يَسْتَطِعِ الصَّوْمَ فَعَلَيْهِ لِكُلِّ يَوْمٍ إِطْعَامُ مِسْكِينٍ"},"src":{"az":"Buxari, Təfsir Bəqərə 25","en":"Bukhari, Tafsir al-Baqarah 25","ru":"Бухари, Тафсир аль-Бакара 25","tr":"Buhârî, Tefsîr el-Bakara 25","ar":"البخاري، تفسير سورة البقرة 25"}},{"id":1633,"t":{"az":"Peyğəmbər (s.a.s) gözəl ətir istifadə etməyi sevərdi.","en":"The Prophet loved using perfume.","ru":"Пророк любил благовония.","tr":"Peygamber (s.a.s) güzel koku kullanmayı severdi.","ar":"كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُحِبُّ الطِّيبَ"},"src":{"az":"Buxari, Libas 73","en":"Bukhari, Libas 73","ru":"Бухари, Либас 73","tr":"Buhârî, Libâs 73","ar":"البخاري، اللباس 73"}},{"id":1634,"t":{"az":"Kimə ətir təklif edilsə geri çevirməsin. Daşıması yüngül, qoxusu gözəldir.","en":"Whoever is offered perfume should not refuse it, for it is light to carry and pleasant in scent.","ru":"Кому предложат благовония, пусть не отказывается, ибо они легки и приятны.","tr":"Kime koku teklif edilirse geri çevirmesin. Taşıması hafif, kokusu güzeldir.","ar":"مَنْ عُرِضَ عَلَيْهِ طِيبٌ فَلاَ يَرُدَّهُ فَإِنَّهُ خَفِيفُ الْمَحْمِلِ طَيِّبُ الرَّائِحَةِ"},"src":{"az":"Muslim, Alfaz 20","en":"Muslim, Alfaz 20","ru":"Муслим, Альфаз 20","tr":"Müslim, Elfâz 20","ar":"مسلم، الألفاظ 20"}},{"id":1635,"t":{"az":"Ayaqqabı geyməkdə, saçını daramaqda, dəstəmaz almaqda və bütün işlərində sağdan başlamağı sevərdi.","en":"He liked to start from the right in putting on shoes, combing hair, ablution, and in all his affairs.","ru":"Он любил начинать справа при надевании обуви, расчёсывании волос, омовении и во всех своих делах.","tr":"Ayakkabı giymede, saçını taramada, abdest almada ve bütün işlerinde sağdan başlamayı severdi.","ar":"كَانَ يُعْجِبُهُ التَّيَمُّنُ فِي تَنَعُّلِهِ وَتَرَجُّلِهِ وَطُهُورِهِ وَفِي شَأْنِهِ كُلِّهِ"},"src":{"az":"Buxari, Vüdu 31","en":"Bukhari, Wudu 31","ru":"Бухари, Вуду 31","tr":"Buhârî, Vudû 31","ar":"البخاري، الوضوء 31"}},{"id":1636,"t":{"az":"Bunu dəyişdirin (ağ saçları boyayın), lakin qara rəngdən çəkinin.","en":"Change this white hair with something, but avoid black.","ru":"Измените это чем-нибудь, но избегайте чёрного.","tr":"Bunu bir şeyle değiştirin ama siyahtan kaçının.","ar":"غَيِّرُوا هَذَا بِشَيْءٍ وَاجْتَنِبُوا السَّوَادَ"},"src":{"az":"Muslim, Libas 79","en":"Muslim, Libas 79","ru":"Муслим, Либас 79","tr":"Müslim, Libâs 79","ar":"مسلم، اللباس 79"}},{"id":1639,"t":{"az":"Sevgi dolu, çoxlu uşaq doğan qadınlarla evlənin, çünki ümmətlər arasında sayınızla öyünəcəyəm.","en":"Marry the loving and fertile, for I will boast of your numbers among the nations.","ru":"Женитесь на любящих и плодовитых, ибо я буду гордиться вашей численностью.","tr":"Seven ve çok çocuk doğuran kadınlarla evlenin, ümmetler arasında sizin çokluğunuzla övüneceğim.","ar":"تَزَوَّجُوا الْوَدُودَ الْوَلُودَ فَإِنِّي مُكَاثِرٌ بِكُمُ الأُمَمَ"},"src":{"az":"Əbu Davud 2050","en":"Abu Dawud 2050","ru":"Абу Дауд 2050","tr":"Ebû Dâvûd 2050","ar":"أبو داود 2050"}},{"id":1642,"t":{"az":"Dul qadın izni olmadan nikahlanmaz, bakirə qız icazəsi olmadan nikahlanmaz.","en":"A previously married woman should not be married without her consent, and a virgin without her permission.","ru":"Ранее замужняя женщина не выходит замуж без согласия, и девственница без разрешения.","tr":"Dul kadın izni olmadan nikahlanmaz, bakire kız izni olmadan nikahlanmaz.","ar":"لاَ تُنْكَحُ الأَيِّمُ حَتَّى تُسْتَأْمَرَ وَلاَ تُنْكَحُ الْبِكْرُ حَتَّى تُسْتَأْذَنَ"},"src":{"az":"Buxari, Nikah 41","en":"Bukhari, Nikah 41","ru":"Бухари, Никах 41","tr":"Buhârî, Nikâh 41","ar":"البخاري، النكاح 41"}},{"id":1644,"t":{"az":"Dəmir üzükdən ibarət olsa belə mehr axtar.","en":"Find something as mahr even if it is a ring of iron.","ru":"Найди что-нибудь в качестве махра, даже кольцо из железа.","tr":"Demir yüzükten ibaret olsa bile mehir ara.","ar":"الْتَمِسْ وَلَوْ خَاتَمًا مِنْ حَدِيدٍ"},"src":{"az":"Buxari, Nikah 37","en":"Bukhari, Nikah 37","ru":"Бухари, Никах 37","tr":"Buhârî, Nikâh 37","ar":"البخاري، النكاح 37"}},{"id":1645,"t":{"az":"Bir qoyunla da olsa ziyafət ver.","en":"Give a wedding feast, even if with one sheep.","ru":"Устрой свадебный пир, даже с одной овцой.","tr":"Bir koyunla da olsa düğün ziyafeti ver.","ar":"أَوْلِمْ وَلَوْ بِشَاةٍ"},"src":{"az":"Buxari, Nikah 68","en":"Bukhari, Nikah 68","ru":"Бухари, Никах 68","tr":"Buhârî, Nikâh 68","ar":"البخاري، النكاح 68"}},{"id":1649,"t":{"az":"Süd əmizdirilmə doğumun haram etdiyini haram edər.","en":"Breastfeeding prohibits what birth prohibits in terms of marriage.","ru":"Кормление грудью делает запретным то, что запрещено рождением.","tr":"Süt emzirme doğumun haram kıldığını haram kılar.","ar":"الرَّضَاعَةُ تُحَرِّمُ مَا تُحَرِّمُ الْوِلاَدَةُ"},"src":{"az":"Buxari, Nikah 20","en":"Bukhari, Nikah 20","ru":"Бухари, Никах 20","tr":"Buhârî, Nikâh 20","ar":"البخاري، النكاح 20"}},{"id":1650,"t":{"az":"Anaya uşağına görə zərər verilməsin, ataya da övladına görə zərər verilməsin.","en":"No mother shall be harmed through her child, nor a father through his child.","ru":"Нельзя причинять вред матери из-за ребёнка и отцу из-за ребёнка.","tr":"Anneye çocuğu yüzünden zarar verilmesin, babaya da çocuğu yüzünden zarar verilmesin.","ar":"لاَ تُضَارَّ وَالِدَةٌ بِوَلَدِهَا وَلاَ مَوْلُودٌ لَهُ بِوَلَدِهِ"},"src":{"az":"Buxari, Təfsir Bəqərə 233","en":"Bukhari, Tafsir al-Baqarah 233","ru":"Бухари, Тафсир аль-Бакара 233","tr":"Buhârî, Tefsîr el-Bakara 233","ar":"البخاري، تفسير سورة البقرة 233"}},{"id":1651,"t":{"az":"Bir adam ailəsinə xərcləyib savab gözləsə, bu onun üçün sədəqədir.","en":"When a man spends on his family seeking reward, it is charity for him.","ru":"Когда мужчина тратит на семью, надеясь на награду, это милостыня.","tr":"Bir adam ailesine harcayıp sevap beklerse bu onun için sadakadır.","ar":"إِذَا أَنْفَقَ الرَّجُلُ عَلَى أَهْلِهِ يَحْتَسِبُهَا فَهِيَ لَهُ صَدَقَةٌ"},"src":{"az":"Buxari, İman 41","en":"Bukhari, Iman 41","ru":"Бухари, Иман 41","tr":"Buhârî, İman 41","ar":"البخاري، الإيمان 41"}},{"id":1653,"t":{"az":"Kim iki qız uşağını böyüyənə qədər baxsa, Qiyamət günü mənimlə belə gələr - barmaqlarını birləşdirdi.","en":"Whoever raises two girls until they reach maturity, he and I will come on the Day of Judgment like this - and he joined his fingers.","ru":"Кто воспитает двух девочек до их взросления, в День Суда мы с ним придём вот так — и он соединил пальцы.","tr":"Kim iki kız çocuğunu büyüyene kadar bakarsa Kıyamet günü benimle böyle gelir - ve parmaklarını birleştirdi.","ar":"مَنْ عَالَ جَارِيَتَيْنِ حَتَّى تَبْلُغَا جَاءَ يَوْمَ الْقِيَامَةِ أَنَا وَهُوَ وَضَمَّ أَصَابِعَهُ"},"src":{"az":"Muslim, Birr 149","en":"Muslim, Birr 149","ru":"Муслим, Бирр 149","tr":"Müslim, Birr 149","ar":"مسلم، البر والصلة 149"}},{"id":1654,"t":{"az":"Mən və yetimə baxan Cənnətdə belə olacağıq - şəhadət və orta barmağına işarə etdi.","en":"I and the guardian of the orphan will be in Paradise like this - and he indicated with his index and middle fingers.","ru":"Я и опекун сироты будем в Раю вот так — и он указал указательным и средним пальцами.","tr":"Ben ve yetimi himaye eden Cennette böyle olacağız - ve işaret ve orta parmağına işaret etti.","ar":"أَنَا وَكَافِلُ الْيَتِيمِ فِي الْجَنَّةِ هَكَذَا وَأَشَارَ بِالسَّبَّابَةِ وَالْوُسْطَى"},"src":{"az":"Buxari, Ədəb 24","en":"Bukhari, Adab 24","ru":"Бухари, Адаб 24","tr":"Buhârî, Edeb 24","ar":"البخاري، الأدب 24"}},{"id":1656,"t":{"az":"Sizə Cənnət əhlini xəbər verimmi? Hər zəif, gücsüz görünən ki, Allaha and versə, Allah andını doğrular. Sizə Cəhənnəm əhlini xəbər verimmi? Hər kobud, tamahkar, təkəbbürlü.","en":"Shall I tell you about the people of Paradise? Every weak and humble person who, if he swore by Allah, Allah would fulfill his oath. Shall I tell you about the people of Hell? Every harsh, greedy, and arrogant person.","ru":"Не сообщить ли вам о людях Рая? Каждый слабый и скромный, если поклянётся Аллахом, Аллах исполнит его клятву. Не сообщить ли вам о людях Ада? Каждый грубый, жадный и высокомерный.","tr":"Size Cennet ehlini haber vereyim mi? Her zayıf ve mütevazı ki Allah'a yemin etse Allah yeminini doğrular. Size Cehennem ehlini haber vereyim mi? Her kaba, tamahkâr ve kibirli.","ar":"أَلاَ أُنَبِّئُكُمْ بِأَهْلِ الْجَنَّةِ كُلُّ ضَعِيفٍ مُتَضَعِّفٍ لَوْ أَقْسَمَ عَلَى اللَّهِ لأَبَرَّهُ أَلاَ أُنَبِّئُكُمْ بِأَهْلِ النَّارِ كُلُّ عُتُلٍّ جَوَّاظٍ مُسْتَكْبِرٍ"},"src":{"az":"Buxari, Təfsir 68","en":"Bukhari, Tafsir 68","ru":"Бухари, Тафсир 68","tr":"Buhârî, Tefsîr 68","ar":"البخاري، التفسير 68"}},{"id":1657,"t":{"az":"Müsəlmana çətinlik, xəstəlik, qəm, kədər, hətta batılan tikan belə isabət etməz ki, Allah günahlarından silməsin.","en":"No fatigue, illness, worry, sadness, or harm befalls a Muslim, not even a thorn, except that Allah expiates some sins through it.","ru":"Мусульманина не постигнет усталость, болезнь, беспокойство, печаль или обида, даже укол колючки, без искупления грехов.","tr":"Müslümana yorgunluk, hastalık, kaygı, üzüntü, hatta batan diken bile isabet etmez ki Allah günahlarından silmesin.","ar":"مَا يُصِيبُ الْمُسْلِمَ مِنْ نَصَبٍ وَلاَ وَصَبٍ وَلاَ هَمٍّ وَلاَ حُزْنٍ وَلاَ أَذًى وَلاَ غَمٍّ حَتَّى الشَّوْكَةِ يُشَاكُهَا إِلاَّ كَفَّرَ اللَّهُ بِهَا مِنْ خَطَايَاهُ"},"src":{"az":"Buxari, Mərdha 1","en":"Bukhari, Marda 1","ru":"Бухари, Марда 1","tr":"Buhârî, Merdâ 1","ar":"البخاري، المرضى 1"}},{"id":1660,"t":{"az":"Möminlər sevgi və mərhəmətdə bir bədən kimidir. Bir üzvü ağrıdıqda qalanı yuxusuzluq və qızdırma ilə cavab verər.","en":"The believers in mutual love and mercy are like a body. When one limb suffers, the rest responds with sleeplessness and fever.","ru":"Верующие в любви и милосердии подобны телу. Когда один орган страдает, остальное тело отзывается бессонницей и лихорадкой.","tr":"Müminler sevgi ve merhamette bir vücut gibidirler. Bir uzvu ağrıdığında geri kalanı uykusuzluk ve ateşle cevap verir.","ar":"مَثَلُ الْمُؤْمِنِينَ فِي تَوَادِّهِمْ وَتَرَاحُمِهِمْ كَمَثَلِ الْجَسَدِ إِذَا اشْتَكَى مِنْهُ عُضْوٌ تَدَاعَى لَهُ سَائِرُ الْجَسَدِ بِالسَّهَرِ وَالْحُمَّى"},"src":{"az":"Muslim, Birr 66","en":"Muslim, Birr 66","ru":"Муслим, Бирр 66","tr":"Müslim, Birr 66","ar":"مسلم، البر والصلة 66"}},{"id":1662,"t":{"az":"Yanaqlara vuran, yaxalıqları yırtan və cahiliyyə çağırışı ilə çağıran bizdən deyildir.","en":"He is not one of us who slaps cheeks, tears garments, and calls with the call of the pre-Islamic era.","ru":"Не из нас тот, кто бьёт себя по щекам, рвёт одежду и призывает призывом невежества.","tr":"Yanaklara vuran, yakaları yırtan ve cahiliye çağrısıyla çağıran bizden değildir.","ar":"لَيْسَ مِنَّا مَنْ لَطَمَ الْخُدُودَ وَشَقَّ الْجُيُوبَ وَدَعَا بِدَعْوَى الْجَاهِلِيَّةِ"},"src":{"az":"Buxari, Cənaiz 36","en":"Bukhari, Jana'iz 36","ru":"Бухари, Джанаиз 36","tr":"Buhârî, Cenâiz 36","ar":"البخاري، الجنائز 36"}},{"id":1663,"t":{"az":"Kim Allah yolunda imanla bir at saxlasa, onun yeməsi və suyu Qiyamət günü tərəzisində olacaq.","en":"Whoever keeps a horse for Allah's cause out of faith, its food and water will be in his scale on Judgment Day.","ru":"Кто содержит коня на пути Аллаха с верой, его корм и питьё будут на весах в День Суда.","tr":"Kim Allah yolunda imanla bir at tutarsa onun yemesi ve suyu Kıyamet günü terazisinde olacaktır.","ar":"مَنْ حَبَسَ فَرَسًا فِي سَبِيلِ اللَّهِ إِيمَانًا وَاحْتِسَابًا فَإِنَّ شِبَعَهُ وَرِيَّهُ فِي مِيزَانِهِ يَوْمَ الْقِيَامَةِ"},"src":{"az":"Buxari, Cihad 45","en":"Bukhari, Jihad 45","ru":"Бухари, Джихад 45","tr":"Buhârî, Cihâd 45","ar":"البخاري، الجهاد 45"}},{"id":1664,"t":{"az":"Kim bir əmlakını vəqf etsə, əsli satılmaz, bağışlanmaz, miras verilməz, lakin meyvəsi xərclənər.","en":"Whoever endows his property as waqf, its original cannot be sold, gifted, or inherited, but its produce is spent.","ru":"Кто сделает вакф из недвижимости, основа не продаётся, не дарится, не наследуется, но плоды расходуются.","tr":"Kim bir mülkünü vakfederse aslı satılmaz, bağışlanmaz, miras bırakılmaz ama meyvesi harcanır.","ar":"مَنْ وَقَفَ عَقَارًا لَهُ لاَ يُبَاعُ أَصْلُهَا وَلاَ يُوهَبُ وَلاَ يُورَثُ وَلَكِنْ يُنْفَقُ ثَمَرَتُهَا"},"src":{"az":"Buxari, Şürut 19","en":"Bukhari, Shurut 19","ru":"Бухари, Шурут 19","tr":"Buhârî, Şurût 19","ar":"البخاري، الشروط 19"}},{"id":1666,"t":{"az":"Alimlər peyğəmbərlərin varisləridir. Peyğəmbərlər elm miras qoymuşlar.","en":"The scholars are heirs of the prophets. The prophets left behind knowledge.","ru":"Учёные — наследники пророков. Пророки оставили знание.","tr":"Âlimler peygamberlerin varisleridir. Peygamberler ilim miras bırakmışlardır.","ar":"إِنَّ الْعُلَمَاءَ وَرَثَةُ الأَنْبِيَاءِ وَإِنَّ الأَنْبِيَاءَ لَمْ يُوَرِّثُوا دِينَارًا وَلاَ دِرْهَمًا وَرَّثُوا الْعِلْمَ"},"src":{"az":"Əbu Davud 3641","en":"Abu Dawud 3641","ru":"Абу Дауд 3641","tr":"Ebû Dâvûd 3641","ar":"أبو داود 3641"}},{"id":1668,"t":{"az":"Peyğəmbər (s.a.s) qorxu namazını bir qrupla bir rəkət qılar, digər qrup düşmənlə üz-üzə olardı.","en":"The Prophet would pray the fear prayer with one group for one rak'ah while the other group faced the enemy.","ru":"Пророк совершал молитву страха с одной группой один ракаат, а другая группа стояла лицом к врагу.","tr":"Peygamber (s.a.s) korku namazını bir grupla bir rekat kılar, diğer grup düşmanla yüz yüze olurdu.","ar":"كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي صَلاَةَ الْخَوْفِ بِإِحْدَى الطَّائِفَتَيْنِ رَكْعَةً وَالطَّائِفَةُ الأُخْرَى مُوَاجِهَةُ الْعَدُوِّ"},"src":{"az":"Buxari, Salat əl-Xovf 1","en":"Bukhari, Salat al-Khawf 1","ru":"Бухари, Салят аль-Хауф 1","tr":"Buhârî, Salâtü'l-Havf 1","ar":"البخاري، صلاة الخوف 1"}},{"id":1669,"t":{"az":"Biriniz səhər olduqda desin: Səhərə çıxdıq və mülk Allahındır. Həmd Allahadır. Allahdan başqa ilah yoxdur, tək Odur, ortağı yoxdur.","en":"When one of you reaches the morning, let him say: We have reached the morning and the dominion belongs to Allah. Praise is for Allah. There is no god but Allah alone with no partner.","ru":"Когда наступит утро, пусть скажет: Мы достигли утра, и власть принадлежит Аллаху. Хвала Аллаху. Нет бога, кроме Аллаха, Единого, без сотоварища.","tr":"Biriniz sabah olduğunda desin: Sabaha çıktık ve mülk Allah'ındır. Hamd Allah'adır. Allah'tan başka ilah yoktur, tek O'dur, ortağı yoktur.","ar":"إِذَا أَصْبَحَ أَحَدُكُمْ فَلْيَقُلْ أَصْبَحْنَا وَأَصْبَحَ الْمُلْكُ لِلَّهِ وَالْحَمْدُ لِلَّهِ لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ"},"src":{"az":"Muslim, Zikr 75","en":"Muslim, Dhikr 75","ru":"Муслим, Зикр 75","tr":"Müslim, Zikir 75","ar":"مسلم، الذكر 75"}},{"id":1670,"t":{"az":"İstiğfarın ən üstünü budur: Allahım, Sən mənim Rəbbimsən, Səndən başqa ilah yoxdur, məni Sən yaratdın, mən Sənin qulunam, əhdinə və vədinə bacardığım qədər sadiqəm.","en":"The master of seeking forgiveness is to say: O Allah, You are my Lord. There is no god but You. You created me and I am Your servant. I uphold Your covenant and promise as best I can.","ru":"Лучшая мольба о прощении: О Аллах, Ты мой Господь. Нет бога, кроме Тебя. Ты создал меня, и я Твой раб. Я верен Твоему завету и обещанию, насколько могу.","tr":"İstiğfarın en üstünü şudur: Allahım, Sen benim Rabbimsin, Senden başka ilah yoktur, beni Sen yarattın, ben Senin kulunum, ahdine ve vadine gücüm yettiğince bağlıyım.","ar":"سَيِّدُ الاِسْتِغْفَارِ أَنْ تَقُولَ اللَّهُمَّ أَنْتَ رَبِّي لاَ إِلَهَ إِلاَّ أَنْتَ خَلَقْتَنِي وَأَنَا عَبْدُكَ وَأَنَا عَلَى عَهْدِكَ وَوَعْدِكَ مَا اسْتَطَعْتُ"},"src":{"az":"Buxari, Dəavat 2","en":"Bukhari, Da'awat 2","ru":"Бухари, Даават 2","tr":"Buhârî, Deavât 2","ar":"البخاري، الدعوات 2"}},{"id":1671,"t":{"az":"Kim gündə yüz dəfə \"La ilahə illəllahu vahdəhu la şərikə ləh, ləhul-mulku və ləhul-hamdu və huvə alə kulli şeyin qadir\" desə, on kölə azad etmiş qədər savab alar.","en":"Whoever says \"La ilaha illallahu wahdahu la sharika lah, lahul-mulku wa lahul-hamdu wa huwa ala kulli shay'in qadir\" one hundred times a day will have the reward of freeing ten slaves.","ru":"Кто скажет «Ля иляха илляллаху вахдаху ля шарика лях, ляхуль-мульку ва ляхуль-хамду ва хува аля кулли шайин кадир» сто раз в день, получит награду, равную освобождению десяти рабов.","tr":"Kim günde yüz kere \"La ilahe illallahu vahdehu la şerike leh, lehül-mülkü ve lehül-hamdü ve hüve ala külli şeyin kadir\" derse on köle azat etmiş kadar sevap alır.","ar":"مَنْ قَالَ لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ فِي يَوْمٍ مِائَةَ مَرَّةٍ كَانَتْ لَهُ عَدْلَ عَشْرِ رِقَابٍ"},"src":{"az":"Buxari, Dəavat 64","en":"Bukhari, Da'awat 64","ru":"Бухари, Даават 64","tr":"Buhârî, Deavât 64","ar":"البخاري، الدعوات 64"}},{"id":1679,"t":{"az":"Biriniz yatağına girdikdə yatağını silkələsin, sonra desin: Rəbbim, Sənin adınla yanımı qoydum və Səninlə qaldıracağam.","en":"When one goes to bed, dust off the bed, then say: In Your name, my Lord, I lay my side and by You I raise it.","ru":"Ложась в постель, стряхни её, затем скажи: Именем Твоим, Господь мой, я положил свой бок и Тобой подниму его.","tr":"Biriniz yatağına girdiğinde yatağını silkesin, sonra desin: Rabbim, Senin adınla yanımı koydum ve Seninle kaldıracağım.","ar":"إِذَا أَوَى أَحَدُكُمْ إِلَى فِرَاشِهِ فَلْيَنْفُضْ فِرَاشَهُ بِدَاخِلَةِ إِزَارِهِ ثُمَّ يَقُولُ بِاسْمِكَ رَبِّي وَضَعْتُ جَنْبِي وَبِكَ أَرْفَعُهُ"},"src":{"az":"Buxari, Dəavat 13","en":"Bukhari, Da'awat 13","ru":"Бухари, Даават 13","tr":"Buhârî, Deavât 13","ar":"البخاري، الدعوات 13"}},{"id":1686,"t":{"az":"Qonşu öz qonşuluğuna daha çox haqlıdır (şüf'ə haqqı).","en":"The neighbor has more right to his adjacent property (right of pre-emption).","ru":"Сосед имеет больше прав на прилегающую собственность (право преимущественной покупки).","tr":"Komşu kendi komşuluğuna daha çok hak sahibidir (şüfa hakkı).","ar":"الْجَارُ أَحَقُّ بِصَقَبِهِ"},"src":{"az":"Buxari, Şüf'ə 2","en":"Bukhari, Shuf'ah 2","ru":"Бухари, Шуфа 2","tr":"Buhârî, Şuf'a 2","ar":"البخاري، الشفعة 2"}},{"id":1690,"t":{"az":"Ölüm ağappaq qoç şəklində gətirilər, Cənnət ilə Cəhənnəm arasında kəsilər. Sonra deyilər: Ey Cənnət əhli, əbədiyyət var ölüm yox! Ey Cəhənnəm əhli, əbədiyyət var ölüm yox!","en":"Death will be brought in the form of a white ram and slaughtered between Paradise and Hell. Then it will be said: O people of Paradise, eternity and no death! O people of Hell, eternity and no death!","ru":"Смерть будет принесена в виде белого барана и заколота между Раем и Адом. Затем скажут: О обитатели Рая, вечность без смерти! О обитатели Ада, вечность без смерти!","tr":"Ölüm bembeyaz koç şeklinde getirilir, Cennet ile Cehennem arasında kesilir. Sonra denir: Ey Cennet ehli, ebediyet var ölüm yok! Ey Cehennem ehli, ebediyet var ölüm yok!","ar":"يُؤْتَى بِالْمَوْتِ كَهَيْئَةِ كَبْشٍ أَمْلَحَ فَيُذْبَحُ بَيْنَ الْجَنَّةِ وَالنَّارِ ثُمَّ يُقَالُ يَا أَهْلَ الْجَنَّةِ خُلُودٌ فَلاَ مَوْتَ وَيَا أَهْلَ النَّارِ خُلُودٌ فَلاَ مَوْتَ"},"src":{"az":"Buxari, Riqaq 51","en":"Bukhari, Riqaq 51","ru":"Бухари, Рикак 51","tr":"Buhârî, Rikâk 51","ar":"البخاري، الرقاق 51"}},{"id":1691,"t":{"az":"Biriniz ayaqyoluna girdikdə nə qibləyə tərəf dursun, nə də arxasını çevirsin.","en":"When one enters the toilet, let him not face the qiblah nor turn his back to it.","ru":"Когда входишь в уборную, не обращайся лицом к кибле и не поворачивайся к ней спиной.","tr":"Biriniz tuvalete girdiğinde ne kıbleye dönsün ne de sırtını çevirsin.","ar":"إِذَا دَخَلَ أَحَدُكُمُ الْخَلاَءَ فَلاَ يَسْتَقْبِلِ الْقِبْلَةَ وَلاَ يَسْتَدْبِرْهَا"},"src":{"az":"Buxari, Vüdu 11","en":"Bukhari, Wudu 11","ru":"Бухари, Вуду 11","tr":"Buhârî, Vudû 11","ar":"البخاري، الوضوء 11"}},{"id":1692,"t":{"az":"Peyğəmbər (s.a.s) su ilə istinca edərdi (təmizlənərdi).","en":"The Prophet used to cleanse himself with water.","ru":"Пророк очищался водой.","tr":"Peygamber (s.a.s) su ile istinca ederdi (temizlenirdi).","ar":"كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَسْتَنْجِي بِالْمَاءِ"},"src":{"az":"Buxari, Vüdu 15","en":"Bukhari, Wudu 15","ru":"Бухари, Вуду 15","tr":"Buhârî, Vudû 15","ar":"البخاري، الوضوء 15"}},{"id":1693,"t":{"az":"Biriniz yuxudan oyandıqda əlini üç dəfə yumadan qaba batırmasın.","en":"When one of you wakes from sleep, let him not dip his hand in the vessel until he has washed it three times.","ru":"Когда проснётесь, не погружайте руку в сосуд, пока не вымоете её три раза.","tr":"Biriniz uykudan uyandığında elini üç kere yıkamadan kaba batırmasın.","ar":"إِذَا اسْتَيْقَظَ أَحَدُكُمْ مِنْ نَوْمِهِ فَلاَ يَغْمِسْ يَدَهُ فِي الإِنَاءِ حَتَّى يَغْسِلَهَا ثَلاَثًا"},"src":{"az":"Buxari, Vüdu 26","en":"Bukhari, Wudu 26","ru":"Бухари, Вуду 26","tr":"Buhârî, Vudû 26","ar":"البخاري، الوضوء 26"}},{"id":1694,"t":{"az":"Kim mənim bu dəstəmazım kimi dəstəmaz alıb sonra iki rəkət qılsa və o iki rəkətdə nəfsi ilə danışmasa, keçmiş günahları bağışlanar.","en":"Whoever performs wudu like mine then prays two rak'ahs without his mind wandering, his past sins will be forgiven.","ru":"Кто совершит омовение подобно моему, затем помолится два ракаата, не отвлекаясь мыслями, ему простятся прошлые грехи.","tr":"Kim benim bu abdestim gibi abdest alıp iki rekat kılar da o iki rekatta nefsiyle konuşmazsa geçmiş günahları bağışlanır.","ar":"مَنْ تَوَضَّأَ نَحْوَ وُضُوئِي هَذَا ثُمَّ صَلَّى رَكْعَتَيْنِ لاَ يُحَدِّثُ فِيهِمَا نَفْسَهُ غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ"},"src":{"az":"Buxari, Vüdu 24","en":"Bukhari, Wudu 24","ru":"Бухари, Вуду 24","tr":"Buhârî, Vudû 24","ar":"البخاري، الوضوء 24"}},{"id":1695,"t":{"az":"Yaşıl torpaqda səfər etdikdə dəvələrə yerdən paylarını verin. Quraqlıq zamanı səfər etdikdə isə yolu tezləşdirin.","en":"When you travel in fertile land, give the camels their share of the ground. When you travel in drought, hasten the journey.","ru":"Когда путешествуете по плодородной земле, дайте верблюдам их долю от земли. Когда путешествуете в засуху, ускоряйте путь.","tr":"Yeşil toprakta seyahat ettiğinizde develere yerden paylarını verin. Kuraklıkta seyahat ettiğinizde ise yolu hızlandırın.","ar":"إِذَا سَافَرْتُمْ فِي الْخِصْبِ فَأَعْطُوا الإِبِلَ حَظَّهَا مِنَ الأَرْضِ وَإِذَا سَافَرْتُمْ فِي السَّنَةِ فَأَسْرِعُوا عَلَيْهَا السَّيْرَ"},"src":{"az":"Muslim, İmarat 178","en":"Muslim, Imarah 178","ru":"Муслим, Имара 178","tr":"Müslim, İmâre 178","ar":"مسلم، الإمارة 178"}},{"id":1696,"t":{"az":"Səfər əzabın bir parçasıdır, birinizin yeməyinə, içməyinə və yuxusuna mane olar. İşini bitirdikdə ailəsinə tez qayıtsın.","en":"Travel is a piece of torment, preventing one from food, drink, and sleep. When one finishes his task, let him hasten back to his family.","ru":"Путешествие — часть мучения, оно лишает еды, питья и сна. Когда закончит дело, пусть поспешит к семье.","tr":"Seferi azabın bir parçasıdır, kişinin yemesine, içmesine ve uyumasına engel olur. İşini bitirdiğinde ailesine acele dönsün.","ar":"السَّفَرُ قِطْعَةٌ مِنَ الْعَذَابِ يَمْنَعُ أَحَدَكُمْ طَعَامَهُ وَشَرَابَهُ وَنَوْمَهُ فَإِذَا قَضَى نَهْمَتَهُ مِنْ وَجْهِهِ فَلْيُعَجِّلْ إِلَى أَهْلِهِ"},"src":{"az":"Buxari, Cihad 132","en":"Bukhari, Jihad 132","ru":"Бухари, Джихад 132","tr":"Buhârî, Cihâd 132","ar":"البخاري، الجهاد 132"}},{"id":1697,"t":{"az":"Allahım, səfərin çətinliyindən, mənzərənin kədərindən, mal və ailədə pis dönüşdən Sənə sığınıram.","en":"O Allah, I seek refuge in You from the hardship of travel, gloom of the sight, and evil of return in wealth and family.","ru":"О Аллах, прибегаю к Тебе от тягот путешествия, мрачного вида и дурного возвращения в имуществе и семье.","tr":"Allah'ım, seferin zorluğundan, manzaranın hüznünden, mal ve ailede kötü dönüşten Sana sığınırım.","ar":"اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ وَعْثَاءِ السَّفَرِ وَكَآبَةِ الْمَنْظَرِ وَسُوءِ الْمُنْقَلَبِ فِي الْمَالِ وَالأَهْلِ"},"src":{"az":"Muslim, Həcc 425","en":"Muslim, Hajj 425","ru":"Муслим, Хадж 425","tr":"Müslim, Hac 425","ar":"مسلم، الحج 425"}},{"id":1698,"t":{"az":"Allaha və Axirət gününə inanan qadın bir gün bir gecəlik yolu məhrəmsiz getməsin.","en":"A woman who believes in Allah and the Last Day should not travel a day and night's journey without a mahram.","ru":"Женщина, верующая в Аллаха и Судный день, не должна путешествовать день и ночь без махрама.","tr":"Allah'a ve ahiret gününe inanan kadın bir gün bir gecelik yolu mahremsiz gitmesin.","ar":"مَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الآخِرِ فَلاَ يُسَافِرِ الْمَرْأَةُ مَسِيرَةَ يَوْمٍ وَلَيْلَةٍ إِلاَّ مَعَ ذِي مَحْرَمٍ"},"src":{"az":"Buxari, Təqsir 4","en":"Bukhari, Taqsir 4","ru":"Бухари, Таксир 4","tr":"Buhârî, Taksîr 4","ar":"البخاري، تقصير الصلاة 4"}},{"id":1699,"t":{"az":"Kim hakimlik vəzifəsinə təyin olunarsa, bıçaqsız kəsilmişdir.","en":"Whoever is appointed as a judge has been slaughtered without a knife.","ru":"Кого назначили судьёй, тот зарезан без ножа.","tr":"Kim hakimlik görevine atanırsa bıçaksız kesilmiştir.","ar":"مَنْ وُلِّيَ الْقَضَاءَ فَقَدْ ذُبِحَ بِغَيْرِ سِكِّينٍ"},"src":{"az":"Əbu Davud 3571","en":"Abu Dawud 3571","ru":"Абу Дауд 3571","tr":"Ebû Dâvûd 3571","ar":"أبو داود 3571"}},{"id":1700,"t":{"az":"Hakim hökm verərkən ictihad edib doğru taparsa, iki savab alar. İctihad edib xəta etsə, bir savab alar.","en":"When a judge makes a ruling, strives to be correct, and is right, he gets two rewards. If he strives and errs, he gets one reward.","ru":"Когда судья выносит решение, старается и оказывается прав, ему две награды. Если старается и ошибается, ему одна награда.","tr":"Hakim hüküm verirken ictihad edip doğruyu bulursa iki sevap alır. İctihad edip hata ederse bir sevap alır.","ar":"إِذَا حَكَمَ الْحَاكِمُ فَاجْتَهَدَ ثُمَّ أَصَابَ فَلَهُ أَجْرَانِ وَإِذَا حَكَمَ فَاجْتَهَدَ ثُمَّ أَخْطَأَ فَلَهُ أَجْرٌ"},"src":{"az":"Buxari, İ'tisam 21","en":"Bukhari, I'tisam 21","ru":"Бухари, Итисам 21","tr":"Buhârî, İ'tisâm 21","ar":"البخاري، الاعتصام بالكتاب والسنة 21"}},{"id":1701,"t":{"az":"Varisə vəsiyyət caiz deyildir.","en":"A bequest is not permissible for an heir.","ru":"Завещание не допускается для наследника.","tr":"Varise vasiyet caiz değildir.","ar":"الْوَصِيَّةُ لاَ تَجُوزُ لِوَارِثٍ"},"src":{"az":"Tirmizi 2120","en":"Tirmidhi 2120","ru":"Тирмизи 2120","tr":"Tirmizî 2120","ar":"الترمذي 2120"}},{"id":1702,"t":{"az":"Allah hər haq sahibinə haqqını vermişdir, varisə vəsiyyət yoxdur.","en":"Allah has given every rightful person his right, so no bequest to an heir.","ru":"Аллах дал каждому обладателю права его право, поэтому нет завещания наследнику.","tr":"Allah her hak sahibine hakkını vermiştir, varise vasiyet yoktur.","ar":"إِنَّ اللَّهَ قَدْ أَعْطَى كُلَّ ذِي حَقٍّ حَقَّهُ فَلاَ وَصِيَّةَ لِوَارِثٍ"},"src":{"az":"Əbu Davud 2870","en":"Abu Dawud 2870","ru":"Абу Дауд 2870","tr":"Ebû Dâvûd 2870","ar":"أبو داود 2870"}},{"id":1703,"t":{"az":"Vəsiyyət etmək istədiyi bir şeyi olan müsəlmanın vəsiyyətini yanında yazılı saxlamadan iki gecə keçirməyə haqqı yoxdur.","en":"It is not right for a Muslim who has something to bequeath to sleep two nights without having his will written beside him.","ru":"Нет права мусульманину, имеющему то, о чём хочет завещать, провести две ночи без написанного при нём завещания.","tr":"Vasiyet etmek istediği bir şeyi olan Müslümanın vasiyetini yanında yazılı tutmadan iki gece geçirmeye hakkı yoktur.","ar":"مَا حَقُّ امْرِئٍ مُسْلِمٍ لَهُ شَيْءٌ يُرِيدُ أَنْ يُوصِيَ فِيهِ يَبِيتُ لَيْلَتَيْنِ إِلاَّ وَوَصِيَّتُهُ مَكْتُوبَةٌ عِنْدَهُ"},"src":{"az":"Buxari, Vasaya 1","en":"Bukhari, Wasaya 1","ru":"Бухари, Васая 1","tr":"Buhârî, Vesâyâ 1","ar":"البخاري، الوصايا 1"}},{"id":1704,"t":{"az":"Allah buyurur: Mən qulumun Məni zənn etdiyi kimiyəm, Məni istədiyi kimi zənn etsin.","en":"Allah says: I am as My servant thinks of Me, so let him think of Me as he wishes.","ru":"Аллах говорит: Я таков, каким Мой раб думает обо Мне, пусть думает обо Мне, что пожелает.","tr":"Allah buyurur: Ben kulumun Beni zannettiği gibiyim, Beni istediği gibi zannetsin.","ar":"يَقُولُ اللَّهُ تَعَالَى أَنَا عِنْدَ ظَنِّ عَبْدِي بِي فَلْيَظُنَّ بِي مَا شَاءَ"},"src":{"az":"Əhməd 16016","en":"Ahmad 16016","ru":"Ахмад 16016","tr":"Ahmed 16016","ar":"أحمد 16016"}},{"id":1706,"t":{"az":"Qulun Rəbbinə ən yaxın olduğu an səcdə halıdır, çoxlu dua edin.","en":"The closest a servant is to his Lord is when he is in prostration, so increase your supplication.","ru":"Ближайшее состояние раба к Господу — когда он в земном поклоне, так увеличивайте мольбу.","tr":"Kulun Rabbine en yakın olduğu an secde halidir, çokça dua edin.","ar":"أَقْرَبُ مَا يَكُونُ الْعَبْدُ مِنْ رَبِّهِ وَهُوَ سَاجِدٌ فَأَكْثِرُوا الدُّعَاءَ"},"src":{"az":"Muslim, Salat 215","en":"Muslim, Salah 215","ru":"Муслим, Салят 215","tr":"Müslim, Salât 215","ar":"مسلم، الصلاة 215"}},{"id":1710,"t":{"az":"Birinizin duası qəbul olunar, tələsmədikcə. Tələsmək \"Rəbbimə dua etdim, qəbul etmədi\" deməkdir.","en":"The supplication of any one of you is answered as long as he does not become impatient, saying: I called upon my Lord but He did not respond.","ru":"Мольба каждого из вас принимается, пока он не торопится, говоря: Я взывал к Господу, но Он не ответил мне.","tr":"Birinizin duası kabul olunur, acele etmediği sürece. Acele etmek \"Rabbime dua ettim, kabul etmedi\" demektir.","ar":"يُسْتَجَابُ لأَحَدِكُمْ مَا لَمْ يَعْجَلْ يَقُولُ قَدْ دَعَوْتُ رَبِّي فَلَمْ يَسْتَجِبْ لِي"},"src":{"az":"Buxari, Dəavat 22","en":"Bukhari, Da'awat 22","ru":"Бухари, Даават 22","tr":"Buhârî, Deavât 22","ar":"البخاري، الدعوات 22"}},{"id":1713,"t":{"az":"Kim özünün və ya başqasının yetiminə baxsa, mən və o Cənnətdə bu ikisi kimiyik.","en":"Whoever sponsors an orphan, whether his own or another's, I and he will be like these two in Paradise.","ru":"Кто опекает сироту, своего или чужого, я и он будем в Раю как эти два (пальца).","tr":"Kim kendi veya başkasının yetimini himaye ederse ben ve o Cennette bu ikisi gibiyiz.","ar":"مَنْ كَفَلَ يَتِيمًا لَهُ أَوْ لِغَيْرِهِ فَأَنَا وَهُوَ كَهَاتَيْنِ فِي الْجَنَّةِ"},"src":{"az":"Muslim, Zühd 42","en":"Muslim, Zuhd 42","ru":"Муслим, Зухд 42","tr":"Müslim, Zühd 42","ar":"مسلم، الزهد 42"}},{"id":1716,"t":{"az":"Quranı mahir oxuyan kəramli və itaətkar mələklərlə birlikdədir. Quranı çətinliklə, kəkələyərək oxuyan isə iki savab qazanar.","en":"The one skilled in Quran is with the noble and obedient angels. The one who reads it with difficulty, stammering, gets two rewards.","ru":"Искусный в Коране будет с благородными и послушными ангелами. Кто читает его с трудом, запинаясь, получит двойную награду.","tr":"Kur'an'ı mahir okuyan kerim ve itaatkar meleklerle birliktedir. Kur'an'ı zorlanarak kekeleyerek okuyan ise iki sevap kazanır.","ar":"الْمَاهِرُ بِالْقُرْآنِ مَعَ السَّفَرَةِ الْكِرَامِ الْبَرَرَةِ وَالَّذِي يَقْرَأُ الْقُرْآنَ وَيَتَتَعْتَعُ فِيهِ وَهُوَ عَلَيْهِ شَاقٌّ لَهُ أَجْرَانِ"},"src":{"az":"Muslim, Müsafirin 244","en":"Muslim, Musafirin 244","ru":"Муслим, Мусафирин 244","tr":"Müslim, Müsâfirîn 244","ar":"مسلم، صلاة المسافرين 244"}},{"id":1717,"t":{"az":"Yalnız iki kişiyə qibtə olunur: Allahın Quran verdiyi adam ki, gecə-gündüz onu oxuyur; və Allahın mal verdiyi adam ki, gecə-gündüz onu xərcləyir.","en":"There is no envy except in two cases: a man to whom Allah gave the Quran and he recites it night and day, and a man to whom Allah gave wealth and he spends it night and day.","ru":"Нет зависти, кроме как в двух случаях: человек, которому Аллах дал Коран и он читает его ночью и днём, и человек, которому Аллах дал богатство и он тратит его ночью и днём.","tr":"Yalnızca iki kişiye gıpta edilir: Allah'ın Kur'an verdiği adam ki gece gündüz onu okur; ve Allah'ın mal verdiği adam ki gece gündüz onu harcar.","ar":"لاَ حَسَدَ إِلاَّ فِي اثْنَتَيْنِ رَجُلٌ آتَاهُ اللَّهُ الْقُرْآنَ فَهُوَ يَقُومُ بِهِ آنَاءَ اللَّيْلِ وَآنَاءَ النَّهَارِ وَرَجُلٌ آتَاهُ اللَّهُ مَالاً فَهُوَ يُنْفِقُهُ آنَاءَ اللَّيْلِ وَآنَاءَ النَّهَارِ"},"src":{"az":"Buxari, Fəzailul-Quran 20","en":"Bukhari, Fada'il al-Qur'an 20","ru":"Бухари, Фадаиль аль-Куран 20","tr":"Buhârî, Fezâilü'l-Kur'ân 20","ar":"البخاري، فضائل القرآن 20"}},{"id":1719,"t":{"az":"İman yetmiş neçə şöbədir. Ən üstünü \"La ilahə illəllah\" deməkdir, ən aşağısı yoldan əziyyəti götürməkdir. Həya da imanın bir şöbəsidir.","en":"Faith has seventy-odd branches. The highest is saying \"La ilaha illallah\" and the lowest is removing harm from the road. And modesty is a branch of faith.","ru":"Вера имеет семьдесят с лишним ветвей. Высшая — слова «Ля иляха илляллах», низшая — устранение вреда с дороги. И стыдливость — ветвь веры.","tr":"İman yetmiş küsur şubedir. En üstünü \"La ilahe illallah\" demektir, en alt mertebesi yoldan eziyeti kaldırmaktır. Haya da imanın bir şubesidir.","ar":"الإِيمَانُ بِضْعٌ وَسَبْعُونَ شُعْبَةً فَأَفْضَلُهَا قَوْلُ لاَ إِلَهَ إِلاَّ اللَّهُ وَأَدْنَاهَا إِمَاطَةُ الأَذَى عَنِ الطَّرِيقِ وَالْحَيَاءُ شُعْبَةٌ مِنَ الإِيمَانِ"},"src":{"az":"Muslim, İman 58","en":"Muslim, Iman 58","ru":"Муслим, Иман 58","tr":"Müslim, İman 58","ar":"مسلم، الإيمان 58"}},{"id":1720,"t":{"az":"Din nəsihətdir. Dedik: Kimə? Buyurdu: Allaha, Kitabına, Rəsuluna, müsəlman rəhbərlərinə və ümumiyyətinə.","en":"Religion is sincere counsel. We asked: To whom? He said: To Allah, His Book, His Messenger, the leaders of the Muslims, and their common folk.","ru":"Религия — это искренний совет. Мы спросили: Кому? Он сказал: Аллаху, Его Книге, Его Посланнику, правителям мусульман и простым мусульманам.","tr":"Din nasihattir. Dedik: Kime? Buyurdu: Allah'a, Kitabına, Rasulüne, Müslüman önderlerine ve geneline.","ar":"الدِّينُ النَّصِيحَةُ قُلْنَا لِمَنْ قَالَ لِلَّهِ وَلِكِتَابِهِ وَلِرَسُولِهِ وَلأَئِمَّةِ الْمُسْلِمِينَ وَعَامَّتِهِمْ"},"src":{"az":"Muslim, İman 95","en":"Muslim, Iman 95","ru":"Муслим, Иман 95","tr":"Müslim, İman 95","ar":"مسلم، الإيمان 95"}},{"id":1721,"t":{"az":"Kim aldatsa, məndən deyildir.","en":"Whoever deceives is not from me.","ru":"Кто обманывает, тот не от меня.","tr":"Kim aldatırsa benden değildir.","ar":"مَنْ غَشَّ فَلَيْسَ مِنِّي"},"src":{"az":"Muslim, İman 164","en":"Muslim, Iman 164","ru":"Муслим, Иман 164","tr":"Müslim, İman 164","ar":"مسلم، الإيمان 164"}},{"id":1723,"t":{"az":"Dəstəmazı kamil almaq imanın yarısıdır. \"Əlhəmdulilləh\" tərəzini doldurar. \"Subhanəllah\" və \"Əlhəmdulilləh\" göylə yer arasını doldurar.","en":"Performing ablution fully is half of faith. \"Alhamdulillah\" fills the scale. \"Subhanallah\" and \"Alhamdulillah\" fill what is between heaven and earth.","ru":"Полное омовение — половина веры. «Альхамдулиллях» наполняет весы. «Субханаллах» и «Альхамдулиллях» наполняют то, что между небом и землёй.","tr":"Abdesti tam almak imanın yarısıdır. \"Elhamdülillah\" teraziyi doldurur. \"Sübhanallah\" ve \"Elhamdülillah\" gökle yer arasını doldurur.","ar":"إِسْبَاغُ الْوُضُوءِ شَطْرُ الإِيمَانِ وَالْحَمْدُ لِلَّهِ تَمْلأُ الْمِيزَانَ وَسُبْحَانَ اللَّهِ وَالْحَمْدُ لِلَّهِ تَمْلآنِ مَا بَيْنَ السَّمَاءِ وَالأَرْضِ"},"src":{"az":"Muslim, Taharat 1","en":"Muslim, Taharah 1","ru":"Муслим, Тахара 1","tr":"Müslim, Tahâret 1","ar":"مسلم، الطهارة 1"}},{"id":1724,"t":{"az":"Namaz nurdur, sədəqə dəlildir, səbr işıqdır, Quran sənin lehinə və ya əleyhinə dəlildir.","en":"Prayer is light, charity is proof, patience is illumination, and the Quran is evidence for or against you.","ru":"Молитва — свет, милостыня — доказательство, терпение — сияние, и Коран — довод за или против тебя.","tr":"Namaz nurdur, sadaka delildir, sabır ışıktır, Kur'an senin lehine veya aleyhine delildir.","ar":"الصَّلاَةُ نُورٌ وَالصَّدَقَةُ بُرْهَانٌ وَالصَّبْرُ ضِيَاءٌ وَالْقُرْآنُ حُجَّةٌ لَكَ أَوْ عَلَيْكَ"},"src":{"az":"Muslim, Taharat 1","en":"Muslim, Taharah 1","ru":"Муслим, Тахара 1","tr":"Müslim, Tahâret 1","ar":"مسلم، الطهارة 1"}},{"id":1726,"t":{"az":"Qiyamət günü qulun ilk hesab verəcəyi namazdır. Namaz düzgün olsa, digər əməlləri də düzgün olar. Pozulsa, digər əməlləri də pozular.","en":"The first thing a servant will be held accountable for on the Day of Judgment is prayer. If it is sound, his other deeds will be sound. If it is corrupt, his other deeds will be corrupt.","ru":"Первое, за что будет спрошен раб в День Суда — молитва. Если она в порядке, остальные дела будут в порядке. Если испорчена, остальные дела будут испорчены.","tr":"Kıyamet günü kulun ilk hesap vereceği namazdır. Namaz düzgün olsa diğer amelleri de düzgün olur. Bozulsa diğer amelleri de bozulur.","ar":"أَوَّلُ مَا يُحَاسَبُ بِهِ الْعَبْدُ يَوْمَ الْقِيَامَةِ الصَّلاَةُ فَإِنْ صَلُحَتْ صَلُحَ سَائِرُ عَمَلِهِ وَإِنْ فَسَدَتْ فَسَدَ سَائِرُ عَمَلِهِ"},"src":{"az":"Tirmizi 413","en":"Tirmidhi 413","ru":"Тирмизи 413","tr":"Tirmizî 413","ar":"الترمذي 413"}},{"id":1730,"t":{"az":"Ey insanlar, salamı yayın, yemək yedirin, qohumluq bağlarını qoruyun, gecə insanlar yuxuda ikən namaz qılın ki, Cənnətə salamatlıqla girəsiniz.","en":"O people, spread peace, feed the hungry, maintain kinship ties, and pray at night while people sleep, and you will enter Paradise in peace.","ru":"О люди, распространяйте мир, кормите, поддерживайте родственные связи, молитесь ночью, когда люди спят, и вы войдёте в Рай с миром.","tr":"Ey insanlar, selamı yayın, yemek yedirin, akrabalık bağlarını koruyun, insanlar uyurken gece namazı kılın ki Cennete selametle giresiniz.","ar":"يَا أَيُّهَا النَّاسُ أَفْشُوا السَّلاَمَ وَأَطْعِمُوا الطَّعَامَ وَصِلُوا الأَرْحَامَ وَصَلُّوا بِاللَّيْلِ وَالنَّاسُ نِيَامٌ تَدْخُلُوا الْجَنَّةَ بِسَلاَمٍ"},"src":{"az":"Tirmizi 2485","en":"Tirmidhi 2485","ru":"Тирмизи 2485","tr":"Tirmizî 2485","ar":"الترمذي 2485"}},{"id":1731,"t":{"az":"Müsəlmanın qardaşını üç gecədən çox tərk etməsi halal deyildir. Qarşılaşdıqda biri o tərəfə, digəri bu tərəfə dönər. Ən xeyirlisi salam verməyə birinci başlayandır.","en":"It is not permissible for a Muslim to abandon his brother for more than three nights. They meet and each turns away. The better of them is the one who initiates the greeting.","ru":"Мусульманину нельзя покидать своего брата более трёх ночей. Они встречаются, и каждый отворачивается. Лучший из них тот, кто первым приветствует.","tr":"Müslümanın kardeşini üç geceden fazla terk etmesi helal değildir. Karşılaştıklarında biri öbür tarafa, diğeri bu tarafa döner. En hayırlısı selama ilk başlayandır.","ar":"لاَ يَحِلُّ لِمُسْلِمٍ أَنْ يَهْجُرَ أَخَاهُ فَوْقَ ثَلاَثِ لَيَالٍ يَلْتَقِيَانِ فَيُعْرِضُ هَذَا وَيُعْرِضُ هَذَا وَخَيْرُهُمَا الَّذِي يَبْدَأُ بِالسَّلاَمِ"},"src":{"az":"Buxari, Ədəb 62","en":"Bukhari, Adab 62","ru":"Бухари, Адаб 62","tr":"Buhârî, Edeb 62","ar":"البخاري، الأدب 62"}},{"id":1732,"t":{"az":"Möminin işi heyrətamizdir, bütün işi onun üçün xeyirdir. Bu yalnız möminə xasdır. Xoş bir şey gəlsə şükr edər, xeyir olar. Çətin bir şey gəlsə səbr edər, xeyir olar.","en":"How amazing is the affair of the believer! All his affairs are good, and that is for no one except the believer. If something good happens, he is grateful and that is good for him. If something bad happens, he is patient and that is good for him.","ru":"Удивительно дело верующего! Все его дела — благо, и это только для верующего. Если постигнет его радость, он благодарит, и это благо для него. Если постигнет беда, он терпит, и это благо для него.","tr":"Müminin işi şaşırtıcıdır, bütün işi onun için hayırdır. Bu yalnızca mümine hastır. İyi bir şey gelirse şükreder, hayır olur. Kötü bir şey gelirse sabreder, hayır olur.","ar":"عَجَبًا لأَمْرِ الْمُؤْمِنِ إِنَّ أَمْرَهُ كُلَّهُ خَيْرٌ وَلَيْسَ ذَاكَ لأَحَدٍ إِلاَّ لِلْمُؤْمِنِ إِنْ أَصَابَتْهُ سَرَّاءُ شَكَرَ فَكَانَ خَيْرًا لَهُ وَإِنْ أَصَابَتْهُ ضَرَّاءُ صَبَرَ فَكَانَ خَيْرًا لَهُ"},"src":{"az":"Muslim, Zühd 64","en":"Muslim, Zuhd 64","ru":"Муслим, Зухд 64","tr":"Müslim, Zühd 64","ar":"مسلم، الزهد 64"}},{"id":1744,"t":{"az":"Allah rıfq sahibidir, yumuşaqlığı sevər. Yumuşaqlığa verdiyini sertliyə verməz.","en":"Allah is gentle and loves gentleness. He gives for gentleness what He does not give for harshness.","ru":"Аллах мягок и любит мягкость. Он даёт за мягкость то, что не даёт за грубость.","tr":"Allah rıfk sahibidir, yumuşaklığı sever. Yumuşaklığa verdiğini sertliğe vermez.","ar":"إِنَّ اللَّهَ رَفِيقٌ يُحِبُّ الرِّفْقَ وَيُعْطِي عَلَى الرِّفْقِ مَا لاَ يُعْطِي عَلَى الْعُنْفِ"},"src":{"az":"Muslim, Birr 77","en":"Muslim, Birr 77","ru":"Муслим, Бирр 77","tr":"Müslim, Birr 77","ar":"مسلم، البر والصلة 77"}},{"id":1745,"t":{"az":"Müsəlman dilindən və əlindən müsəlmanların salamat qaldığı kimsədir. Mühacir Allahın qadağan etdiklərini tərk edəndir.","en":"A Muslim is one from whose tongue and hand other Muslims are safe. An emigrant is one who abandons what Allah has forbidden.","ru":"Мусульманин — тот, от языка и руки которого другие мусульмане в безопасности. Переселенец — тот, кто оставил запрещённое Аллахом.","tr":"Müslüman dilinden ve elinden Müslümanların selamette olduğu kimsedir. Muhacir Allah'ın yasakladıklarını terk edendir.","ar":"الْمُسْلِمُ مَنْ سَلِمَ الْمُسْلِمُونَ مِنْ لِسَانِهِ وَيَدِهِ وَالْمُهَاجِرُ مَنْ هَجَرَ مَا نَهَى اللَّهُ عَنْهُ"},"src":{"az":"Buxari, İman 4","en":"Bukhari, Iman 4","ru":"Бухари, Иман 4","tr":"Buhârî, İman 4","ar":"البخاري، الإيمان 4"}},{"id":1747,"t":{"az":"Qiyamət günü möminin tərəzisində gözəl əxlaqdan ağır bir şey yoxdur.","en":"Nothing is heavier on the believer's scale on the Day of Judgment than good character.","ru":"Ничто не тяжелее на весах верующего в День Суда, чем хороший нрав.","tr":"Kıyamet günü müminin terazisinde güzel ahlaktan ağır bir şey yoktur.","ar":"مَا شَيْءٌ أَثْقَلُ فِي مِيزَانِ الْمُؤْمِنِ يَوْمَ الْقِيَامَةِ مِنْ خُلُقٍ حَسَنٍ"},"src":{"az":"Tirmizi 2002","en":"Tirmidhi 2002","ru":"Тирмизи 2002","tr":"Tirmizî 2002","ar":"الترمذي 2002"}},{"id":1751,"t":{"az":"Yaxşılığı əmr etmən sədəqədir, pislikdən çəkindirmən sədəqədir.","en":"Enjoining good is charity, and forbidding evil is charity.","ru":"Повеление одобряемого — милостыня, и запрет порицаемого — милостыня.","tr":"İyiliği emretmen sadakadır, kötülükten sakındırman sadakadır.","ar":"أَمْرُكَ بِالْمَعْرُوفِ صَدَقَةٌ وَنَهْيُكَ عَنِ الْمُنْكَرِ صَدَقَةٌ"},"src":{"az":"Muslim, Zəkat 53","en":"Muslim, Zakat 53","ru":"Муслим, Закят 53","tr":"Müslim, Zekât 53","ar":"مسلم، الزكاة 53"}},{"id":1752,"t":{"az":"Biriniz evlənməyə qadir olsa evlənsin, çünki gözü daha çox qoruyar və namusunu daha çox mühafizə edər. Qadir olmayan oruc tutsun, bu ona qalxandır.","en":"Whoever among you can afford marriage, let him marry, for it lowers the gaze and guards chastity. Whoever cannot, let him fast, for it is a shield.","ru":"Кто из вас способен жениться, пусть женится, ибо это лучше оберегает взор и целомудрие. Кто не способен, пусть постится, ибо это щит.","tr":"Biriniz evlenmeye güç yetirirse evlensin, çünkü gözü daha çok korur ve namusunu daha çok muhafaza eder. Güç yetiremeyen oruç tutsun, bu ona kalkandır.","ar":"مَنِ اسْتَطَاعَ مِنْكُمُ الْبَاءَةَ فَلْيَتَزَوَّجْ فَإِنَّهُ أَغَضُّ لِلْبَصَرِ وَأَحْصَنُ لِلْفَرْجِ وَمَنْ لَمْ يَسْتَطِعْ فَعَلَيْهِ بِالصَّوْمِ فَإِنَّهُ لَهُ وِجَاءٌ"},"src":{"az":"Buxari, Nikah 2","en":"Bukhari, Nikah 2","ru":"Бухари, Никах 2","tr":"Buhârî, Nikâh 2","ar":"البخاري، النكاح 2"}},{"id":1753,"t":{"az":"Qadının kişi üzərindəki haqqı: yedikdə onu yedirsin, geyindikdə geyindirsin, üzünə vurmasın, çirkin söz deməsin və evdən kənar tərk etməsin.","en":"The wife's right upon her husband is that he feeds her when he eats, clothes her when he clothes himself, does not strike the face, does not insult, and does not forsake her except in the house.","ru":"Право жены на мужа: кормить её, когда ест, одевать, когда одевается, не бить по лицу, не оскорблять и не покидать, кроме как в доме.","tr":"Kadının koca üzerindeki hakkı: yediğinde onu yedirsin, giyindiğinde giydirsin, yüzüne vurmasın, çirkin söz söylemesin ve evden dışarıda terk etmesin.","ar":"حَقُّ الزَّوْجَةِ عَلَى الزَّوْجِ أَنْ يُطْعِمَهَا إِذَا طَعِمَ وَيَكْسُوَهَا إِذَا اكْتَسَى وَلاَ يَضْرِبِ الْوَجْهَ وَلاَ يُقَبِّحْ وَلاَ يَهْجُرْ إِلاَّ فِي الْبَيْتِ"},"src":{"az":"İbn Macə 1850","en":"Ibn Majah 1850","ru":"Ибн Маджа 1850","tr":"İbn Mâce 1850","ar":"ابن ماجه 1850"}},{"id":1754,"t":{"az":"Dünyanın ən xeyirli malı saleh qadındır.","en":"The best provision of the world is a righteous woman.","ru":"Лучшее из мирских благ — праведная жена.","tr":"Dünyanın en hayırlı metaı salih kadındır.","ar":"خَيْرُ مَتَاعِ الدُّنْيَا الْمَرْأَةُ الصَّالِحَةُ"},"src":{"az":"Muslim, Rida 64","en":"Muslim, Rada' 64","ru":"Муслим, Рада 64","tr":"Müslim, Radâ 64","ar":"مسلم، الرضاع 64"}},{"id":1755,"t":{"az":"Vəlisinin izni olmadan nikah olunan qadının nikahı batildir.","en":"Any woman who is married without the permission of her guardian, her marriage is void.","ru":"Любая женщина, вышедшая замуж без разрешения опекуна, её брак недействителен.","tr":"Velisinin izni olmadan nikah edilen kadının nikahı batıldır.","ar":"أَيُّمَا امْرَأَةٍ نُكِحَتْ بِغَيْرِ إِذْنِ وَلِيِّهَا فَنِكَاحُهَا بَاطِلٌ"},"src":{"az":"Əbu Davud 2083","en":"Abu Dawud 2083","ru":"Абу Дауд 2083","tr":"Ebû Dâvûd 2083","ar":"أبو داود 2083"}},{"id":1756,"t":{"az":"Vəlisiz nikah yoxdur.","en":"There is no marriage without a guardian.","ru":"Нет брака без опекуна.","tr":"Velisiz nikah yoktur.","ar":"لاَ نِكَاحَ إِلاَّ بِوَلِيٍّ"},"src":{"az":"Əbu Davud 2085","en":"Abu Dawud 2085","ru":"Абу Дауд 2085","tr":"Ebû Dâvûd 2085","ar":"أبو داود 2085"}},{"id":1757,"t":{"az":"Heç bir səbəb olmadan ərindən boşanma istəyən qadına Cənnətin qoxusu haramdır.","en":"Any woman who asks her husband for divorce without a valid reason, the fragrance of Paradise is forbidden to her.","ru":"Любой женщине, попросившей развод без причины, запрещён аромат Рая.","tr":"Hiçbir sebep olmadan kocasından boşanma isteyen kadına Cennetin kokusu haramdır.","ar":"أَيُّمَا امْرَأَةٍ سَأَلَتْ زَوْجَهَا الطَّلاَقَ مِنْ غَيْرِ مَا بَأْسٍ فَحَرَامٌ عَلَيْهَا رَائِحَةُ الْجَنَّةِ"},"src":{"az":"Əbu Davud 2226","en":"Abu Dawud 2226","ru":"Абу Дауд 2226","tr":"Ebû Dâvûd 2226","ar":"أبو داود 2226"}},{"id":1758,"t":{"az":"Allah Cənnət əhlini rəhməti ilə Cənnətə daxil edər, Cəhənnəm əhlini də Cəhənnəmə daxil edər.","en":"Allah will admit the people of Paradise into Paradise by His mercy, and will admit the people of Hell into Hell.","ru":"Аллах введёт обитателей Рая в Рай по Своей милости и введёт обитателей Ада в Ад.","tr":"Allah Cennet ehlini rahmetiyle Cennete koyar, Cehennem ehlini de Cehenneme koyar.","ar":"يُدْخِلُ اللَّهُ أَهْلَ الْجَنَّةِ الْجَنَّةَ يُدْخِلُ مَنْ يَشَاءُ بِرَحْمَتِهِ وَيُدْخِلُ أَهْلَ النَّارِ النَّارَ"},"src":{"az":"Buxari, Riqaq 51","en":"Bukhari, Riqaq 51","ru":"Бухари, Рикак 51","tr":"Buhârî, Rikâk 51","ar":"البخاري، الرقاق 51"}},{"id":1761,"t":{"az":"Hər gün səhər iki mələk enir. Biri deyər: Allahım, xərcləyənə əvəzini ver. Digəri deyər: Allahım, xəsisə tələf ver.","en":"Every morning two angels descend. One says: O Allah, give the one who spends a replacement. The other says: O Allah, give the miser destruction.","ru":"Каждое утро спускаются два ангела. Один говорит: О Аллах, дай расходующему возмещение. Другой говорит: О Аллах, дай скупому убыток.","tr":"Her sabah iki melek iner. Biri der: Allah'ım, harcayana karşılığını ver. Diğeri der: Allah'ım, cimriye telef ver.","ar":"مَا مِنْ يَوْمٍ يُصْبِحُ الْعِبَادُ فِيهِ إِلاَّ مَلَكَانِ يَنْزِلاَنِ فَيَقُولُ أَحَدُهُمَا اللَّهُمَّ أَعْطِ مُنْفِقًا خَلَفًا وَيَقُولُ الآخَرُ اللَّهُمَّ أَعْطِ مُمْسِكًا تَلَفًا"},"src":{"az":"Buxari, Zəkat 27","en":"Bukhari, Zakat 27","ru":"Бухари, Закят 27","tr":"Buhârî, Zekât 27","ar":"البخاري، الزكاة 27"}},{"id":1763,"t":{"az":"Kim halal qazancdan bir xurma dəyərində sədəqə versə - Allah yalnız halal olanı qəbul edər - Allah onu sağ əli ilə qəbul edər, sonra sahibi üçün böyüdər.","en":"Whoever gives charity equal to a date from lawful earnings - and Allah accepts only what is pure - Allah accepts it with His right hand and nurtures it for its owner.","ru":"Кто подаст милостыню стоимостью в финик из дозволенного заработка — а Аллах принимает только чистое — Аллах примет её Своей правой рукой и взрастит для её хозяина.","tr":"Kim helal kazançtan bir hurma değerinde sadaka verirse - Allah yalnız helal olanı kabul eder - Allah onu sağ eliyle kabul eder, sonra sahibi için büyütür.","ar":"مَنْ تَصَدَّقَ بِعَدْلِ تَمْرَةٍ مِنْ كَسْبٍ طَيِّبٍ وَلاَ يَقْبَلُ اللَّهُ إِلاَّ الطَّيِّبَ فَإِنَّ اللَّهَ يَتَقَبَّلُهَا بِيَمِينِهِ ثُمَّ يُرَبِّيهَا لِصَاحِبِهَا"},"src":{"az":"Buxari, Zəkat 8","en":"Bukhari, Zakat 8","ru":"Бухари, Закят 8","tr":"Buhârî, Zekât 8","ar":"البخاري، الزكاة 8"}},{"id":1766,"t":{"az":"Dəstəmazı gözəl alıb məscidə gəlib iki rəkət namaz qılan kəsə Cənnət vacib olar.","en":"No man performs wudu well, then comes to the mosque and prays two rak'ahs, except that Paradise becomes obligatory for him.","ru":"Всякий, кто хорошо совершит омовение, придёт в мечеть и помолится два ракаата, тому обязателен Рай.","tr":"Abdesti güzel alıp mescide gelip iki rekat namaz kılan kimseye Cennet vacip olur.","ar":"مَا مِنْ رَجُلٍ يَتَوَضَّأُ فَيُحْسِنُ الْوُضُوءَ ثُمَّ يَأْتِي الْمَسْجِدَ فَيُصَلِّي رَكْعَتَيْنِ إِلاَّ وَجَبَتْ لَهُ الْجَنَّةُ"},"src":{"az":"Əbu Davud 906","en":"Abu Dawud 906","ru":"Абу Дауд 906","tr":"Ebû Dâvûd 906","ar":"أبو داود 906"}},{"id":1767,"t":{"az":"İslam beş üzərində qurulmuşdur: Allahdan başqa ilah olmadığına və Muhammədin Allahın elçisi olduğuna şəhadət, namaz qılmaq, zəkat vermək, Ramazan orucu tutmaq və həcc etmək.","en":"Islam is built on five pillars: testimony that there is no god but Allah and Muhammad is His messenger, establishing prayer, paying zakat, fasting Ramadan, and pilgrimage.","ru":"Ислам построен на пяти: свидетельство, что нет бога, кроме Аллаха и Мухаммад — Его посланник, совершение молитвы, выплата закята, пост Рамадана и хадж.","tr":"İslam beş üzerine kurulmuştur: Allah'tan başka ilah olmadığına ve Muhammed'in O'nun elçisi olduğuna şehadet, namaz kılmak, zekat vermek, Ramazan orucu tutmak ve hacca gitmek.","ar":"بُنِيَ الإِسْلاَمُ عَلَى خَمْسٍ شَهَادَةِ أَنْ لاَ إِلَهَ إِلاَّ اللَّهُ وَأَنَّ مُحَمَّدًا رَسُولُ اللَّهِ وَإِقَامِ الصَّلاَةِ وَإِيتَاءِ الزَّكَاةِ وَصَوْمِ رَمَضَانَ وَحَجِّ الْبَيْتِ"},"src":{"az":"Buxari, İman 2","en":"Bukhari, Iman 2","ru":"Бухари, Иман 2","tr":"Buhârî, İman 2","ar":"البخاري، الإيمان 2"}},{"id":1771,"t":{"az":"Kim səhər və axşam üç dəfə \"Bismillahilləzi la yədurru maəsmihi şeyun fil-ardi və la fis-səma və huvəs-Səmiül-Alim\" desə, heç nə ona zərər verməz.","en":"Whoever says three times morning and evening \"In the name of Allah with whose name nothing on earth or in heaven can harm, and He is the All-Hearing, All-Knowing,\" nothing will harm him.","ru":"Кто скажет утром и вечером три раза «Именем Аллаха, с именем Которого ничто не навредит на земле и на небе, и Он — Всеслышащий, Всезнающий», ничто не навредит ему.","tr":"Kim sabah ve akşam üç kere \"Bismillahillezi la yedurru measmihi şeyün fil-ardı ve la fis-semai ve hüves-Semiül-Alim\" derse hiçbir şey ona zarar vermez.","ar":"مَنْ قَالَ حِينَ يُصْبِحُ وَحِينَ يُمْسِي بِسْمِ اللَّهِ الَّذِي لاَ يَضُرُّ مَعَ اسْمِهِ شَيْءٌ فِي الأَرْضِ وَلاَ فِي السَّمَاءِ وَهُوَ السَّمِيعُ الْعَلِيمُ ثَلاَثَ مَرَّاتٍ لَمْ يَضُرَّهُ شَيْءٌ"},"src":{"az":"Əbu Davud 5088","en":"Abu Dawud 5088","ru":"Абу Дауд 5088","tr":"Ebû Dâvûd 5088","ar":"أبو داود 5088"}},{"id":1772,"t":{"az":"Kim yatağına girəndə Ayətul-Kürsini oxusa, Allahdan bir mühafiz ondan ayrılmaz və səhərə qədər şeytan ona yaxınlaşa bilməz.","en":"Whoever recites Ayat al-Kursi when going to bed, a guardian from Allah will remain with him and no devil will approach him until morning.","ru":"Кто прочтёт Аят аль-Курси, ложась спать, от Аллаха останется с ним хранитель, и шайтан не приблизится к нему до утра.","tr":"Kim yatağına girdiğinde Ayetel Kürsi okursa Allah'tan bir koruyucu ondan ayrılmaz ve sabaha kadar şeytan ona yaklaşamaz.","ar":"مَنْ قَرَأَ آيَةَ الْكُرْسِيِّ حِينَ يَأْوِي إِلَى فِرَاشِهِ لَمْ يَزَلْ عَلَيْهِ مِنَ اللَّهِ حَافِظٌ وَلاَ يَقْرَبُهُ شَيْطَانٌ حَتَّى يُصْبِحَ"},"src":{"az":"Buxari, Vəkala 10","en":"Bukhari, Wakalah 10","ru":"Бухари, Вакаля 10","tr":"Buhârî, Vekâlet 10","ar":"البخاري، الوكالة 10"}},{"id":1778,"t":{"az":"İnsanların gözəl yoldaşlığıma ən çox layiq olanı kimdir? Buyurdu: Anan. Sonra kim? Anan. Sonra kim? Anan. Sonra kim? Atan.","en":"Who is most deserving of my good companionship? He said: Your mother. Then who? Your mother. Then who? Your mother. Then who? Your father.","ru":"Кто наиболее достоин моего хорошего обращения? Он сказал: Твоя мать. Потом кто? Твоя мать. Потом кто? Твоя мать. Потом кто? Твой отец.","tr":"İnsanların güzel arkadaşlığıma en çok layık olanı kimdir? Buyurdu: Annen. Sonra kim? Annen. Sonra kim? Annen. Sonra kim? Baban.","ar":"مَنْ أَحَقُّ النَّاسِ بِحُسْنِ صَحَابَتِي قَالَ أُمُّكَ قَالَ ثُمَّ مَنْ قَالَ ثُمَّ أُمُّكَ قَالَ ثُمَّ مَنْ قَالَ ثُمَّ أُمُّكَ قَالَ ثُمَّ مَنْ قَالَ ثُمَّ أَبُوكَ"},"src":{"az":"Buxari, Ədəb 2","en":"Bukhari, Adab 2","ru":"Бухари, Адаб 2","tr":"Buhârî, Edeb 2","ar":"البخاري، الأدب 2"}},{"id":1779,"t":{"az":"Burnu yerdə sürtünsün, burnu yerdə sürtünsün, burnu yerdə sürtünsün! Dedilər: Kimin, ya Rəsulullah? Buyurdu: Ata-anasından birini və ya hər ikisini yaşlı halda gördüyü halda Cənnətə girməyənin.","en":"May his nose be rubbed in dust! They asked: Who, O Messenger of Allah? He said: The one who finds one or both parents in old age and does not enter Paradise.","ru":"Да будет унижен! Спросили: Кто, о Посланник Аллаха? Сказал: Тот, кто застал одного или обоих родителей в старости и не вошёл в Рай.","tr":"Burnu yere sürtülsün! Dediler: Kimin ya Rasulallah? Buyurdu: Anne-babasından birini veya ikisini yaşlı halde bulup da Cennete giremeyenin.","ar":"رَغِمَ أَنْفُهُ ثُمَّ رَغِمَ أَنْفُهُ ثُمَّ رَغِمَ أَنْفُهُ قِيلَ مَنْ يَا رَسُولَ اللَّهِ قَالَ مَنْ أَدْرَكَ وَالِدَيْهِ عِنْدَ الْكِبَرِ أَحَدَهُمَا أَوْ كِلَيْهِمَا ثُمَّ لَمْ يَدْخُلِ الْجَنَّةَ"},"src":{"az":"Muslim, Birr 9","en":"Muslim, Birr 9","ru":"Муслим, Бирр 9","tr":"Müslim, Birr 9","ar":"مسلم، البر والصلة 9"}},{"id":1780,"t":{"az":"Ölünün arxasınca üç şey gedir: ailəsi, malı və əməli. İkisi geri dönər, biri qalar: ailəsi və malı geri dönər, əməli qalar.","en":"Three things follow the dead: his family, wealth, and deeds. Two return and one remains: his family and wealth return, and his deeds remain.","ru":"За покойным следуют трое: его семья, имущество и дела. Двое возвращаются, а одно остаётся: семья и имущество возвращаются, а дела остаются.","tr":"Ölünün arkasından üç şey gider: ailesi, malı ve ameli. İkisi geri döner, biri kalır: ailesi ve malı geri döner, ameli kalır.","ar":"الْمَيِّتُ يُتْبَعُ ثَلاَثَةً أَهْلُهُ وَمَالُهُ وَعَمَلُهُ فَيَرْجِعُ اثْنَانِ وَيَبْقَى وَاحِدٌ يَرْجِعُ أَهْلُهُ وَمَالُهُ وَيَبْقَى عَمَلُهُ"},"src":{"az":"Buxari, Riqaq 42","en":"Bukhari, Riqaq 42","ru":"Бухари, Рикак 42","tr":"Buhârî, Rikâk 42","ar":"البخاري، الرقاق 42"}},{"id":1781,"t":{"az":"Məbrur həccin mükafatı yalnız Cənnətdir.","en":"An accepted Hajj has no reward except Paradise.","ru":"Принятый хадж не имеет иной награды, кроме Рая.","tr":"Mebrur haccın mükâfatı yalnızca Cennettir.","ar":"الْحَجُّ الْمَبْرُورُ لَيْسَ لَهُ جَزَاءٌ إِلاَّ الْجَنَّةُ"},"src":{"az":"Buxari, Umrə 1","en":"Bukhari, Umrah 1","ru":"Бухари, Умра 1","tr":"Buhârî, Umre 1","ar":"البخاري، العمرة 1"}},{"id":1782,"t":{"az":"Bir ümrədən digərinə aralarındakı günahlar üçün kəffarədir.","en":"Umrah to umrah is an expiation for what is between them.","ru":"Умра за умрой — искупление для того, что между ними.","tr":"Umreden umreye aralarındaki günahlar için kefarettir.","ar":"الْعُمْرَةُ إِلَى الْعُمْرَةِ كَفَّارَةٌ لِمَا بَيْنَهُمَا"},"src":{"az":"Buxari, Umrə 1","en":"Bukhari, Umrah 1","ru":"Бухари, Умра 1","tr":"Buhârî, Umre 1","ar":"البخاري، العمرة 1"}},{"id":1786,"t":{"az":"Halal aydındır, haram aydındır. Aralarında şübhəli şeylər var ki, çoxları onları bilməz. Şübhəlilərdən çəkinən dini və namusu üçün təmiz qalmış olar.","en":"The lawful is clear and the unlawful is clear, and between them are doubtful matters that many people do not know. Whoever avoids doubtful matters has safeguarded his religion and honor.","ru":"Дозволенное ясно и запретное ясно, а между ними сомнительное, которое многие не знают. Кто остерегается сомнительного, оберегает свою религию и честь.","tr":"Helal bellidir, haram bellidir. Aralarında şüpheli şeyler vardır ki çoğu insan onları bilmez. Şüphelilerden sakınan dinini ve namusunu korumuş olur.","ar":"إِنَّ الْحَلاَلَ بَيِّنٌ وَإِنَّ الْحَرَامَ بَيِّنٌ وَبَيْنَهُمَا أُمُورٌ مُشْتَبِهَاتٌ لاَ يَعْلَمُهُنَّ كَثِيرٌ مِنَ النَّاسِ فَمَنِ اتَّقَى الشُّبُهَاتِ اسْتَبْرَأَ لِدِينِهِ وَعِرْضِهِ"},"src":{"az":"Buxari, İman 39","en":"Bukhari, Iman 39","ru":"Бухари, Иман 39","tr":"Buhârî, İman 39","ar":"البخاري، الإيمان 39"}},{"id":1793,"t":{"az":"Qul qardaşının köməyində olduqca Allah da qulun köməyindədir.","en":"Allah is in the aid of His servant as long as the servant is in the aid of his brother.","ru":"Аллах помогает рабу, пока раб помогает своему брату.","tr":"Kul kardeşinin yardımında olduğu sürece Allah da kulun yardımındadır.","ar":"وَاللَّهُ فِي عَوْنِ الْعَبْدِ مَا كَانَ الْعَبْدُ فِي عَوْنِ أَخِيهِ"},"src":{"az":"Muslim, Zikr 38","en":"Muslim, Dhikr 38","ru":"Муслим, Зикр 38","tr":"Müslim, Zikir 38","ar":"مسلم، الذكر 38"}},{"id":1796,"t":{"az":"Zülmdən çəkinin, çünki zülm Qiyamət günü zülmətlərdir. Xəsislikdən çəkinin, çünki xəsislik sizdən əvvəlkiləri həlak etmişdir.","en":"Beware of injustice for it will be darkness on the Day of Judgment. Beware of miserliness for it destroyed those before you.","ru":"Остерегайтесь несправедливости, ибо она станет мраком в День Суда. Остерегайтесь скупости, ибо она погубила тех, кто был до вас.","tr":"Zulümden sakının, çünkü zulüm Kıyamet günü karanlıklardır. Cimrilikten sakının, çünkü cimrilik sizden öncekileri helak etmiştir.","ar":"اتَّقُوا الظُّلْمَ فَإِنَّ الظُّلْمَ ظُلُمَاتٌ يَوْمَ الْقِيَامَةِ وَاتَّقُوا الشُّحَّ فَإِنَّ الشُّحَّ أَهْلَكَ مَنْ كَانَ قَبْلَكُمْ"},"src":{"az":"Muslim, Birr 56","en":"Muslim, Birr 56","ru":"Муслим, Бирр 56","tr":"Müslim, Birr 56","ar":"مسلم، البر والصلة 56"}},{"id":1798,"t":{"az":"Biriniz bir pislik görsə, əli ilə dəyişdirsin. Bacarmasa, dili ilə. Onu da bacarmasa, qəlbi ilə. Bu imanın ən zəif dərəcəsidir.","en":"Whoever sees evil, let him change it with his hand. If he cannot, then with his tongue. If he cannot, then with his heart, and that is the weakest of faith.","ru":"Кто увидит порицаемое, пусть изменит это рукой. Если не может, то языком. Если не может, то сердцем, и это самая слабая степень веры.","tr":"Biriniz bir kötülük görürse eliyle değiştirsin. Gücü yetmezse diliyle. Onu da yapamazsa kalbiyle. Bu imanın en zayıf derecesidir.","ar":"مَنْ رَأَى مِنْكُمْ مُنْكَرًا فَلْيُغَيِّرْهُ بِيَدِهِ فَإِنْ لَمْ يَسْتَطِعْ فَبِلِسَانِهِ فَإِنْ لَمْ يَسْتَطِعْ فَبِقَلْبِهِ وَذَلِكَ أَضْعَفُ الإِيمَانِ"},"src":{"az":"Muslim, İman 78","en":"Muslim, Iman 78","ru":"Муслим, Иман 78","tr":"Müslim, İman 78","ar":"مسلم، الإيمان 78"}},{"id":1800,"t":{"az":"Bir-birinizə həsəd aparmayın, qiymət artırmayın, nifrət etməyin, bir-birinizə arxa çevirməyin, birinin alış-verişi üzərinə alış-veriş etməyin. Allahın qulları, qardaş olun.","en":"Do not envy, do not inflate prices, do not hate, do not turn your backs, do not undercut each other in trade. Be servants of Allah, brothers.","ru":"Не завидуйте, не набивайте цену, не ненавидьте, не отворачивайтесь, не перебивайте торговлю друг друга. Будьте рабами Аллаха, братьями.","tr":"Birbirinize haset etmeyin, fiyat artırmayın, nefret etmeyin, birbirinize sırt çevirmeyin, birinin alışverişi üzerine alışveriş yapmayın. Allah'ın kulları, kardeş olun.","ar":"لاَ تَحَاسَدُوا وَلاَ تَنَاجَشُوا وَلاَ تَبَاغَضُوا وَلاَ تَدَابَرُوا وَلاَ يَبِعْ بَعْضُكُمْ عَلَى بَيْعِ بَعْضٍ وَكُونُوا عِبَادَ اللَّهِ إِخْوَانًا"},"src":{"az":"Muslim, Birr 32","en":"Muslim, Birr 32","ru":"Муслим, Бирр 32","tr":"Müslim, Birr 32","ar":"مسلم، البر والصلة 32"}},{"id":1801,"t":{"az":"Hər müsəlman digər müsəlmana haramdır: qanı, malı və namusu.","en":"Every Muslim is inviolable to another Muslim: his blood, wealth, and honor.","ru":"Каждый мусульманин неприкосновенен для другого: его кровь, имущество и честь.","tr":"Her Müslüman diğer Müslümana haramdır: kanı, malı ve namusu.","ar":"كُلُّ الْمُسْلِمِ عَلَى الْمُسْلِمِ حَرَامٌ دَمُهُ وَمَالُهُ وَعِرْضُهُ"},"src":{"az":"Muslim, Birr 32","en":"Muslim, Birr 32","ru":"Муслим, Бирр 32","tr":"Müslim, Birr 32","ar":"مسلم، البر والصلة 32"}},{"id":1802,"t":{"az":"İnsana şər olaraq müsəlman qardaşını kiçik görməsi kifayətdir.","en":"It is enough evil for a person to look down upon his Muslim brother.","ru":"Достаточно зла для человека — презирать своего брата-мусульманина.","tr":"Kişiye kötülük olarak Müslüman kardeşini küçük görmesi yeter.","ar":"بِحَسْبِ امْرِئٍ مِنَ الشَّرِّ أَنْ يَحْقِرَ أَخَاهُ الْمُسْلِمَ"},"src":{"az":"Muslim, Birr 32","en":"Muslim, Birr 32","ru":"Муслим, Бирр 32","tr":"Müslim, Birr 32","ar":"مسلم، البر والصلة 32"}},{"id":1803,"t":{"az":"İcazə almadan birinin evinin içinə baxmaq halal deyildir. Əgər baxarsa, sanki içəri girmişdir.","en":"It is not permissible for a person to look inside another's house without permission. If he looks, it is as if he has entered.","ru":"Не дозволено человеку смотреть внутрь чужого дома без разрешения. Если посмотрит, как будто вошёл.","tr":"İzin almadan birinin evinin içine bakmak helal değildir. Eğer bakarsa sanki içeri girmiştir.","ar":"لاَ يَحِلُّ لِرَجُلٍ أَنْ يَنْظُرَ فِي جَوْفِ بَيْتِ امْرِئٍ حَتَّى يَسْتَأْذِنَ فَإِنْ نَظَرَ فَقَدْ دَخَلَ"},"src":{"az":"Buxari, İsti'zan 11","en":"Bukhari, Isti'dhan 11","ru":"Бухари, Истизан 11","tr":"Buhârî, İsti'zân 11","ar":"البخاري، الاستئذان 11"}},{"id":1804,"t":{"az":"İcazə istəmək yalnız göz (baxış) üçün qoyulmuşdur.","en":"Permission was ordained only for the sake of the gaze.","ru":"Испрашивание разрешения было установлено ради взора.","tr":"İzin istemek yalnızca bakış (göz) için konulmuştur.","ar":"إِنَّمَا جُعِلَ الاِسْتِئْذَانُ مِنْ أَجْلِ الْبَصَرِ"},"src":{"az":"Buxari, İsti'zan 11","en":"Bukhari, Isti'dhan 11","ru":"Бухари, Истизан 11","tr":"Buhârî, İsti'zân 11","ar":"البخاري، الاستئذان 11"}},{"id":1805,"t":{"az":"Kim sübh namazını qılsa, Allahın himayəsindədir. Allahın himayəsini pozmayın.","en":"Whoever prays the dawn prayer is under the protection of Allah, so do not violate Allah's protection.","ru":"Кто совершит утреннюю молитву, тот под защитой Аллаха, так не нарушайте защиту Аллаха.","tr":"Kim sabah namazını kılarsa Allah'ın himayesindedir. Allah'ın himayesini bozmayın.","ar":"مَنْ صَلَّى الصُّبْحَ فَهُوَ فِي ذِمَّةِ اللَّهِ فَلاَ تُخْفِرُوا اللَّهَ فِي ذِمَّتِهِ"},"src":{"az":"Muslim, Mesacid 261","en":"Muslim, Masajid 261","ru":"Муслим, Масаджид 261","tr":"Müslim, Mesâcid 261","ar":"مسلم، المساجد 261"}},{"id":1807,"t":{"az":"Rəbbin qula ən yaxın olduğu an gecənin son hissəsidir. O saatda Allahı zikr edənlərdən ola bilərsənsə, ol.","en":"The closest the Lord is to His servant is in the last part of the night. If you can be among those who remember Allah at that hour, then be.","ru":"Ближайшее к рабу время Господа — последняя часть ночи. Если можешь быть среди тех, кто поминает Аллаха в тот час, будь.","tr":"Rabbin kula en yakın olduğu an gecenin son kısmıdır. O saatte Allah'ı zikredenlerden olabilirsen ol.","ar":"أَقْرَبُ مَا يَكُونُ الرَّبُّ مِنَ الْعَبْدِ فِي جَوْفِ اللَّيْلِ الآخِرِ فَإِنِ اسْتَطَعْتَ أَنْ تَكُونَ مِمَّنْ يَذْكُرُ اللَّهَ فِي تِلْكَ السَّاعَةِ فَكُنْ"},"src":{"az":"Tirmizi 3579","en":"Tirmidhi 3579","ru":"Тирмизи 3579","tr":"Tirmizî 3579","ar":"الترمذي 3579"}},{"id":1808,"t":{"az":"Rəbbimiz hər gecə gecənin son üçdə biri qaldıqda dünya səmasına enir və buyurur: Kim Mənə dua edər ki, ona cavab verim?","en":"Our Lord descends every night to the lowest heaven when the last third of the night remains and says: Who calls upon Me that I may answer?","ru":"Наш Господь нисходит каждую ночь к ближнему небу, когда остаётся последняя треть ночи, и говорит: Кто взывает ко Мне, чтобы Я ответил?","tr":"Rabbimiz her gece gecenin son üçte biri kaldığında dünya semasına iner ve buyurur: Kim Bana dua eder ki ona cevap vereyim?","ar":"يَنْزِلُ رَبُّنَا تَبَارَكَ وَتَعَالَى كُلَّ لَيْلَةٍ إِلَى السَّمَاءِ الدُّنْيَا حِينَ يَبْقَى ثُلُثُ اللَّيْلِ الآخِرُ يَقُولُ مَنْ يَدْعُونِي فَأَسْتَجِيبَ لَهُ"},"src":{"az":"Buxari, Təhəccüd 14","en":"Bukhari, Tahajjud 14","ru":"Бухари, Тахаджуд 14","tr":"Buhârî, Teheccüd 14","ar":"البخاري، التهجد 14"}},{"id":1812,"t":{"az":"Kim \"Subhanəllahi və bihəmdihi\" desə, Cənnətdə ona bir xurma ağacı əkilər.","en":"Whoever says \"Subhanallahi wa bihamdihi,\" a palm tree will be planted for him in Paradise.","ru":"Кто скажет «Субханаллахи ва бихамдихи», для него будет посажена пальма в Раю.","tr":"Kim \"Sübhanallahi ve bihamdihi\" derse Cennette ona bir hurma ağacı dikilir.","ar":"مَنْ قَالَ سُبْحَانَ اللَّهِ وَبِحَمْدِهِ غُرِسَتْ لَهُ نَخْلَةٌ فِي الْجَنَّةِ"},"src":{"az":"Tirmizi 3465","en":"Tirmidhi 3465","ru":"Тирмизи 3465","tr":"Tirmizî 3465","ar":"الترمذي 3465"}},{"id":1815,"t":{"az":"Zaman yaxınlaşmadıqca qiyamət qopmaz. İl ay kimi, ay həftə kimi, həftə gün kimi, gün saat kimi olar.","en":"The Hour will not come until time contracts: a year will be like a month, a month like a week, a week like a day, and a day like an hour.","ru":"Час не наступит, пока не сблизится время: год станет как месяц, месяц как неделя, неделя как день, день как час.","tr":"Zaman yakınlaşmadıkça kıyamet kopmaz. Yıl ay gibi, ay hafta gibi, hafta gün gibi, gün saat gibi olur.","ar":"لاَ تَقُومُ السَّاعَةُ حَتَّى يَتَقَارَبَ الزَّمَانُ فَتَكُونُ السَّنَةُ كَالشَّهْرِ وَالشَّهْرُ كَالْجُمُعَةِ وَالْجُمُعَةُ كَالْيَوْمِ وَالْيَوْمُ كَالسَّاعَةِ"},"src":{"az":"Tirmizi 2332","en":"Tirmidhi 2332","ru":"Тирмизи 2332","tr":"Tirmizî 2332","ar":"الترمذي 2332"}},{"id":1817,"t":{"az":"Kim mal yığıb baha satmaq üçün saxlasa, günahkardır.","en":"Whoever hoards goods is a sinner.","ru":"Кто придерживает товар (для повышения цены), тот грешник.","tr":"Kim mal stoklar (pahalı satmak için) o günahkârdır.","ar":"مَنِ احْتَكَرَ فَهُوَ خَاطِئٌ"},"src":{"az":"Muslim, Müsaqat 130","en":"Muslim, Musaqah 130","ru":"Муслим, Мусака 130","tr":"Müslim, Müsâkât 130","ar":"مسلم، المساقاة 130"}},{"id":1821,"t":{"az":"Kim bir müsəlmanın alış-verişini ləğv etsə (peşman olanda), Allah da Qiyamət günü onun büdrəməsini bağışlayar.","en":"Whoever cancels a Muslim's transaction (when he regrets), Allah will overlook his stumble on the Day of Judgment.","ru":"Кто расторгнет сделку мусульманина (когда тот раскаялся), Аллах простит ему его оступок в День Суда.","tr":"Kim bir Müslümanın alışverişini fesheder (pişman olduğunda), Allah da Kıyamet günü onun tökezlemesini bağışlar.","ar":"مَنْ أَقَالَ مُسْلِمًا بَيْعَتَهُ أَقَالَهُ اللَّهُ عَثْرَتَهُ يَوْمَ الْقِيَامَةِ"},"src":{"az":"Əbu Davud 3460","en":"Abu Dawud 3460","ru":"Абу Дауд 3460","tr":"Ebû Dâvûd 3460","ar":"أبو داود 3460"}},{"id":1823,"t":{"az":"Kim çətin vəziyyətdəki birinə möhlət versə və ya borcunu bağışlasa, Allah onu Öz kölgəsindən başqa kölgə olmayan gün kölgəsində saxlayar.","en":"Whoever gives respite to one in difficulty or forgives his debt, Allah will shade him on the Day when there is no shade but His.","ru":"Кто даст отсрочку нуждающемуся или простит ему долг, Аллах укроет его в Своей тени в День, когда нет тени, кроме Его.","tr":"Kim zor durumdaki birine mühlet verir veya borcunu bağışlarsa Allah onu Kendi gölgesinden başka gölge olmayan gün gölgesinde barındırır.","ar":"مَنْ أَنْظَرَ مُعْسِرًا أَوْ وَضَعَ عَنْهُ أَظَلَّهُ اللَّهُ فِي ظِلِّهِ يَوْمَ لاَ ظِلَّ إِلاَّ ظِلُّهُ"},"src":{"az":"Muslim, Zühd 74","en":"Muslim, Zuhd 74","ru":"Муслим, Зухд 74","tr":"Müslim, Zühd 74","ar":"مسلم، الزهد 74"}},{"id":1826,"t":{"az":"Qiyamət günü üç nəfərin mən düşməniyəm: Mənim adımla söz verib xəyanət edən, azad insanı satıb pulunu yeyən, işçini işlədib haqqını verməyən.","en":"Three people I will oppose on the Day of Judgment: a man who gave a pledge in My name then betrayed, a man who sold a free person and consumed his price, and a man who hired a worker and took full work but did not pay.","ru":"Трём я буду противником в День Суда: человеку, давшему обещание Моим именем и предавшему, продавшему свободного и съевшему его цену, и нанявшему работника и не заплатившему ему.","tr":"Kıyamet günü üç kişinin ben düşmanıyım: Benim adımla söz verip ihanet eden, hür insanı satıp parasını yiyen, işçiyi çalıştırıp hakkını vermeyen.","ar":"ثَلاَثَةٌ أَنَا خَصْمُهُمْ يَوْمَ الْقِيَامَةِ رَجُلٌ أَعْطَى بِي ثُمَّ غَدَرَ وَرَجُلٌ بَاعَ حُرًّا فَأَكَلَ ثَمَنَهُ وَرَجُلٌ اسْتَأْجَرَ أَجِيرًا فَاسْتَوْفَى مِنْهُ وَلَمْ يُعْطِهِ أَجْرَهُ"},"src":{"az":"Buxari, Büyu' 106","en":"Bukhari, Buyu' 106","ru":"Бухари, Буйу 106","tr":"Buhârî, Büyû' 106","ar":"البخاري، البيوع 106"}},{"id":1827,"t":{"az":"İmam amin dedikdə siz də amin deyin. Kimin amini mələklərin amini ilə üst-üstə düşsə, keçmiş günahları bağışlanar.","en":"When the imam says Amin, say Amin, for whoever's Amin coincides with the Amin of the angels, his past sins will be forgiven.","ru":"Когда имам скажет «Амин», говорите «Амин». Чей «Амин» совпадёт с «Амин» ангелов, тому простятся прошлые грехи.","tr":"İmam amin dediğinde siz de amin deyin. Kimin amini meleklerin amini ile örtüşürse geçmiş günahları bağışlanır.","ar":"إِذَا أَمَّنَ الإِمَامُ فَأَمِّنُوا فَإِنَّهُ مَنْ وَافَقَ تَأْمِينُهُ تَأْمِينَ الْمَلاَئِكَةِ غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ"},"src":{"az":"Buxari, Dəavat 55","en":"Bukhari, Da'awat 55","ru":"Бухари, Даават 55","tr":"Buhârî, Deavât 55","ar":"البخاري، الدعوات 55"}},{"id":1828,"t":{"az":"İnsanın evində qıldığı namaz mənim bu məscidimdəki namazdan üstündür, fərz namazlar istisna.","en":"A man's prayer in his house is better than his prayer in this mosque of mine, except for obligatory prayers.","ru":"Молитва человека дома лучше его молитвы в этой мечети, кроме обязательных.","tr":"Kişinin evinde kıldığı namaz benim bu mescidimdeki namazdan üstündür, farz namazlar hariç.","ar":"صَلاَةُ الْمَرْءِ فِي بَيْتِهِ أَفْضَلُ مِنْ صَلاَتِهِ فِي مَسْجِدِي هَذَا إِلاَّ الْمَكْتُوبَةَ"},"src":{"az":"Buxari, Əzan 81","en":"Bukhari, Adhan 81","ru":"Бухари, Азан 81","tr":"Buhârî, Ezan 81","ar":"البخاري، الأذان 81"}},{"id":1831,"t":{"az":"Allahın doxsan doqquz - yüzdən bir əskik - adı vardır. Kim onları saysa (əzbərləsə), Cənnətə girər.","en":"Allah has ninety-nine names - one hundred minus one. Whoever memorizes them will enter Paradise.","ru":"У Аллаха девяносто девять имён — сто без одного. Кто выучит их, войдёт в Рай.","tr":"Allah'ın doksan dokuz - yüzden bir eksik - ismi vardır. Kim onları sayar (ezberlerse) Cennete girer.","ar":"لِلَّهِ تِسْعَةٌ وَتِسْعُونَ اسْمًا مِائَةٌ إِلاَّ وَاحِدًا مَنْ أَحْصَاهَا دَخَلَ الْجَنَّةَ"},"src":{"az":"Buxari, Dəavat 68","en":"Bukhari, Da'awat 68","ru":"Бухари, Даават 68","tr":"Buhârî, Deavât 68","ar":"البخاري، الدعوات 68"}},{"id":1832,"t":{"az":"Allahın doxsan doqquz adı var. Kim onları qoruya, Cənnətə girər. O təkdir, təki sevər.","en":"Allah has ninety-nine names. Whoever preserves them will enter Paradise. He is Odd (One) and loves the odd number.","ru":"У Аллаха девяносто девять имён. Кто сохранит их, войдёт в Рай. Он Нечётный и любит нечётное.","tr":"Allah'ın doksan dokuz ismi vardır. Kim onları korursa Cennete girer. O tektir, teki sever.","ar":"إِنَّ لِلَّهِ تِسْعَةً وَتِسْعِينَ اسْمًا مَنْ حَفِظَهَا دَخَلَ الْجَنَّةَ وَهُوَ وِتْرٌ يُحِبُّ الْوِتْرَ"},"src":{"az":"Buxari, Tövhid 12","en":"Bukhari, Tawhid 12","ru":"Бухари, Таухид 12","tr":"Buhârî, Tevhîd 12","ar":"البخاري، التوحيد 12"}},{"id":1834,"t":{"az":"Kim Allahdan başqa ilah olmadığına və Muhammədin Allahın elçisi olduğuna şəhadət etsə, Allah onu Cəhənnəmə haram edər.","en":"Whoever testifies that there is no god but Allah and Muhammad is the Messenger of Allah, Allah will forbid him from the Fire.","ru":"Кто засвидетельствует, что нет бога, кроме Аллаха и Мухаммад — Посланник Аллаха, Аллах запретит ему Огонь.","tr":"Kim Allah'tan başka ilah olmadığına ve Muhammed'in Allah'ın elçisi olduğuna şehadet ederse Allah onu Cehenneme haram kılar.","ar":"مَنْ شَهِدَ أَنْ لاَ إِلَهَ إِلاَّ اللَّهُ وَأَنَّ مُحَمَّدًا رَسُولُ اللَّهِ حَرَّمَ اللَّهُ عَلَيْهِ النَّارَ"},"src":{"az":"Muslim, İman 47","en":"Muslim, Iman 47","ru":"Муслим, Иман 47","tr":"Müslim, İman 47","ar":"مسلم، الإيمان 47"}},{"id":1835,"t":{"az":"Ey oğlan, sənə bəzi sözlər öyrədirəm: Allahı qoru, Allah səni qorusun. Allahı qoru, Onu qarşında tapasan.","en":"O boy, I will teach you some words: Be mindful of Allah and He will protect you. Be mindful of Allah and you will find Him before you.","ru":"О мальчик, я научу тебя словам: Оберегай Аллаха, и Он оберегёт тебя. Оберегай Аллаха, и ты найдёшь Его перед собой.","tr":"Ey oğul, sana bazı sözler öğretiyorum: Allah'ı koru, Allah seni korusun. Allah'ı koru, O'nu karşında bulursun.","ar":"يَا غُلاَمُ إِنِّي أُعَلِّمُكَ كَلِمَاتٍ احْفَظِ اللَّهَ يَحْفَظْكَ احْفَظِ اللَّهَ تَجِدْهُ تُجَاهَكَ"},"src":{"az":"Tirmizi 2516","en":"Tirmidhi 2516","ru":"Тирмизи 2516","tr":"Tirmizî 2516","ar":"الترمذي 2516"}},{"id":1836,"t":{"az":"İstədikdə Allahdan istə. Kömək istədikdə Allahdan kömək istə.","en":"When you ask, ask Allah. When you seek help, seek help from Allah.","ru":"Когда просишь, проси Аллаха. Когда ищешь помощи, ищи помощи у Аллаха.","tr":"İstediğinde Allah'tan iste. Yardım istediğinde Allah'tan yardım iste.","ar":"وَإِذَا سَأَلْتَ فَاسْأَلِ اللَّهَ وَإِذَا اسْتَعَنْتَ فَاسْتَعِنْ بِاللَّهِ"},"src":{"az":"Tirmizi 2516","en":"Tirmidhi 2516","ru":"Тирмизи 2516","tr":"Tirmizî 2516","ar":"الترمذي 2516"}},{"id":1837,"t":{"az":"Bil ki, ümmət sənə fayda vermək üçün toplansa, Allahın yazdığından başqa sənə fayda verə bilməz.","en":"Know that if the nation gathered to benefit you, they could not benefit you except with what Allah has written for you.","ru":"Знай, если вся умма соберётся, чтобы помочь тебе, они не помогут тебе ничем, кроме того, что Аллах предписал тебе.","tr":"Bil ki, ümmet sana fayda vermek için toplansa, Allah'ın yazdığından başka sana fayda veremez.","ar":"وَاعْلَمْ أَنَّ الأُمَّةَ لَوِ اجْتَمَعَتْ عَلَى أَنْ يَنْفَعُوكَ بِشَيْءٍ لَمْ يَنْفَعُوكَ إِلاَّ بِشَيْءٍ قَدْ كَتَبَهُ اللَّهُ لَكَ"},"src":{"az":"Tirmizi 2516","en":"Tirmidhi 2516","ru":"Тирмизи 2516","tr":"Tirmizî 2516","ar":"الترمذي 2516"}},{"id":1839,"t":{"az":"Bil ki, xoşlamadığın şeyə səbr etməkdə çoxlu xeyir var. Zəfər səbrlə bərabərdir, asanlıq çətinliklə bərabərdir.","en":"Know that in patience with what you dislike there is great good, victory is with patience, relief is with hardship, and ease comes with difficulty.","ru":"Знай, что в терпении перед тем, что не нравится, много блага. Победа приходит с терпением, облегчение — с трудностью, и с тягостью — лёгкость.","tr":"Bil ki hoşlanmadığın şeye sabretmekte çok hayır vardır. Zafer sabırla beraberdir, rahatlık sıkıntıyla beraberdir, zorlukla beraber kolaylık vardır.","ar":"وَاعْلَمْ أَنَّ فِي الصَّبْرِ عَلَى مَا تَكْرَهُ خَيْرًا كَثِيرًا وَأَنَّ النَّصْرَ مَعَ الصَّبْرِ وَأَنَّ الْفَرَجَ مَعَ الْكَرْبِ وَأَنَّ مَعَ الْعُسْرِ يُسْرًا"},"src":{"az":"Əhməd 2803","en":"Ahmad 2803","ru":"Ахмад 2803","tr":"Ahmed 2803","ar":"أحمد 2803"}},{"id":1841,"t":{"az":"Allah bir qul üçün xeyir istədikdə onu işlədir. Dedilər: Necə? Buyurdu: Ölümündən əvvəl saleh əmələ müvəffəq edər.","en":"When Allah wants good for a servant, He employs him. They asked: How? He said: He grants him success in righteous deeds before his death.","ru":"Когда Аллах желает блага рабу, Он использует его. Спросили: Как? Сказал: Направляет его к праведным делам перед смертью.","tr":"Allah bir kul için hayır istediğinde onu çalıştırır. Dediler: Nasıl? Buyurdu: Ölümünden önce salih amele muvaffak kılar.","ar":"إِذَا أَرَادَ اللَّهُ بِعَبْدٍ خَيْرًا اسْتَعْمَلَهُ قِيلَ كَيْفَ يَسْتَعْمِلُهُ قَالَ يُوَفِّقُهُ لِعَمَلٍ صَالِحٍ قَبْلَ مَوْتِهِ"},"src":{"az":"Tirmizi 2142","en":"Tirmidhi 2142","ru":"Тирмизи 2142","tr":"Tirmizî 2142","ar":"الترمذي 2142"}},{"id":1842,"t":{"az":"Qul Allahın razılığından olan bir söz söylər, ona əhəmiyyət verməz, amma Allah onu bu sözlə dərəcələrə yüksəldər.","en":"A servant may utter a word pleasing to Allah to which he pays no attention, and Allah raises him degrees by it.","ru":"Раб может произнести слово, угодное Аллаху, не придавая ему значения, а Аллах возвысит его этим на степени.","tr":"Kul Allah'ın rızasından olan bir söz söyler, ona önem vermez, ama Allah onu bu sözle dereceler yükseltir.","ar":"إِنَّ الْعَبْدَ لَيَتَكَلَّمُ بِالْكَلِمَةِ مِنْ رِضْوَانِ اللَّهِ لاَ يُلْقِي لَهَا بَالاً يَرْفَعُهُ اللَّهُ بِهَا دَرَجَاتٍ"},"src":{"az":"Buxari, Riqaq 23","en":"Bukhari, Riqaq 23","ru":"Бухари, Рикак 23","tr":"Buhârî, Rikâk 23","ar":"البخاري، الرقاق 23"}},{"id":1843,"t":{"az":"Qul Allahın qəzəbindən olan bir söz söylər, əhəmiyyət verməz, amma onunla Cəhənnəmə yuvarlanar.","en":"A servant may utter a word displeasing to Allah to which he pays no attention, and it plunges him into Hell.","ru":"Раб может произнести слово, вызывающее гнев Аллаха, не придавая ему значения, и оно ввергнет его в Ад.","tr":"Kul Allah'ın gazabından olan bir söz söyler, önem vermez, ama onunla Cehenneme yuvarlanır.","ar":"وَإِنَّ الْعَبْدَ لَيَتَكَلَّمُ بِالْكَلِمَةِ مِنْ سُخْطِ اللَّهِ لاَ يُلْقِي لَهَا بَالاً يَهْوِي بِهَا فِي جَهَنَّمَ"},"src":{"az":"Buxari, Riqaq 23","en":"Bukhari, Riqaq 23","ru":"Бухари, Рикак 23","tr":"Buhârî, Rikâk 23","ar":"البخاري، الرقاق 23"}},{"id":1845,"t":{"az":"Allah gecə əlini uzadar ki, gündüz pis iş görən tövbə etsin. Gündüz əlini uzadar ki, gecə pis iş görən tövbə etsin. Günəş qərbdən doğana qədər.","en":"Allah extends His hand at night for the sinner of the day to repent, and extends His hand by day for the sinner of the night to repent, until the sun rises from the west.","ru":"Аллах протягивает руку ночью, чтобы дневной грешник покаялся, и протягивает руку днём, чтобы ночной грешник покаялся, пока солнце не взойдёт с запада.","tr":"Allah gece elini uzatır ki gündüz kötülük eden tövbe etsin. Gündüz elini uzatır ki gece kötülük eden tövbe etsin. Güneş batıdan doğana kadar.","ar":"إِنَّ اللَّهَ يَبْسُطُ يَدَهُ بِاللَّيْلِ لِيَتُوبَ مُسِيءُ النَّهَارِ وَيَبْسُطُ يَدَهُ بِالنَّهَارِ لِيَتُوبَ مُسِيءُ اللَّيْلِ حَتَّى تَطْلُعَ الشَّمْسُ مِنْ مَغْرِبِهَا"},"src":{"az":"Muslim, Tövbə 31","en":"Muslim, Tawbah 31","ru":"Муслим, Тауба 31","tr":"Müslim, Tevbe 31","ar":"مسلم، التوبة 31"}},{"id":1848,"t":{"az":"Ondan başqa ilah olmayan, diri və Qaim olan Allahdan bağışlanma diləyir və Ona tövbə edirəm.","en":"I seek forgiveness from Allah, there is no god but He, the Ever-Living, the Sustainer, and I repent to Him.","ru":"Прошу прощения у Аллаха, кроме Которого нет бога, Живого, Вседержителя, и каюсь перед Ним.","tr":"Ondan başka ilah olmayan, diri ve Kaim olan Allah'tan bağışlanma diler ve O'na tövbe ederim.","ar":"أَسْتَغْفِرُ اللَّهَ الَّذِي لاَ إِلَهَ إِلاَّ هُوَ الْحَيُّ الْقَيُّومُ وَأَتُوبُ إِلَيْهِ"},"src":{"az":"Əbu Davud 1517","en":"Abu Dawud 1517","ru":"Абу Дауд 1517","tr":"Ebû Dâvûd 1517","ar":"أبو داود 1517"}},{"id":1852,"t":{"az":"Kim cümə günü dəstəmaz alsa yetər, kim qüsl alsa, qüsl daha əfzəldir.","en":"Whoever performs wudu on Friday, that suffices. And whoever performs ghusl, ghusl is better.","ru":"Кто совершит омовение в пятницу, достаточно. А кто совершит полное омовение, то лучше.","tr":"Kim cuma günü abdest alırsa yeter. Kim gusül alırsa gusül daha faziletlidir.","ar":"مَنْ تَوَضَّأَ يَوْمَ الْجُمُعَةِ فَبِهَا وَنِعْمَتْ وَمَنِ اغْتَسَلَ فَالْغُسْلُ أَفْضَلُ"},"src":{"az":"Tirmizi 497","en":"Tirmidhi 497","ru":"Тирмизи 497","tr":"Tirmizî 497","ar":"الترمذي 497"}},{"id":1853,"t":{"az":"Cümə günü imam xütbə oxuyarkən yanındakına \"sus\" desən, boş danışmış olarsan.","en":"If you say to your companion \"Be quiet\" on Friday while the imam is delivering the sermon, you have spoken idly.","ru":"Если скажешь соседу «Молчи» в пятницу во время проповеди имама, ты совершил пустословие.","tr":"Cuma günü imam hutbe okurken yanındakine \"sus\" dersen boş konuşmuş olursun.","ar":"إِذَا قُلْتَ لِصَاحِبِكَ يَوْمَ الْجُمُعَةِ أَنْصِتْ وَالإِمَامُ يَخْطُبُ فَقَدْ لَغَوْتَ"},"src":{"az":"Buxari, Cümə 36","en":"Bukhari, Jumu'ah 36","ru":"Бухари, Джума 36","tr":"Buhârî, Cuma 36","ar":"البخاري، الجمعة 36"}},{"id":1855,"t":{"az":"Cümə günündə bir saat var ki, müsəlman qul ayaq üstə namaz qılıb Allahdan bir şey istəsə, Allah ona mütləq verər.","en":"In it (Friday) there is an hour in which no Muslim servant stands praying and asks Allah for something except that He gives it to him.","ru":"В ней (пятнице) есть час, в который мусульманин, стоя в молитве и прося Аллаха, непременно получит просимое.","tr":"Cuma gününde bir saat vardır ki Müslüman kul namaz kılıp Allah'tan bir şey isterse Allah ona mutlaka verir.","ar":"فِيهَا سَاعَةٌ لاَ يُوَافِقُهَا عَبْدٌ مُسْلِمٌ وَهُوَ قَائِمٌ يُصَلِّي يَسْأَلُ اللَّهَ شَيْئًا إِلاَّ أَعْطَاهُ إِيَّاهُ"},"src":{"az":"Buxari, Cümə 37","en":"Bukhari, Jumu'ah 37","ru":"Бухари, Джума 37","tr":"Buhârî, Cuma 37","ar":"البخاري، الجمعة 37"}},{"id":1856,"t":{"az":"Ramazandan sonra ən əfzəl oruc Allahın Muhərrəm ayı, fərzdən sonra ən əfzəl namaz gecə namazıdır.","en":"The best fasting after Ramadan is the month of Muharram, and the best prayer after obligatory prayer is night prayer.","ru":"Лучший пост после Рамадана — месяц Мухаррам, и лучшая молитва после обязательной — ночная.","tr":"Ramazandan sonra en faziletli oruç Muharrem ayıdır, farzdan sonra en faziletli namaz gece namazıdır.","ar":"أَفْضَلُ الصِّيَامِ بَعْدَ رَمَضَانَ شَهْرُ اللَّهِ الْمُحَرَّمُ وَأَفْضَلُ الصَّلاَةِ بَعْدَ الْمَكْتُوبَةِ صَلاَةُ اللَّيْلِ"},"src":{"az":"Muslim, Siyam 202","en":"Muslim, Siyam 202","ru":"Муслим, Сыям 202","tr":"Müslim, Sıyâm 202","ar":"مسلم، الصيام 202"}},{"id":1858,"t":{"az":"Ərəfə günü orucunun bir əvvəlki və bir sonrakı ilin günahlarını silməsini Allahdan gözləyirəm.","en":"I anticipate that fasting the day of Arafah will expiate the sins of the preceding and following year.","ru":"Я надеюсь, что пост в день Арафа искупит грехи предыдущего и следующего года.","tr":"Arefe günü orucunun bir önceki ve bir sonraki yılın günahlarını silmesini Allah'tan bekliyorum.","ar":"صِيَامُ يَوْمِ عَرَفَةَ أَحْتَسِبُ عَلَى اللَّهِ أَنْ يُكَفِّرَ السَّنَةَ الَّتِي قَبْلَهُ وَالسَّنَةَ الَّتِي بَعْدَهُ"},"src":{"az":"Muslim, Siyam 196","en":"Muslim, Siyam 196","ru":"Муслим, Сыям 196","tr":"Müslim, Sıyâm 196","ar":"مسلم، الصيام 196"}},{"id":1859,"t":{"az":"Kim Ramazan bayramından sonra altı gün oruc tutsa, bütün ili oruc tutmuş kimi olar.","en":"Whoever fasts six days after Eid al-Fitr, it is as if he fasted the entire year.","ru":"Кто постится шесть дней после праздника разговения, это подобно посту целого года.","tr":"Kim Ramazan bayramından sonra altı gün oruç tutarsa bütün yılı oruç tutmuş gibi olur.","ar":"مَنْ صَامَ سِتَّةَ أَيَّامٍ بَعْدَ الْفِطْرِ كَانَ كَصِيَامِ الدَّهْرِ"},"src":{"az":"Muslim, Siyam 204","en":"Muslim, Siyam 204","ru":"Муслим, Сыям 204","tr":"Müslim, Sıyâm 204","ar":"مسلم، الصيام 204"}},{"id":1861,"t":{"az":"Kim sarımsaq və ya soğan yeyərsə, bizdən uzaqlaşsın, yaxud məscidimizdən uzaq dursun.","en":"Whoever eats garlic or onion, let him keep away from us or from our mosque.","ru":"Кто ел чеснок или лук, пусть сторонится нас или нашей мечети.","tr":"Kim sarımsak veya soğan yerse bizden uzak dursun veya mescidimizden uzak dursun.","ar":"مَنْ أَكَلَ ثُومًا أَوْ بَصَلاً فَلْيَعْتَزِلْنَا أَوْ لِيَعْتَزِلْ مَسْجِدَنَا"},"src":{"az":"Buxari, Əzan 160","en":"Bukhari, Adhan 160","ru":"Бухари, Азан 160","tr":"Buhârî, Ezan 160","ar":"البخاري، الأذان 160"}},{"id":1862,"t":{"az":"Biriniz namaz qılarkən uyuqlasa, yuxusu gedənə qədər yatsın.","en":"If one of you gets drowsy while praying, let him sleep until sleepiness leaves him.","ru":"Если кто-то задремлет во время молитвы, пусть ляжет, пока сонливость не пройдёт.","tr":"Biriniz namaz kılarken uyuklasa uykusu geçene kadar yatsın.","ar":"إِذَا نَعَسَ أَحَدُكُمْ وَهُوَ يُصَلِّي فَلْيَرْقُدْ حَتَّى يَذْهَبَ عَنْهُ النَّوْمُ"},"src":{"az":"Buxari, Vüdu 53","en":"Bukhari, Wudu 53","ru":"Бухари, Вуду 53","tr":"Buhârî, Vudû 53","ar":"البخاري، الوضوء 53"}},{"id":1871,"t":{"az":"Təcəssüs etməyin, araşdırmayın, yarışmayın, həsəd aparmayın, nifrət etməyin, arxa çevirməyin.","en":"Do not spy, do not pry, do not compete, do not envy, do not hate, and do not turn away from each other.","ru":"Не шпионьте, не выведывайте, не соперничайте, не завидуйте, не ненавидьте и не отворачивайтесь.","tr":"Casusluk yapmayın, araştırmayın, yarışmayın, haset etmeyin, nefret etmeyin, sırt çevirmeyin.","ar":"لاَ تَجَسَّسُوا وَلاَ تَحَسَّسُوا وَلاَ تَنَافَسُوا وَلاَ تَحَاسَدُوا وَلاَ تَبَاغَضُوا وَلاَ تَدَابَرُوا"},"src":{"az":"Buxari, Ədəb 57","en":"Bukhari, Adab 57","ru":"Бухари, Адаб 57","tr":"Buhârî, Edeb 57","ar":"البخاري، الأدب 57"}},{"id":1872,"t":{"az":"Kim qardaşına dəmir alət ilə işarə etsə, mələklər onu lənətləyər, buraxana qədər, hətta ata-ana bir qardaşı olsa belə.","en":"Whoever points at his brother with an iron weapon, the angels curse him until he puts it down, even if it is his full brother.","ru":"Кто укажет на брата железным оружием, ангелы проклинают его, пока не опустит, даже если это его родной брат.","tr":"Kim kardeşine demir aletle işaret ederse melekler onu lanetler, bırakana kadar, ata-ana bir kardeşi olsa bile.","ar":"مَنْ أَشَارَ إِلَى أَخِيهِ بِحَدِيدَةٍ فَإِنَّ الْمَلاَئِكَةَ تَلْعَنُهُ حَتَّى يَدَعَهَا وَإِنْ كَانَ أَخَاهُ لأَبِيهِ وَأُمِّهِ"},"src":{"az":"Muslim, Birr 125","en":"Muslim, Birr 125","ru":"Муслим, Бирр 125","tr":"Müslim, Birr 125","ar":"مسلم، البر والصلة 125"}},{"id":1873,"t":{"az":"Müsəlmanın müsəlmanı qorxutması halal deyildir.","en":"It is not permissible for a Muslim to frighten another Muslim.","ru":"Мусульманину не дозволено пугать другого мусульманина.","tr":"Müslümanın Müslümanı korkutması helal değildir.","ar":"لاَ يَحِلُّ لِمُسْلِمٍ أَنْ يُرَوِّعَ مُسْلِمًا"},"src":{"az":"Əbu Davud 5004","en":"Abu Dawud 5004","ru":"Абу Дауд 5004","tr":"Ebû Dâvûd 5004","ar":"أبو داود 5004"}},{"id":1874,"t":{"az":"Kim yalan and ilə müsəlmanın haqqını alsa, Allah ona Cəhənnəmi vacib etmiş və Cənnəti haram etmişdir.","en":"Whoever takes the right of a Muslim by a false oath, Allah has made the Fire obligatory for him and Paradise forbidden.","ru":"Кто отберёт право мусульманина ложной клятвой, Аллах обязал ему Огонь и запретил ему Рай.","tr":"Kim yalan yeminle Müslümanın hakkını alırsa Allah ona Cehennemi vacip kılmış ve Cenneti haram kılmıştır.","ar":"مَنِ اقْتَطَعَ حَقَّ امْرِئٍ مُسْلِمٍ بِيَمِينِهِ فَقَدْ أَوْجَبَ اللَّهُ لَهُ النَّارَ وَحَرَّمَ عَلَيْهِ الْجَنَّةَ"},"src":{"az":"Muslim, İman 218","en":"Muslim, Iman 218","ru":"Муслим, Иман 218","tr":"Müslim, İman 218","ar":"مسلم، الإيمان 218"}},{"id":1875,"t":{"az":"Kim bir qarış torpaq zülm etsə, yeddi qat yerdən boyununa dolanacaq.","en":"Whoever unjustly seizes a span of land, it will be entwined around his neck from seven earths.","ru":"Кто несправедливо захватит пядь земли, она будет обвита вокруг его шеи из семи земель.","tr":"Kim bir karış toprak haksızlık ederse yedi kat yerden boynuna dolanacaktır.","ar":"مَنْ ظَلَمَ قِيدَ شِبْرٍ مِنَ الأَرْضِ طُوِّقَهُ مِنْ سَبْعِ أَرَضِينَ"},"src":{"az":"Buxari, Məzalim 13","en":"Bukhari, Mazalim 13","ru":"Бухари, Мазалим 13","tr":"Buhârî, Mezâlim 13","ar":"البخاري، المظالم 13"}},{"id":1878,"t":{"az":"Gümüşdə onda birin dörddə biri (iki buçuq faiz) zəkat var.","en":"In silver, there is a quarter of a tenth (2.5%) as zakat.","ru":"В серебре закят составляет четверть десятины (2,5%).","tr":"Gümüşte onda birin dörtte biri (yüzde iki buçuk) zekat vardır.","ar":"فِي الرِّقَةِ رُبْعُ الْعُشْرِ"},"src":{"az":"Buxari, Zəkat 38","en":"Bukhari, Zakat 38","ru":"Бухари, Закят 38","tr":"Buhârî, Zekât 38","ar":"البخاري، الزكاة 38"}},{"id":1879,"t":{"az":"Kim İslamda gözəl bir adət qoysa, onun savabı və ondan sonra onu edənlərin savabı onundur, onların savabından heç nə əskiksiz.","en":"Whoever introduces a good practice in Islam will have its reward and the reward of those who act upon it after him, without diminishing their rewards.","ru":"Кто введёт в Ислам хорошую практику, получит её награду и награду тех, кто последует ей, без уменьшения их наград.","tr":"Kim İslam'da güzel bir çığır açarsa onun sevabı ve ondan sonra onu yapanların sevabı onundur, onların sevabından hiçbir şey eksilmeden.","ar":"مَنْ سَنَّ فِي الإِسْلاَمِ سُنَّةً حَسَنَةً فَلَهُ أَجْرُهَا وَأَجْرُ مَنْ عَمِلَ بِهَا بَعْدَهُ مِنْ غَيْرِ أَنْ يَنْقُصَ مِنْ أُجُورِهِمْ شَيْءٌ"},"src":{"az":"Muslim, İlm 15","en":"Muslim, Ilm 15","ru":"Муслим, Ильм 15","tr":"Müslim, İlim 15","ar":"مسلم، العلم 15"}},{"id":1880,"t":{"az":"Kim İslamda pis bir adət qoysa, onun günahı və ondan sonra edənlərin günahı üzərindədir, onların günahından heç nə əskiksiz.","en":"Whoever introduces a bad practice in Islam will bear its sin and the sin of those who act upon it, without diminishing their sins.","ru":"Кто введёт в Ислам дурную практику, понесёт её грех и грех тех, кто последует ей, без уменьшения их грехов.","tr":"Kim İslam'da kötü bir çığır açarsa onun günahı ve ondan sonra onu yapanların günahı üzerindedir, onların günahından hiçbir şey eksilmeden.","ar":"وَمَنْ سَنَّ فِي الإِسْلاَمِ سُنَّةً سَيِّئَةً كَانَ عَلَيْهِ وِزْرُهَا وَوِزْرُ مَنْ عَمِلَ بِهَا مِنْ بَعْدِهِ مِنْ غَيْرِ أَنْ يَنْقُصَ مِنْ أَوْزَارِهِمْ شَيْءٌ"},"src":{"az":"Muslim, İlm 15","en":"Muslim, Ilm 15","ru":"Муслим, Ильм 15","tr":"Müslim, İlim 15","ar":"مسلم، العلم 15"}},{"id":1884,"t":{"az":"Kim qəsdən mənim adımdan yalan uydursa, Cəhənnəmdən yerini hazırlasın.","en":"Whoever intentionally lies about me, let him prepare his seat in the Fire.","ru":"Кто намеренно возведёт на меня ложь, пусть приготовит себе место в Огне.","tr":"Kim kasıtlı olarak benim adıma yalan uydurursa Cehennemdeki yerini hazırlasın.","ar":"مَنْ كَذَبَ عَلَيَّ مُتَعَمِّدًا فَلْيَتَبَوَّأْ مَقْعَدَهُ مِنَ النَّارِ"},"src":{"az":"Buxari, İlm 38","en":"Bukhari, Ilm 38","ru":"Бухари, Ильм 38","tr":"Buhârî, İlim 38","ar":"البخاري، العلم 38"}},{"id":1885,"t":{"az":"Allah bizdən bir hədis eşidib onu qoruyan və başqasına çatdıranın üzünü nurlandırsın. Necə fiqh daşıyan vardır ki, özündən daha fəqih olana çatdırır.","en":"May Allah brighten a person who hears a hadith from us, memorizes it, and conveys it. Many a carrier of knowledge conveys it to one more knowledgeable.","ru":"Да украсит Аллах лицо того, кто услышит от нас хадис, запомнит и передаст. Сколько несущих знание передают его более знающему.","tr":"Allah bizden bir hadis işitip onu koruyarak başkasına ulaştıranın yüzünü nurlandırsın. Nice fıkıh taşıyan vardır ki kendisinden daha fakih olana ulaştırır.","ar":"نَضَّرَ اللَّهُ امْرَأً سَمِعَ مِنَّا حَدِيثًا فَحَفِظَهُ حَتَّى يُبَلِّغَهُ فَرُبَّ حَامِلِ فِقْهٍ إِلَى مَنْ هُوَ أَفْقَهُ مِنْهُ"},"src":{"az":"Tirmizi 2656","en":"Tirmidhi 2656","ru":"Тирмизи 2656","tr":"Tirmizî 2656","ar":"الترمذي 2656"}},{"id":1886,"t":{"az":"İnsanın ən pis miniyi \"belə deyirlər\" sözüdür.","en":"What a wretched mount for a man is \"they claim.\"","ru":"Какое скверное средство передвижения для человека — «утверждают».","tr":"İnsanın en kötü bineği \"öyle diyorlar\" sözüdür.","ar":"بِئْسَ مَطِيَّةُ الرَّجُلِ زَعَمُوا"},"src":{"az":"Əbu Davud 4972","en":"Abu Dawud 4972","ru":"Абу Дауд 4972","tr":"Ebû Dâvûd 4972","ar":"أبو داود 4972"}},{"id":1888,"t":{"az":"Kim bizə silah çəksə, bizdən deyildir.","en":"Whoever bears arms against us is not one of us.","ru":"Кто поднимет на нас оружие, тот не из нас.","tr":"Kim bize silah çekerse bizden değildir.","ar":"مَنْ حَمَلَ عَلَيْنَا السِّلاَحَ فَلَيْسَ مِنَّا"},"src":{"az":"Buxari, Fitən 7","en":"Bukhari, Fitan 7","ru":"Бухари, Фитан 7","tr":"Buhârî, Fiten 7","ar":"البخاري، الفتن 7"}},{"id":1891,"t":{"az":"Kim müsəlmanların işindən bir şeyə vəli olub ehtiyaclarından, çətinliklərindən gizlənsə, Allah da onun ehtiyacından, çətinliyindən gizlənər.","en":"Whoever is in charge of Muslim affairs and hides from their needs and poverty, Allah will hide from his needs and poverty.","ru":"Кто управляет делами мусульман и скрывается от их нужд и бедности, Аллах скроется от его нужд и бедности.","tr":"Kim Müslümanların işinden bir şeye veli olup ihtiyaçlarından, sıkıntılarından gizlenirse Allah da onun ihtiyacından, sıkıntısından gizlenir.","ar":"مَنْ وَلِيَ مِنْ أَمْرِ الْمُسْلِمِينَ شَيْئًا فَاحْتَجَبَ دُونَ حَاجَتِهِمْ وَخَلَّتِهِمْ وَفَقْرِهِمْ احْتَجَبَ اللَّهُ عَنْهُ دُونَ حَاجَتِهِ وَخَلَّتِهِ وَفَقْرِهِ"},"src":{"az":"Əbu Davud 2948","en":"Abu Dawud 2948","ru":"Абу Дауд 2948","tr":"Ebû Dâvûd 2948","ar":"أبو داود 2948"}},{"id":1892,"t":{"az":"Allah elmi insanlardan çəkib almaz, amma alimlərin canını alaraq elmi alar. Alim qalmadıqda insanlar cahil başçılar tutarlar.","en":"Allah does not take knowledge by snatching it from people, but by taking the scholars. When no scholar remains, people take ignorant leaders.","ru":"Аллах не забирает знание, вырывая его у людей, а забирает учёных. Когда не останется учёного, люди возьмут невежественных лидеров.","tr":"Allah ilmi insanlardan çekip almaz, âlimlerin canını alarak ilmi alır. Âlim kalmadığında insanlar cahil başkanlar tutarlar.","ar":"إِنَّ اللَّهَ لاَ يَقْبِضُ الْعِلْمَ انْتِزَاعًا يَنْتَزِعُهُ مِنَ الْعِبَادِ وَلَكِنْ يَقْبِضُ الْعِلْمَ بِقَبْضِ الْعُلَمَاءِ حَتَّى إِذَا لَمْ يُبْقِ عَالِمًا اتَّخَذَ النَّاسُ رُؤُوسًا جُهَّالاً"},"src":{"az":"Buxari, İlm 34","en":"Bukhari, Ilm 34","ru":"Бухари, Ильм 34","tr":"Buhârî, İlim 34","ar":"البخاري، العلم 34"}},{"id":1894,"t":{"az":"Allahı uca tutmaqdan biri yaşlı müsəlmana, ifrata varmayan və onu tərk etməyən Quran əhlinə, adalətli rəhbərə ikram etməkdir.","en":"Part of glorifying Allah is honoring the elderly Muslim, the carrier of the Quran who neither exaggerates nor neglects it, and the just ruler.","ru":"Частью возвеличивания Аллаха является почитание пожилого мусульманина, носителя Корана без крайностей и справедливого правителя.","tr":"Allah'ı yüceltmekten biri yaşlı Müslümana, ifrata kaçmayan ve onu terk etmeyen Kur'an ehline, adaletli yöneticiye ikram etmektir.","ar":"إِنَّ مِنْ إِجْلاَلِ اللَّهِ إِكْرَامَ ذِي الشَّيْبَةِ الْمُسْلِمِ وَحَامِلِ الْقُرْآنِ غَيْرِ الْغَالِي فِيهِ وَالْجَافِي عَنْهُ وَإِكْرَامَ ذِي السُّلْطَانِ الْمُقْسِطِ"},"src":{"az":"Əbu Davud 4843","en":"Abu Dawud 4843","ru":"Абу Дауд 4843","tr":"Ebû Dâvûd 4843","ar":"أبو داود 4843"}},{"id":1895,"t":{"az":"Hər gün səhər və axşam üç dəfə \"Bismillahilləzi la yədurru maəsmihi şeyun fil-ardi və la fis-səma və huvəs-Səmiül-Alim\" deyən qula heç nə zərər verməz.","en":"No servant says morning and evening three times \"Bismillahilladhi la yadurru ma'asmihi shay'un fil-ardi wa la fis-sama' wa huwas-Sami'ul-Alim\" and is harmed by anything.","ru":"Ни один раб, сказавший утром и вечером три раза «Бисмилляхиллязи ля ядурру маасмихи шайун филь-арди ва ля фис-сама ва хувас-Самиуль-Алим», не будет ничем поражён.","tr":"Her gün sabah ve akşam üç kere \"Bismillahillezi la yedurru measmihi şeyün fil-ardı ve la fis-semai ve hüves-Semiül-Alim\" diyen kula hiçbir şey zarar vermez.","ar":"مَا مِنْ عَبْدٍ يَقُولُ فِي صَبَاحِ كُلِّ يَوْمٍ وَمَسَاءِ كُلِّ لَيْلَةٍ بِسْمِ اللَّهِ الَّذِي لاَ يَضُرُّ مَعَ اسْمِهِ شَيْءٌ فِي الأَرْضِ وَلاَ فِي السَّمَاءِ وَهُوَ السَّمِيعُ الْعَلِيمُ ثَلاَثَ مَرَّاتٍ فَيَضُرَّهُ شَيْءٌ"},"src":{"az":"Tirmizi 3388","en":"Tirmidhi 3388","ru":"Тирмизи 3388","tr":"Tirmizî 3388","ar":"الترمذي 3388"}},{"id":1898,"t":{"az":"Allaha and olsun, iman etməz! Allaha and olsun, iman etməz! Allaha and olsun, iman etməz! Dedilər: Kim, ya Rəsulullah? Buyurdu: Qonşusu şərindən əmin olmayan.","en":"By Allah, he does not believe! By Allah, he does not believe! By Allah, he does not believe! They asked: Who? He said: The one whose neighbor is not safe from his evil.","ru":"Клянусь Аллахом, не уверует! Клянусь Аллахом, не уверует! Клянусь Аллахом, не уверует! Спросили: Кто? Сказал: Тот, чей сосед не в безопасности от его зла.","tr":"Allah'a yemin olsun, iman etmez! Allah'a yemin olsun, iman etmez! Allah'a yemin olsun, iman etmez! Dediler: Kim ya Rasulallah? Buyurdu: Komşusu şerrinden emin olmayan.","ar":"وَاللَّهِ لاَ يُؤْمِنُ وَاللَّهِ لاَ يُؤْمِنُ وَاللَّهِ لاَ يُؤْمِنُ قِيلَ وَمَنْ يَا رَسُولَ اللَّهِ قَالَ الَّذِي لاَ يَأْمَنُ جَارُهُ بَوَائِقَهُ"},"src":{"az":"Buxari, Ədəb 29","en":"Bukhari, Adab 29","ru":"Бухари, Адаб 29","tr":"Buhârî, Edeb 29","ar":"البخاري، الأدب 29"}},{"id":1900,"t":{"az":"Kim ruzisinin bollaşmasını və ömrünün uzanmasını istəyirsə, qohumluq bağını qorusun.","en":"Whoever wants his provision expanded and his life extended, let him maintain family ties.","ru":"Кто хочет, чтобы его удел был расширен и жизнь продлена, пусть поддерживает родственные связи.","tr":"Kim rızkının bollaşmasını ve ömrünün uzamasını istiyorsa akrabalık bağını korusun.","ar":"مَنْ أَرَادَ أَنْ يُبْسَطَ لَهُ فِي رِزْقِهِ وَيُنْسَأَ لَهُ فِي أَثَرِهِ فَلْيَصِلْ رَحِمَهُ"},"src":{"az":"Buxari, Ədəb 12","en":"Bukhari, Adab 12","ru":"Бухари, Адаб 12","tr":"Buhârî, Edeb 12","ar":"البخاري، الأدب 12"}},{"id":1902,"t":{"az":"İnsanlara rəhm etməyənə Allah rəhm etməz.","en":"Whoever does not show mercy to people, Allah will not show mercy to him.","ru":"Кто не проявляет милости к людям, Аллах не проявит к нему милости.","tr":"İnsanlara merhamet etmeyene Allah merhamet etmez.","ar":"مَنْ لاَ يَرْحَمِ النَّاسَ لاَ يَرْحَمْهُ اللَّهُ"},"src":{"az":"Buxari, Ədəb 27","en":"Bukhari, Adab 27","ru":"Бухари, Адаб 27","tr":"Buhârî, Edeb 27","ar":"البخاري، الأدب 27"}},{"id":1905,"t":{"az":"Qul düşünmədən bir söz söylər, onunla Cəhənnəmə şərq ilə qərb arasından daha uzaq düşər.","en":"A servant may utter a word without thinking, by which he falls into the Fire farther than the distance between east and west.","ru":"Раб может произнести слово, не подумав, и оно сбросит его в Ад дальше, чем расстояние между востоком и западом.","tr":"Kul düşünmeden bir söz söyler, onunla Cehenneme doğu ile batı arasından daha uzak düşer.","ar":"إِنَّ الْعَبْدَ لَيَتَكَلَّمُ بِالْكَلِمَةِ مَا يَتَبَيَّنُ فِيهَا يَزِلُّ بِهَا فِي النَّارِ أَبْعَدَ مِمَّا بَيْنَ الْمَشْرِقِ"},"src":{"az":"Buxari, Riqaq 23","en":"Bukhari, Riqaq 23","ru":"Бухари, Рикак 23","tr":"Buhârî, Rikâk 23","ar":"البخاري، الرقاق 23"}},{"id":1909,"t":{"az":"Kim \"La ilahə illəllahu vahdəhu la şərikə ləh, ləhul-mulku və ləhul-hamdu, yuhyi və yumit və huvə alə kulli şeyin qadir\" on dəfə desə, dörd kölə azad etmiş qədər savab alar.","en":"Whoever says \"La ilaha illallahu wahdahu la sharika lah, lahul-mulku wa lahul-hamdu yuhyi wa yumit wa huwa ala kulli shay'in qadir\" ten times, it equals freeing four slaves.","ru":"Кто скажет «Ля иляха илляллаху вахдаху ля шарика лях, ляхуль-мульку ва ляхуль-хамду юхьи ва юмит ва хува аля кулли шайин кадир» десять раз, получит награду, равную освобождению четырёх рабов.","tr":"Kim \"La ilahe illallahu vahdehu la şerike leh, lehül-mülkü ve lehül-hamdü yuhyi ve yümit ve hüve ala külli şeyin kadir\" on kere derse dört köle azat etmiş kadar sevap alır.","ar":"لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ يُحْيِي وَيُمِيتُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ مَنْ قَالَهَا عَشْرَ مَرَّاتٍ كَانَتْ لَهُ عِدْلَ أَرْبَعِ رِقَابٍ"},"src":{"az":"Muslim 2693","en":"Muslim 2693","ru":"Муслим 2693","tr":"Müslim 2693","ar":"مسلم 2693"}},{"id":1911,"t":{"az":"Kim Allaha heç nəyi şərik qoşmadan ölsə, Cənnətə girər. Kim Allaha şərik qoşaraq ölsə, Cəhənnəmə girər.","en":"Whoever dies not associating anything with Allah will enter Paradise. Whoever dies associating something with Allah will enter the Fire.","ru":"Кто умрёт, не придавая Аллаху сотоварищей, войдёт в Рай. Кто умрёт, придавая Аллаху сотоварищей, войдёт в Ад.","tr":"Kim Allah'a hiçbir şeyi ortak koşmadan ölürse Cennete girer. Kim Allah'a ortak koşarak ölürse Cehenneme girer.","ar":"مَنْ مَاتَ لاَ يُشْرِكُ بِاللَّهِ شَيْئًا دَخَلَ الْجَنَّةَ وَمَنْ مَاتَ يُشْرِكُ بِاللَّهِ شَيْئًا دَخَلَ النَّارَ"},"src":{"az":"Muslim, İman 151","en":"Muslim, Iman 151","ru":"Муслим, Иман 151","tr":"Müslim, İman 151","ar":"مسلم، الإيمان 151"}},{"id":1912,"t":{"az":"Bütün ümmətim Cənnətə girər, imtina edən istisna. Dedilər: Kim imtina edər? Buyurdu: Mənə itaət edən Cənnətə girər, mənə üsyan edən isə imtina etmiş kimidir.","en":"All my ummah will enter Paradise except those who refuse. They asked: Who refuses? He said: Whoever obeys me enters Paradise, and whoever disobeys me has refused.","ru":"Вся моя община войдёт в Рай, кроме отказавшихся. Спросили: Кто отказывается? Сказал: Кто подчиняется мне, войдёт в Рай, кто ослушается — тот отказался.","tr":"Bütün ümmetim Cennete girer, reddeden hariç. Dediler: Kim reddeder? Buyurdu: Bana itaat eden Cennete girer, bana isyan eden reddetmiştir.","ar":"كُلُّ أُمَّتِي يَدْخُلُونَ الْجَنَّةَ إِلاَّ مَنْ أَبَى قَالُوا وَمَنْ يَأْبَى قَالَ مَنْ أَطَاعَنِي دَخَلَ الْجَنَّةَ وَمَنْ عَصَانِي فَقَدْ أَبَى"},"src":{"az":"Buxari, İ'tisam 2","en":"Bukhari, I'tisam 2","ru":"Бухари, Итисам 2","tr":"Buhârî, İ'tisâm 2","ar":"البخاري، الاعتصام بالكتاب والسنة 2"}},{"id":1914,"t":{"az":"Sünnətimə və hidayət olunmuş raşidi xəlifələrin sünnətinə sarılın, ona azı dişlərinizlə yapışın.","en":"Hold onto my Sunnah and the way of the rightly guided caliphs. Bite onto it with your molars.","ru":"Держитесь моей Сунны и пути праведных халифов. Вцепитесь в них коренными зубами.","tr":"Sünnetime ve hidayet olunmuş raşit halifelerin sünnetine sarılın, ona azı dişlerinizle yapışın.","ar":"عَلَيْكُمْ بِسُنَّتِي وَسُنَّةِ الْخُلَفَاءِ الرَّاشِدِينَ الْمَهْدِيِّينَ عَضُّوا عَلَيْهَا بِالنَّوَاجِذِ"},"src":{"az":"Əbu Davud 4607","en":"Abu Dawud 4607","ru":"Абу Дауд 4607","tr":"Ebû Dâvûd 4607","ar":"أبو داود 4607"}},{"id":1915,"t":{"az":"Kim işa namazını camaatla qılsa, gecənin yarısını ibadətlə keçirmiş kimidir. Kim sübh namazını camaatla qılsa, bütün gecəni namaz qılmış kimidir.","en":"Whoever prays Isha in congregation, it is as if he stood in prayer for half the night. Whoever prays Fajr in congregation, it is as if he prayed the entire night.","ru":"Кто помолится ишу в коллективе, как будто молился полночи. Кто помолится утреннюю в коллективе, как будто молился всю ночь.","tr":"Kim yatsı namazını cemaatle kılarsa gecenin yarısını ibadetle geçirmiş gibidir. Kim sabah namazını cemaatle kılarsa bütün geceyi namaz kılmış gibidir.","ar":"مَنْ صَلَّى الْعِشَاءَ فِي جَمَاعَةٍ فَكَأَنَّمَا قَامَ نِصْفَ اللَّيْلِ وَمَنْ صَلَّى الصُّبْحَ فِي جَمَاعَةٍ فَكَأَنَّمَا صَلَّى اللَّيْلَ كُلَّهُ"},"src":{"az":"Muslim, Mesacid 260","en":"Muslim, Masajid 260","ru":"Муслим, Масаджид 260","tr":"Müslim, Mesâcid 260","ar":"مسلم، المساجد 260"}},{"id":1918,"t":{"az":"Həcc ibadətlərinizi məndən öyrənin.","en":"Take your rites of pilgrimage from me.","ru":"Берите свои обряды хаджа от меня.","tr":"Hac ibadetlerinizi benden öğrenin.","ar":"خُذُوا عَنِّي مَنَاسِكَكُمْ"},"src":{"az":"Muslim, Həcc 310","en":"Muslim, Hajj 310","ru":"Муслим, Хадж 310","tr":"Müslim, Hac 310","ar":"مسلم، الحج 310"}},{"id":1919,"t":{"az":"Kim yalandan and içərək müsəlmanın malını alsa, Allahla O ona qəzəbli halda qarşılaşar.","en":"Whoever seizes a Muslim's property with a false oath will meet Allah while He is angry with him.","ru":"Кто захватит имущество мусульманина ложной клятвой, встретит Аллаха, когда Он на него гневается.","tr":"Kim yalan yeminle Müslümanın malını alırsa Allah ile O ona gazaplı halde karşılaşır.","ar":"مَنِ اقْتَطَعَ مَالَ امْرِئٍ مُسْلِمٍ بِيَمِينٍ كَاذِبَةٍ لَقِيَ اللَّهَ وَهُوَ عَلَيْهِ غَضْبَانُ"},"src":{"az":"Buxari, Müsaqat 12","en":"Bukhari, Musaqah 12","ru":"Бухари, Мусака 12","tr":"Buhârî, Müsâkât 12","ar":"البخاري، المساقاة 12"}},{"id":1920,"t":{"az":"Hakimlər üçdür. İkisi Cəhənnəmdə, biri Cənnətdədir. Haqqı bilib onunla hökm verən Cənnətdədir.","en":"Judges are of three kinds: two in the Fire and one in Paradise. The one who knew the truth and judged by it is in Paradise.","ru":"Судьи бывают трёх видов: двое в Аду и один в Раю. Тот, кто знал истину и судил по ней, в Раю.","tr":"Hakimler üçtür. İkisi Cehennemdedir, biri Cennettedir. Hakkı bilip onunla hükmeden Cennettedir.","ar":"الْقُضَاةُ ثَلاَثَةٌ اثْنَانِ فِي النَّارِ وَوَاحِدٌ فِي الْجَنَّةِ رَجُلٌ عَرَفَ الْحَقَّ فَقَضَى بِهِ فَهُوَ فِي الْجَنَّةِ"},"src":{"az":"Əbu Davud 3573","en":"Abu Dawud 3573","ru":"Абу Дауд 3573","tr":"Ebû Dâvûd 3573","ar":"أبو داود 3573"}},{"id":1921,"t":{"az":"Qiyamət günü Allah yanında ən böyük əmanət xəyanətlərindən biri: kişi xanımı ilə yaxınlıq edir, sonra onun sirrini yayır.","en":"Among the greatest betrayals of trust before Allah on the Day of Judgment is a man who is intimate with his wife, then spreads her secrets.","ru":"Среди величайших предательств доверия перед Аллахом в День Суда — мужчина, который сближается с женой, а затем разглашает её секреты.","tr":"Kıyamet günü Allah katında en büyük emanet ihanetlerinden biri: kişi eşiyle yakınlık kurar, sonra onun sırrını yayar.","ar":"إِنَّ مِنْ أَعْظَمِ الأَمَانَةِ عِنْدَ اللَّهِ يَوْمَ الْقِيَامَةِ الرَّجُلُ يُفْضِي إِلَى امْرَأَتِهِ وَتُفْضِي إِلَيْهِ ثُمَّ يَنْشُرُ سِرَّهَا"},"src":{"az":"Muslim, Nikah 123","en":"Muslim, Nikah 123","ru":"Муслим, Никах 123","tr":"Müslim, Nikâh 123","ar":"مسلم، النكاح 123"}},{"id":1922,"t":{"az":"Bir kişi bir qadınla baş-başa qalmasın, bir qadın məhrəmsiz səfər etməsin.","en":"No man should be alone with a woman, and no woman should travel without a mahram.","ru":"Мужчина не должен оставаться наедине с женщиной, и женщина не должна путешествовать без махрама.","tr":"Bir erkek bir kadınla baş başa kalmasın, bir kadın mahremsiz sefere çıkmasın.","ar":"لاَ يَخْلُوَنَّ رَجُلٌ بِامْرَأَةٍ وَلاَ تُسَافِرَنَّ امْرَأَةٌ إِلاَّ وَمَعَهَا مَحْرَمٌ"},"src":{"az":"Buxari, Nikah 111","en":"Bukhari, Nikah 111","ru":"Бухари, Никах 111","tr":"Buhârî, Nikâh 111","ar":"البخاري، النكاح 111"}},{"id":1923,"t":{"az":"Allahım, ümmətimin erkən saatlarını bərəkətli et.","en":"O Allah, bless my ummah in its early hours.","ru":"О Аллах, благослови мою общину в её ранние часы.","tr":"Allah'ım, ümmetimin erken saatlerini bereketli kıl.","ar":"اللَّهُمَّ بَارِكْ لأُمَّتِي فِي بُكُورِهَا"},"src":{"az":"Tirmizi 1212","en":"Tirmidhi 1212","ru":"Тирмизи 1212","tr":"Tirmizî 1212","ar":"الترمذي 1212"}},{"id":1924,"t":{"az":"Kim qoruyucu divarı olmayan bir damda gecələsə, himayə ondan götürülmüşdür.","en":"Whoever sleeps on the roof of a house without a wall, the covenant of protection is lifted from him.","ru":"Кто переночует на крыше дома без ограждения, с него снята защита.","tr":"Kim koruyucu duvarı olmayan bir çatıda gecelerse himaye ondan kaldırılmıştır.","ar":"مَنْ بَاتَ عَلَى ظَهْرِ بَيْتٍ لَيْسَ لَهُ حِجَارٌ فَقَدْ بَرِئَتْ مِنْهُ الذِّمَّةُ"},"src":{"az":"Əbu Davud 5041","en":"Abu Dawud 5041","ru":"Абу Дауд 5041","tr":"Ebû Dâvûd 5041","ar":"أبو داود 5041"}},{"id":1926,"t":{"az":"Ya duası tez qəbul olunar, ya axirətə saxlanar, ya da ondan misli qədər bir şər uzaqlaşdırılar.","en":"Either his supplication is answered immediately, or it is stored for him in the Hereafter, or an equivalent evil is averted from him.","ru":"Либо его мольба будет исполнена сразу, либо отложена для него в загробной жизни, либо от него будет отведено равное зло.","tr":"Ya duası hemen kabul olunur, ya ahirete saklanır, ya da ondan misli kadar bir şer uzaklaştırılır.","ar":"إِمَّا أَنْ تُعَجَّلَ لَهُ دَعْوَتُهُ وَإِمَّا أَنْ يَدَّخِرَهَا لَهُ فِي الآخِرَةِ وَإِمَّا أَنْ يَصْرِفَ عَنْهُ مِنَ السُّوءِ مِثْلَهَا"},"src":{"az":"Əhməd 11133","en":"Ahmad 11133","ru":"Ахмад 11133","tr":"Ahmed 11133","ar":"أحمد 11133"}},{"id":1933,"t":{"az":"Dilin daima Allahın zikri ilə yaş olsun.","en":"Keep your tongue moist with the remembrance of Allah.","ru":"Пусть твой язык всегда будет влажным от поминания Аллаха.","tr":"Dilin daima Allah'ın zikriyle ıslak olsun.","ar":"مَا يَزَالُ لِسَانُكَ رَطْبًا مِنْ ذِكْرِ اللَّهِ"},"src":{"az":"Tirmizi 3375","en":"Tirmidhi 3375","ru":"Тирмизи 3375","tr":"Tirmizî 3375","ar":"الترمذي 3375"}},{"id":1934,"t":{"az":"Allaha və Axirət gününə inanan qohumluq bağını qorusun.","en":"Whoever believes in Allah and the Last Day should maintain family ties.","ru":"Кто верит в Аллаха и Судный день, пусть поддерживает родственные связи.","tr":"Allah'a ve ahiret gününe inanan akrabalık bağını korusun.","ar":"مَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الآخِرِ فَلْيَصِلْ رَحِمَهُ"},"src":{"az":"Buxari, Ədəb 85","en":"Bukhari, Adab 85","ru":"Бухари, Адаб 85","tr":"Buhârî, Edeb 85","ar":"البخاري، الأدب 85"}},{"id":1935,"t":{"az":"Əsl qohumluq bağını qoruyan, qarşılıq verən deyil, kəsildikdə bağlayan kimsədir.","en":"The one who maintains family ties is not the one who reciprocates, but the one who, when ties are cut, reconnects them.","ru":"Поддерживающий родственные связи — не тот, кто отвечает взаимностью, а тот, кто восстанавливает их, когда они разорваны.","tr":"Asıl akrabalık bağını koruyan karşılık veren değil, kesildiğinde bağlayan kimsedir.","ar":"لَيْسَ الْوَاصِلُ بِالْمُكَافِئِ وَلَكِنِ الْوَاصِلُ الَّذِي إِذَا قُطِعَتْ رَحِمُهُ وَصَلَهَا"},"src":{"az":"Buxari, Ədəb 15","en":"Bukhari, Adab 15","ru":"Бухари, Адаб 15","tr":"Buhârî, Edeb 15","ar":"البخاري، الأدب 15"}},{"id":1939,"t":{"az":"Mənim dostlarım təqva sahibləridir, kim olursa olsunlar və harada olursa olsunlar.","en":"My allies are the God-fearing, whoever they are and wherever they are.","ru":"Мои союзники — богобоязненные, кем бы они ни были и где бы ни были.","tr":"Benim dostlarım takva sahipleridir, kim olursa olsunlar ve nerede olursa olsunlar.","ar":"إِنَّ أَوْلِيَاءِيَ مِنْهُمُ الْمُتَّقُونَ مَنْ كَانُوا وَحَيْثُ كَانُوا"},"src":{"az":"Əhməd 22052","en":"Ahmad 22052","ru":"Ахмад 22052","tr":"Ahmed 22052","ar":"أحمد 22052"}},{"id":1940,"t":{"az":"Ey insanlar, Rəbbiniz birdir, atanız birdir. Ərəbin əcəmə, əcəmin ərəbə üstünlüyü yoxdur, ancaq təqva ilə.","en":"O people, your Lord is One and your father is one. There is no superiority of an Arab over a non-Arab or vice versa, except by piety.","ru":"О люди, ваш Господь един и ваш отец един. Нет превосходства араба над неарабом и наоборот, кроме как по богобоязненности.","tr":"Ey insanlar, Rabbiniz birdir, babanız birdir. Arabın Arap olmayana, Arap olmayanın Araba üstünlüğü yoktur, ancak takvayla.","ar":"يَا أَيُّهَا النَّاسُ إِنَّ رَبَّكُمْ وَاحِدٌ وَإِنَّ أَبَاكُمْ وَاحِدٌ لاَ فَضْلَ لِعَرَبِيٍّ عَلَى أَعْجَمِيٍّ وَلاَ لأَعْجَمِيٍّ عَلَى عَرَبِيٍّ إِلاَّ بِالتَّقْوَى"},"src":{"az":"Əhməd 23489","en":"Ahmad 23489","ru":"Ахмад 23489","tr":"Ahmed 23489","ar":"أحمد 23489"}},{"id":1942,"t":{"az":"Azan verənlər Qiyamət günü ən uzun boyunlu insanlardır.","en":"The muezzins will have the longest necks (highest status) on the Day of Judgment.","ru":"Муэдзины будут обладателями самых длинных шей (высшего статуса) в День Суда.","tr":"Müezzinler Kıyamet günü en uzun boyunlu insanlar olacaktır.","ar":"الْمُؤَذِّنُونَ أَطْوَلُ النَّاسِ أَعْنَاقًا يَوْمَ الْقِيَامَةِ"},"src":{"az":"Muslim, Salat 14","en":"Muslim, Salah 14","ru":"Муслим, Салят 14","tr":"Müslim, Salât 14","ar":"مسلم، الصلاة 14"}},{"id":1943,"t":{"az":"Azançını eşitdikdə onun dediyini deyin, sonra mənə salavat gətirin.","en":"When you hear the muezzin, repeat what he says, then send blessings upon me.","ru":"Когда услышите муэдзина, повторяйте за ним, затем благословляйте меня.","tr":"Müezzini duyduğunuzda onun dediğini söyleyin, sonra bana salat getirin.","ar":"إِذَا سَمِعْتُمُ الْمُؤَذِّنَ فَقُولُوا مِثْلَ مَا يَقُولُ ثُمَّ صَلُّوا عَلَيَّ"},"src":{"az":"Muslim, Salat 11","en":"Muslim, Salah 11","ru":"Муслим, Салят 11","tr":"Müslim, Salât 11","ar":"مسلم، الصلاة 11"}},{"id":1945,"t":{"az":"Kim azan eşitdikdə bu duanı oxusa, Qiyamət günü şəfaətim ona halal olar.","en":"Whoever says this dua upon hearing the adhan, my intercession will be permissible for him on the Day of Judgment.","ru":"Кто скажет эту мольбу при слышании азана, моё заступничество будет ему дозволено в День Суда.","tr":"Kim ezanı duyunca bu duayı okursa Kıyamet günü şefaatim ona helal olur.","ar":"مَنْ قَالَ حِينَ يَسْمَعُ النِّدَاءَ اللَّهُمَّ رَبَّ هَذِهِ الدَّعْوَةِ التَّامَّةِ وَالصَّلاَةِ الْقَائِمَةِ آتِ مُحَمَّدًا الْوَسِيلَةَ وَالْفَضِيلَةَ وَابْعَثْهُ مَقَامًا مَحْمُودًا حَلَّتْ لَهُ شَفَاعَتِي يَوْمَ الْقِيَامَةِ"},"src":{"az":"Buxari, Əzan 8","en":"Bukhari, Adhan 8","ru":"Бухари, Азан 8","tr":"Buhârî, Ezan 8","ar":"البخاري، الأذان 8"}},{"id":1947,"t":{"az":"Kim səbr etməyə çalışsa, Allah onu səbrli edər. Heç kimə səbrdən daha xeyirli və geniş bir nemət verilməmişdir.","en":"Whoever strives to be patient, Allah will make him patient. No one has been given a gift better and more comprehensive than patience.","ru":"Кто старается быть терпеливым, Аллах сделает его терпеливым. Никому не было дано дара лучше и обширнее терпения.","tr":"Kim sabretmeye çalışırsa Allah onu sabırlı kılar. Hiç kimseye sabırdan daha hayırlı ve geniş bir nimet verilmemiştir.","ar":"مَنْ يَتَصَبَّرْ يُصَبِّرْهُ اللَّهُ وَمَا أُعْطِيَ أَحَدٌ عَطَاءً خَيْرًا وَأَوْسَعَ مِنَ الصَّبْرِ"},"src":{"az":"Buxari, Zəkat 50","en":"Bukhari, Zakat 50","ru":"Бухари, Закят 50","tr":"Buhârî, Zekât 50","ar":"البخاري، الزكاة 50"}},{"id":1948,"t":{"az":"Kim iffətli olmağa çalışsa, Allah onu iffətli edər. Kim ehtiyacsız olmağa çalışsa, Allah onu ehtiyacsız edər.","en":"Whoever tries to be chaste, Allah will make him chaste. Whoever tries to be self-sufficient, Allah will make him self-sufficient.","ru":"Кто стремится к целомудрию, Аллах сделает его целомудренным. Кто стремится к довольству, Аллах обогатит его.","tr":"Kim iffetli olmaya çalışırsa Allah onu iffetli kılar. Kim müstağni olmaya çalışırsa Allah onu müstağni kılar.","ar":"مَنْ يَسْتَعْفِفْ يُعِفَّهُ اللَّهُ وَمَنْ يَسْتَغْنِ يُغْنِهِ اللَّهُ"},"src":{"az":"Buxari, Zəkat 50","en":"Bukhari, Zakat 50","ru":"Бухари, Закят 50","tr":"Buhârî, Zekât 50","ar":"البخاري، الزكاة 50"}},{"id":1949,"t":{"az":"Zənginlik nəfsin zənginliyidir.","en":"True richness is the richness of the soul.","ru":"Истинное богатство — богатство души.","tr":"Zenginlik nefsin zenginliğidir.","ar":"الْغِنَى غِنَى النَّفْسِ"},"src":{"az":"Buxari, Riqaq 15","en":"Bukhari, Riqaq 15","ru":"Бухари, Рикак 15","tr":"Buhârî, Rikâk 15","ar":"البخاري، الرقاق 15"}},{"id":1951,"t":{"az":"Yalnız iki kişiyə qibtə edilər: Allahın mal verib haqq yolunda xərcləyən, Allahın hikmət verib onunla hökm verən və öyrədən.","en":"There is no envy except in two cases: a man to whom Allah gave wealth and he spends it in truth, and a man to whom Allah gave wisdom and he judges and teaches with it.","ru":"Нет зависти, кроме как к двоим: человеку, которому Аллах дал богатство и он тратит его на истину, и человеку, которому Аллах дал мудрость и он судит и обучает ей.","tr":"Yalnızca iki kişiye gıpta edilir: Allah'ın mal verip hak yolunda harcayan, Allah'ın hikmet verip onunla hükmeden ve öğreten.","ar":"لاَ حَسَدَ إِلاَّ فِي اثْنَتَيْنِ رَجُلٌ آتَاهُ اللَّهُ مَالاً فَسَلَّطَهُ عَلَى هَلَكَتِهِ فِي الْحَقِّ وَرَجُلٌ آتَاهُ اللَّهُ الْحِكْمَةَ فَهُوَ يَقْضِي بِهَا وَيُعَلِّمُهَا"},"src":{"az":"Buxari, İlm 15","en":"Bukhari, Ilm 15","ru":"Бухари, Ильм 15","tr":"Buhârî, İlim 15","ar":"البخاري، العلم 15"}},{"id":1957,"t":{"az":"Güclü mömin zəif mömindən Allaha daha xeyirli və daha sevimlidir. Hər ikisində xeyir var.","en":"The strong believer is better and more beloved to Allah than the weak believer, and in both there is good.","ru":"Сильный верующий лучше и любимее Аллахом, чем слабый верующий, и в каждом из них благо.","tr":"Güçlü mümin zayıf müminden Allah'a daha hayırlı ve daha sevimlidir. Her ikisinde hayır vardır.","ar":"الْمُؤْمِنُ الْقَوِيُّ خَيْرٌ وَأَحَبُّ إِلَى اللَّهِ مِنَ الْمُؤْمِنِ الضَّعِيفِ وَفِي كُلٍّ خَيْرٌ"},"src":{"az":"Muslim, Qədər 34","en":"Muslim, Qadar 34","ru":"Муслим, Кадар 34","tr":"Müslim, Kader 34","ar":"مسلم، القدر 34"}},{"id":1958,"t":{"az":"Sənə fayda verən şeyə çalış, Allahdan kömək istə və aciz olma.","en":"Strive for what benefits you, seek help from Allah, and do not give up.","ru":"Стремись к тому, что тебе полезно, проси помощи у Аллаха и не отчаивайся.","tr":"Sana fayda veren şeye çalış, Allah'tan yardım iste ve aciz olma.","ar":"احْرِصْ عَلَى مَا يَنْفَعُكَ وَاسْتَعِنْ بِاللَّهِ وَلاَ تَعْجَزْ"},"src":{"az":"Muslim, Qədər 34","en":"Muslim, Qadar 34","ru":"Муслим, Кадар 34","tr":"Müslim, Kader 34","ar":"مسلم، القدر 34"}},{"id":1959,"t":{"az":"De: Allaha inandım, sonra doğru yolda ol.","en":"Say: I believe in Allah, then be steadfast.","ru":"Скажи: Я уверовал в Аллаха, затем будь стоек.","tr":"De: Allah'a inandım, sonra dosdoğru ol.","ar":"قُلْ آمَنْتُ بِاللَّهِ ثُمَّ اسْتَقِمْ"},"src":{"az":"Muslim, İman 62","en":"Muslim, Iman 62","ru":"Муслим, Иман 62","tr":"Müslim, İman 62","ar":"مسلم، الإيمان 62"}},{"id":1961,"t":{"az":"İş əhli olmayanlara tapşırıldıqda qiyaməti gözlə.","en":"When authority is given to those unqualified, await the Hour.","ru":"Когда дело вручено не тем, кто его достоин, жди Часа.","tr":"İş ehli olmayanlara havale edildiğinde kıyameti bekle.","ar":"إِذَا وُسِّدَ الأَمْرُ إِلَى غَيْرِ أَهْلِهِ فَانْتَظِرِ السَّاعَةَ"},"src":{"az":"Buxari, İlm 2","en":"Bukhari, Ilm 2","ru":"Бухари, Ильм 2","tr":"Buhârî, İlim 2","ar":"البخاري، العلم 2"}},{"id":1962,"t":{"az":"Günəşin doğduğu ən xeyirli gün cümə günüdür. O gün Adəm yaradıldı, Cənnətə daxil edildi və oradan çıxarıldı.","en":"The best day on which the sun rises is Friday. On it Adam was created, admitted to Paradise, and removed from it.","ru":"Лучший день, в который восходит солнце — пятница. В этот день был создан Адам, введён в Рай и выведен из него.","tr":"Güneşin doğduğu en hayırlı gün cuma günüdür. O gün Adem yaratıldı, Cennete konuldu ve çıkarıldı.","ar":"خَيْرُ يَوْمٍ طَلَعَتْ عَلَيْهِ الشَّمْسُ يَوْمُ الْجُمُعَةِ فِيهِ خُلِقَ آدَمُ وَفِيهِ أُدْخِلَ الْجَنَّةَ وَفِيهِ أُخْرِجَ مِنْهَا"},"src":{"az":"Muslim, Cümə 18","en":"Muslim, Jumu'ah 18","ru":"Муслим, Джума 18","tr":"Müslim, Cuma 18","ar":"مسلم، الجمعة 18"}},{"id":1963,"t":{"az":"Siz bezənə qədər Allah bezməz.","en":"Allah does not tire of rewarding until you tire of doing good.","ru":"Аллах не устаёт давать, пока вы не устанете.","tr":"Siz bıkana kadar Allah bıkmaz.","ar":"لاَ يَمَلُّ اللَّهُ حَتَّى تَمَلُّوا"},"src":{"az":"Buxari, İman 32","en":"Bukhari, Iman 32","ru":"Бухари, Иман 32","tr":"Buhârî, İman 32","ar":"البخاري، الإيمان 32"}},{"id":1965,"t":{"az":"Kim insanları narazı edərək Allahın razılığını axtarsa, Allah onu insanlardan qoruyar. Kim Allahı narazı edərək insanların razılığını axtarsa, Allah onu insanlara buraxar.","en":"Whoever seeks Allah's pleasure at the expense of people's anger, Allah will suffice him against people. Whoever seeks people's pleasure at the expense of Allah's anger, Allah will leave him to people.","ru":"Кто ищет довольства Аллаха, вызывая гнев людей, Аллах защитит его от людей. Кто ищет довольства людей, вызывая гнев Аллаха, Аллах оставит его людям.","tr":"Kim insanları kızdırarak Allah'ın rızasını ararsa Allah onu insanlardan korur. Kim Allah'ı kızdırarak insanların rızasını ararsa Allah onu insanlara bırakır.","ar":"مَنِ الْتَمَسَ رِضَاءَ اللَّهِ بِسَخَطِ النَّاسِ كَفَاهُ اللَّهُ مُؤْنَةَ النَّاسِ وَمَنِ الْتَمَسَ رِضَاءَ النَّاسِ بِسَخَطِ اللَّهِ وَكَلَهُ اللَّهُ إِلَى النَّاسِ"},"src":{"az":"Tirmizi 2414","en":"Tirmidhi 2414","ru":"Тирмизи 2414","tr":"Tirmizî 2414","ar":"الترمذي 2414"}},{"id":1970,"t":{"az":"Allah bağışlayan qulun ancaq izzətini artırar.","en":"Allah does not increase a servant through forgiveness except in honor.","ru":"Аллах увеличивает честь прощающего раба.","tr":"Allah affeden kulun ancak izzetini artırır.","ar":"وَمَا زَادَ اللَّهُ عَبْدًا بِعَفْوٍ إِلاَّ عِزًّا"},"src":{"az":"Muslim, Birr 69","en":"Muslim, Birr 69","ru":"Муслим, Бирр 69","tr":"Müslim, Birr 69","ar":"مسلم، البر والصلة 69"}},{"id":1971,"t":{"az":"Kim sizə Allaha sığınaraq sığınsa, qoruyun. Kim Allahın adı ilə istəsə, verin. Kim sizi dəvət etsə, qəbul edin. Kim sizə yaxşılıq etsə, mükafatlandırın.","en":"Whoever seeks refuge in Allah's name, give him refuge. Whoever asks in Allah's name, give him. Whoever invites you, accept. Whoever does you a favor, repay him.","ru":"Кто прибегает к защите Аллаха, защитите его. Кто просит именем Аллаха, дайте. Кто приглашает, примите. Кто оказал вам добро, отплатите.","tr":"Kim size Allah'a sığınarak sığınırsa koruyun. Kim Allah'ın adıyla isterse verin. Kim sizi davet ederse kabul edin. Kim size iyilik yaparsa karşılığını verin.","ar":"مَنِ اسْتَعَاذَكُمْ بِاللَّهِ فَأَعِيذُوهُ وَمَنْ سَأَلَكُمْ بِاللَّهِ فَأَعْطُوهُ وَمَنْ دَعَاكُمْ فَأَجِيبُوهُ وَمَنْ صَنَعَ إِلَيْكُمْ مَعْرُوفًا فَكَافِئُوهُ"},"src":{"az":"Əbu Davud 5109","en":"Abu Dawud 5109","ru":"Абу Дауд 5109","tr":"Ebû Dâvûd 5109","ar":"أبو داود 5109"}},{"id":1973,"t":{"az":"Sizə yaxşılıq edənə mükafat verin. Əgər verməyə bir şey tapmasanız, müqabil gördüyünüzə qədər dua edin.","en":"Whoever does you a favor, repay him. If you cannot find anything to repay, supplicate for him until you feel you have repaid him.","ru":"Кто оказал вам добро, отплатите. Если не найдёте чем, молитесь за него, пока не почувствуете, что отплатили.","tr":"Size iyilik edene mükafat verin. Karşılık verecek bir şey bulamazsanız yeterli gördüğünüze kadar dua edin.","ar":"مَنْ صَنَعَ إِلَيْكُمْ مَعْرُوفًا فَكَافِئُوهُ فَإِنْ لَمْ تَجِدُوا مَا تُكَافِئُونَهُ فَادْعُوا لَهُ حَتَّى تَرَوْا أَنَّكُمْ قَدْ كَافَأْتُمُوهُ"},"src":{"az":"Əbu Davud 1672","en":"Abu Dawud 1672","ru":"Абу Дауд 1672","tr":"Ebû Dâvûd 1672","ar":"أبو داود 1672"}},{"id":1975,"t":{"az":"Müsəlmanın qardaşının alış-verişi üzərinə alış-veriş etməsi və qardaşının elçiliyi üzərinə elçi göndərməsi halal deyildir.","en":"It is not permissible for a Muslim to sell over his brother's sale or propose over his brother's proposal.","ru":"Мусульманину не дозволено продавать поверх сделки брата или свататься поверх сватовства брата.","tr":"Müslümanın kardeşinin alışverişi üzerine alışveriş yapması ve kardeşinin dünürlüğü üzerine dünür göndermesi helal değildir.","ar":"لاَ يَحِلُّ لِلْمُسْلِمِ أَنْ يَبِيعَ عَلَى بَيْعِ أَخِيهِ وَلاَ يَخْطُبَ عَلَى خِطْبَةِ أَخِيهِ"},"src":{"az":"Muslim, Nikah 52","en":"Muslim, Nikah 52","ru":"Муслим, Никах 52","tr":"Müslim, Nikâh 52","ar":"مسلم، النكاح 52"}},{"id":1976,"t":{"az":"Kim Allahdan başqasına and içsə, küfr etmiş və ya şirk qoşmuş olar.","en":"Whoever swears by other than Allah has committed disbelief or polytheism.","ru":"Кто поклянётся не Аллахом, тот впал в неверие или многобожие.","tr":"Kim Allah'tan başkasına yemin ederse küfretmiş veya şirk koşmuş olur.","ar":"مَنْ حَلَفَ بِغَيْرِ اللَّهِ فَقَدْ كَفَرَ أَوْ أَشْرَكَ"},"src":{"az":"Tirmizi 1535","en":"Tirmidhi 1535","ru":"Тирмизи 1535","tr":"Tirmizî 1535","ar":"الترمذي 1535"}},{"id":1977,"t":{"az":"Kim bir and içdikdən sonra daha xeyirli olanı görsə, andını kəffarə etsin və daha xeyirli olanı etsin.","en":"Whoever swears an oath and then sees something better, let him expiate his oath and do that which is better.","ru":"Кто поклянётся, а потом увидит лучшее, пусть искупит клятву и сделает лучшее.","tr":"Kim bir yemin edip sonra daha hayırlı olanı görürse yemininin kefaretini versin ve daha hayırlı olanı yapsın.","ar":"مَنْ حَلَفَ عَلَى يَمِينٍ ثُمَّ رَأَى خَيْرًا مِنْهَا فَلْيُكَفِّرْ عَنْ يَمِينِهِ وَلْيَأْتِ الَّذِي هُوَ خَيْرٌ"},"src":{"az":"Muslim, Əyman 11","en":"Muslim, Ayman 11","ru":"Муслим, Айман 11","tr":"Müslim, Eymân 11","ar":"مسلم، الأيمان 11"}},{"id":1978,"t":{"az":"Allah ümmətimin xətasını, unutqanlığını və zorla etdirildiyini bağışlamışdır.","en":"Allah has forgiven my ummah for mistakes, forgetfulness, and what they are forced to do.","ru":"Аллах простил моей общине ошибки, забывчивость и то, к чему их принудили.","tr":"Allah ümmetimin hatasını, unutkanlığını ve zorla yaptırılanı bağışlamıştır.","ar":"إِنَّ اللَّهَ تَجَاوَزَ لِي عَنْ أُمَّتِي الْخَطَأَ وَالنِّسْيَانَ وَمَا اسْتُكْرِهُوا عَلَيْهِ"},"src":{"az":"İbn Macə 2043","en":"Ibn Majah 2043","ru":"Ибн Маджа 2043","tr":"İbn Mâce 2043","ar":"ابن ماجه 2043"}},{"id":1979,"t":{"az":"Dinarların ən əfzəli kişinin ailəsinə xərclədiyi dinardır.","en":"The best dinar is the one a man spends on his family.","ru":"Лучший динар — тот, который мужчина тратит на свою семью.","tr":"Dinarların en faziletlisi kişinin ailesine harcadığı dinardır.","ar":"أَفْضَلُ الدَّنَانِيرِ دِينَارٌ يُنْفِقُهُ الرَّجُلُ عَلَى عِيَالِهِ"},"src":{"az":"Muslim, Zəkat 39","en":"Muslim, Zakat 39","ru":"Муслим, Закят 39","tr":"Müslim, Zekât 39","ar":"مسلم، الزكاة 39"}},{"id":1980,"t":{"az":"Allah yolunda, kölə azad etmək üçün, yoxsula sədəqə olaraq və ailəyə xərclənən dinardan ən böyük savablısı ailəyə xərclədiyin dinardır.","en":"Of the dinars spent in Allah's cause, freeing a slave, charity to the poor, and on family - the greatest in reward is the one spent on family.","ru":"Из динаров, потраченных на пути Аллаха, на освобождение раба, на милостыню бедняку и на семью — наибольшая награда за потраченный на семью.","tr":"Allah yolunda, köle azat etmek için, yoksula sadaka olarak ve aileye harcanan dinardan en büyük sevaplısı aileye harcadığın dinardır.","ar":"دِينَارٌ أَنْفَقْتَهُ فِي سَبِيلِ اللَّهِ وَدِينَارٌ أَنْفَقْتَهُ فِي رَقَبَةٍ وَدِينَارٌ تَصَدَّقْتَ بِهِ عَلَى مِسْكِينٍ وَدِينَارٌ أَنْفَقْتَهُ عَلَى أَهْلِكَ أَعْظَمُهَا أَجْرًا الَّذِي أَنْفَقْتَهُ عَلَى أَهْلِكَ"},"src":{"az":"Muslim, Zəkat 39","en":"Muslim, Zakat 39","ru":"Муслим, Закят 39","tr":"Müslim, Zekât 39","ar":"مسلم، الزكاة 39"}},{"id":1985,"t":{"az":"Kim müsəlman bir kölə azad etsə, Allah onun hər uzvuna qarşılıq sahibinin bir uzvunu Cəhənnəmdən azad edər.","en":"Whoever frees a Muslim slave, Allah will free each of his limbs from the Fire for each limb of the slave.","ru":"Кто освободит мусульманского раба, Аллах освободит от Огня каждую его часть тела за каждую часть тела раба.","tr":"Kim Müslüman bir köle azat ederse Allah onun her uzvuna karşılık sahibinin bir uzvunu Cehennemden azat eder.","ar":"مَنْ أَعْتَقَ رَقَبَةً مُسْلِمَةً أَعْتَقَ اللَّهُ بِكُلِّ عُضْوٍ مِنْهَا عُضْوًا مِنْهُ مِنَ النَّارِ"},"src":{"az":"Buxari, Kəffaratül-Əyman 6","en":"Bukhari, Kaffarat al-Ayman 6","ru":"Бухари, Каффарат аль-Айман 6","tr":"Buhârî, Keffârâtü'l-Eymân 6","ar":"البخاري، كفارات الأيمان 6"}},{"id":1987,"t":{"az":"Kim ov və ya mal-qara iti xaricində it saxlasa, hər gün əməlindən iki qirat əskildilər.","en":"Whoever keeps a dog except for hunting or guarding livestock, two qirats are deducted from his reward daily.","ru":"Кто содержит собаку, кроме охотничьей или пастушьей, ежедневно теряет два кирата из награды.","tr":"Kim av veya çoban köpeği dışında köpek tutarsa her gün amelinden iki kırat eksilir.","ar":"مَنِ اقْتَنَى كَلْبًا إِلاَّ كَلْبَ صَيْدٍ أَوْ مَاشِيَةٍ نَقَصَ مِنْ أَجْرِهِ كُلَّ يَوْمٍ قِيرَاطَانِ"},"src":{"az":"Muslim, Müsaqat 50","en":"Muslim, Musaqah 50","ru":"Муслим, Мусака 50","tr":"Müslim, Müsâkât 50","ar":"مسلم، المساقاة 50"}},{"id":1990,"t":{"az":"Həya imandandır, iman Cənnətdədir. Ədəbsizlik kobudluqdandır, kobudluq Cəhənnəmdədir.","en":"Modesty is from faith and faith leads to Paradise. Obscenity is from harshness and harshness leads to the Fire.","ru":"Стыдливость от веры, а вера в Раю. Непристойность от грубости, а грубость в Аду.","tr":"Haya imandandır, iman Cennettedir. Edepsizlik kabalıktandır, kabalık Cehennemdedir.","ar":"الْحَيَاءُ مِنَ الإِيمَانِ وَالإِيمَانُ فِي الْجَنَّةِ وَالْبَذَاءُ مِنَ الْجَفَاءِ وَالْجَفَاءُ فِي النَّارِ"},"src":{"az":"Tirmizi 2009","en":"Tirmidhi 2009","ru":"Тирмизи 2009","tr":"Tirmizî 2009","ar":"الترمذي 2009"}},{"id":1992,"t":{"az":"Kimdən bir elm soruşulub gizləsə, Allah Qiyamət günü onu oddan bir yüyənlə yüyənləyər.","en":"Whoever is asked about knowledge and conceals it, Allah will bridle him with a bridle of fire on the Day of Judgment.","ru":"У кого спросят о знании, а он скроет его, Аллах взнуздает его огненной уздой в День Суда.","tr":"Kimden bir ilim sorulup gizlerse Allah Kıyamet günü onu ateşten bir gemle gemler.","ar":"مَنْ سُئِلَ عَنْ عِلْمٍ فَكَتَمَهُ أَلْجَمَهُ اللَّهُ بِلِجَامٍ مِنْ نَارٍ يَوْمَ الْقِيَامَةِ"},"src":{"az":"Əbu Davud 3658","en":"Abu Dawud 3658","ru":"Абу Дауд 3658","tr":"Ebû Dâvûd 3658","ar":"أبو داود 3658"}},{"id":1993,"t":{"az":"Uşaqlarınıza yeddi yaşında namazı əmr edin, on yaşında ondan ötrü cəzalandırın.","en":"Command your children to pray at age seven and discipline them for it at age ten.","ru":"Повелевайте детям молиться с семи лет и наказывайте за неё с десяти лет.","tr":"Çocuklarınıza yedi yaşında namazı emredin, on yaşında onun için cezalandırın.","ar":"مُرُوا أَوْلاَدَكُمْ بِالصَّلاَةِ وَهُمْ أَبْنَاءُ سَبْعِ سِنِينَ وَاضْرِبُوهُمْ عَلَيْهَا وَهُمْ أَبْنَاءُ عَشْرٍ"},"src":{"az":"Əbu Davud 495","en":"Abu Dawud 495","ru":"Абу Дауд 495","tr":"Ebû Dâvûd 495","ar":"أبو داود 495"}},{"id":1995,"t":{"az":"Mən yalnız gözəl əxlaqı tamamlamaq üçün göndərildim.","en":"I was sent only to perfect noble character.","ru":"Я был послан лишь для того, чтобы довершить благородство нравов.","tr":"Ben yalnızca güzel ahlakı tamamlamak için gönderildim.","ar":"إِنَّمَا بُعِثْتُ لأُتَمِّمَ مَكَارِمَ الأَخْلاَقِ"},"src":{"az":"Əhməd 8952","en":"Ahmad 8952","ru":"Ахмад 8952","tr":"Ahmed 8952","ar":"أحمد 8952"}},{"id":1997,"t":{"az":"Doğru hərəkət edin, orta yolu tutun və sevinin.","en":"Do your best, try to be near perfection, and receive glad tidings.","ru":"Поступайте правильно, стремитесь к совершенству и радуйтесь.","tr":"Doğru hareket edin, orta yolu tutun ve sevinin.","ar":"سَدِّدُوا وَقَارِبُوا وَأَبْشِرُوا"},"src":{"az":"Buxari, İman 29","en":"Bukhari, Iman 29","ru":"Бухари, Иман 29","tr":"Buhârî, İman 29","ar":"البخاري، الإيمان 29"}},{"id":1998,"t":{"az":"Aranızda bir şey qoydum ki, ona sarılsanız, heç vaxt azmayacaqsınız: Allahın Kitabı.","en":"I have left among you that which, if you hold fast to it, you will never go astray: the Book of Allah.","ru":"Я оставил вам то, за что если ухватитесь, никогда не заблудитесь: Книгу Аллаха.","tr":"Aranızda bir şey bıraktım ki ona sarılırsanız asla sapıtmayacaksınız: Allah'ın Kitabı.","ar":"تَرَكْتُ فِيكُمْ مَا إِنْ تَمَسَّكْتُمْ بِهِ لَنْ تَضِلُّوا كِتَابَ اللَّهِ"},"src":{"az":"Muslim, Həcc 147","en":"Muslim, Hajj 147","ru":"Муслим, Хадж 147","tr":"Müslim, Hac 147","ar":"مسلم، الحج 147"}},{"id":1999,"t":{"az":"Aranızda iki ağır şey qoyuram. Birincisi Allahın Kitabıdır, onda hidayət və nur var. Allahın Kitabını alın və ona sarılın.","en":"I am leaving among you two weighty things. The first is the Book of Allah, in which there is guidance and light. Take hold of the Book of Allah and cling to it.","ru":"Я оставляю вам две важные вещи. Первая — Книга Аллаха, в которой руководство и свет. Держитесь Книги Аллаха и цепляйтесь за неё.","tr":"Aranızda iki ağır şey bırakıyorum. Birincisi Allah'ın Kitabıdır, onda hidayet ve nur vardır. Allah'ın Kitabını alın ve ona sarılın.","ar":"إِنِّي تَارِكٌ فِيكُمْ ثَقَلَيْنِ أَوَّلُهُمَا كِتَابُ اللَّهِ فِيهِ الْهُدَى وَالنُّورُ فَخُذُوا بِكِتَابِ اللَّهِ وَاسْتَمْسِكُوا بِهِ"},"src":{"az":"Muslim, Fəzailus-Sahaba 36","en":"Muslim, Fada'il as-Sahabah 36","ru":"Муслим, Фадаиль ас-Сахаба 36","tr":"Müslim, Fezâilü's-Sahâbe 36","ar":"مسلم، فضائل الصحابة 36"}},{"id":2000,"t":{"az":"Allahım, mənə hidayət ver və məni doğru yola yönəlt.","en":"O Allah, guide me and direct me to the right path.","ru":"О Аллах, наставь меня и направь на прямой путь.","tr":"Allah'ım, bana hidayet ver ve beni doğru yola yönelt.","ar":"اللَّهُمَّ اهْدِنِي وَسَدِّدْنِي"},"src":{"az":"Muslim, Zikr 78","en":"Muslim, Dhikr 78","ru":"Муслим, Зикр 78","tr":"Müslim, Zikir 78","ar":"مسلم، الذكر 78"}}]
